const LINES: Record<string, readonly [string, string, string]> = {"genesis-14-1":["В дни Амрафеля, царя Шинъара, Арьоха, царя Элласара, Кедорлаомера, царя Эйлама, и Тидаля, царя Гоим,","In de dagen van Amrafel, koning van Sinear, Arjoch, koning van Ellasar, Kedorlaomer, koning van Elam, en Tidal, koning van Gojim,",""],"genesis-14-2":["они пошли войной на Беру, царя Сдома, на Биршу, царя Аморы, на Шинава, царя Адмы, на Шемевера, царя Цевоима, и на царя Белы, то есть Цоара.","voerden zij oorlog met Bera, koning van Sedom, met Birsja, koning van Amora, met Sjinaav, koning van Adma, met Sjemever, koning van Tsevoïm, en met de koning van Bela, dat is Tsoar.",""],"genesis-14-3":["Все они сошлись в долине Сиддим — это Солёное море.","Zij allen kwamen samen in het dal Siddim — dat is de Zoutzee.",""],"genesis-14-4":["Двенадцать лет они служили Кедорлаомеру, а на тринадцатый год восстали.","Twaalf jaar dienden zij Kedorlaomer, en in het dertiende jaar kwamen zij in opstand.",""],"genesis-14-5":["В четырнадцатый год пришёл Кедорлаомер и цари, которые были с ним, и разбили рефаим в Аштерот-Карнаиме, зузим в Хаме и эмим в Шаве-Кирьятаиме,","In het veertiende jaar kwam Kedorlaomer met de koningen die bij hem waren, en zij versloegen de Refaïm in Asjterot-Karnajim, de Zoeziem in Ham en de Emim in Sjavé-Kirjataïm,",""],"genesis-14-6":["и хори в их горах Сеира, до Эль-Парана, что у пустыни.","en de Chori op hun berg Seïr, tot El-Paran, dat aan de woestijn ligt.","JPS: место El-paran; фр.: plaine de Pharan. По-еврейски אֵיל פָּארָן — местность Эль-Паран."],"genesis-14-7":["Они повернули, пришли в Эйн-Мишпат, то есть в Кадеш, и разбили всю землю амалекитян, а также эмори, которые жили в Хацацон-Тамаре.","Zij keerden om, kwamen bij Ein-Misjpat, dat is Kadesj, en versloegen heel het land van de Amalekieten en ook de Emori die in Chatsatson-Tamar woonden.",""],"genesis-14-8":["Вышли царь Сдома, царь Аморы, царь Адмы, царь Цевоима и царь Белы, то есть Цоара, и выстроились против них для войны в долине Сиддим:","Toen trokken de koning van Sedom, de koning van Amora, de koning van Adma, de koning van Tsevoïm en de koning van Bela, dat is Tsoar, uit en stelden zich tegen hen op voor de strijd in het dal Siddim:",""],"genesis-14-9":["против Кедорлаомера, царя Эйлама, Тидаля, царя Гоим, Амрафеля, царя Шинъара, и Арьоха, царя Элласара — четверо царей против пятерых.","tegen Kedorlaomer, koning van Elam, Tidal, koning van Gojim, Amrafel, koning van Sinear, en Arjoch, koning van Ellasar — vier koningen tegen de vijf.",""],"genesis-14-10":["Долина Сиддим была в смоляных ямах. Цари Сдома и Аморы побежали и упали туда, а уцелевшие бежали в горы.","Het dal Siddim zat vol pekputten. De koningen van Sedom en Amora vluchtten en vielen daarin, en wie overbleven vluchtten naar het gebergte.",""],"genesis-14-11":["Они забрали всё имущество Сдома и Аморы и весь их хлеб и ушли.","Zij namen alle have van Sedom en Amora en al hun voedsel en trokken weg.",""],"genesis-14-12":["Забрали и Лота, сына брата Аврама, вместе с его имуществом, и ушли. А Лот жил в Сдоме.","Zij namen ook Lot mee, de zoon van de broer van Avram, met zijn have, en trokken weg. Lot woonde in Sedom.",""],"genesis-14-13":["Пришёл спасшийся и рассказал Авраму, еврею. Тот жил у теребинтов Мамре-эмори, брата Эшколя и брата Анера, и они были в брите с Аврамом.","Een vluchteling kwam en vertelde het aan Avram, de Hebreeër. Die woonde bij de terebinten van Mamre, de Emori, broer van Esjkol en broer van Aner, en zij stonden met Avram in een briet.","JPS: terebinths; фр.: plaines. По-еврейски אֵלֹנֵי מַמְרֵא — теребинты Мамре."],"genesis-14-14":["Аврам услышал, что его брат взят в плен, вооружил своих выученных людей, рождённых в его доме, — триста восемнадцать — и преследовал до Дана.","Toen Avram hoorde dat zijn broer gevangen was weggevoerd, rustte hij zijn geoefende mannen uit, geboren in zijn huis, driehonderdachttien, en achtervolgde hen tot Dan.","JPS: his brother; фр.: son parent. По-еврейски אָחִיו — его брат; в 14:12 Лот назван сыном брата Аврама."],"genesis-14-15":["Ночью он разделил своих людей и напал на них, он и его слуги, разбил их и преследовал до Ховы, что слева от Дамаска.","Hij verdeelde zijn mannen en overviel hen in de nacht, hij en zijn dienaren, versloeg hen en achtervolgde hen tot Chova, links van Dammesek.",""],"genesis-14-16":["Он вернул всё имущество. Вернул и Лота, своего брата, и его имущество, а также женщин и народ.","Hij bracht alle have terug. Ook Lot, zijn broer, en zijn have bracht hij terug, en ook de vrouwen en het volk.",""],"genesis-14-17":["Царь Сдома вышел ему навстречу, когда Аврам возвращался после победы над Кедорлаомером и царями, которые были с ним, в долину Шаве, то есть в долину царя.","De koning van Sedom ging hem tegemoet, toen hij terugkwam van de overwinning op Kedorlaomer en de koningen die bij hem waren, in het dal Sjavé, dat is het Koningsdal.",""],"genesis-14-18":["Малки-Цедек, царь Шалема, вынес хлеб и вино. Он был священником Бога Всевышнего.","Malki-Tsedek, koning van Sjalem, bracht brood en wijn naar buiten. Hij was priester van God de Allerhoogste.",""],"genesis-14-19":["Он благословил его и сказал: «Благословен Аврам Богом Всевышним, Творцом неба и земли.","Hij zegende hem en zei: «Gezegend is Avram door God de Allerhoogste, Maker van hemel en aarde.",""],"genesis-14-20":["И благословен Бог Всевышний, который отдал твоих врагов в твою руку». И он дал ему десятую часть от всего.","En gezegend is God de Allerhoogste, die je vijanden in je hand heeft gegeven.» En hij gaf hem een tiende van alles.","Подлежащее וַיִּתֶּן־לוֹ не названо. Фр. прямо говорит, что десятину дал Аврам; обычное чтение то же."],"genesis-14-21":["Царь Сдома сказал Авраму: «Отдай мне людей, а имущество возьми себе».","De koning van Sedom zei tegen Avram: «Geef mij de mensen, de have mag jij houden.»",""],"genesis-14-22":["Аврам сказал царю Сдома: «Я поднял руку к Господу, Богу Всевышнему, Творцу неба и земли:","Avram zei tegen de koning van Sedom: «Ik heb mijn hand opgeheven naar de Eeuwige, God de Allerhoogste, Maker van hemel en aarde:",""],"genesis-14-23":["ни нитки, ни ремешка от сандалии — ничего из твоего я не возьму, чтобы ты не сказал: „это я обогатил Аврама“.","geen draad en geen riem van een sandaal, niets van wat van jou is zal ik nemen, zodat jij niet zegt: „ik heb Avram rijk gemaakt“.",""],"genesis-14-24":["Только то, что съели эти юноши, и долю людей, которые ходили со мной, — Анера, Эшколя и Мамре, — пусть они возьмут свою долю».","Alleen wat de jongemannen al hebben gegeten, en het deel van de mannen die met mij meegingen — Aner, Esjkol en Mamre — laten zij hun deel nemen.»",""],"genesis-15-1":["После этих событий было слово Господа к Авраму в видении: «Не бойся, Аврам. Я — щит тебе. Награда твоя очень велика».","Na deze dingen kwam het woord van de Eeuwige tot Avram in een visioen: «Wees niet bang, Avram. Ik ben een schild voor je. Je loon zal zeer groot zijn.»",""],"genesis-15-2":["Аврам сказал: «Господь Бог, что Ты дашь мне? Я ухожу бездетным, а распорядитель моего дома — Элиэзер из Дамаска».","Avram zei: «Eeuwige, God, wat wilt U mij geven? Ik ga kinderloos heen, en de beheerder van mijn huis is Eliëzer uit Dammesek.»","בֶּן־מֶשֶׁק בֵּיתִי тёмное место. JPS: possessor of my house; фр. добавляет fils adoptif. Переведено как распорядитель дома, без «приёмный сын»."],"genesis-15-3":["Аврам сказал: «Ты не дал мне потомства, и вот домочадец наследует мне».","Avram zei: «U hebt mij geen nageslacht gegeven, en zie, iemand uit mijn huis zal mij erven.»",""],"genesis-15-4":["И было слово Господа к нему: «Не он наследует тебе, а тот, кто выйдет из твоего чрева, — он наследует тебе».","Toen kwam het woord van de Eeuwige tot hem: «Niet deze zal jou erven, maar wie uit jouw lichaam voortkomt, die zal jou erven.»",""],"genesis-15-5":["Он вывел его наружу и сказал: «Посмотри на небо и сосчитай звёзды, если сможешь их сосчитать». И сказал ему: «Таким будет твоё потомство».","Hij leidde hem naar buiten en zei: «Kijk naar de hemel en tel de sterren, als je ze tellen kunt.» En Hij zei tegen hem: «Zo zal jouw nageslacht zijn.»",""],"genesis-15-6":["Он поверил Господу, и Он счёл это ему праведностью.","Hij vertrouwde op de Eeuwige, en Die rekende het hem als gerechtigheid.","JPS: righteousness; фр.: mérite. По-еврейски צְדָקָה — праведность, не христианское «вменение»."],"genesis-15-7":["И сказал ему: «Я — Господь, который вывел тебя из Ур-Касдим, чтобы отдать тебе эту землю в наследие».","En Hij zei tegen hem: «Ik ben de Eeuwige, die je uit Ur-Kasdim heeft geleid om je dit land in bezit te geven.»",""],"genesis-15-8":["Он сказал: «Господь Бог, по чему я узнаю, что я наследую её?»","Hij zei: «Eeuwige, God, waaraan zal ik weten dat ik het in bezit zal nemen?»",""],"genesis-15-9":["Он сказал ему: «Возьми Мне трёхлетнюю телицу, трёхлетнюю козу, трёхлетнего барана, горлицу и молодого голубя».","Hij zei tegen hem: «Neem voor Mij een driejarige vaars, een driejarige geit, een driejarige ram, een tortel en een jonge duif.»",""],"genesis-15-10":["Он взял всё это, рассёк их пополам и положил половину каждого напротив другой, а птиц не рассёк.","Hij nam dit alles, deelde ze middendoor en legde elke helft tegenover de andere. De vogels deelde hij niet.",""],"genesis-15-11":["Хищные птицы спустились на туши, и Аврам отогнал их.","Roofvogels daalden neer op de kadavers, en Avram joeg ze weg.",""],"genesis-15-12":["Солнце уже садилось, и крепкий сон напал на Аврама, и вот — ужас, великая тьма нападает на него.","De zon stond op het punt onder te gaan, en een diepe slaap viel op Avram, en zie: angst, een grote duisternis, viel op hem.",""],"genesis-15-13":["И сказал Авраму: «Знай твёрдо: твоё потомство будет пришельцем в чужой земле. Им будут служить, и те будут угнетать их четыреста лет.","En Hij zei tegen Avram: «Weet het zeker: jouw nageslacht zal vreemdeling zijn in een land dat niet van hen is. Men zal hen laten dienen en hen vierhonderd jaar verdrukken.",""],"genesis-15-14":["Но и тот народ, которому они будут служить, Я осужу, а потом они выйдут с большим имуществом.","Maar ook het volk dat zij zullen dienen, zal Ik vonnissen, en daarna zullen zij wegtrekken met veel have.",""],"genesis-15-15":["А ты отойдёшь к своим отцам в мире и будешь погребён в доброй старости.","Jij zult in vrede tot je vaderen gaan. Je zult begraven worden in een goede ouderdom.",""],"genesis-15-16":["Четвёртое поколение вернётся сюда, потому что вина эмори до сих пор не полна».","Het vierde geslacht zal hier terugkomen, want de schuld van de Emori is tot nu toe niet vol.»",""],"genesis-15-17":["Солнце зашло, и была тьма. И вот дымящаяся печь и огненный факел прошли между этими частями.","De zon was ondergegaan en het was duister. En zie, een rokende oven en een vlammende fakkel gingen tussen deze stukken door.","JPS: smoking furnace and flaming torch; фр.: tourbillon de fumée et sillon de feu. По-еврейски תַּנּוּר עָשָׁן וְלַפִּיד אֵשׁ — дымящаяся печь и огненный факел."],"genesis-15-18":["В тот день Господь заключил с Аврамом брит и сказал: «Твоему потомству Я отдал эту землю, от реки Египта до великой реки, реки Перат:","Op die dag sloot de Eeuwige een briet met Avram en zei: «Aan jouw nageslacht heb Ik dit land gegeven, van de rivier van Egypte tot de grote rivier, de rivier Perat:",""],"genesis-15-19":["кени, книззи и кадмони,","de Keni, de Kenizzi en de Kadmoni,",""],"genesis-15-20":["хеттов, перизеев и рефаим,","de Chitti, de Perizzi en de Refaïm,",""],"genesis-15-21":["эмори, кнаани, гиргаши и евусеев».","de Emori, de Kenaäniet, de Girgasji en de Jevusiet.»",""],"joshua-24-1":["Йехошуа собрал все колена Исраэля в Шехем. Он призвал старейшин Исраэля, его глав, его судей и его надзирателей, и они встали перед Богом.","Jehosjoea riep alle stammen van Israël bijeen in Sjechem. Hij riep de oudsten van Israël, zijn hoofden, zijn rechters en zijn opzieners, en zij stelden zich op voor God.",""],"joshua-24-2":["Йехошуа сказал всему народу: «Так сказал Господь, Бог Исраэля: „За Рекой издавна жили ваши отцы — Терах, отец Авраама и отец Нахора, — и служили другим богам.","Jehosjoea zei tegen heel het volk: «Zo zegt de Eeuwige, de God van Israël: „Aan de overkant van de Rivier woonden jullie vaderen van oudsher — Terach, de vader van Abraham en de vader van Nachor — en zij dienden andere goden.",""],"joshua-24-3":["Я взял вашего отца Авраама из-за Реки, водил его по всей земле Кнаан, умножил его потомство и дал ему Ицхака.","Ik nam jullie vader Abraham van de overkant van de Rivier, liet hem door heel het land Kenaän gaan, maakte zijn nageslacht talrijk en gaf hem Jitschak.",""],"joshua-24-4":["Ицхаку Я дал Яакова и Эсава. Эсаву Я дал гору Сеир, чтобы владеть ею, а Яаков и его сыновья спустились в Египет.","Aan Jitschak gaf Ik Jaäkov en Esav. Aan Esav gaf Ik het Seïr-gebergte om het in bezit te nemen, en Jaäkov en zijn kinderen daalden af naar Egypte.",""],"joshua-24-5":["Я послал Моше и Аарона и поразил Египет тем, что сделал в нём, а потом вывел вас.","Ik zond Mosje en Aharon en trof Egypte met wat Ik in zijn midden deed, en daarna leidde Ik jullie uit.",""],"joshua-24-6":["Я вывел ваших отцов из Египта, и вы пришли к морю, а египтяне погнались за вашими отцами на колесницах и на конях до Тростникового моря.","Ik leidde jullie vaderen uit Egypte, en jullie kwamen bij de zee. De Egyptenaren achtervolgden jullie vaderen met wagens en ruiters tot aan de Rietzee.","JPS: Red Sea; фр.: mer des Joncs. По-еврейски יַם־סוּף — Тростниковое море."],"joshua-24-7":["Они воззвали к Господу, и Он положил тьму между вами и египтянами, навёл на них море, и оно покрыло их. Ваши глаза видели, что Я сделал в Египте. Потом вы жили в пустыне много дней.","Zij riepen tot de Eeuwige. Hij zette duisternis tussen jullie en de Egyptenaren, bracht de zee over hen, en die bedekte hen. Jullie ogen hebben gezien wat Ik in Egypte heb gedaan. Daarna woonden jullie vele dagen in de woestijn.",""],"joshua-24-8":["Я привёл вас в землю эмори, которые жили по ту сторону Ярдена. Они воевали с вами. Я отдал их в вашу руку, вы взяли их землю, и Я истребил их перед вами.","Ik bracht jullie naar het land van de Emori, die aan de overkant van de Jarden woonden. Zij streden tegen jullie. Ik gaf hen in jullie hand, jullie namen hun land in, en Ik vaagde hen weg voor jullie uit.",""],"joshua-24-9":["Поднялся Балак, сын Циппора, царь Моава, и воевал против Исраэля. Он послал и призвал Билама, сына Беора, чтобы проклясть вас.","Toen stond Balak op, de zoon van Tsippor, koning van Moav, en streed tegen Israël. Hij liet Bilam, de zoon van Beor, roepen om jullie te vervloeken.","Во французском источнике опечатка fis вместо fils. По-еврейски בֶּן — сын."],"joshua-24-10":["Но Я не захотел слушать Билама, и он ещё благословил вас, и Я избавил вас от его руки.","Maar Ik wilde niet naar Bilam luisteren. Hij zegende jullie juist, en Ik redde jullie uit zijn hand.",""],"joshua-24-11":["Вы перешли Ярден и пришли к Йерихо. Против вас воевали хозяева Йерихо — эмори, перизеи, кнаани, хетты, гиргаши, хивви и евусеи, — и Я отдал их в вашу руку.","Jullie trokken de Jarden over en kwamen bij Jericho. De heren van Jericho streden tegen jullie: de Emori, de Perizzi, de Kenaäniet, de Chitti, de Girgasji, de Chivvi en de Jevusiet. Ik gaf hen in jullie hand.",""],"joshua-24-12":["Я послал перед вами шершней, и они прогнали их от вас — двух царей эмори, — не твоим мечом и не твоим луком.","Ik zond horzels voor jullie uit, en die dreven hen voor jullie weg, de twee koningen van de Emori, niet door jouw zwaard en niet door jouw boog.",""],"joshua-24-13":["Я дал вам землю, над которой ты не трудился, и города, которых вы не строили и в которых вы живёте. Вы едите от виноградников и олив, которых не сажали“.","Ik gaf jullie een land waar jij niet voor hebt gezwoegd, en steden die jullie niet hebben gebouwd en waar jullie wonen. Jullie eten van wijngaarden en olijfbomen die jullie niet hebben geplant.“",""],"joshua-24-14":["Теперь бойтесь Господа и служите Ему искренне и верно. Уберите богов, которым служили ваши отцы за Рекой и в Египте, и служите Господу.","Nu dan: vrees de Eeuwige en dien Hem oprecht en trouw. Doe de goden weg die jullie vaderen dienden aan de overkant van de Rivier en in Egypte, en dien de Eeuwige.",""],"joshua-24-15":["Если вам тягостно служить Господу, выберите сегодня, кому будете служить: богам, которым служили ваши отцы за Рекой, или богам эмори, в чьей земле вы живёте. А я и мой дом будем служить Господу».","Als het jullie slecht lijkt de Eeuwige te dienen, kies dan vandaag wie jullie willen dienen: de goden die jullie vaderen aan de overkant van de Rivier dienden, of de goden van de Emori in wier land jullie wonen. Maar ik en mijn huis, wij zullen de Eeuwige dienen.»",""],"joshua-24-16":["Народ ответил: «Этого не будет, чтобы мы оставили Господа и служили другим богам.","Het volk antwoordde: «Dat nooit, dat wij de Eeuwige zouden verlaten om andere goden te dienen.",""],"joshua-24-17":["Ведь Господь, наш Бог, — это Он вывел нас и наших отцов из земли Египта, из дома рабства. Он сделал у нас на глазах эти великие знамения и хранил нас на всём пути, которым мы шли, и среди всех народов, через которых мы проходили.","Want de Eeuwige, onze God, Hij is het die ons en onze vaderen uit het land Egypte heeft geleid, uit het slavenhuis. Hij heeft deze grote tekenen voor onze ogen gedaan en ons behoed op heel de weg die wij gingen, te midden van alle volken waar wij doorheen trokken.",""],"joshua-24-18":["Господь прогнал от нас все народы и эмори, жителя этой земли. Мы тоже будем служить Господу, потому что Он — наш Бог».","De Eeuwige dreef alle volken voor ons weg, en de Emori die het land bewoonde. Ook wij zullen de Eeuwige dienen, want Hij is onze God.»",""],"joshua-24-19":["Йехошуа сказал народу: «Вы не сможете служить Господу, потому что Он — святой Бог, Он — ревнивый Бог. Он не простит вашего преступления и ваших грехов.","Jehosjoea zei tegen het volk: «Jullie kunnen de Eeuwige niet dienen, want Hij is een heilige God, Hij is een jaloerse God. Hij zal jullie overtreding en jullie zonden niet vergeven.","Фр. добавляет aisément («нелегко»). В еврейском этого слова нет."],"joshua-24-20":["Если вы оставите Господа и будете служить чужим богам, Он обратится, сделает вам зло и истребит вас после того, как делал вам добро».","Als jullie de Eeuwige verlaten en vreemde goden dienen, zal Hij Zich keren, jullie kwaad doen en jullie vernietigen, nadat Hij jullie goed heeft gedaan.»",""],"joshua-24-21":["Народ сказал Йехошуа: «Нет! Мы будем служить Господу».","Het volk zei tegen Jehosjoea: «Nee! De Eeuwige zullen wij dienen.»",""],"joshua-24-22":["Йехошуа сказал народу: «Вы свидетели против самих себя, что выбрали себе Господа, чтобы служить Ему». Они сказали: «Свидетели».","Jehosjoea zei tegen het volk: «Jullie zijn getuigen tegen jezelf, dat jullie voor de Eeuwige hebben gekozen om Hem te dienen.» Zij zeiden: «Wij zijn getuigen.»",""],"joshua-24-23":["«Теперь уберите чужих богов, которые среди вас, и обратите сердце к Господу, Богу Исраэля».","«Doe nu de vreemde goden weg die bij jullie zijn, en richt jullie hart op de Eeuwige, de God van Israël.»",""],"joshua-24-24":["Народ сказал Йехошуа: «Господу, нашему Богу, мы будем служить, и Его голос будем слушать».","Het volk zei tegen Jehosjoea: «De Eeuwige, onze God, zullen wij dienen, en naar Zijn stem zullen wij luisteren.»",""],"joshua-24-25":["В тот день Йехошуа заключил с народом брит и установил ему закон и право в Шехеме.","Op die dag sloot Jehosjoea een briet met het volk en stelde voor hen een wet en een recht vast in Sjechem.",""],"joshua-24-26":["Йехошуа записал эти слова в книгу Торы Бога, взял большой камень и поставил его там, под дубом, что у святилища Господа.","Jehosjoea schreef deze woorden in het boek van de Tora van God. Hij nam een grote steen en zette die daar neer, onder de eik bij het heiligdom van de Eeuwige.",""],"genesis-19-30":["Лот поднялся из Цоара и поселился на горе, и две его дочери с ним, потому что он боялся жить в Цоаре. Он поселился в пещере, он и две его дочери.","Lot trok op uit Tsoar en ging op de berg wonen, en zijn twee dochters met hem, want hij was bang om in Tsoar te wonen. Hij ging in een grot wonen, hij en zijn twee dochters.",""],"genesis-19-31":["Старшая сказала младшей: «Наш отец стар, и нет на земле мужчины, который вошёл бы к нам, как это бывает на всей земле.","De oudste zei tegen de jongste: «Onze vader is oud, en er is geen man op de aarde die tot ons zou komen, zoals het gaat op heel de aarde.",""],"genesis-19-32":["Идём, напоим нашего отца вином и ляжем с ним, и сохраним потомство от нашего отца».","Kom, laten we onze vader wijn te drinken geven en bij hem gaan liggen, en laten we nageslacht van onze vader in leven houden.»",""],"genesis-19-33":["Они напоили своего отца вином в ту ночь. Старшая вошла и легла со своим отцом. Он не знал, когда она легла и когда встала.","Zij gaven hun vader die nacht wijn te drinken. De oudste kwam binnen en ging bij haar vader liggen. Hij wist het niet toen zij ging liggen en toen zij opstond.","JPS: knew not when she lay down; фр.: ne la reconnut point. По-еврейски לֹא־יָדַע בְּשִׁכְבָהּ — не знал, когда она легла."],"genesis-19-34":["На другой день старшая сказала младшей: «Вот, вчера ночью я легла со своим отцом. Напоим его вином и в эту ночь тоже. Войди и ляг с ним, и сохраним потомство от нашего отца».","De volgende dag zei de oudste tegen de jongste: «Kijk, vannacht heb ik bij mijn vader gelegen. Laten we hem ook deze nacht wijn te drinken geven. Ga naar binnen en ga bij hem liggen, en laten we nageslacht van onze vader in leven houden.»",""],"genesis-19-35":["В ту ночь они тоже напоили своего отца вином. Младшая встала и легла с ним. Он не знал, когда она легла и когда встала.","Ook die nacht gaven zij hun vader wijn te drinken. De jongste stond op en ging bij hem liggen. Hij wist het niet toen zij ging liggen en toen zij opstond.","JPS: knew not when; фр.: ne la reconnut point. По-еврейски לֹא־יָדַע בְּשִׁכְבָהּ וּבְקֻמָהּ — не знал, когда она легла и когда встала."],"genesis-19-36":["Обе дочери Лота зачали от своего отца.","De twee dochters van Lot werden zwanger van hun vader.",""],"genesis-19-37":["Старшая родила сына и назвала его Моав. Он отец Моава до сегодняшнего дня.","De oudste baarde een zoon en noemde hem Moav. Hij is de vader van Moav tot op deze dag.",""],"genesis-19-38":["Младшая тоже родила сына и назвала его Бен-Амми. Он отец сыновей Аммона до сегодняшнего дня.","Ook de jongste baarde een zoon en noemde hem Ben-Ammi. Hij is de vader van de zonen van Ammon tot op deze dag.",""],"genesis-20-1":["Авраам отправился оттуда в землю Негев, поселился между Кадешем и Шуром и был пришельцем в Граре.","Abraham trok van daar naar het land Negev, vestigde zich tussen Kadesj en Sjoer en was vreemdeling in Gerar.",""],"genesis-20-2":["Авраам сказал о Саре, своей жене: «Она моя сестра». Авимелех, царь Грара, послал и взял Сару.","Abraham zei van Sara, zijn vrouw: «Zij is mijn zuster.» Avimelech, de koning van Gerar, stuurde en nam Sara.",""],"genesis-20-3":["Бог пришёл к Авимелеху в ночном сне и сказал ему: «Вот, ты умрёшь из-за женщины, которую ты взял: она замужем».","God kwam tot Avimelech in een droom van de nacht en zei tegen hem: «Je zult sterven om de vrouw die je hebt genomen. Zij is de vrouw van een man.»","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-20-4":["Авимелех не приблизился к ней. Он сказал: «Владыка, неужели Ты убьёшь и праведный народ?","Avimelech was niet tot haar genaderd. Hij zei: «Heer, zult U ook een rechtvaardig volk doden?","В стихе אֲדֹנָי, не יהוה: Владыка / Heer. JPS: a righteous nation; фр.: un peuple innocent. По-еврейски גּוֹי צַדִּיק — праведный народ."],"genesis-20-5":["Разве не он сам сказал мне: „Она моя сестра“? И она сама тоже сказала: „Он мой брат“. В простоте сердца и с чистыми руками я сделал это».","Heeft hij zelf niet tegen mij gezegd: „Zij is mijn zuster“? En zij, ook zij, heeft gezegd: „Hij is mijn broer.“ In de eenvoud van mijn hart en met reine handen heb ik dit gedaan.»",""],"genesis-20-6":["Бог сказал ему во сне: «Я тоже знаю, что ты сделал это в простоте сердца, и Я удержал тебя, чтобы ты не согрешил против Меня. Поэтому Я не дал тебе прикоснуться к ней.","God zei tegen hem in de droom: «Ook Ik weet dat je dit in de eenvoud van je hart hebt gedaan, en Ik heb je ook weerhouden tegen Mij te zondigen. Daarom heb Ik je niet toegestaan haar aan te raken.",""],"genesis-20-7":["Теперь верни жену этого человека, потому что он пророк. Он помолится за тебя, и ты будешь жить. А если ты её не вернёшь, знай: ты непременно умрёшь, ты и всё, что у тебя».","Geef nu de vrouw van die man terug, want hij is een profeet. Hij zal voor je bidden, en je zult leven. Als je haar niet teruggeeft, weet dan dat je zeker zult sterven, jij en alles wat van jou is.»",""],"genesis-20-8":["Авимелех встал рано утром, позвал всех своих слуг и сказал им в уши все эти слова. Люди очень испугались.","Avimelech stond vroeg in de morgen op, riep al zijn dienaren en sprak al deze woorden in hun oren. De mannen werden zeer bang.",""],"genesis-20-9":["Авимелех позвал Авраама и сказал ему: «Что ты нам сделал? Чем я согрешил против тебя, что ты навёл на меня и на моё царство великий грех? Дела, которых не делают, ты сделал со мной».","Avimelech riep Abraham en zei tegen hem: «Wat heb je ons aangedaan? Wat heb ik tegen je misdaan, dat je over mij en over mijn koninkrijk een grote zonde hebt gebracht? Daden die men niet doet, heb je mij aangedaan.»",""],"genesis-20-10":["Авимелех сказал Аврааму: «Что ты увидел, что сделал это?»","Avimelech zei tegen Abraham: «Wat heb je gezien, dat je dit hebt gedaan?»","JPS: what sawest thou; фр.: qu'avais-tu en vue. По-еврейски מָה רָאִיתָ — что ты увидел."],"genesis-20-11":["Авраам сказал: «Я сказал: „Верно, нет страха перед Богом в этом месте, и меня убьют из-за моей жены“.","Abraham zei: «Ik zei: „Vast is er geen vrees voor God op deze plaats, en zij zullen mij doden om mijn vrouw.“",""],"genesis-20-12":["К тому же она и вправду моя сестра, дочь моего отца, только не дочь моей матери, и она стала мне женой.","Bovendien is zij werkelijk mijn zuster, de dochter van mijn vader, maar niet de dochter van mijn moeder, en zij is mijn vrouw geworden.",""],"genesis-20-13":["Когда Бог заставил меня скитаться от дома моего отца, я сказал ей: „Вот добро, которое ты сделаешь мне. Во всяком месте, куда мы придём, скажи обо мне: Он мой брат“».","Toen God mij liet rondzwerven, weg van het huis van mijn vader, zei ik tegen haar: „Dit is de goedheid die je mij zult doen. Op elke plaats waar wij komen, zeg van mij: Hij is mijn broer.“»","JPS: say of me, He is my brother; фр.: dis que je suis ton frère. По-еврейски אִמְרִי־לִי אָחִי הוּא — скажи обо мне: он мой брат."],"genesis-20-14":["Авимелех взял овец и быков, рабов и рабынь, отдал их Аврааму и вернул ему Сару, его жену.","Avimelech nam schapen en runderen, slaven en slavinnen, gaf ze aan Abraham en gaf hem Sara, zijn vrouw, terug.",""],"genesis-20-15":["Авимелех сказал: «Вот моя земля перед тобой. Живи там, где хорошо в твоих глазах».","Avimelech zei: «Hier is mijn land, voor je. Woon waar het goed is in jouw ogen.»",""],"genesis-20-16":["Саре он сказал: «Вот, я дал твоему брату тысячу серебра. Вот, это тебе покрытие глаз для всех, кто с тобой, и перед всеми ты оправдана».","Tegen Sara zei hij: «Ik heb je broer duizend zilver gegeven. Dit is voor jou een bedekking van de ogen voor allen die bij je zijn, en tegenover allen ben je in het gelijk gesteld.»","JPS: covering of the eyes, thou art righted, thy brother; фр.: voile, regarder en face, ton parent. По-еврейски כְּסוּת עֵינַיִם, וְנֹכָחַת, לְאָחִיךְ — покрытие глаз, ты оправдана, твоему брату."],"genesis-20-17":["Авраам помолился Богу, и Бог исцелил Авимелеха, его жену и его рабынь, и они рожали.","Abraham bad tot God, en God genas Avimelech, zijn vrouw en zijn slavinnen, en zij baarden.",""],"genesis-20-18":["Господь крепко закрыл всякое чрево в доме Авимелеха из-за Сары, жены Авраама.","De Eeuwige had iedere schoot in het huis van Avimelech volkomen gesloten, om Sara, de vrouw van Abraham.","JPS: the LORD; фр.: Dieu. По-еврейски יְהֹוָה — Господь."],"genesis-21-1":["Господь навестил Сару, как Он сказал, и Господь сделал Саре так, как Он говорил.","De Eeuwige bezocht Sara, zoals Hij had gezegd, en de Eeuwige deed voor Sara zoals Hij had gesproken.",""],"genesis-21-2":["Сара зачала и родила Аврааму сына в его старости, в назначенный срок, о котором говорил ему Бог.","Sara werd zwanger en baarde Abraham een zoon in zijn ouderdom, op de vastgestelde tijd waarover God tot hem gesproken had.",""],"genesis-21-3":["Авраам назвал имя своего сына, который родился у него, которого родила ему Сара, — Ицхак.","Abraham noemde de naam van zijn zoon die hem geboren was, die Sara hem gebaard had: Jitschak.",""],"genesis-21-4":["Авраам обрезал своего сына Ицхака, восьми дней от роду, как повелел ему Бог.","Abraham besneed zijn zoon Jitschak toen die acht dagen oud was, zoals God hem geboden had.",""],"genesis-21-5":["Аврааму было сто лет, когда у него родился его сын Ицхак.","Abraham was honderd jaar oud toen zijn zoon Jitschak hem geboren werd.",""],"genesis-21-6":["Сара сказала: «Бог сделал мне смех. Каждый, кто услышит, будет смеяться из-за меня».","Sara zei: «God heeft gelach voor mij gemaakt. Iedereen die het hoort, zal vanwege mij lachen.»","JPS: laughter, will laugh; фр.: félicité, félicitera. По-еврейски צְחֹק и יִצְחַק — смех, игра с именем Ицхак."],"genesis-21-7":["Она сказала: «Кто сказал бы Аврааму, что Сара кормит детей грудью? А я родила ему сына в его старости».","Zij zei: «Wie zou tegen Abraham gezegd hebben dat Sara kinderen zoogt? Ik heb hem een zoon gebaard in zijn ouderdom.»",""],"genesis-21-8":["Ребёнок вырос и был отнят от груди. Авраам устроил большой пир в день, когда Ицхака отняли от груди.","Het kind groeide op en werd gespeend. Abraham maakte een groot feest op de dag dat Jitschak gespeend werd.",""],"genesis-21-9":["Сара увидела сына Агари, египтянки, которого та родила Аврааму: он смеялся.","Sara zag de zoon van Hagar, de Egyptische, die zij Abraham gebaard had: hij lachte.","JPS: making sport; фр.: railleries. По-еврейски מְצַחֵק — смеялся, тот же корень, что имя Ицхак."],"genesis-21-10":["Она сказала Аврааму: «Прогони эту рабыню и её сына, потому что сын этой рабыни не будет наследником вместе с моим сыном, с Ицхаком».","Zij zei tegen Abraham: «Jaag deze slavin en haar zoon weg, want de zoon van deze slavin zal niet erven samen met mijn zoon, met Jitschak.»",""],"genesis-21-11":["Это было очень плохо в глазах Авраама из-за его сына.","De zaak was zeer kwalijk in de ogen van Abraham, vanwege zijn zoon.",""],"genesis-21-12":["Бог сказал Аврааму: «Пусть это не будет плохо в твоих глазах из-за мальчика и из-за твоей рабыни. Всё, что скажет тебе Сара, слушай её голос, потому что в Ицхаке тебе будет названо потомство.","God zei tegen Abraham: «Laat het niet kwalijk zijn in jouw ogen vanwege de jongen en vanwege je slavin. Luister naar haar stem in alles wat Sara tegen je zegt, want in Jitschak zal voor jou nageslacht genoemd worden.","JPS: in Isaac shall seed be called to thee; фр.: la postérité d'Isaac portera ton nom. По-еврейски בְיִצְחָק יִקָּרֵא לְךָ זָרַע — в Ицхаке тебе будет названо потомство."],"genesis-21-13":["Сына рабыни Я тоже сделаю народом, потому что он твоё потомство».","Ook de zoon van de slavin zal Ik tot een volk maken, want hij is jouw nageslacht.»",""],"genesis-21-14":["Авраам встал рано утром, взял хлеб и мех с водой, дал Агари, положив ей на плечо, и ребёнка, и отослал её. Она ушла и заблудилась в пустыне Беэр-Шевы.","Abraham stond vroeg in de morgen op, nam brood en een zak water, gaf het aan Hagar, legde het op haar schouder, en het kind, en stuurde haar weg. Zij ging en dwaalde in de woestijn van Beër-Sjeva.","JPS отделяет ребёнка от «положил на плечо»; фр. кладёт на плечо и ребёнка. По-еврейски וְאֶת־הַיֶּלֶד — отдельное дополнение к «дал»."],"genesis-21-15":["Вода в мехе кончилась, и она бросила ребёнка под один из кустов.","Het water uit de zak was op, en zij wierp het kind onder een van de struiken.","JPS: cast under shrubs; фр.: abandonna au pied d'un arbre. По-еврейски וַתַּשְׁלֵךְ תַּחַת אַחַד הַשִּׂיחִם — бросила под один из кустов."],"genesis-21-16":["Она пошла и села напротив, поодаль, на расстоянии выстрела из лука, потому что сказала: «Не видеть бы мне смерти ребёнка». Она села напротив, подняла голос и заплакала.","Zij ging weg en ging tegenover hem zitten, op een afstand van een boogschot, want zij zei: «Laat ik de dood van het kind niet zien.» Zij zat tegenover hem, verhief haar stem en weende.",""],"genesis-21-17":["Бог услышал голос мальчика. Посланник Бога воззвал к Агари с неба и сказал ей: «Что с тобой, Агар? Не бойся, потому что Бог услышал голос мальчика там, где он.","God hoorde de stem van de jongen. Een bode van God riep tot Hagar vanuit de hemel en zei tegen haar: «Wat is er met je, Hagar? Wees niet bang, want God heeft de stem van de jongen gehoord, daar waar hij is.","JPS: angel of God, the voice; фр.: messager du Seigneur, le gémissement. По-еврейски מַלְאַךְ אֱלֹהִים и קוֹל — посланник Бога и голос."],"genesis-21-18":["Встань, подними мальчика и крепко держи его своей рукой, потому что Я сделаю его великим народом».","Sta op, til de jongen op en houd hem vast met je hand, want Ik zal hem tot een groot volk maken.»",""],"genesis-21-19":["Бог открыл ей глаза, и она увидела колодец с водой. Она пошла, наполнила мех водой и напоила мальчика.","God opende haar ogen, en zij zag een put met water. Zij ging, vulde de zak met water en gaf de jongen te drinken.","JPS: God, a well; фр.: le Seigneur, une source. По-еврейски אֱלֹהִים и בְּאֵר — Бог и колодец."],"genesis-21-20":["Бог был с мальчиком, и он вырос. Он жил в пустыне и стал стрелком из лука.","God was met de jongen, en hij groeide op. Hij woonde in de woestijn en werd een boogschutter.",""],"genesis-21-21":["Он жил в пустыне Паран, и его мать взяла ему жену из земли Египта.","Hij woonde in de woestijn Paran, en zijn moeder nam voor hem een vrouw uit het land Egypte.",""],"i-samuel-1-1":["Был один человек из Раматаим-Цофим, с горы Эфраима. Имя его — Элькана, сын Йерохама, сын Элигу, сын Тоху, сын Цуфа, эфратянин.","Er was een man uit Ramatajim-Tsofim, van de berg Efrajim. Zijn naam was Elkana, zoon van Jerocham, zoon van Elihoe, zoon van Tochoe, zoon van Tsoef, een Efratiet.","JPS: an Ephraimite; фр.: un Ephratéen. По-еврейски אֶפְרָתִי — эфратянин."],"i-samuel-1-2":["У него были две жены. Одну звали Ханна, другую — Пнина. У Пнины были дети, у Ханны детей не было.","Hij had twee vrouwen. De ene heette Channa, de andere Penina. Penina had kinderen, Channa had geen kinderen.",""],"i-samuel-1-3":["Этот человек из года в год поднимался из своего города, чтобы поклониться и принести жертву Господу воинств в Шило. Там два сына Эли, Хофни и Пинхас, были священниками Господа.","Deze man ging jaar na jaar uit zijn stad op, om zich neer te buigen en te offeren aan de Eeuwige der legerscharen in Sjilo. Daar waren de twee zonen van Eli, Chofni en Pinchas, priesters van de Eeuwige.",""],"i-samuel-1-4":["Когда пришёл день, Элькана принёс жертву и дал доли Пнине, своей жене, и всем её сыновьям и дочерям.","Toen de dag kwam, bracht Elkana een offer en gaf hij porties aan Penina, zijn vrouw, en aan al haar zonen en dochters.",""],"i-samuel-1-5":["А Ханне он давал одну двойную долю, потому что любил Ханну. Господь же закрыл её чрево.","Aan Channa gaf hij één dubbele portie, want hij hield van Channa. Maar de Eeuwige had haar schoot gesloten.","JPS: a double portion; фр.: une seule portion, à son grand déplaisir. По-еврейски מָנָה אַחַת אַפָּיִם — тёмное место: одна доля, אַפָּיִם как «двойная»."],"i-samuel-1-6":["Её соперница сильно злила её, чтобы та роптала, потому что Господь закрыл её чрево.","Haar rivale tergde haar hevig, om haar te laten morren, want de Eeuwige had haar schoot gesloten.","JPS: the LORD; фр.: Dieu. По-еврейски יְהֹוָה — Господь."],"i-samuel-1-7":["Так бывало из года в год: каждый раз, когда она поднималась в дом Господа, та её злила, и она плакала и не ела.","Zo gebeurde het jaar op jaar: telkens als zij opging naar het huis van de Eeuwige, tergde de ander haar, en zij weende en at niet.",""],"i-samuel-1-8":["Элькана, её муж, сказал ей: «Ханна, почему ты плачешь? Почему ты не ешь? Почему твоё сердце печалится? Разве я не лучше тебе, чем десять сыновей?»","Elkana, haar man, zei tegen haar: «Channa, waarom huil je? Waarom eet je niet? Waarom is je hart bedroefd? Ben ik voor jou niet beter dan tien zonen?»",""],"i-samuel-1-9":["Ханна встала после еды в Шило и после питья. Эли, священник, сидел на сиденье у косяка храма Господа.","Channa stond op na het eten in Sjilo en na het drinken. Eli, de priester, zat op de zetel bij de deurpost van de tempel van de Eeuwige.","JPS: the priest; фр.: le pontife. По-еврейски הַכֹּהֵן — священник."],"i-samuel-1-10":["Она была горька душой, молилась Господу и сильно плакала.","Zij was bitter van ziel, bad tot de Eeuwige en weende hevig.",""],"i-samuel-1-11":["Она дала обет и сказала: «Господь воинств, если Ты действительно взглянешь на страдание Твоей рабы, вспомнишь меня и не забудешь Твою рабу, и дашь Твоей рабе мужское потомство, я отдам его Господу на все дни его жизни, и бритва не взойдёт ему на голову».","Zij deed een gelofte en zei: «Eeuwige der legerscharen, als U werkelijk de ellende van Uw slavin aanziet, aan mij denkt en Uw slavin niet vergeet, en aan Uw slavin mannelijk nageslacht geeft, dan geef ik hem aan de Eeuwige voor alle dagen van zijn leven, en geen scheermes zal op zijn hoofd komen.»",""],"i-samuel-1-12":["Она долго молилась перед Господом, а Эли смотрел на её рот.","Terwijl zij lang bad voor de Eeuwige, lette Eli op haar mond.",""],"i-samuel-1-13":["Ханна говорила в своём сердце: только губы её двигались, а голоса не было слышно. Эли счёл её пьяной.","Channa sprak in haar hart: alleen haar lippen bewogen, haar stem was niet te horen. Eli hield haar voor dronken.",""],"i-samuel-1-14":["Эли сказал ей: «До каких пор ты будешь пьяной? Убери от себя своё вино».","Eli zei tegen haar: «Hoe lang blijf je dronken? Doe je wijn van je weg.»","JPS: put away thy wine from thee; фр.: va cuver ton vin. По-еврейски הָסִירִי אֶת־יֵינֵךְ מֵעָלָיִךְ — убери от себя своё вино."],"i-samuel-1-15":["Ханна ответила: «Нет, господин мой, я женщина с тяжёлым духом. Вина и крепкого напитка я не пила. Я излила свою душу перед Господом.","Channa antwoordde: «Nee, mijn heer, ik ben een vrouw met een zwaar gemoed. Wijn en sterke drank heb ik niet gedronken. Ik heb mijn ziel uitgestort voor de Eeuwige.",""],"i-samuel-1-16":["Не сочти свою рабу дочерью ничтожества. От великой жалобы и досады я говорила до сих пор».","Reken je slavin niet als een dochter van niets. Door mijn vele klacht en mijn ergernis heb ik tot nu toe gesproken.»",""],"i-samuel-1-17":["Эли ответил: «Иди с миром, и Бог Исраэля даст тебе то, чего ты просила у Него».","Eli antwoordde: «Ga in vrede, en de God van Israël geve wat je Hem gevraagd hebt.»",""],"i-samuel-1-18":["Она сказала: «Пусть твоя служанка найдёт милость в твоих глазах». Женщина пошла своей дорогой, поела, и прежнего лица у неё уже не было.","Zij zei: «Laat je dienares gunst vinden in jouw ogen.» De vrouw ging haar weg, at, en haar gezicht was niet meer zoals het geweest was.","JPS добавляет sad; фр.: physionomie ne fut plus la même. По-еврейски וּפָנֶיהָ לֹא־הָיוּ־לָהּ עוֹד — прежнего лица у неё уже не было."],"i-samuel-1-19":["Они встали рано утром, поклонились Господу, вернулись и пришли в свой дом, в Раму. Элькана был с Ханной, своей женой, и Господь вспомнил её.","Zij stonden vroeg in de morgen op, bogen zich neer voor de Eeuwige, keerden terug en kwamen naar hun huis, naar Rama. Elkana sliep met Channa, zijn vrouw, en de Eeuwige herinnerde zich haar.",""],"i-samuel-1-20":["Когда дни совершили круг, Ханна зачала и родила сына, и назвала его Шмуэль: «потому что от Господа я просила его».","Toen de kring van de dagen rond was, werd Channa zwanger en baarde zij een zoon. Zij noemde hem Sjemoeël: «want van de Eeuwige heb ik hem gevraagd.»",""],"genesis-24-15":["Он ещё не кончил говорить, и вот выходит Ривка, которая родилась у Бетуэля, сына Мильки, жены Нахора, брата Авраама, и кувшин её на плече.","Hij was nog niet uitgesproken, en zie, Rivka kwam naar buiten, geboren bij Betoel, de zoon van Milka, de vrouw van Nachor, de broer van Abraham, met haar kruik op haar schouder.",""],"genesis-24-16":["Девушка была очень красива на вид, девственница, и ни один мужчина не был с ней. Она спустилась к источнику, наполнила свой кувшин и поднялась.","Het meisje was heel mooi om te zien, een maagd, en geen man had met haar geslapen. Zij daalde af naar de bron, vulde haar kruik en kwam weer boven.","JPS: neither had any man known her; фр.: nul homme n'avait approché d'elle. По-еврейски לֹא יְדָעָהּ — ни один мужчина не был с ней."],"genesis-24-17":["Слуга побежал ей навстречу и сказал: «Дай мне, прошу, глотнуть немного воды из твоего кувшина».","De dienaar snelde haar tegemoet en zei: «Laat mij, alsjeblieft, een beetje water drinken uit jouw kruik.»",""],"genesis-24-18":["Она сказала: «Пей, господин мой». Она поспешила, спустила кувшин на руку и напоила его.","Zij zei: «Drink, mijn heer.» Zij haastte zich, liet haar kruik op haar hand zakken en gaf hem te drinken.",""],"genesis-24-19":["Когда она напоила его, она сказала: «Я начерпаю и твоим верблюдам, пока они не кончат пить».","Toen zij hem te drinken had gegeven, zei zij: «Ook voor jouw kamelen zal ik putten, totdat zij klaar zijn met drinken.»",""],"genesis-24-20":["Она поспешила, вылила кувшин в поилку, снова побежала к колодцу черпать и начерпала всем его верблюдам.","Zij haastte zich, leegde haar kruik in de drinkbak, rende weer naar de put om te putten en putte voor al zijn kamelen.","JPS: the well; фр.: la fontaine. По-еврейски הַבְּאֵר — колодец."],"genesis-24-21":["Человек смотрел на неё в изумлении и молчал, чтобы узнать, дал ли Господь успех его пути или нет.","De man keek haar verwonderd aan en zweeg, om te weten of de Eeuwige zijn weg had doen slagen of niet.",""],"genesis-24-22":["Когда верблюды напились, человек взял золотое кольцо весом в бека и два браслета для её рук, весом в десять золота.","Toen de kamelen gedronken hadden, nam de man een gouden ring, een beka zwaar, en twee armbanden voor haar armen, tien goud in gewicht.","JPS: half a shekel; фр.: un béka. По-еврейски בֶּקַע — бека."],"genesis-24-23":["Он сказал: «Чья ты дочь? Скажи мне, прошу. Есть ли в доме твоего отца место нам переночевать?»","Hij zei: «Van wie ben jij de dochter? Zeg het mij, alsjeblieft. Is er in het huis van je vader plaats voor ons om te overnachten?»",""],"genesis-24-24":["Она сказала ему: «Я дочь Бетуэля, сына Мильки, которого она родила Нахору».","Zij zei tegen hem: «Ik ben de dochter van Betoel, de zoon van Milka, die zij aan Nachor gebaard heeft.»",""],"genesis-24-25":["Она сказала ему: «Есть у нас и солома, и корма вдоволь, и место переночевать».","Zij zei tegen hem: «Wij hebben zowel stro als voer in overvloed, en ook plaats om te overnachten.»",""],"genesis-24-26":["Человек склонился и пал ниц перед Господом.","De man boog zich en wierp zich neer voor de Eeuwige.",""],"genesis-24-27":["Он сказал: «Благословен Господь, Бог моего господина Авраама, который не отнял у моего господина Своё добро и Свою верность. Меня Господь по пути привёл к дому братьев моего господина».","Hij zei: «Gezegend is de Eeuwige, de God van mijn heer Abraham, die Zijn goedheid en Zijn trouw niet aan mijn heer heeft onttrokken. Mij heeft de Eeuwige op de weg geleid naar het huis van de broers van mijn heer.»","Фр. обрывает стих на mon maître и пишет Il с заглавной. Дальше в еврейском говорит человек: меня Господь привёл к дому братьев моего господина."],"genesis-24-28":["Девушка побежала и рассказала в доме своей матери эти слова.","Het meisje rende weg en vertelde in het huis van haar moeder deze woorden.","JPS: her mother's house; фр.: la chambre de sa mère. По-еврейски לְבֵית אִמָּהּ — в дом своей матери."],"genesis-24-29":["У Ривки был брат, его звали Лаван. Лаван побежал к человеку наружу, к источнику.","Rivka had een broer, zijn naam was Lavan. Lavan rende naar de man toe, naar buiten, naar de bron.",""],"genesis-24-30":["Когда он увидел кольцо и браслеты на руках своей сестры и услышал слова своей сестры Ривки: «Так сказал мне этот человек», он подошёл к человеку. И вот, тот стоял у верблюдов при источнике.","Toen hij de ring zag en de armbanden aan de armen van zijn zuster, en de woorden hoorde van zijn zuster Rivka: «Zo heeft die man tegen mij gesproken», ging hij naar de man. En zie, die stond bij de kamelen bij de bron.",""],"genesis-24-31":["Он сказал: «Войди, благословенный Господом. Зачем ты стоишь снаружи? Я освободил дом и место для верблюдов».","Hij zei: «Kom binnen, gezegende van de Eeuwige. Waarom blijf je buiten staan? Ik heb het huis vrijgemaakt, en er is plaats voor de kamelen.»","JPS: blessed of the LORD; фр.: bien-aimé du Seigneur. По-еврейски בְּרוּךְ יְהֹוָה — благословенный Господом."],"genesis-24-32":["Человек вошёл в дом и развьючил верблюдов. Он дал солому и корм верблюдам и воду, чтобы омыть свои ноги и ноги людей, которые были с ним.","De man kwam het huis binnen en laadde de kamelen af. Hij gaf stro en voer voor de kamelen, en water om zijn voeten te wassen en de voeten van de mannen die bij hem waren.","JPS: he gave; фр.: on apporta. Подлежащее וַיִּתֵּן не названо отдельно."],"genesis-24-33":["Перед ним поставили есть. Он сказал: «Не буду есть, пока не скажу свои слова». Тот сказал: «Говори».","Er werd eten voor hem neergezet. Hij zei: «Ik eet niet, totdat ik mijn woorden heb gesproken.» De ander zei: «Spreek.»",""],"genesis-24-34":["Он сказал: «Я слуга Авраама.","Hij zei: «Ik ben de dienaar van Abraham.",""],"genesis-24-35":["Господь очень благословил моего господина, и тот стал велик. Он дал ему овец и быков, серебро и золото, рабов и рабынь, верблюдов и ослов.","De Eeuwige heeft mijn heer zeer gezegend, en hij is groot geworden. Hij heeft hem schapen en runderen gegeven, zilver en goud, slaven en slavinnen, kamelen en ezels.",""],"genesis-24-36":["Сара, жена моего господина, родила моему господину сына после своей старости, и он отдал ему всё, что у него есть.","Sara, de vrouw van mijn heer, heeft mijn heer een zoon gebaard na haar ouderdom, en hij heeft hem alles gegeven wat hij heeft.",""],"genesis-24-37":["Мой господин взял с меня клятву, сказав: „Не бери жену моему сыну из дочерей кнаани, в чьей земле я живу.","Mijn heer heeft mij een eed laten zweren: „Neem voor mijn zoon geen vrouw uit de dochters van de Kenaäniet, in wiens land ik woon.",""],"genesis-24-38":["Нет: к дому моего отца ты пойдёшь и к моему роду, и возьмёшь жену моему сыну“.","Nee: naar het huis van mijn vader zul je gaan en naar mijn familie, en daar zul je een vrouw voor mijn zoon nemen.“",""],"genesis-24-39":["Я сказал своему господину: „Может быть, женщина не пойдёт за мной“.","Ik zei tegen mijn heer: „Misschien gaat de vrouw niet met mij mee.“",""],"genesis-24-40":["Он сказал мне: „Господь, перед которым я хожу, пошлёт с тобой Своего посланника, даст успех твоему пути, и ты возьмёшь жену моему сыну из моего рода и из дома моего отца.","Hij zei tegen mij: „De Eeuwige, voor wie ik gewandeld heb, zal Zijn bode met je meesturen, je weg doen slagen, en je zult een vrouw voor mijn zoon nemen uit mijn familie en uit het huis van mijn vader.","JPS: His angel; фр.: son envoyé. По-еврейски מַלְאָכוֹ — Его посланник."],"genesis-24-41":["Тогда ты будешь свободен от моей клятвы, когда придёшь к моему роду. Если же тебе её не отдадут, ты будешь чист от моей клятвы“.","Dan zul je vrij zijn van mijn eed, wanneer je bij mijn familie komt. En als zij haar niet aan je geven, zul je vrij zijn van mijn eed.“",""],"genesis-24-42":["Сегодня я пришёл к источнику и сказал: „Господь, Бог моего господина Авраама, если Ты дашь, прошу, успех моему пути, которым я иду:","Vandaag kwam ik bij de bron en zei: „Eeuwige, God van mijn heer Abraham, als U alstublieft mijn weg doet slagen, de weg die ik ga:",""],"genesis-24-43":["вот, я стою у источника воды, и пусть будет: молодая женщина выйдет черпать, и я скажу ей: дай мне, прошу, немного воды из твоего кувшина,","zie, ik sta bij de waterbron. Laat het gebeuren dat de jonge vrouw die komt putten, en tegen wie ik zeg: geef mij, alsjeblieft, een beetje water uit jouw kruik,",""],"genesis-24-44":["и она скажет мне: пей и ты, и твоим верблюдам я тоже начерпаю, — пусть она будет той женщиной, которую Господь определил сыну моего господина“.","en zij tegen mij zegt: drink ook jij, en ook voor jouw kamelen zal ik putten, — laat haar de vrouw zijn die de Eeuwige heeft aangewezen voor de zoon van mijn heer.“","JPS: appointed; фр.: agrée. По-еврейски הֹכִיחַ — определил."],"genesis-24-45":["Я ещё не кончил говорить в своём сердце, и вот выходит Ривка, и кувшин её на плече. Она спустилась к источнику и начерпала. Я сказал ей: „Напой меня, прошу“.","Ik was nog niet uitgesproken in mijn hart, en zie, Rivka kwam naar buiten, haar kruik op haar schouder. Zij daalde af naar de bron en putte. Ik zei tegen haar: „Laat mij drinken, alsjeblieft.“",""],"genesis-24-46":["Она поспешила, спустила с себя кувшин и сказала: „Пей, и твоих верблюдов я тоже напою“. Я пил, и верблюдов она тоже напоила.","Zij haastte zich, liet haar kruik van zich af zakken en zei: „Drink, en ook je kamelen zal ik te drinken geven.“ Ik dronk, en ook de kamelen gaf zij te drinken.","Во французском нет конца стиха: וָאֵשְׁתְּ וְגַם הַגְּמַלִּים הִשְׁקָתָה — я пил, и верблюдов она напоила."],"genesis-24-47":["Я спросил её и сказал: „Чья ты дочь?“ Она сказала: „Дочь Бетуэля, сына Нахора, которого родила ему Милька“. Я надел кольцо ей на нос и браслеты ей на руки.","Ik vroeg haar en zei: „Van wie ben jij de dochter?“ Zij zei: „De dochter van Betoel, de zoon van Nachor, die Milka hem gebaard heeft.“ Ik deed de ring aan haar neus en de armbanden aan haar armen.",""],"genesis-24-48":["Я склонился и пал ниц перед Господом и благословил Господа, Бога моего господина Авраама, который вёл меня путём истины, чтобы взять дочь брата моего господина его сыну.","Ik boog mij en wierp mij neer voor de Eeuwige, en ik zegende de Eeuwige, de God van mijn heer Abraham, die mij op de weg van waarheid heeft geleid om de dochter van de broer van mijn heer te nemen voor zijn zoon.","JPS: my master's brother's daughter; фр.: la parente de mon maître. По-еврейски בַּת־אֲחִי אֲדֹנִי — дочь брата моего господина."],"genesis-24-49":["Теперь, если вы делаете добро и верность моему господину, скажите мне. Если нет, скажите мне, и я поверну направо или налево».","Nu dan, als jullie goedheid en trouw bewijzen aan mijn heer, zeg het mij. Zo niet, zeg het mij, zodat ik naar rechts of naar links kan gaan.»",""],"genesis-24-50":["Лаван и Бетуэль ответили: «От Господа вышло это дело. Мы не можем сказать тебе ни дурного, ни доброго.","Lavan en Betoel antwoordden: «Van de Eeuwige is deze zaak uitgegaan. Wij kunnen je niets kwaads of goeds zeggen.","JPS: from the LORD; фр.: de Dieu. По-еврейски מֵיְהֹוָה — от Господа."],"genesis-24-51":["Вот Ривка перед тобой. Возьми и иди, и пусть она будет женой сыну твоего господина, как сказал Господь».","Hier is Rivka voor je. Neem haar en ga, en laat haar een vrouw zijn voor de zoon van jouw heer, zoals de Eeuwige gesproken heeft.»",""],"genesis-24-52":["Когда слуга Авраама услышал их слова, он пал ниц на землю перед Господом.","Toen de dienaar van Abraham hun woorden hoorde, wierp hij zich ter aarde voor de Eeuwige.",""],"proverbs-31-10":["Доблестную жену кто найдёт? Её цена далеко выше жемчуга.","Een vrouw van kracht, wie zal haar vinden? Haar waarde ligt ver boven parels.","JPS: rubies; фр.: perles. По-еврейски פְּנִינִים — жемчуг."],"proverbs-31-11":["Сердце её мужа доверяет ей, и в добыче у него нет недостатка.","Het hart van haar man vertrouwt op haar, en aan buit ontbreekt het hem niet.","JPS: gain; фр.: ressources. По-еврейски שָׁלָל — добыча."],"proverbs-31-12":["Она воздаёт ему добром, а не злом, все дни своей жизни.","Zij doet hem goed en geen kwaad, alle dagen van haar leven.","JPS: good and not evil; фр.: bonheur, ne lui cause pas de peine. По-еврейски טוֹב וְלֹא־רָע — добро, а не зло."],"proverbs-31-13":["Она ищет шерсть и лён и работает с охотой своих рук.","Zij zoekt wol en vlas en werkt met de lust van haar handen.",""],"proverbs-31-14":["Она — как купеческие корабли, издалека привозит свой хлеб.","Zij is als koopvaardijschepen, van verre brengt zij haar brood.",""],"proverbs-31-15":["Она встаёт ещё ночью, даёт добычу своему дому и долю своим служанкам.","Zij staat op terwijl het nog nacht is, geeft prooi aan haar huis en een vast deel aan haar dienaressen.","JPS: food; фр.: vivres. По-еврейски טֶרֶף — добыча."],"proverbs-31-16":["Она задумала поле и взяла его. Плодом своих рук она посадила виноградник.","Zij neemt een akker in overweging en verwerft hem. Van de vrucht van haar handen plant zij een wijngaard.",""],"proverbs-31-17":["Она опоясывает силой свои бёдра и укрепляет свои руки.","Zij gordt haar lendenen met kracht en maakt haar armen sterk.",""],"proverbs-31-18":["Она вкусила, что хорош её товар. В ночи её светильник не гаснет.","Zij proeft dat haar koopwaar goed is. Haar lamp gaat in de nacht niet uit.","JPS: perceiveth; фр.: s'assure. По-еврейски טָעֲמָה — вкусила."],"proverbs-31-19":["Она протягивает руки к гребню, и ладони её держат веретено.","Zij strekt haar handen uit naar de spinrok, en haar handpalmen houden de spil.","JPS: distaff; фр.: rouet. По-еврейски כִּישׁוֹר — гребень пряхи, не колесо."],"proverbs-31-20":["Ладонь свою она открывает бедному, и руки свои протягивает нищему.","Haar handpalm opent zij voor de arme, en haar handen strekt zij uit naar de behoeftige.",""],"proverbs-31-21":["Она не боится снега для своего дома, потому что весь её дом одет в багрянец.","Zij vreest de sneeuw niet voor haar huis, want heel haar huis is in scharlaken gekleed.","JPS: scarlet; фр.: riches étoffes. По-еврейски שָׁנִים — багрянец, либо «вдвойне»."],"proverbs-31-22":["Покрывала она сделала себе. Тонкий лён и пурпур — её одежда.","Spreien maakt zij voor zichzelf. Fijn linnen en purper zijn haar kleding.","JPS: coverlets; фр.: tapis, и добавляет se brode. По-еврейски מַרְבַדִּים — покрывала, без «вышивает»."],"proverbs-31-23":["Её муж известен в воротах, когда сидит со старейшинами земли.","Haar man is bekend in de poorten, als hij zit met de oudsten van het land.",""],"proverbs-31-24":["Льняное полотно она сделала и продала, и пояс отдала купцу.","Linnen maakte zij en verkocht het, en een gordel gaf zij aan de koopman.",""],"proverbs-31-25":["Сила и достоинство — её одежда, и она смеётся над грядущим днём.","Kracht en waardigheid zijn haar kleding, en zij lacht om de komende dag.",""],"proverbs-31-26":["Свой рот она открывает с мудростью, и Тора доброты на её языке.","Haar mond opent zij met wijsheid, en de Tora van goedheid is op haar tong.","JPS: the law of kindness; фр.: des leçons de bonté. По-еврейски תּוֹרַת־חֶסֶד — Тора доброты."],"proverbs-31-27":["Она смотрит за путями своего дома и не ест хлеб праздности.","Zij houdt de wegen van haar huis in het oog en eet niet het brood van ledigheid.",""],"proverbs-31-28":["Встают её сыновья и называют её счастливой. Её муж — и он хвалит её:","Haar zonen staan op en noemen haar gelukkig. Haar man, en hij prijst haar:",""],"proverbs-31-29":["«Многие дочери явили доблесть, а ты поднялась выше всех их».","«Veel dochters hebben kracht getoond, maar jij stijgt uit boven hen allen.»",""],"proverbs-31-30":["Прелесть — ложь, и красота — пар. Женщина, боящаяся Господа, она будет восхвалена.","Bevalligheid is leugen, en schoonheid is een zucht. Een vrouw die de Eeuwige vreest, zij zal geprezen worden.",""],"proverbs-31-31":["Дайте ей от плода её рук, и пусть дела её хвалят её в воротах.","Jullie, geef haar van de vrucht van haar handen, en laten haar werken haar prijzen in de poorten.",""],"genesis-26-13":["Этот человек богател и всё богател, пока не стал очень богат.","De man werd rijk en bleef rijker worden, tot hij zeer rijk was.",""],"genesis-26-14":["У него были стада овец и коз, стада крупного скота и много работников, и Плиштим завидовали ему.","Hij had kudden schapen en geiten, kudden runderen en veel knechten, en de Pelisjtim waren jaloers op hem.","JPS: a great household; фр.: cultures considérables. По-еврейски עֲבֻדָּה — работа, здесь работники."],"genesis-26-15":["Все колодцы, которые выкопали слуги его отца в дни Авраама, его отца, Плиштим засыпали и наполнили землёй.","Alle putten die de knechten van zijn vader hadden gegraven in de dagen van zijn vader Abraham, stopten de Pelisjtim dicht en vulden ze met aarde.",""],"genesis-26-16":["Авимелех сказал Ицхаку: «Уйди от нас, потому что ты стал гораздо могущественнее нас».","Avimelech zei tegen Jitschak: «Ga bij ons weg, want je bent veel machtiger geworden dan wij.»",""],"genesis-26-17":["Ицхак ушёл оттуда, остановился в долине Грара и поселился там.","Jitschak trok daarvandaan, sloeg zijn kamp op in het dal van Gerar en woonde daar.",""],"genesis-26-18":["Ицхак снова выкопал колодцы с водой, которые выкопали во дни Авраама, его отца. Плиштим засыпали их после смерти Авраама. Он дал им те имена, которыми назвал их его отец.","Jitschak groef opnieuw de waterputten die men in de dagen van zijn vader Abraham had gegraven. De Pelisjtim hadden ze na de dood van Abraham dichtgestopt. Hij gaf ze de namen die zijn vader ze had gegeven.",""],"genesis-26-19":["Слуги Ицхака копали в долине и нашли там колодец живой воды.","De knechten van Jitschak groeven in het dal en vonden daar een put met levend water.","JPS: a well of living water; фр.: une source d’eau vive. По-еврейски בְּאֵר מַיִם חַיִּים — колодец живой воды."],"genesis-26-20":["Пастухи Грара стали спорить с пастухами Ицхака и говорили: «Вода наша». Он назвал колодец Эсек, потому что они спорили с ним.","De herders van Gerar twistten met de herders van Jitschak en zeiden: «Het water is van ons.» Hij noemde de put Esek, omdat zij met hem twistten.",""],"genesis-26-21":["Они выкопали другой колодец, и из-за него тоже спорили. Он назвал его Ситна.","Zij groeven een andere put, en ook daarover twistten zij. Hij noemde die Sitna.",""],"genesis-26-22":["Он перешёл оттуда и выкопал другой колодец, и из-за него не спорили. Он назвал его Реховот и сказал: «Теперь Господь дал нам простор, и мы будем плодиться на этой земле».","Hij trok daarvandaan en groef een andere put, en daarover twistten zij niet. Hij noemde die Rechovot en zei: «Nu heeft de Eeuwige ons ruimte gegeven, en wij zullen vruchtbaar zijn in het land.»",""],"genesis-26-23":["Оттуда он поднялся в Беэр-Шеву.","Vandaar trok hij op naar Beër-Sjeva.",""],"genesis-26-24":["В ту ночь ему явился Господь и сказал: «Я — Бог Авраама, твоего отца. Не бойся, потому что Я с тобой. Я благословлю тебя и умножу твоё потомство ради Авраама, Моего слуги».","Die nacht verscheen de Eeuwige aan hem en zei: «Ik ben de God van Abraham, je vader. Wees niet bang, want Ik ben met je. Ik zal je zegenen en je nageslacht talrijk maken omwille van Abraham, Mijn dienaar.»",""],"genesis-26-25":["Он построил там жертвенник, воззвал к имени Господа, поставил там свой шатёр, и там слуги Ицхака выкопали колодец.","Hij bouwde daar een altaar, riep de naam van de Eeuwige aan, zette daar zijn tent op, en daar groeven de knechten van Jitschak een put.",""],"genesis-26-26":["Авимелех пришёл к нему из Грара, и Ахузат, его друг, и Пихоль, начальник его войска.","Avimelech kwam vanuit Gerar naar hem toe, met Achoezat, zijn vriend, en Pichol, de bevelhebber van zijn leger.",""],"genesis-26-27":["Ицхак сказал им: «Зачем вы пришли ко мне? Вы ненавидите меня и отослали меня от себя».","Jitschak zei tegen hen: «Waarom zijn jullie naar mij gekomen? Jullie haten mij en hebben mij van jullie weggestuurd.»",""],"genesis-26-28":["Они сказали: «Мы ясно увидели, что Господь с тобой, и мы сказали: пусть будет клятва между нами, между нами и тобой, и заключим с тобой брит,","Zij zeiden: «Wij hebben duidelijk gezien dat de Eeuwige met je is, en wij zeiden: laat er een eed zijn tussen ons, tussen ons en jou, en laten wij een briet met je sluiten,","JPS: an oath; фр.: un engagement réciproque. По-еврейски אָלָה — клятва."],"genesis-26-29":["что ты не сделаешь нам зла, как мы тебя не тронули и как мы делали тебе только добро и отпустили тебя с миром. Теперь ты благословен Господом».","dat je ons geen kwaad zult doen, zoals wij jou niet hebben aangeraakt en zoals wij jou alleen goed hebben gedaan en jou in vrede hebben weggestuurd. Jij bent nu door de Eeuwige gezegend.»","JPS: thou art now the blessed; фр.: sois béni. По-еврейски אַתָּה עַתָּה בְּרוּךְ יְהֹוָה — ты теперь благословен Господом."],"genesis-26-30":["Он устроил им пир, и они ели и пили.","Hij richtte een maaltijd voor hen aan, en zij aten en dronken.",""],"genesis-26-31":["Утром они встали рано и поклялись друг другу. Ицхак отпустил их, и они ушли от него с миром.","Vroeg in de morgen stonden zij op en zwoeren elkaar een eed. Jitschak liet hen gaan, en zij gingen in vrede van hem weg.","JPS: in peace; фр.: amicalement. По-еврейски בְּשָׁלוֹם — с миром."],"genesis-26-32":["В тот же день пришли слуги Ицхака, рассказали ему о колодце, который выкопали, и сказали ему: «Мы нашли воду».","Diezelfde dag kwamen de knechten van Jitschak, vertelden hem over de put die zij hadden gegraven, en zeiden tegen hem: «Wij hebben water gevonden.»",""],"genesis-26-33":["Он назвал её Шива. Поэтому имя города — Беэр-Шева до сего дня.","Hij noemde die Sjiva. Daarom is de naam van de stad Beër-Sjeva tot op deze dag.",""],"genesis-26-34":["Эсаву было сорок лет, и он взял в жёны Йегудит, дочь Беэри, хетта, и Басемат, дочь Эйлона, хетта.","Esav was veertig jaar en nam tot vrouw Jehoedit, de dochter van Beëri de Chitti, en Basemat, de dochter van Elon de Chitti.",""],"genesis-26-35":["Они были горечью духа для Ицхака и Ривки.","Zij werden een bitterheid van geest voor Jitschak en Rivka.",""],"genesis-27-1":["Ицхак состарился, и глаза его ослабели, так что он не видел. Он позвал Эсава, своего старшего сына, и сказал ему: «Сын мой». Тот сказал ему: «Вот я».","Toen Jitschak oud was geworden en zijn ogen dof waren, zodat hij niet zien kon, riep hij Esav, zijn oudste zoon, en zei tegen hem: «Mijn zoon.» Hij zei tegen hem: «Hier ben ik.»",""],"genesis-27-2":["Он сказал: «Вот, я состарился, я не знаю дня моей смерти.","Hij zei: «Zie, ik ben oud geworden, ik weet de dag van mijn dood niet.",""],"genesis-27-3":["Теперь возьми своё оружие, свой колчан и свой лук, выйди в поле и налови мне дичи.","Neem nu je wapens, je pijlkoker en je boog, ga het veld in en jaag wild voor mij.",""],"genesis-27-4":["Приготовь мне вкусное блюдо, какое я люблю, принеси мне, и я поем, чтобы моя душа благословила тебя, прежде чем я умру».","Maak voor mij een smakelijk gerecht, zoals ik het graag heb, breng het mij, en ik zal eten, zodat mijn ziel je zegent voordat ik sterf.»","JPS: my soul; фр.: mon cœur. По-еврейски נַפְשִׁי — моя душа."],"genesis-27-5":["Ривка слышала, как Ицхак говорил Эсаву, своему сыну. Эсав пошёл в поле охотиться на дичь, чтобы принести её.","Rivka hoorde hoe Jitschak sprak tegen Esav, zijn zoon. Esav ging het veld in om wild te jagen en het te brengen.",""],"genesis-27-6":["Ривка сказала Яакову, своему сыну: «Вот, я слышала, как твой отец говорил Эсаву, твоему брату:","Rivka zei tegen Jaäkov, haar zoon: «Hoor, ik heb gehoord hoe je vader tegen Esav, je broer, zei:",""],"genesis-27-7":["„Принеси мне дичь и приготовь мне вкусное блюдо, я поем и благословлю тебя перед Господом перед моей смертью“.","„Breng mij wild en maak voor mij een smakelijk gerecht, dan zal ik eten en je zegenen voor de Eeuwige, vóór mijn dood“.",""],"genesis-27-8":["Теперь, сын мой, послушай мой голос, то, что я тебе велю.","Nu, mijn zoon, luister naar mijn stem, naar wat ik je opdraag.",""],"genesis-27-9":["Пойди к стаду и возьми мне оттуда двух хороших козлят, и я приготовлю из них твоему отцу вкусное блюдо, какое он любит.","Ga naar de kudde en haal mij daarvandaan twee goede geitenbokjes. Ik maak daar voor je vader een smakelijk gerecht van, zoals hij het graag heeft.",""],"genesis-27-10":["Ты принесёшь это отцу, он поест, и он благословит тебя перед смертью».","Jij brengt het naar je vader, hij zal eten, en hij zal je zegenen vóór zijn dood.»",""],"genesis-27-11":["Яаков сказал Ривке, своей матери: «Эсав, мой брат, человек волосатый, а я человек гладкий.","Jaäkov zei tegen Rivka, zijn moeder: «Esav, mijn broer, is een behaarde man, en ik ben een gladde man.",""],"genesis-27-12":["Может быть, отец ощупает меня, и я буду в его глазах как тот, кто его морочит, и навлеку на себя проклятие, а не благословение».","Misschien betast mijn vader mij, en dan lijk ik in zijn ogen iemand die hem voor de gek houdt, en breng ik een vloek over mij, en geen zegen.»","JPS: a mocker; фр.: un trompeur. По-еврейски כִּמְתַעְתֵּעַ — как тот, кто морочит."],"genesis-27-13":["Мать сказала ему: «На мне твоё проклятие, сын мой. Только послушай мой голос, пойди и возьми мне их».","Zijn moeder zei tegen hem: «Op mij je vloek, mijn zoon. Luister alleen naar mijn stem, ga en haal ze voor mij.»",""],"genesis-27-14":["Он пошёл, взял и принёс матери, и мать приготовила вкусное блюдо, какое любил его отец.","Hij ging, nam en bracht het naar zijn moeder, en zijn moeder maakte een smakelijk gerecht, zoals zijn vader het graag had.",""],"genesis-27-15":["Ривка взяла лучшие одежды Эсава, своего старшего сына, которые были у неё в доме, и одела Яакова, своего младшего сына.","Rivka nam de mooiste kleren van Esav, haar oudste zoon, die bij haar in huis waren, en trok ze Jaäkov, haar jongste zoon, aan.",""],"genesis-27-16":["Шкурами козлят она обтянула его руки и гладкое место на шее.","De huiden van de geitenbokjes deed zij om zijn handen en om het gladde van zijn hals.",""],"genesis-27-17":["Она дала вкусное блюдо и хлеб, которые приготовила, в руки Яакова, своего сына.","Zij gaf het smakelijke gerecht en het brood dat zij had gemaakt in de hand van Jaäkov, haar zoon.",""],"genesis-27-18":["Он вошёл к отцу и сказал: «Отец мой». Тот сказал: «Вот я. Кто ты, сын мой?»","Hij kwam bij zijn vader en zei: «Mijn vader.» Die zei: «Hier ben ik. Wie ben jij, mijn zoon?»",""],"genesis-27-19":["Яаков сказал отцу: «Я — Эсав, твой первенец. Я сделал, как ты мне сказал. Встань, прошу, сядь и поешь моей дичи, чтобы твоя душа благословила меня».","Jaäkov zei tegen zijn vader: «Ik ben Esav, je eerstgeborene. Ik heb gedaan zoals je mij gezegd hebt. Sta op, ga zitten en eet van mijn wild, zodat je ziel mij zegent.»","JPS: thy soul; фр.: ton cœur. По-еврейски נַפְשֶׁךָ — твоя душа."],"genesis-27-20":["Ицхак сказал сыну: «Как это ты так быстро нашёл, сын мой?» Тот сказал: «Господь, твой Бог, послал мне навстречу».","Jitschak zei tegen zijn zoon: «Hoe heb je het zo snel gevonden, mijn zoon?» Hij zei: «De Eeuwige, je God, heeft het mij doen tegenkomen.»","JPS: sent me good speed; фр.: bonne chance. По-еврейски הִקְרָה לְפָנָי — послал мне навстречу."],"genesis-27-21":["Ицхак сказал Яакову: «Подойди, я ощупаю тебя, сын мой: ты ли это мой сын Эсав или нет?»","Jitschak zei tegen Jaäkov: «Kom dichterbij, dan betast ik je, mijn zoon, of jij werkelijk mijn zoon Esav bent of niet?»",""],"genesis-27-22":["Яаков подошёл к Ицхаку, своему отцу. Тот ощупал его и сказал: «Голос — голос Яакова, а руки — руки Эсава».","Jaäkov kwam dicht bij Jitschak, zijn vader. Die betastte hem en zei: «De stem is de stem van Jaäkov, maar de handen zijn de handen van Esav.»",""],"genesis-27-23":["Он не узнал его, потому что руки его были волосатые, как руки Эсава, его брата, и благословил его.","Hij herkende hem niet, want zijn handen waren behaard als de handen van Esav, zijn broer, en hij zegende hem.",""],"genesis-27-24":["Он сказал: «Ты и есть мой сын Эсав?» Тот сказал: «Я».","Hij zei: «Ben jij werkelijk mijn zoon Esav?» Hij zei: «Ik ben het.»",""],"genesis-27-25":["Он сказал: «Подай мне, я поем дичи моего сына, чтобы моя душа благословила тебя». Тот подал ему, и он ел. Он принёс ему вина, и он пил.","Hij zei: «Breng het bij mij, dan eet ik van het wild van mijn zoon, zodat mijn ziel je zegent.» Hij bracht het bij hem, en hij at. Hij bracht hem wijn, en hij dronk.","JPS: my soul; фр.: mon cœur. По-еврейски נַפְשִׁי — моя душа."],"genesis-27-26":["Ицхак, его отец, сказал ему: «Подойди и поцелуй меня, сын мой».","Jitschak, zijn vader, zei tegen hem: «Kom dichterbij en kus mij, mijn zoon.»",""],"genesis-27-27":["Он подошёл и поцеловал его. Тот вдохнул запах его одежды, благословил его и сказал: «Вот, запах моего сына — как запах поля, которое благословил Господь.","Hij kwam dichtbij en kuste hem. Die rook de geur van zijn kleren, zegende hem en zei: «Zie, de geur van mijn zoon is als de geur van een veld dat de Eeuwige heeft gezegend.",""],"i-kings-1-32":["Царь Давид сказал: «Позовите ко мне Цадока, священника, Натана, пророка, и Бенаягу, сына Йегояды». Они пришли к царю.","Koning David zei: «Roep Tsadok, de priester, Natan, de profeet, en Benajaoe, de zoon van Jehojada, bij mij.» Zij kwamen voor de koning.",""],"i-kings-1-33":["Царь сказал им: «Возьмите с собой слуг вашего господина, посадите моего сына Шломо на моего мула и сведите его к Гихону.","De koning zei tegen hen: «Neem de dienaren van jullie heer met jullie mee, zet mijn zoon Sjlomo op mijn eigen muildier en breng hem omlaag naar Gichon.",""],"i-kings-1-34":["Там Цадок, священник, и Натан, пророк, помажут его царём над Исраэлем. Затрубите в шофар и скажите: „Да живёт царь Шломо“.","Daar zullen Tsadok, de priester, en Natan, de profeet, hem zalven tot koning over Israël. Blaas op de sjofar en zeg: „Leve koning Sjlomo“.",""],"i-kings-1-35":["Потом поднимитесь за ним. Он придёт, сядет на мой престол и будет царствовать вместо меня. Его я назначил правителем над Исраэлем и над Йегудой».","Daarna trekken jullie achter hem op. Hij zal komen, op mijn troon gaan zitten en in mijn plaats regeren. Hem heb ik aangesteld als vorst over Israël en over Jehoeda.»","JPS: prince; фр.: chef. По-еврейски נָגִיד — назначенный правитель."],"i-kings-1-36":["Бенаягу, сын Йегояды, ответил царю: «Амен. Так пусть скажет Господь, Бог моего господина, царя.","Benajaoe, de zoon van Jehojada, antwoordde de koning: «Amen. Laat de Eeuwige, de God van mijn heer de koning, zo zeggen.",""],"i-kings-1-37":["Как Господь был с моим господином, царём, так пусть будет Он со Шломо и сделает его престол выше престола моего господина, царя Давида».","Zoals de Eeuwige met mijn heer de koning is geweest, zo moge Hij met Sjlomo zijn en zijn troon groter maken dan de troon van mijn heer, koning David.»",""],"i-kings-1-38":["Цадок, священник, Натан, пророк, Бенаягу, сын Йегояды, Керети и Пелети спустились, посадили Шломо на мула царя Давида и повели его к Гихону.","Tsadok de priester, Natan de profeet, Benajaoe de zoon van Jehojada, en de Kereti en de Peleti daalden af, zetten Sjlomo op het muildier van koning David en brachten hem naar Gichon.",""],"i-kings-1-39":["Цадок, священник, взял рог с маслом из шатра и помазал Шломо. Затрубили в шофар, и весь народ сказал: «Да живёт царь Шломо».","Tsadok de priester nam de hoorn met olie uit de tent en zalfde Sjlomo. Zij bliezen op de sjofar, en heel het volk zei: «Leve koning Sjlomo.»",""],"i-kings-1-40":["Весь народ поднялся за ним. Народ играл на флейтах и радовался великой радостью, и земля раскололась от их голоса.","Heel het volk trok achter hem op. Het volk speelde op fluiten en juichte met grote vreugde, en de aarde scheurde van hun geluid.","JPS: the earth rent; фр.: ébranlaient la terre. По-еврейски וַתִּבָּקַע הָאָרֶץ — земля раскололась."],"i-kings-1-41":["Адониягу и все званые, которые были с ним, услышали это, когда кончили есть. Йоав услышал звук шофара и сказал: «Почему шумит город?»","Adoniahoe en alle genodigden die bij hem waren hoorden het, toen zij klaar waren met eten. Joav hoorde het geluid van de sjofar en zei: «Waarom is de stad in oproer?»",""],"i-kings-1-42":["Он ещё говорил, и вот пришёл Йонатан, сын Эвьятара, священника. Адониягу сказал: «Войди. Ты достойный человек и несёшь добрую весть».","Hij sprak nog, en zie, Jonatan, de zoon van Evjatar de priester, kwam. Adoniahoe zei: «Kom binnen. Jij bent een flink man en je brengt goed nieuws.»",""],"i-kings-1-43":["Йонатан ответил Адониягу: «На самом деле наш господин, царь Давид, поставил Шломо царём.","Jonatan antwoordde Adoniahoe: «Werkelijk, onze heer koning David heeft Sjlomo koning gemaakt.",""],"i-kings-1-44":["Царь послал с ним Цадока, священника, Натана, пророка, Бенаягу, сына Йегояды, Керети и Пелети, и они посадили его на мула царя.","De koning heeft Tsadok de priester, Natan de profeet, Benajaoe de zoon van Jehojada en de Kereti en de Peleti met hem meegestuurd, en zij hebben hem op het muildier van de koning gezet.",""],"i-kings-1-45":["Цадок, священник, и Натан, пророк, помазали его царём у Гихона. Оттуда они поднялись радостные, и город шумит. Это тот голос, который вы слышали.","Tsadok de priester en Natan de profeet hebben hem bij Gichon tot koning gezalfd. Zij zijn vandaar opgetrokken, vol vreugde, en de stad is in oproer. Dat is het geluid dat jullie hebben gehoord.",""],"i-kings-1-46":["Шломо тоже сел на царский престол.","Ook heeft Sjlomo plaatsgenomen op de troon van het koningschap.",""],"i-kings-1-47":["Ещё пришли слуги царя благословить нашего господина, царя Давида, и сказали: „Пусть Бог сделает имя Шломо лучше твоего имени, а его престол выше твоего престола“. И царь поклонился на ложе.","Ook kwamen de dienaren van de koning om onze heer, koning David, te zegenen. Zij zeiden: „Moge God de naam van Sjlomo beter maken dan jouw naam en zijn troon groter dan jouw troon.“ En de koning boog zich neer op het bed.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"i-kings-1-48":["А царь сказал ещё так: „Благословен Господь, Бог Исраэля, который сегодня дал сидящего на моём престоле, и мои глаза видят это“».","Ook zei de koning dit: „Gezegend is de Eeuwige, de God van Israël, die vandaag iemand heeft gegeven die op mijn troon zit, en mijn ogen zien het.“»",""],"i-kings-1-49":["Все званые Адониягу затрепетали, встали и пошли каждый своей дорогой.","Alle genodigden van Adoniahoe beefden, stonden op en gingen ieder zijn eigen weg.",""],"i-kings-1-50":["Адониягу испугался Шломо, встал, пошёл и схватился за рога жертвенника.","Adoniahoe was bang voor Sjlomo. Hij stond op, ging en greep de horens van het altaar.",""],"i-kings-1-51":["Шломо передали: «Вот, Адониягу боится царя Шломо. Он схватился за рога жертвенника и говорит: „Пусть царь Шломо поклянётся мне сегодня, что не умертвит своего слугу мечом“».","Men berichtte Sjlomo: «Zie, Adoniahoe is bang voor koning Sjlomo. Hij heeft de horens van het altaar gegrepen en zegt: „Laat koning Sjlomo mij vandaag zweren dat hij zijn dienaar niet met het zwaard zal doden.“»",""],"i-kings-1-52":["Шломо сказал: «Если он будет достойным человеком, ни один волос его не упадёт на землю. А если найдётся в нём зло, он умрёт».","Sjlomo zei: «Als hij een flink man blijkt, zal geen haar van hem op de aarde vallen. Maar als er kwaad in hem gevonden wordt, zal hij sterven.»",""],"i-kings-1-53":["Царь Шломо послал, и его свели с жертвенника. Он пришёл, поклонился царю Шломо, и Шломо сказал ему: «Ступай в свой дом».","Koning Sjlomo stuurde, en zij haalden hem van het altaar af. Hij kwam en boog zich neer voor koning Sjlomo, en Sjlomo zei tegen hem: «Ga naar je huis.»",""],"genesis-30-1":["Рахель увидела, что не родила Яакову, и Рахель позавидовала сестре, и сказала Яакову: «Дай мне сыновей, а если нет — я умру».","Rachel zag dat zij Jaäkov niet gebaard had. Rachel was jaloers op haar zuster en zei tegen Jaäkov: «Geef mij zonen, en zo niet, dan sterf ik.»",""],"genesis-30-2":["Яаков разгневался на Рахель и сказал: «Разве я вместо Бога, который не дал тебе плода чрева?»","Jaäkov werd woedend op Rachel en zei: «Sta ik soms op de plaats van God, die jou de vrucht van de schoot heeft onthouden?»",""],"genesis-30-3":["Она сказала: «Вот моя служанка Бильга. Войди к ней, пусть она родит мне на колени, и через неё у меня тоже будут дети».","Zij zei: «Hier is mijn dienstmaagd Bilha. Ga bij haar binnen, laat zij op mijn knieën baren, en ook ik zal door haar kinderen krijgen.»","JPS: upon my knees; фр.: dans mes bras. По-еврейски עַל־בִּרְכַּי — на моих коленях."],"genesis-30-4":["Она дала ему свою рабыню Бильгу в жёны, и Яаков вошёл к ней.","Zij gaf hem Bilha, haar slavin, tot vrouw, en Jaäkov ging bij haar binnen.",""],"genesis-30-5":["Бильга зачала и родила Яакову сына.","Bilha werd zwanger en baarde Jaäkov een zoon.",""],"genesis-30-6":["Рахель сказала: «Бог рассудил меня, услышал и мой голос и дал мне сына». Поэтому она назвала его Дан.","Rachel zei: «God heeft mij recht gedaan, ook mijn stem gehoord en mij een zoon gegeven.» Daarom noemde zij hem Dan.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-30-7":["Бильга, рабыня Рахели, снова зачала и родила Яакову второго сына.","Bilha, de slavin van Rachel, werd opnieuw zwanger en baarde Jaäkov een tweede zoon.",""],"genesis-30-8":["Рахель сказала: «Божьей борьбой я боролась с сестрой и одолела». И она назвала его Нафтали.","Rachel zei: «Met een worsteling van God heb ik met mijn zuster geworsteld, en ik heb het gehaald.» En zij noemde hem Naftali.","JPS: mighty wrestlings; фр.: une lutte de Dieu. По-еврейски נַפְתּוּלֵי אֱלֹהִים — борьба Бога."],"genesis-30-9":["Леа увидела, что перестала рожать, взяла свою рабыню Зильпу и дала её Яакову в жёны.","Lea zag dat zij ophield met baren. Zij nam Zilpa, haar slavin, en gaf haar aan Jaäkov tot vrouw.",""],"genesis-30-10":["Зильпа, рабыня Леи, родила Яакову сына.","Zilpa, de slavin van Lea, baarde Jaäkov een zoon.",""],"genesis-30-11":["Леа сказала: «Пришла удача». И назвала его Гад.","Lea zei: «Geluk is gekomen.» En zij noemde hem Gad.","JPS: Fortune is come; фр.: une bande m’arrive. По-еврейски בָּא גָד — пришла удача; имя Гад."],"genesis-30-12":["Зильпа, рабыня Леи, родила Яакову второго сына.","Zilpa, de slavin van Lea, baarde Jaäkov een tweede zoon.",""],"genesis-30-13":["Леа сказала: «К моему счастью, дочери назвали меня счастливой». И она назвала его Ашер.","Lea zei: «Tot mijn geluk: dochters hebben mij gelukkig genoemd.» En zij noemde hem Asjer.","JPS: Happy am I, daughters will call me happy; фр.: né pour mon bonheur, les filles m’ont nommée. По-еврейски בְּאָשְׁרִי כִּי אִשְּׁרוּנִי בָּנוֹת — к счастью моему, дочери назвали меня счастливой."],"genesis-30-14":["Реувен пошёл во дни жатвы пшеницы, нашёл в поле мандрагоры и принёс их Лее, своей матери. Рахель сказала Лее: «Дай мне, прошу, мандрагор твоего сына».","Reüven ging in de dagen van de tarweoogst, vond alruinen op het veld en bracht ze naar Lea, zijn moeder. Rachel zei tegen Lea: «Geef mij toch van de alruinen van je zoon.»",""],"genesis-30-15":["Та сказала ей: «Мало того, что ты забрала моего мужа? Ещё и мандрагоры моего сына возьмёшь?» Рахель сказала: «Тогда он ляжет с тобой этой ночью за мандрагоры твоего сына».","Zij zei tegen haar: «Is het nog niet genoeg dat je mijn man hebt genomen? Wil je ook de alruinen van mijn zoon nemen?» Rachel zei: «Dan zal hij vannacht bij jou slapen, in ruil voor de alruinen van je zoon.»",""],"genesis-30-16":["Вечером Яаков пришёл с поля. Леа вышла ему навстречу и сказала: «Ты войдёшь ко мне, потому что я наняла тебя за мандрагоры моего сына». И он спал с ней в ту ночь.","Jaäkov kwam ’s avonds van het veld. Lea ging hem tegemoet en zei: «Bij mij kom je binnen, want ik heb je gehuurd voor de alruinen van mijn zoon.» En hij sliep met haar die nacht.",""],"genesis-30-17":["Бог услышал Лею, она зачала и родила Яакову пятого сына.","God luisterde naar Lea. Zij werd zwanger en baarde Jaäkov een vijfde zoon.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-30-18":["Леа сказала: «Бог дал мне мою плату за то, что я отдала свою рабыню мужу». И она назвала его Иссахар.","Lea zei: «God heeft mij mijn loon gegeven, omdat ik mijn slavin aan mijn man heb gegeven.» En zij noemde hem Jissachar.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-30-19":["Леа снова зачала и родила Яакову шестого сына.","Lea werd opnieuw zwanger en baarde Jaäkov een zesde zoon.",""],"genesis-30-20":["Леа сказала: «Бог одарил меня добрым даром. На этот раз мой муж будет жить со мной, потому что я родила ему шестерых сыновей». И она назвала его Зевулун.","Lea zei: «God heeft mij een goed geschenk gegeven. Ditmaal zal mijn man bij mij wonen, omdat ik hem zes zonen heb gebaard.» En zij noemde hem Zevuloen.","JPS: a good dowry, my husband will dwell with me; фр.: m’a accordée comme un don, fera de moi sa compagne. По-еврейски זֵבֶד טוֹב — добрый дар; יִזְבְּלֵנִי — будет жить со мной."],"genesis-30-21":["Потом она родила дочь и назвала её Дина.","Daarna baarde zij een dochter en noemde haar Dina.",""],"genesis-30-22":["Бог вспомнил Рахель, Бог услышал её и открыл её чрево.","God dacht aan Rachel. God luisterde naar haar en opende haar schoot.","JPS: God; фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"genesis-30-23":["Она зачала, родила сына и сказала: «Бог снял с меня позор».","Zij werd zwanger, baarde een zoon en zei: «God heeft mijn schande weggenomen.»",""],"genesis-30-24":["Она назвала его Йосеф и сказала: «Пусть Господь прибавит мне ещё одного сына».","Zij noemde hem Josef en zei: «De Eeuwige voege mij nog een zoon toe.»","JPS: the LORD; фр.: Dieu. По-еврейски יְהֹוָה — Господь."],"genesis-30-25":["Когда Рахель родила Йосефа, Яаков сказал Лавану: «Отпусти меня, я пойду в своё место и в свою землю.","Toen Rachel Josef had gebaard, zei Jaäkov tegen Lavan: «Laat mij gaan, dan trek ik naar mijn eigen plaats en naar mijn land.",""],"genesis-30-26":["Отдай моих жён и моих детей, тех жён, за которых я служил тебе, и я уйду. Ты сам знаешь, какую службу я сослужил тебе».","Geef mij mijn vrouwen en mijn kinderen, de vrouwen voor wie ik jou gediend heb, en laat mij gaan. Jij weet zelf welke dienst ik jou gedaan heb.»","JPS относит for whom и к детям; фр. — только к жёнам. По-еврейски בָּהֵן женский род: служба за жён."],"genesis-30-27":["Лаван сказал ему: «Если я нашёл милость в твоих глазах… Я гадал, и Господь благословил меня из-за тебя».","Lavan zei tegen hem: «Als ik genade heb gevonden in jouw ogen… Ik heb gewicheld, en de Eeuwige heeft mij om jou gezegend.»","JPS: I have observed the signs; фр.: j’avais bien auguré. По-еврейски נִחַשְׁתִּי — я гадал."],"genesis-30-28":["Он сказал: «Назначь свою плату мне, и я её дам».","Hij zei: «Noem mij je loon, en ik zal het geven.»",""],"genesis-30-29":["Он сказал ему: «Ты знаешь, как я служил тебе и каким стал твой скот у меня.","Hij zei tegen hem: «Jij weet hoe ik jou gediend heb en hoe het je vee bij mij is vergaan.",""],"genesis-30-30":["Мало было у тебя до меня, а оно сильно умножилось, и Господь благословил тебя благодаря мне. Когда же и я поработаю для своего дома?»","Weinig was wat jij had voordat ik kwam, en het is sterk toegenomen, en de Eeuwige heeft jou door mij gezegend. Wanneer zal ik ook voor mijn eigen huis werken?»","JPS: whithersoever I turned; фр.: grâce à moi. По-еврейски לְרַגְלִי — у моей ноги, из-за меня."],"genesis-30-31":["Он сказал: «Что мне дать тебе?» Яаков сказал: «Не давай мне ничего. Если сделаешь для меня вот это, я снова буду пасти твоё стадо и стеречь его.","Hij zei: «Wat zal ik je geven?» Jaäkov zei: «Je hoeft mij niets te geven. Als je dit voor mij doet, zal ik opnieuw je kudde weiden en bewaken.",""],"genesis-30-32":["Я пройду сегодня через всё твоё стадо. Убери оттуда всякую крапчатую и пятнистую скотину, всякую бурую среди овец и пятнистую и крапчатую среди коз. Это будет моя плата.","Ik zal vandaag door heel je kudde gaan. Haal daaruit elk gespikkeld en gevlekt dier weg, elk bruin dier onder de schapen, en de gevlekte en gespikkelde onder de geiten. Dat zal mijn loon zijn.","JPS: dark; фр.: brun. По-еврейски חוּם — бурый."],"genesis-30-33":["Моя праведность ответит против меня завтра, когда ты придёшь посмотреть мою плату перед собой: всякая коза не крапчатая и не пятнистая и всякая овца не бурая, если окажется у меня, — краденая».","Mijn gerechtigheid zal tegen mij getuigen op de dag van morgen, wanneer jij mijn loon komt nazien: elk dier onder de geiten dat niet gespikkeld en gevlekt is, en elk bruin dier onder de schapen, als het bij mij is, is gestolen.»","JPS: witness against me; фр.: parlera pour moi. По-еврейски וְעָנְתָה־בִּי — ответит против меня."],"genesis-30-34":["Лаван сказал: «Хорошо, пусть будет по твоему слову».","Lavan zei: «Goed, laat het zijn zoals jij hebt gezegd.»",""],"genesis-30-35":["В тот день он отделил полосатых и пятнистых козлов, всех крапчатых и пятнистых коз, всякую скотину, в которой была белая шерсть, и всех бурых среди овец, и отдал их в руки своих сыновей.","Die dag haalde hij de gestreepte en gevlekte bokken weg, alle gespikkelde en gevlekte geiten, alles waar wit in zat, en alle bruine dieren onder de schapen, en gaf ze in handen van zijn zonen.",""],"genesis-30-36":["Он положил три дня пути между собой и Яаковом, а Яаков пас оставшееся стадо Лавана.","Hij legde een afstand van drie dagreizen tussen zichzelf en Jaäkov, en Jaäkov weidde wat er over was van de kudde van Lavan.",""],"genesis-30-37":["Яаков взял себе свежие прутья тополя, миндаля и платана и вырезал на них белые полосы, обнажив белизну, которая была на прутьях.","Jaäkov nam verse stokken van populier, amandel en plataan en schilde er witte strepen in, zodat het wit van de stokken bloot kwam.",""],"genesis-30-38":["Он поставил прутья, которые очистил, в желобах, в поилках, куда стадо приходило пить, перед стадом, и они приходили в охоту, когда подходили пить.","Hij zette de stokken die hij geschild had in de goten, in de drinkbakken waar de kudde kwam drinken, vóór de kudde, en zij werden hitsig wanneer zij kwamen drinken.","JPS: they conceived; фр.: entrait en chaleur. По-еврейски וַיֵּחַמְנָה — приходили в охоту."],"genesis-30-39":["Стадо приходило в охоту у прутьев, и стадо рожало полосатых, крапчатых и пятнистых.","De kudde werd hitsig bij de stokken, en de kudde wierp gestreepte, gespikkelde en gevlekte jongen.",""],"genesis-30-40":["Яаков отделил ягнят и поставил стадо лицом к полосатым и ко всем бурым в стаде Лавана. Свои стада он держал отдельно и не ставил их к стаду Лавана.","Jaäkov scheidde de lammeren af en richtte de kudde met het gezicht naar de gestreepte en naar alle bruine dieren in de kudde van Lavan. Zijn eigen kudden hield hij apart en hij zette ze niet bij de kudde van Lavan.","JPS: streaked; фр. здесь: tachetés. По-еврейски עָקֹד — полосатый, как עֲקֻדִּים выше."],"genesis-30-41":["Каждый раз, когда крепкие в стаде приходили в охоту, Яаков клал прутья перед глазами стада в желобах, чтобы они приходили в охоту у прутьев.","Telkens als de sterke dieren van de kudde hitsig werden, legde Jaäkov de stokken voor de ogen van de kudde in de goten, zodat zij bij de stokken hitsig werden.",""],"genesis-30-42":["А когда стадо было слабым, он не клал. Слабые доставались Лавану, а крепкие — Яакову.","Maar als de kudde zwak was, legde hij ze niet. Zo waren de zwakke dieren voor Lavan en de sterke voor Jaäkov.",""],"genesis-30-43":["Этот человек чрезвычайно разбогател. У него было много скота, рабыни и рабы, верблюды и ослы.","De man werd buitengewoon rijk. Hij had veel vee, slavinnen en slaven, kamelen en ezels.",""],"i-kings-3-3":["Шломо любил Господа и ходил по уставам Давида, своего отца. Только на высотах он приносил жертвы и воскурял.","Sjlomo had de Eeuwige lief en leefde naar de inzettingen van zijn vader David. Alleen op de hoogten bracht hij offers en brandde hij wierook.","JPS: sacrificed and offered; фр.: brûlait de l’encens. По-еврейски מַקְטִיר — воскурял."],"i-kings-3-4":["Царь пошёл в Гивон принести там жертву, потому что там была великая высота. Тысячу всесожжений вознёс Шломо на том жертвеннике.","De koning ging naar Givon om daar te offeren, want daar was de grote hoogte. Duizend brandoffers bracht Sjlomo op dat altaar.",""],"i-kings-3-5":["В Гивоне Господь явился Шломо в ночном сне, и Бог сказал: «Проси, что Мне дать тебе».","In Givon verscheen de Eeuwige aan Sjlomo in een droom bij nacht, en God zei: «Vraag wat Ik je geven zal.»","Является יְהֹוָה, говорит אֱלֹהִים. JPS сохраняет оба; фр. сводит речь к Seigneur."],"i-kings-3-6":["Шломо сказал: «Ты сделал великую милость Твоему слуге Давиду, моему отцу, как он ходил перед Тобой в истине, в праведности и в прямоте сердца с Тобой. Ты сохранил ему эту великую милость и дал ему сына, который сидит на его престоле, как это сегодня.","Sjlomo zei: «U hebt Uw dienaar David, mijn vader, grote goedheid bewezen, zoals hij voor U wandelde in waarheid, in gerechtigheid en in oprechtheid van hart met U. U hebt deze grote goedheid voor hem bewaard en hem een zoon gegeven die op zijn troon zit, zoals het vandaag is.","JPS: according as he walked; фр.: parce qu’il a marché. По-еврейски כַּאֲשֶׁר — как он ходил."],"i-kings-3-7":["А теперь, Господь, Бог мой, Ты поставил Твоего слугу царём вместо Давида, моего отца, а я малый юноша и не умею ни выйти, ни войти.","Nu dan, Eeuwige, mijn God, U hebt Uw dienaar koning gemaakt in de plaats van mijn vader David, en ik ben een jonge jongen, ik weet niet uit te gaan of binnen te komen.","JPS: I know not how to go out or come in; фр.: inhabile à me conduire. По-еврейски לֹא אֵדַע צֵאת וָבֹא — не умею выйти и войти."],"i-kings-3-8":["Твой слуга — среди Твоего народа, который Ты избрал, народа великого, которого не счесть и не пересчитать, так его много.","Uw dienaar staat te midden van Uw volk dat U hebt uitgekozen, een groot volk dat niet geteld en niet opgesomd kan worden, zo talrijk is het.",""],"i-kings-3-9":["Дай Твоему слуге слушающее сердце, чтобы судить Твой народ и различать добро и зло. Кто сможет судить этот многочисленный народ Твой?»","Geef Uw dienaar een luisterend hart om Uw volk te richten en te onderscheiden tussen goed en kwaad. Want wie kan dit talrijke volk van U richten?»","JPS: an understanding heart; фр.: un cœur intelligent. По-еврейски לֵב שֹׁמֵעַ — слушающее сердце."],"i-kings-3-10":["Это было угодно Владыке, что Шломо просил именно этого.","Het beviel de Heer dat Sjlomo juist dit had gevraagd.","В стихе אֲדֹנָי, не יהוה: Владыка / Heer."],"i-kings-3-11":["Бог сказал ему: «За то, что ты просил этого и не просил себе долгих дней, не просил себе богатства и не просил души твоих врагов, а просил себе разумения, чтобы слышать суд,","God zei tegen hem: «Omdat je dit gevraagd hebt, en niet voor jezelf vele dagen hebt gevraagd, en niet voor jezelf rijkdom hebt gevraagd, en niet het leven van je vijanden hebt gevraagd, maar voor jezelf inzicht hebt gevraagd om recht te horen,",""],"i-kings-3-12":["Вот, Я сделал по твоим словам. Вот, Я дал тебе мудрое и разумное сердце, так что подобного тебе не было до тебя, и после тебя не встанет подобный тебе.","Zie, Ik heb gedaan naar je woorden. Zie, Ik heb je een wijs en verstandig hart gegeven, zodat er vóór jou niemand was zoals jij, en na jou zal niemand opstaan zoals jij.",""],"i-kings-3-13":["Также то, чего ты не просил, Я дал тебе: и богатство, и почёт, так что не было подобного тебе никого среди царей во все твои дни.","Ook wat je niet gevraagd hebt, heb Ik je gegeven: rijkdom en eer, zodat er onder de koningen niemand was zoals jij, al je dagen.",""],"i-kings-3-14":["Если ты будешь ходить Моими путями, хранить Мои уставы и Мои мицвот, как ходил Давид, твой отец, Я продлю твои дни».","Als je op Mijn wegen gaat, om Mijn inzettingen en Mijn mitswot te houden, zoals je vader David is gegaan, dan zal Ik je dagen verlengen.»",""],"i-kings-3-15":["Шломо проснулся, и вот — это сон. Он пришёл в Йерушалаим, встал перед ковчегом брит Владыки, вознёс всесожжения, принёс жертвы благополучия и устроил пир всем своим слугам.","Sjlomo ontwaakte, en zie, het was een droom. Hij kwam naar Jeroesjalajim, ging staan voor de ark van de briet van de Heer, bracht brandoffers, bracht vredeoffers en richtte een maaltijd aan voor al zijn dienaren.","В стихе אֲדֹנָי, не יהוה: Владыка / Heer. JPS: peace-offerings; фр.: sacrifices rémunératoires. По-еврейски שְׁלָמִים — жертвы благополучия."],"genesis-34-1":["Дина, дочь Леи, которую та родила Яакову, вышла посмотреть на дочерей земли.","Dina, de dochter van Lea, die zij aan Jaäkov had gebaard, ging naar buiten om de dochters van het land te zien.","JPS: to see; фр.: faire connaissance. По-еврейски לִרְאוֹת — посмотреть."],"genesis-34-2":["Увидел её Шехем, сын Хамора, хивви, князь земли. Он взял её, был с ней и унизил её.","Sjechem, de zoon van Chamor, de Chivvi, vorst van het land, zag haar. Hij nam haar, sliep met haar en vernederde haar.","JPS сохраняет три глагола: took, lay with, humbled. Фр. сводит их к enleva и s’approcha en faisant violence. По-еврейски וַיִּקַּח, וַיִּשְׁכַּב, וַיְעַנֶּהָ."],"genesis-34-3":["Его душа прилепилась к Дине, дочери Яакова. Он полюбил девушку и говорил к сердцу девушки.","Zijn ziel kleefde aan Dina, de dochter van Jaäkov. Hij hield van het meisje en sprak tot het hart van het meisje.","JPS: spoke comfortingly; фр.: parla à son cœur. По-еврейски עַל־לֵב — говорил к сердцу девушки."],"genesis-34-4":["Шехем сказал Хамору, своему отцу: «Возьми мне эту девочку в жёны».","Sjechem zei tegen Chamor, zijn vader: «Neem dit jonge meisje voor mij tot vrouw.»",""],"genesis-34-5":["Яаков услышал, что тот осквернил Дину, его дочь. Сыновья Яакова были с его скотом в поле, и Яаков молчал, пока они не пришли.","Jaäkov hoorde dat hij Dina, zijn dochter, ontreinigd had. Zijn zonen waren met zijn vee op het veld, en Jaäkov zweeg tot zij kwamen.","JPS: defiled; фр.: déshonoré. По-еврейски טִמֵּא — осквернил."],"genesis-34-6":["Хамор, отец Шехема, вышел к Яакову, чтобы говорить с ним.","Chamor, de vader van Sjechem, ging naar Jaäkov toe om met hem te spreken.",""],"genesis-34-7":["Сыновья Яакова пришли с поля, когда услышали это. Эти люди горевали и сильно разгневались, потому что он сделал гнусность в Исраэле: был с дочерью Яакова. Так не делают.","De zonen van Jaäkov kwamen van het veld toen zij het hoorden. De mannen waren bedroefd en werden zeer kwaad, omdat hij een schanddaad in Israël had gedaan: hij had met de dochter van Jaäkov geslapen. Zo doet men niet.","JPS: lying with; фр.: viol. По-еврейски לִשְׁכַּב אֶת — был с дочерью Яакова."],"genesis-34-8":["Хамор говорил с ними: «Душа моего сына Шехема привязалась к вашей дочери. Отдайте же её ему в жёны.","Chamor sprak met hen: «De ziel van mijn zoon Sjechem hangt aan jullie dochter. Geef haar toch aan hem tot vrouw.",""],"genesis-34-9":["Породнитесь с нами: ваших дочерей отдавайте нам, а наших дочерей берите себе.","Sluit huwelijken met ons: geef jullie dochters aan ons en neem onze dochters voor jullie.",""],"genesis-34-10":["Живите с нами, и земля будет перед вами. Селитесь, торгуйте на ней и берите на ней владение».","Woon bij ons, en het land ligt voor jullie open. Vestig je, drijf er handel en neem er bezit.»","JPS: trade; фр.: exploitez. По-еврейски וְסִחֲרוּהָ — торгуйте."],"genesis-34-11":["Шехем сказал её отцу и её братьям: «Пусть я найду благоволение в ваших глазах. Что скажете мне, то я дам.","Sjechem zei tegen haar vader en haar broers: «Laat ik gunst vinden in jullie ogen. Wat jullie tegen mij zeggen, zal ik geven.",""],"genesis-34-12":["Назначьте мне очень большой выкуп за невесту и дар, и я дам, как вы скажете мне. Только отдайте мне девушку в жёны».","Leg mij een zeer hoge bruidsprijs en een groot geschenk op. Ik geef wat jullie mij zeggen. Geef mij alleen het meisje tot vrouw.»",""],"genesis-34-13":["Сыновья Яакова ответили Шехему и Хамору, его отцу, с обманом. Они говорили так, потому что он осквернил Дину, их сестру.","De zonen van Jaäkov antwoordden Sjechem en Chamor, zijn vader, met bedrog. Zij spraken zo omdat hij Dina, hun zuster, ontreinigd had.",""],"genesis-34-14":["Они сказали им: «Мы не можем сделать это — отдать нашу сестру мужчине, у которого есть крайняя плоть. Это позор для нас.","Zij zeiden tegen hen: «Wij kunnen dit niet doen: onze zuster geven aan een man die een voorhuid heeft. Dat is een schande voor ons.",""],"genesis-34-15":["Только на этом мы согласимся с вами: если вы станете как мы и у вас будет обрезан каждый мужчина.","Alleen hierop stemmen wij met jullie in: als jullie worden zoals wij en bij jullie iedere man besneden wordt.",""],"genesis-34-16":["Тогда мы отдадим вам наших дочерей, а ваших дочерей возьмём себе, будем жить с вами и станем одним народом.","Dan geven wij onze dochters aan jullie en nemen wij jullie dochters voor ons. Wij zullen bij jullie wonen en één volk worden.",""],"genesis-34-17":["Если же вы не послушаете нас и не обрежетесь, мы заберём нашу дочь и уйдём».","Maar als jullie niet naar ons luisteren en je niet laten besnijden, nemen wij onze dochter mee en gaan wij weg.»",""],"genesis-34-18":["Их слова были хороши в глазах Хамора и в глазах Шехема, сына Хамора.","Hun woorden waren goed in de ogen van Chamor en in de ogen van Sjechem, de zoon van Chamor.",""],"genesis-34-19":["Юноша не замедлил сделать это, потому что ему была желанна дочь Яакова. А он был почтённее всех в доме своего отца.","De jongeman stelde het niet uit om het te doen, want hij begeerde de dochter van Jaäkov. Hij was geëerd boven allen in het huis van zijn vader.","JPS: deferred not; фр.: n’hésita point. По-еврейски לֹא־אֵחַר — не замедлил."],"genesis-34-20":["Хамор и Шехем, его сын, пришли к воротам своего города и сказали людям своего города:","Chamor en zijn zoon Sjechem kwamen bij de poort van hun stad en zeiden tegen de mannen van hun stad:",""],"genesis-34-21":["«Эти люди мирны с нами. Пусть живут на земле и торгуют на ней: земля перед ними просторна. Их дочерей возьмём себе в жёны, а наших дочерей отдадим им.","«Deze mannen zijn in vrede met ons. Laten zij in het land wonen en er handel drijven: het land ligt wijd voor hen open. Hun dochters nemen wij voor ons tot vrouwen, en onze dochters geven wij aan hen.","JPS: peaceable; фр.: de bonne foi. По-еврейски שְׁלֵמִים — мирны, целы с нами."],"genesis-34-22":["Только на этом эти люди согласятся жить с нами и стать одним народом: если у нас будет обрезан каждый мужчина, как обрезаны они.","Alleen hierop zullen deze mannen instemmen om bij ons te wonen en één volk te worden: als bij ons iedere man besneden wordt, zoals zij besneden zijn.",""],"genesis-34-23":["Их скот, их имущество и все их животные — разве не нашими они будут? Только согласимся с ними, и они будут жить с нами».","Hun vee, hun have en al hun dieren, zullen die niet van ons worden? Laten wij alleen met hen instemmen, dan zullen zij bij ons wonen.»",""],"genesis-34-24":["Хамора и Шехема, его сына, послушали все, кто выходит из ворот его города. Обрезали каждого мужчину — всех, кто выходит из ворот его города.","Naar Chamor en naar zijn zoon Sjechem luisterden allen die de poort van zijn stad uitgingen. Zij besneden iedere man, allen die de poort van zijn stad uitgingen.","JPS: went out of the gate; фр.: habitaient l’enceinte, citoyens. По-еврейски יֹצְאֵי שַׁעַר — выходящие из ворот города."],"genesis-34-25":["На третий день, когда им было больно, двое из сыновей Яакова, Шимон и Леви, братья Дины, взяли каждый свой меч, пришли на город спокойно и убили всех мужчин.","Op de derde dag, toen zij pijn hadden, namen twee zonen van Jaäkov, Sjimon en Levi, broers van Dina, ieder zijn zwaard en kwamen rustig op de stad af en doodden alle mannen.","JPS: unawares; фр.: avec assurance. По-еврейски בֶּטַח — спокойно: город был беспечен, братья шли без боязни."],"genesis-34-26":["Хамора и Шехема, его сына, они убили остриём меча, забрали Дину из дома Шехема и вышли.","Chamor en zijn zoon Sjechem doodden zij met de scherpte van het zwaard. Zij haalden Dina uit het huis van Sjechem en gingen weg.",""],"genesis-34-27":["Сыновья Яакова пришли к убитым и разграбили город, потому что те осквернили их сестру.","De zonen van Jaäkov kwamen bij de gevallenen en plunderden de stad, omdat zij hun zuster ontreinigd hadden.","JPS: they had defiled; фр.: la ville avait déshonoré. По-еврейски טִמְּאוּ — множественное число: осквернили."],"genesis-34-28":["Их овец, их крупный скот и их ослов, и то, что было в городе, и то, что было в поле, они забрали.","Hun schapen, hun runderen en hun ezels, en wat in de stad was en wat op het veld was, namen zij mee.",""],"genesis-34-29":["Всё их добро, всех их детей и их жён они увели в плен и разграбили, и всё, что было в доме.","Al hun goed, al hun kinderen en hun vrouwen voerden zij gevangen weg en plunderden zij, en alles wat in huis was.",""],"genesis-34-30":["Яаков сказал Шимону и Леви: «Вы привели меня в беду и сделали меня смрадным для жителей земли, для кнаани и перизея. А меня мало числом. Они соберутся против меня, разобьют меня, и я буду истреблён, я и мой дом».","Jaäkov zei tegen Sjimon en Levi: «Jullie hebben mij in het ongeluk gestort en mij stinkend gemaakt bij de bewoners van het land, bij de Kenaäniet en de Perizzi. En ik ben met weinig man. Zij zullen zich tegen mij verzamelen en mij verslaan, en ik zal worden weggevaagd, ik en mijn huis.»",""],"genesis-34-31":["Они сказали: «Разве с нашей сестрой поступают как с блудницей?»","Zij zeiden: «Moest men onze zuster behandelen als een vrouw die zich verkoopt?»",""],"genesis-35-1":["Бог сказал Яакову: «Встань, поднимись в Бейт-Эль и живи там. Сделай там жертвенник Богу, который явился тебе, когда ты бежал от Эсава, своего брата».","God zei tegen Jaäkov: «Sta op, trek op naar Bet-El en woon daar. Maak daar een altaar voor de God die aan je verscheen toen je vluchtte voor Esav, je broer.»","Фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог, не Господь."],"genesis-35-2":["Яаков сказал своему дому и всем, кто был с ним: «Уберите чужих богов, которые среди вас, очиститесь и смените одежды.","Jaäkov zei tegen zijn huis en tegen allen die bij hem waren: «Doe de vreemde goden weg die bij jullie zijn, reinig je en verwissel je kleren.",""],"genesis-35-3":["Встанем и поднимемся в Бейт-Эль. Я сделаю там жертвенник Богу, который ответил мне в день моей беды и был со мной на пути, которым я шёл».","Laten wij opstaan en optrekken naar Bet-El. Ik zal daar een altaar maken voor de God die mij antwoord gaf op de dag van mijn nood en met mij was op de weg die ik ging.»",""],"genesis-35-4":["Они отдали Яакову всех чужих богов, которые были у них в руках, и серьги, которые были у них в ушах. Яаков закопал их под теребинтом, что у Шехема.","Zij gaven Jaäkov alle vreemde goden die in hun hand waren, en de ringen die in hun oren waren. Jaäkov begroef ze onder de terebint bij Sjechem.","JPS: rings, terebinth; фр.: joyaux, tilleul. По-еврейски נְזָמִים — серьги, הָאֵלָה — теребинт."],"genesis-35-5":["Они двинулись в путь. Ужас Божий был на городах вокруг них, и те не гнались за сыновьями Яакова.","Zij trokken verder. Een schrik van God lag op de steden rondom hen, en die achtervolgden de zonen van Jaäkov niet.",""],"genesis-35-6":["Яаков пришёл в Луз, что в земле Кнаан, то есть в Бейт-Эль, он и весь народ, который был с ним.","Jaäkov kwam in Loez, in het land Kenaän, dat is Bet-El, hij en heel het volk dat bij hem was.",""],"genesis-35-7":["Он построил там жертвенник и назвал это место Эль Бейт-Эль, потому что там ему открылся Бог, когда он бежал от своего брата.","Hij bouwde daar een altaar en noemde de plaats El Bet-El, omdat God zich daar aan hem openbaarde toen hij vluchtte voor zijn broer.","JPS: God was revealed; фр.: les puissances célestes. По-еврейски נִגְלוּ אֵלָיו הָאֱלֹהִים — глагол во множественном числе."],"genesis-35-8":["Умерла Двора, кормилица Ривки. Её похоронили ниже Бейт-Эля, под дубом, и он назвал его Аллон-Бахут.","Dvora, de voedster van Rivka, stierf. Zij werd begraven beneden Bet-El, onder de eik, en hij gaf die de naam Allon-Bachoet.","Фр. переводит имя: le Chêne des Pleurs. По-еврейски אַלּוֹן בָּכוּת — имя Аллон-Бахут."],"genesis-35-9":["Бог снова явился Яакову, когда тот пришёл из Падан-Арама, и благословил его.","God verscheen opnieuw aan Jaäkov toen hij uit Paddan-Aram kwam, en Hij zegende hem.","JPS: Paddan-aram; фр.: territoire d’Aram. По-еврейски פַּדַּן אֲרָם — Падан-Арам."],"genesis-35-10":["Бог сказал ему: «Имя твоё — Яаков. Не будут больше звать тебя Яаков, но Исраэль будет твоё имя». И Он назвал его Исраэль.","God zei tegen hem: «Je naam is Jaäkov. Je naam zal niet meer Jaäkov worden genoemd, maar Israël zal je naam zijn.» En Hij noemde hem Israël.",""],"genesis-35-11":["Бог сказал ему: «Я — Эль Шаддай. Плодись и умножайся. От тебя будет народ и собрание народов, и цари выйдут из твоих чресел.","God zei tegen hem: «Ik ben El Sjaddai. Wees vruchtbaar en word talrijk. Uit jou zal een volk komen en een vergadering van volken, en koningen zullen uit je lendenen voortkomen.","JPS: God Almighty, a company of nations; фр.: Dieu tout puissant, un essaim de peuples. По-еврейски אֵל שַׁדַּי — имя Эль Шаддай; קְהַל גּוֹיִם — собрание народов."],"genesis-35-12":["Землю, которую Я дал Аврааму и Ицхаку, Я отдам тебе, и твоему потомству после тебя отдам эту землю».","Het land dat Ik aan Abraham en aan Jitschak heb gegeven, zal Ik aan jou geven, en aan jouw nageslacht na jou zal Ik het land geven.»",""],"genesis-35-13":["Бог поднялся от него на том месте, где говорил с ним.","God steeg op van hem, op de plaats waar Hij met hem gesproken had.","JPS: God went up; фр.: le Seigneur disparut. По-еврейски וַיַּעַל אֱלֹהִים — Бог поднялся."],"genesis-35-14":["Яаков поставил стелу на том месте, где Он говорил с ним, каменную стелу, возлил на неё возлияние и вылил на неё масло.","Jaäkov zette een staande steen op de plaats waar Hij met hem gesproken had, een stenen zuil, en hij goot er een plengoffer over uit en goot er olie over.","JPS: pillar; фр.: monument. По-еврейски מַצֵּבָה — поставленный камень."],"genesis-35-15":["Яаков назвал имя места, где Бог говорил с ним, Бейт-Эль.","Jaäkov noemde de naam van de plaats waar God met hem gesproken had: Bet-El.","Фр.: le Seigneur. По-еврейски אֱלֹהִים — Бог."],"joshua-9-1":["Когда услышали все цари, которые по стороне Ярдена, в горах, в низине и по всему берегу Великого моря напротив Леванона, — хетты и эмори, кнаани, перизеи, хивви и евусеи, —","Toen alle koningen het hoorden die aan de zijde van de Jarden waren, in het bergland, in het laagland en langs heel de kust van de Grote Zee tegenover Levanon — de Chitti en de Emori, de Kenaäniet, de Perizzi, de Chivvi en de Jevusiet —","JPS: beyond the Jordan, the Lowland, in front of Lebanon; фр.: rive, vallée, jusqu’au Liban. По-еврейски עֵבֶר — сторона Ярдена, שְׁפֵלָה — низина, אֶל־מוּל — напротив Леванона."],"joshua-9-2":["они собрались вместе, чтобы воевать с Йехошуа и с Исраэлем, одними устами.","verzamelden zij zich samen om te strijden tegen Jehosjoea en tegen Israël, met één mond.",""],"joshua-9-3":["Жители Гивона услышали, что сделал Йехошуа с Йерихо и с Ай.","De inwoners van Givon hoorden wat Jehosjoea met Jericho en met Ai had gedaan.",""],"joshua-9-4":["Они тоже поступили хитро: пошли, выдали себя за послов и взяли на своих ослов ветхие мешки и винные мехи, ветхие, лопнувшие и перевязанные,","Ook zij handelden met list: zij gingen, gaven zich uit voor gezanten en namen oude zakken mee voor hun ezels, en wijnzakken, oud, gescheurd en dichtgebonden,","JPS: ambassadors; фр.: munis de provisions. В стихе וַיִּצְטַיָּרוּ — выдали себя за послов. JPS: patched; фр.: recousues. מְצֹרָרִים — перевязаны."],"joshua-9-5":["и ветхие залатанные сандалии на ногах, и ветхие плащи на себе. Весь хлеб их припаса был сухой и в крошках.","en versleten, gelapte sandalen aan hun voeten, en versleten mantels om zich heen. Al het brood van hun proviand was droog en verkruimeld.","JPS: crumbs; фр.: moisi. По-еврейски נִקֻּדִים — в крошках, с пятнами."],"joshua-9-6":["Они пришли к Йехошуа, в стан в Гилгаль, и сказали ему и людям Исраэля: «Из далёкой земли мы пришли. Теперь заключите с нами брит».","Zij kwamen bij Jehosjoea, in het kamp te Gilgal, en zeiden tegen hem en tegen de mannen van Israël: «Wij zijn uit een ver land gekomen. Sluit nu een briet met ons.»",""],"joshua-9-7":["Человек Исраэля сказал хивви: «Может быть, ты живёшь среди меня. Как же я заключу с тобой брит?»","De man van Israël zei tegen de Chivvi: «Misschien woon jij in mijn midden. Hoe zou ik dan een briet met jou sluiten?»",""],"joshua-9-8":["Они сказали Йехошуа: «Мы твои рабы». Йехошуа сказал им: «Кто вы и откуда пришли?»","Zij zeiden tegen Jehosjoea: «Wij zijn jouw dienaren.» Jehosjoea zei tegen hen: «Wie zijn jullie, en waar komen jullie vandaan?»",""],"joshua-9-9":["Они сказали ему: «Из очень далёкой земли пришли твои рабы ради имени Господа, твоего Бога. Мы слышали весть о Нём и обо всём, что Он сделал в Египте,","Zij zeiden tegen hem: «Uit een zeer ver land zijn jouw dienaren gekomen omwille van de naam van de Eeuwige, jouw God. Wij hebben de roep over Hem gehoord en alles wat Hij in Egypte heeft gedaan,",""],"joshua-9-10":["и обо всём, что Он сделал двум царям эмори, которые по ту сторону Ярдена: Сихону, царю Хешбона, и Огу, царю Башана, который в Аштароте.","en alles wat Hij heeft gedaan aan de twee koningen van de Emori aan de overkant van de Jarden: aan Sichon, koning van Chesjbon, en aan Og, koning van Basjan, die in Asjtarot was.",""],"joshua-9-11":["Наши старейшины и все жители нашей земли сказали нам: „Возьмите в руки припас на дорогу, идите им навстречу и скажите им: ‚Мы ваши рабы. Теперь заключите с нами брит‘“.","Onze oudsten en alle inwoners van ons land zeiden tegen ons: „Neem proviand voor onderweg in jullie handen, ga hun tegemoet en zeg tegen hen: ‚Wij zijn jullie dienaren. Sluit nu een briet met ons‘.“",""],"joshua-9-12":["Этот наш хлеб мы взяли горячим в припас из наших домов в тот день, когда вышли идти к вам. А теперь вот он сухой и в крошках.","Dit brood van ons namen wij heet mee als proviand uit onze huizen, op de dag dat wij vertrokken om naar jullie te gaan. En nu, zie, het is droog en verkruimeld.","JPS: hot, crumbs; фр.: frais, moisi. По-еврейски חָם — горячий; נִקֻּדִים — в крошках, с пятнами."],"joshua-9-13":["А эти винные мехи мы наполнили новыми, и вот они лопнули. Эти наши плащи и наши сандалии износились от очень долгого пути».","Deze wijnzakken vulden wij nieuw, en zie, ze zijn gescheurd. Deze mantels van ons en onze sandalen zijn versleten van de zeer lange weg.»",""],"joshua-9-14":["Люди взяли из их припаса, а уст Господа не спросили.","De mannen namen van hun proviand, maar de mond van de Eeuwige vroegen zij niet.","JPS добавляет counsel при mouth of the LORD; фр.: consulté le Seigneur, без «уст». По-еврейски אֶת־פִּי יְהוָה לֹא שָׁאָלוּ — не спросили уст Господа."],"joshua-9-15":["Йехошуа заключил с ними мир и заключил с ними брит, чтобы оставить их в живых. Князья общины поклялись им.","Jehosjoea maakte vrede met hen en sloot een briet met hen om hen in leven te laten. De vorsten van de gemeente zwoeren hun een eed.",""],"joshua-9-16":["По прошествии трёх дней после того, как они заключили с ними брит, услышали, что те близки к нему и живут среди него.","Na verloop van drie dagen, nadat zij een briet met hen hadden gesloten, hoorden zij dat zij dicht bij hem waren en in zijn midden woonden.",""],"joshua-9-17":["Сыны Исраэля выступили и на третий день пришли к их городам. Их города: Гивон, Кефира, Беэрот и Кирьят-Еарим.","De zonen van Israël trokken uit en kwamen op de derde dag bij hun steden. Hun steden waren Givon, Kefira, Beërot en Kirjat-Jearim.",""],"joshua-9-18":["Сыны Исраэля не ударили их, потому что князья общины поклялись им Господом, Богом Исраэля. Вся община роптала на князей.","De zonen van Israël sloegen hen niet, want de vorsten van de gemeente hadden hun gezworen bij de Eeuwige, de God van Israël. Heel de gemeente morde tegen de vorsten.",""],"joshua-9-19":["Все князья сказали всей общине: «Мы поклялись им Господом, Богом Исраэля. Теперь мы не можем тронуть их.","Alle vorsten zeiden tegen heel de gemeente: «Wij hebben hun gezworen bij de Eeuwige, de God van Israël. Nu kunnen wij hen niet aanraken.",""],"joshua-9-20":["Вот что мы сделаем им: оставим их в живых, и не будет на нас гнева из-за клятвы, которой мы им поклялись».","Dit zullen wij hun doen: wij laten hen leven, zodat er geen toorn over ons komt vanwege de eed die wij hun hebben gezworen.»","Фр. добавляет divine к קֶצֶף. По-еврейски просто гнев."],"genesis-38-1":["В то время Йегуда отошёл от своих братьев и свернул к одному адулламитянину, которого звали Хира.","In die tijd ging Jehoeda weg van zijn broers en week hij af naar een man uit Adullam, wiens naam Chira was.",""],"genesis-38-2":["Там Йегуда увидел дочь одного кнаани, которого звали Шуа. Он взял её и вошёл к ней.","Daar zag Jehoeda de dochter van een Kenaäniet die Sjoea heette. Hij nam haar en ging bij haar naar binnen.","JPS: took her and went in unto her; фр.: l’épousa et s’approcha. По-еврейски וַיִּקָּחֶהָ וַיָּבֹא אֵלֶיהָ — взял её и вошёл к ней."],"genesis-38-3":["Она зачала, родила сына, и он назвал его Эр.","Zij werd zwanger, baarde een zoon, en hij noemde hem Er.",""],"genesis-38-4":["Она снова зачала, родила сына, и она назвала его Онан.","Zij werd opnieuw zwanger, baarde een zoon, en zij noemde hem Onan.",""],"genesis-38-5":["Она родила ещё сына и назвала его Шела. Он был в Кезиве, когда она родила его.","Zij baarde nog een zoon en noemde hem Sjela. Hij was in Keziv toen zij hem baarde.",""],"genesis-38-6":["Йегуда взял жену Эру, своему первенцу. Её звали Тамар.","Jehoeda nam een vrouw voor Er, zijn eerstgeborene. Haar naam was Tamar.",""],"genesis-38-7":["Эр, первенец Йегуды, был зол в глазах Господа, и Господь умертвил его.","Er, de eerstgeborene van Jehoeda, was slecht in de ogen van de Eeuwige, en de Eeuwige deed hem sterven.","JPS: wicked; фр.: ayant déplu. По-еврейски רַע — зол в глазах Господа."],"genesis-38-8":["Йегуда сказал Онану: «Войди к жене твоего брата, возьми её вместо него и восставь семя твоему брату».","Jehoeda zei tegen Onan: «Ga naar de vrouw van je broer, neem haar in zijn plaats en verwek nageslacht voor je broer.»","JPS: perform the duty of a husband’s brother; фр.: en vertu du lévirat. По-еврейски וְיַבֵּם אֹתָהּ — глагол, без позднего термина «левират»."],"genesis-38-9":["Онан знал, что семя будет не ему. Когда он входил к жене своего брата, он изливал его на землю, чтобы не дать семя своему брату.","Onan wist dat het zaad niet van hem zou zijn. Telkens wanneer hij naar de vrouw van zijn broer ging, stortte hij het op de grond, om zijn broer geen zaad te geven.","JPS: spilled it on the ground; фр.: corrompait sa voie. По-еврейски וְשִׁחֵת אַרְצָה — изливал на землю."],"genesis-38-10":["То, что он сделал, было зло в глазах Господа, и Он умертвил и его.","Wat hij deed, was slecht in de ogen van de Eeuwige, en Hij deed ook hem sterven.",""],"genesis-38-11":["Йегуда сказал Тамар, своей невестке: «Сиди вдовой в доме твоего отца, пока не вырастет Шела, мой сын». Ибо он сказал: «Как бы не умер и он, как его братья». Тамар пошла и жила в доме своего отца.","Jehoeda zei tegen Tamar, zijn schoondochter: «Blijf als weduwe in het huis van je vader, totdat mijn zoon Sjela groot is.» Want hij zei: «Anders sterft ook hij, zoals zijn broers.» Tamar ging weg en woonde in het huis van haar vader.","JPS: for he said; фр.: car il craignait. По-еврейски כִּי אָמַר — ибо он сказал."],"genesis-38-12":["Прошло много дней, и умерла дочь Шуа, жена Йегуды. Йегуда утешился и поднялся к стригальщикам своего скота, он и его друг Хира, адулламитянин, в Тимну.","Er gingen vele dagen voorbij, en de dochter van Sjoea, de vrouw van Jehoeda, stierf. Jehoeda was getroost en trok op naar de scheerders van zijn kudde, hij en zijn vriend Chira, de Adullamiet, naar Timna.","JPS: unto his sheep-shearers; фр.: surveiller la tonte. По-еврейски עַל־גֹּזְזֵי צֹאנוֹ — к стригальщикам его скота."],"genesis-38-13":["Тамар сказали: «Вот твой свёкор поднимается в Тимну стричь свой скот».","Men berichtte Tamar: «Zie, je schoonvader trekt op naar Timna om zijn kudde te scheren.»",""],"genesis-38-14":["Она сняла с себя одежды вдовства, закрылась покрывалом, закуталась и села у входа в Энаим, что на дороге в Тимну. Она видела, что Шела вырос, а её не отдали ему в жёны.","Zij legde haar weduwkleren af, bedekte zich met een sluier, wikkelde zich in en ging zitten bij de ingang van Enajim, aan de weg naar Timna. Zij zag dat Sjela groot was geworden en dat zij hem niet tot vrouw was gegeven.","JPS: the entrance of Enaim; фр.: le carrefour des Deux Sources. По-еврейски פֶּתַח עֵינַיִם — вход Энаим."],"genesis-38-15":["Йегуда увидел её и счёл её блудницей, потому что она закрыла лицо.","Jehoeda zag haar en hield haar voor een vrouw die zich verkoopt, omdat zij haar gezicht bedekt had.",""],"genesis-38-16":["Он свернул к ней с дороги и сказал: «Дай, я войду к тебе». Он не знал, что это его невестка. Она сказала: «Что ты дашь мне, если войдёшь ко мне?»","Hij week naar haar af, bij de weg, en zei: «Toe, laat mij bij je naar binnen gaan.» Hij wist niet dat zij zijn schoondochter was. Zij zei: «Wat geef je mij, als je bij mij naar binnen gaat?»",""],"genesis-38-17":["Он сказал: «Я пришлю козлёнка из стада». Она сказала: «Дашь ли залог, пока не пришлёшь?»","Hij zei: «Ik zal je een geitenbokje uit de kudde sturen.» Zij zei: «Geef je een pand, tot je het stuurt?»",""],"genesis-38-18":["Он сказал: «Какой залог дать тебе?» Она сказала: «Твою печать, твой шнур и твой посох, который у тебя в руке». Он дал ей это, вошёл к ней, и она зачала от него.","Hij zei: «Welk pand zal ik je geven?» Zij zei: «Je zegel, je snoer en je staf die in je hand is.» Hij gaf het haar, ging bij haar naar binnen, en zij werd zwanger van hem.","JPS: came in unto her; фр.: approcha d’elle. По-еврейски וַיָּבֹא אֵלֶיהָ — вошёл к ней."],"genesis-38-19":["Она встала, ушла, сняла с себя покрывало и надела одежды своего вдовства.","Zij stond op, ging weg, legde haar sluier af en trok haar weduwkleren aan.",""],"genesis-38-20":["Йегуда послал козлёнка с другом своим, адулламитянином, чтобы взять залог из руки этой женщины, но тот не нашёл её.","Jehoeda stuurde het geitenbokje met zijn vriend, de Adullamiet, om het pand uit de hand van de vrouw terug te nemen, maar hij vond haar niet.",""],"genesis-38-21":["Он спросил людей её места: «Где посвящённая блудница, та, что в Энаиме у дороги?» Они сказали: «Здесь не было посвящённой блудницы».","Hij vroeg de mannen van haar plaats: «Waar is de gewijde vrouw, zij die in Enajim aan de weg was?» Zij zeiden: «Hier is geen gewijde vrouw geweest.»","JPS и фр. переводят הַקְּדֵשָׁה тем же словом, что זוֹנָה в 38:15: harlot / prostituée. По-еврейски это посвящённая женщина, другое слово."],"genesis-38-22":["Он вернулся к Йегуде и сказал: «Я не нашёл её. И люди этого места сказали: „Здесь не было посвящённой блудницы“».","Hij keerde terug naar Jehoeda en zei: «Ik heb haar niet gevonden. Ook de mannen van de plaats zeiden: „Hier is geen gewijde vrouw geweest.“»","Снова קְדֵשָׁה. JPS и фр. снова harlot / prostituée, как для זוֹנָה."],"genesis-38-23":["Йегуда сказал: «Пусть оставит себе, чтобы нам не стать посмешищем. Вот я послал этого козлёнка, а ты её не нашёл».","Jehoeda zei: «Laat zij het houden, anders worden wij tot schande. Zie, ik heb dit bokje gestuurd, en jij hebt haar niet gevonden.»","JPS: put to shame; фр.: rougir. По-еврейски לָבוּז — стать предметом презрения."],"genesis-38-24":["Около трёх месяцев спустя Йегуде сказали: «Тамар, твоя невестка, блудила, и вот она беременна от блуда». Йегуда сказал: «Выведите её, и пусть её сожгут».","Ongeveer drie maanden later berichtte men Jehoeda: «Tamar, je schoondochter, heeft zich verkocht, en zie, zij is zwanger doordat zij zich verkocht heeft.» Jehoeda zei: «Breng haar naar buiten, en laat haar verbrand worden.»",""],"genesis-38-25":["Её выводили. Она послала своему свёкру сказать: «Я беременна от человека, которому принадлежит это». И сказала: «Узнай, пожалуйста, чьи эта печать, эти шнуры и этот посох».","Men bracht haar naar buiten. Zij stuurde haar schoonvader deze boodschap: «Ik ben zwanger van de man aan wie deze dingen toebehoren.» En zij zei: «Herken toch van wie dit zegel, deze snoeren en deze staf zijn.»",""],"genesis-38-26":["Йегуда узнал их и сказал: «Она праведнее меня, потому что я не отдал её Шеле, моему сыну». И он больше не был с ней.","Jehoeda herkende ze en zei: «Zij is rechtvaardiger dan ik, want ik heb haar niet gegeven aan Sjela, mijn zoon.» En hij sliep niet meer met haar.",""],"genesis-38-27":["Когда пришло ей время родить, вот во чреве у неё близнецы.","Toen het haar tijd was om te baren, zie: een tweeling was in haar schoot.",""],"genesis-38-28":["Когда она рожала, один выставил руку. Повитуха взяла и повязала ему на руку алую нить, сказав: «Этот вышел первым».","Terwijl zij baarde, stak de ene een hand uit. De vroedvrouw nam die en bond een scharlaken draad om zijn hand, en zei: «Deze is het eerst naar buiten gekomen.»",""],"genesis-38-29":["Когда он отдёрнул руку, вышел его брат. Она сказала: «Как ты прорвал себе прорыв!» И назвали его Перец.","Toen hij zijn hand terugtrok, kwam zijn broer naar buiten. Zij zei: «Wat een bres heb je voor jezelf gebroken!» En men noemde hem Perets.","JPS: Wherefore hast thou made a breach; фр.: Avec quelle violence tu te fais jour. По-еврейски מַה־פָּרַצְתָּ עָלֶיךָ פָּרֶץ — какой прорыв ты себе прорвал."],"genesis-38-30":["Потом вышел его брат, у которого на руке была алая нить, и назвали его Зерах.","Daarna kwam zijn broer naar buiten, die de scharlaken draad om zijn hand had, en men noemde hem Zerach.",""],"zechariah-2-14":["«Ликуй и радуйся, дочь Цийона, ибо вот Я прихожу и поселюсь среди тебя», — слово Господа.","«Jubel en verheug je, dochter van Tsijon, want zie, Ik kom en Ik zal in je midden wonen», — woord van de Eeuwige.",""],"zechariah-2-15":["«Многие народы примкнут к Господу в тот день и станут Моим народом. Я поселюсь среди тебя, и ты узнаешь, что Господь воинств послал меня к тебе».","«Vele volken zullen zich op die dag bij de Eeuwige aansluiten en Mij tot volk zijn. Ik zal in je midden wonen, en jij zult weten dat de Eeuwige der legerscharen mij naar jou heeft gezonden.»",""],"zechariah-2-16":["Господь возьмёт Йегуду как свою долю на святой земле и снова изберёт Йерушалаим.","De Eeuwige zal Jehoeda als zijn deel in bezit nemen op de heilige grond en Jeroesjalajim opnieuw verkiezen.",""],"zechariah-2-17":["«Умолкни, всякая плоть, перед Господом, ибо Он пробудился из своего святого жилища».","«Wees stil, alle vlees, voor de Eeuwige, want Hij is ontwaakt uit zijn heilige woning.»","JPS: all flesh; фр.: toute créature. По-еврейски כָּל־בָּשָׂר — всякая плоть."],"zechariah-3-1":["Он показал мне Йехошуа, первосвященника. Тот стоял перед посланником Господа, а обвинитель стоял по правую руку от него, чтобы обвинять его.","Hij liet mij Jehosjoea zien, de hogepriester. Die stond voor de bode van de Eeuwige, en de aanklager stond aan zijn rechterhand om hem aan te klagen.",""],"zechariah-3-2":["Господь сказал обвинителю: «Пусть Господь укорит тебя, обвинитель, пусть укорит тебя Господь, избравший Йерушалаим. Разве этот — не головня, выхваченная из огня?»","De Eeuwige zei tegen de aanklager: «Laat de Eeuwige jou bestraffen, aanklager. Laat de Eeuwige die Jeroesjalajim heeft verkozen, jou bestraffen. Is hij niet een stuk brandhout, uit het vuur gerukt?»","JPS и фр.: Satan. По-еврейски הַשָּׂטָן с артиклем — обвинитель, не имя."],"zechariah-3-3":["А Йехошуа был одет в грязные одежды и стоял перед посланником.","Jehosjoea droeg vuile kleren en stond voor de bode.",""],"zechariah-3-4":["Он ответил и сказал тем, кто стоял перед ним: «Снимите с него грязные одежды». И сказал ему: «Смотри, Я снял с тебя твою вину и одену тебя в праздничные одежды».","Hij antwoordde en zei tegen hen die voor hem stonden: «Trek de vuile kleren van hem uit.» En hij zei tegen hem: «Zie, Ik heb je schuld van je weggenomen en Ik zal je in feestkleren kleden.»","JPS: robes; фр.: habits de prix. По-еврейски מַחֲלָצוֹת — праздничные одежды."],"zechariah-3-5":["Я сказал: «Пусть наденут ему на голову чистый тюрбан». Они надели чистый тюрбан ему на голову и одели его в одежды, а посланник Господа стоял рядом.","Ik zei: «Laten zij een reine tulband op zijn hoofd zetten.» Zij zetten de reine tulband op zijn hoofd en kleedden hem in kleren, en de bode van de Eeuwige stond erbij.","JPS: mitre; фр.: tiare. По-еврейски צָנִיף — тюрбан, головная повязка."],"zechariah-3-6":["Посланник Господа засвидетельствовал Йехошуа и сказал:","De bode van de Eeuwige betuigde aan Jehosjoea en zei:","JPS: forewarned; фр.: fit cette déclaration. По-еврейски וַיָּעַד — торжественно засвидетельствовал."],"zechariah-3-7":["«Так сказал Господь воинств: „Если ты будешь ходить Моими путями и хранить Мою стражу, и если также ты будешь судить Мой дом и стеречь Мои дворы, то Я дам тебе ходить среди этих стоящих.","«Zo zegt de Eeuwige der legerscharen: „Als je op Mijn wegen gaat en Mijn wacht houdt, en als ook jij over Mijn huis rechtspreekt en Mijn voorhoven bewaakt, dan geef Ik je te lopen tussen hen die hier staan.",""],"zechariah-3-8":["Слушай же, Йехошуа, первосвященник, ты и твои товарищи, которые сидят перед тобой: они — люди-знамение. Вот Я привожу Моего раба, отрасль.","Hoor toch, Jehosjoea, hogepriester, jij en je gezellen die voor je zitten: zij zijn mannen die een teken zijn. Zie, Ik breng Mijn dienaar, de spruit.","JPS: men that are a sign; фр.: personnages de marque. По-еврейски אַנְשֵׁי מוֹפֵת — люди-знамение. צֶמַח — отрасль, не титул."],"zechariah-3-9":["Ибо вот камень, который Я положил перед Йехошуа: на одном камне семь глаз. Вот Я вырезаю на нём резьбу, — слово Господа воинств, — и сниму вину этой земли в один день.","Want zie, de steen die Ik voor Jehosjoea heb gelegd: op één steen zeven ogen. Zie, Ik graveer zijn gravering, — woord van de Eeuwige der legerscharen, — en Ik neem de schuld van dat land weg op één dag.","JPS: seven facets; фр.: sept yeux. По-еврейски עֵינַיִם — семь глаз."],"zechariah-3-10":["В тот день, — слово Господа воинств, — вы будете звать каждый своего ближнего под виноградную лозу и под смоковницу“».","Op die dag, — woord van de Eeuwige der legerscharen, — zullen jullie ieder zijn naaste roepen onder de wijnstok en onder de vijgenboom.“»",""],"zechariah-4-1":["Посланник, который говорил со мной, вернулся и разбудил меня, как человека, которого будят ото сна.","De bode die met mij sprak, kwam terug en wekte mij, als een man die uit zijn slaap wordt gewekt.",""],"zechariah-4-2":["Он сказал мне: «Что ты видишь?» Я сказал: «Я увидел, и вот светильник, весь из золота, и чаша наверху него, и семь его лампад на нём, семь и семь трубок к лампадам, которые наверху него,","Hij zei tegen mij: «Wat zie je?» Ik zei: «Ik heb gezien, en zie: een lampenstandaard, helemaal van goud, met zijn schaal bovenop, en zijn zeven lampen erop, zeven en zeven tuiten naar de lampen die bovenop hem staan,","JPS: seven pipes, yea seven; фр.: sept conduits. По-еврейски שִׁבְעָה וְשִׁבְעָה מוּצָקוֹת — семь и семь трубок."],"zechariah-4-3":["и две маслины при нём: одна справа от чаши, другая слева от неё».","en twee olijfbomen erbij, één rechts van de schaal en één links ervan.»",""],"zechariah-4-4":["Я ответил и сказал посланнику, который говорил со мной: «Что это, господин мой?»","Ik antwoordde en zei tegen de bode die met mij sprak: «Wat zijn deze dingen, mijn heer?»","JPS: my lord; фр.: Seigneur. По-еврейски אֲדֹנִי — обращение к посланнику, не имя Бога."],"zechariah-4-5":["Посланник, который говорил со мной, ответил мне: «Разве ты не знаешь, что это?» Я сказал: «Нет, господин мой».","De bode die met mij sprak antwoordde mij: «Weet je niet wat deze zijn?» Ik zei: «Nee, mijn heer.»","JPS: what these are; фр.: ce que signifient ces choses. По-еврейски מָה־הֵמָּה אֵלֶּה — что это, без «означают»."],"zechariah-4-6":["Он ответил и сказал мне: «Вот слово Господа к Зерубавелю: „Не силой и не мощью, но Моим духом, — сказал Господь воинств.","Hij antwoordde en zei tegen mij: «Dit is het woord van de Eeuwige tot Zeroebavel: „Niet door kracht en niet door vermogen, maar door Mijn geest, zegt de Eeuwige der legerscharen.",""],"zechariah-4-7":["Кто ты, великая гора, перед Зерубавелем? Стань равниной. Он вынесет верхний камень при криках: ‚Благоволение, благоволение ему!‘“».","Wie ben jij, grote berg, voor Zeroebavel? Word een vlakte. Hij zal de topsteen naar buiten brengen onder het geroep: ‚Gunst, gunst voor hem!‘“»","JPS: Grace, grace; фр.: Qu’elle est belle. По-еврейски חֵן חֵן לָהּ — благоволение камню; местоимение женского рода при אֶבֶן."],"genesis-41-53":["Семь лет изобилия, которые были в земле Египта, подошли к концу.","De zeven jaren van overvloed die er in het land Egypte waren, liepen ten einde.",""],"genesis-41-54":["Начались семь лет голода, как сказал Йосеф. Голод был во всех странах, а во всей земле Египта был хлеб.","De zeven jaren van honger braken aan, zoals Josef had gezegd. Er was honger in alle landen, maar in heel het land Egypte was er brood.",""],"genesis-41-55":["Вся земля Египта голодала, и народ воззвал к фараону о хлебе. Фараон сказал всему Египту: «Идите к Йосефу. Что он вам скажет, то и делайте».","Heel het land Egypte leed honger, en het volk riep tot de farao om brood. De farao zei tegen heel Egypte: «Ga naar Josef. Wat hij jullie zegt, dat moeten jullie doen.»",""],"genesis-41-56":["Голод был по всему лицу земли. Йосеф открыл всё, что в них было, и продавал зерно Египту. Голод в земле Египта стал сильным.","De honger lag over heel het oppervlak van de aarde. Josef opende alles wat daarin was en verkocht graan aan Egypte. De honger werd sterk in het land Egypte.",""],"genesis-41-57":["Со всей земли приходили в Египет, к Йосефу, покупать зерно, потому что голод стал сильным по всей земле.","Uit heel de aarde kwamen zij naar Egypte, naar Josef, om graan te kopen, want de honger was sterk geworden in heel de aarde.",""],"genesis-42-1":["Яаков увидел, что в Египте есть зерно, и сказал своим сыновьям: «Почему вы смотрите друг на друга?»","Jaäkov zag dat er graan was in Egypte, en hij zei tegen zijn zonen: «Waarom kijken jullie elkaar aan?»",""],"genesis-42-2":["Он сказал: «Вот, я слышал, что в Египте есть зерно. Спуститесь туда и купите нам оттуда, чтобы нам жить, а не умереть».","Hij zei: «Zie, ik heb gehoord dat er graan is in Egypte. Daal daarheen af en koop daar voor ons, zodat wij leven en niet sterven.»",""],"genesis-42-3":["Десять братьев Йосефа спустились купить зерно в Египте.","Tien broers van Josef daalden af om graan in Egypte te kopen.",""],"genesis-42-4":["Биньямина, брата Йосефа, Яаков не послал с братьями, потому что сказал: «Как бы не случилась с ним беда».","Binjamin, de broer van Josef, stuurde Jaäkov niet met zijn broers mee, want hij zei: «Anders overkomt hem een ongeluk.»",""],"genesis-42-5":["Сыновья Исраэля пришли купить зерно среди других пришедших, потому что в земле Кнаан был голод.","De zonen van Israël kwamen graan kopen te midden van de anderen die kwamen, want er was honger in het land Kenaän.",""],"genesis-42-6":["Йосеф был правителем над землёй, это он продавал зерно всему народу земли. Братья Йосефа пришли и поклонились ему лицами до земли.","Josef was de heerser over het land; hij was het die graan verkocht aan heel het volk van het land. De broers van Josef kwamen en bogen zich voor hem neer, met hun gezicht ter aarde.",""],"genesis-42-7":["Йосеф увидел своих братьев и узнал их, но держался с ними как чужой и говорил с ними жёстко. Он сказал им: «Откуда вы пришли?» Они сказали: «Из земли Кнаан, купить еду».","Josef zag zijn broers en herkende hen, maar hij deed zich aan hen als een vreemde voor en sprak hard tegen hen. Hij zei tegen hen: «Waar komen jullie vandaan?» Zij zeiden: «Uit het land Kenaän, om voedsel te kopen.»",""],"genesis-42-8":["Йосеф узнал братьев, а они его не узнали.","Josef herkende zijn broers, maar zij herkenden hem niet.",""],"genesis-42-9":["Йосеф вспомнил сны, которые он видел о них, и сказал им: «Вы шпионы. Вы пришли увидеть наготу земли».","Josef herinnerde zich de dromen die hij over hen gedroomd had, en hij zei tegen hen: «Jullie zijn spionnen. Jullie zijn gekomen om de naaktheid van het land te zien.»","JPS: nakedness of the land; фр.: côté faible. По-еврейски עֶרְוַת הָאָרֶץ — нагота земли."],"genesis-42-10":["Они сказали ему: «Нет, господин мой. Твои слуги пришли купить еду.","Zij zeiden tegen hem: «Nee, mijn heer. Je dienaren zijn gekomen om voedsel te kopen.",""],"genesis-42-11":["Все мы — сыновья одного человека, мы честные люди. Твои слуги не были шпионами».","Wij allen zijn zonen van één man, wij zijn eerlijke mensen. Je dienaren zijn geen spionnen geweest.»",""],"genesis-42-12":["Он сказал им: «Нет, вы пришли увидеть наготу земли».","Hij zei tegen hen: «Nee, jullie zijn gekomen om de naaktheid van het land te zien.»","JPS: nakedness of the land; фр.: côtés faibles. По-еврейски עֶרְוַת הָאָרֶץ — нагота земли."],"genesis-42-13":["Они сказали: «Нас, твоих слуг, двенадцать братьев, сыновей одного человека в земле Кнаан. Младший сегодня с нашим отцом, а одного нет».","Zij zeiden: «Wij, je dienaren, zijn twaalf broers, zonen van één man, in het land Kenaän. De jongste is vandaag bij onze vader, en de ene is er niet.»",""],"genesis-42-14":["Йосеф сказал им: «Именно это я вам и сказал: „вы шпионы“.","Josef zei tegen hen: «Dit is het wat ik tegen jullie gezegd heb: „jullie zijn spionnen“.",""],"genesis-42-15":["Этим вы будете испытаны. Как жив фараон, вы не выйдете отсюда, пока не придёт сюда ваш младший брат.","Hieraan zullen jullie getoetst worden. Zo waar de farao leeft: jullie gaan hier niet weg, tenzij jullie jongste broer hierheen komt.",""],"genesis-42-16":["Пошлите одного из вас, пусть он приведёт вашего брата, а вы будьте связаны. Ваши слова будут проверены: есть ли с вами правда. Если нет — как жив фараон, — вы шпионы».","Stuur één van jullie om jullie broer te halen, en blijf zelf gebonden. Jullie woorden zullen getoetst worden, of de waarheid bij jullie is. Zo niet — zo waar de farao leeft — jullie zijn spionnen.»",""],"genesis-42-17":["Он отдал их под стражу на три дня.","Hij zette hen drie dagen in bewaring.",""],"genesis-42-18":["На третий день Йосеф сказал им: «Сделайте это и живите. Бога я боюсь.","Op de derde dag zei Josef tegen hen: «Doe dit en leef. God vrees ik.","JPS: God; фр.: le Seigneur. По-еврейски הָאֱלֹהִים — Бог."],"genesis-42-19":["Если вы честные, пусть один ваш брат будет связан в доме вашей стражи, а вы идите, отвезите зерно для голода ваших домов.","Als jullie eerlijk zijn, laat dan één van jullie broers gebonden blijven in het huis van jullie bewaring, en ga heen, breng graan voor de honger van jullie huizen.",""],"genesis-42-20":["Младшего брата приведите ко мне. Тогда ваши слова подтвердятся, и вы не умрёте». Так они и сделали.","Breng jullie jongste broer bij mij. Dan zullen jullie woorden bevestigd worden, en jullie zullen niet sterven.» Zo deden zij.",""],"genesis-42-21":["Они сказали друг другу: «Правда, мы виновны перед нашим братом. Мы видели беду его души, когда он умолял нас, и не послушали. Поэтому эта беда и пришла на нас».","Zij zeiden tegen elkaar: «Werkelijk, wij zijn schuldig tegenover onze broer. Wij zagen de nood van zijn ziel toen hij ons smeekte, en wij luisterden niet. Daarom is deze nood over ons gekomen.»","JPS: guilty; фр.: punis. По-еврейски אֲשֵׁמִים — виновны."],"genesis-42-22":["Реувен ответил им: «Разве я не говорил вам: „не грешите против мальчика“, а вы не послушали? Вот, взыскивается и его кровь».","Reüven antwoordde hun: «Heb ik niet tegen jullie gezegd: „bega geen zonde tegen de jongen“, en jullie hebben niet geluisterd? Zie, ook zijn bloed wordt opgeëist.»",""],"genesis-42-23":["Они не знали, что Йосеф их понимает, потому что между ними был переводчик.","Zij wisten niet dat Josef hen verstond, want de tolk stond tussen hen in.",""],"genesis-42-24":["Он отвернулся от них и заплакал. Потом вернулся к ним, поговорил с ними, взял из них Шимона и связал его у них на глазах.","Hij keerde zich van hen af en huilde. Daarna kwam hij bij hen terug, sprak met hen, nam Sjimon uit hun midden en bond hem voor hun ogen vast.",""],"genesis-42-25":["Йосеф велел наполнить их кладь зерном, вернуть серебро каждого в его мешок и дать им припас на дорогу. Так им и сделали.","Josef gebood hun pakken met graan te vullen, ieders zilver in zijn zak terug te leggen en hun voedsel voor onderweg te geven. Zo werd het voor hen gedaan.",""],"genesis-42-26":["Они погрузили своё зерно на ослов и ушли оттуда.","Zij laadden hun graan op hun ezels en gingen daarvandaan.",""],"genesis-42-27":["Один из них открыл свой мешок, чтобы на ночлеге дать корм своему ослу, и увидел своё серебро: вот оно в отверстии его сумки.","Een van hen opende zijn zak om zijn ezel in het nachtverblijf voer te geven, en hij zag zijn zilver: zie, het lag in de opening van zijn reiszak.",""],"genesis-42-28":["Он сказал братьям: «Моё серебро возвращено, и вот оно в моей сумке». Сердце у них упало, они затрепетали и сказали друг другу: «Что это Бог сделал с нами?»","Hij zei tegen zijn broers: «Mijn zilver is teruggebracht, en zie, het ligt in mijn reiszak.» Hun hart bezweek, zij beefden en zeiden tegen elkaar: «Wat heeft God ons aangedaan?»","JPS: God hath done; фр.: le Seigneur nous prépare. По-еврейски אֱלֹהִים עָשָׂה — Бог сделал."],"genesis-42-29":["Они пришли к Яакову, своему отцу, в землю Кнаан и рассказали ему всё, что с ними случилось. Они сказали:","Zij kwamen bij Jaäkov, hun vader, in het land Kenaän en vertelden hem alles wat hun overkomen was. Zij zeiden:",""],"genesis-42-30":["«Человек, господин земли, говорил с нами жёстко и объявил нас шпионами этой земли.","«De man, de heer van het land, sprak hard met ons en zette ons neer als spionnen van het land.",""],"genesis-42-31":["Мы сказали ему: „мы честные люди, мы не были шпионами.","Wij zeiden tegen hem: „wij zijn eerlijke mensen, wij zijn geen spionnen geweest.",""],"genesis-42-32":["Нас двенадцать братьев, сыновей нашего отца. Одного нет, а младший сегодня с нашим отцом в земле Кнаан“.","Wij zijn twaalf broers, zonen van onze vader. De ene is er niet, en de jongste is vandaag bij onze vader in het land Kenaän.“",""],"genesis-42-33":["Человек, господин земли, сказал нам: „по этому я узнаю, что вы честные. Одного вашего брата оставьте у меня, возьмите на голод ваших домов и идите,","De man, de heer van het land, zei tegen ons: „hieraan zal ik weten dat jullie eerlijk zijn. Laat één van jullie broers bij mij, neem mee voor de honger van jullie huizen en ga,",""],"genesis-42-34":["а младшего брата приведите ко мне. Тогда я узнаю, что вы не шпионы, что вы честные. Вашего брата я отдам вам, и вы будете торговать в этой земле“».","en breng jullie jongste broer bij mij. Dan zal ik weten dat jullie geen spionnen zijn, dat jullie eerlijke mensen zijn. Jullie broer zal ik je geven, en jullie mogen handel drijven in het land.“»","JPS: traffic; фр.: circuler. По-еврейски תִּסְחָרוּ — будете торговать."],"genesis-42-35":["Они высыпали свои мешки, и вот у каждого в мешке узел его серебра. Они и их отец увидели узлы серебра и испугались.","Toen zij hun zakken leegden, zie: ieders bundel zilver zat in zijn zak. Zij en hun vader zagen hun bundels zilver en werden bang.",""],"genesis-42-36":["Яаков, их отец, сказал им: «Меня вы лишили детей. Йосефа нет, Шимона нет, а Биньямина хотите забрать. Всё это пало на меня».","Jaäkov, hun vader, zei tegen hen: «Mij hebben jullie van mijn kinderen beroofd. Josef is er niet, Sjimon is er niet, en Binjamin willen jullie meenemen. Dit alles is op mij neergekomen.»",""],"genesis-42-37":["Реувен сказал отцу: «Двух моих сыновей ты убьёшь, если я не приведу его к тебе. Отдай его в мою руку, и я верну его тебе».","Reüven zei tegen zijn vader: «Mijn twee zonen mag je doden als ik hem niet bij je terugbreng. Geef hem in mijn hand, en ik breng hem bij je terug.»",""],"genesis-42-38":["Он сказал: «Сын мой не спустится с вами. Его брат умер, и он один остался. Если на пути, которым вы пойдёте, с ним случится беда, вы с горем спустите мою седину в Шеол».","Hij zei: «Mijn zoon daalt niet met jullie af. Zijn broer is dood, en hij alleen is over. Overkomt hem een ongeluk op de weg die jullie gaan, dan brengen jullie mijn grijze haar in verdriet naar Sjeool.»",""],"genesis-43-1":["Голод в земле был тяжёлым.","De honger in het land was zwaar.",""],"genesis-43-2":["Когда они доели зерно, которое привезли из Египта, отец сказал им: «Вернитесь, купите нам немного еды».","Toen zij het graan opgegeten hadden dat zij uit Egypte hadden meegebracht, zei hun vader tegen hen: «Keer terug, koop een beetje voedsel voor ons.»",""],"genesis-43-3":["Йегуда сказал ему: «Тот человек строго предупредил нас: „вы не увидите моего лица, если ваш брат не будет с вами“.","Jehoeda zei tegen hem: «Die man heeft ons nadrukkelijk gewaarschuwd: „jullie zullen mijn gezicht niet zien als jullie broer niet bij jullie is“.",""],"genesis-43-4":["Если ты пошлёшь нашего брата с нами, мы спустимся и купим тебе еду.","Als je onze broer met ons meestuurt, dalen wij af en kopen wij voedsel voor je.",""],"genesis-43-5":["А если не пошлёшь, мы не спустимся, потому что тот человек сказал нам: „вы не увидите моего лица, если ваш брат не будет с вами“».","Maar als je hem niet meestuurt, dalen wij niet af, want de man heeft tegen ons gezegd: „jullie zullen mijn gezicht niet zien, tenzij jullie broer bij jullie is.“»",""],"genesis-43-6":["Исраэль сказал: «Зачем вы сделали мне зло, рассказав тому человеку, есть ли у вас ещё брат?»","Israël zei: «Waarom hebben jullie mij dit kwaad gedaan, de man te vertellen of jullie nog een broer hebben?»","JPS: whether ye had yet a brother; фр.: que vous avez encore un frère. По-еврейски הַעוֹד לָכֶם אָח — вопрос: есть ли у вас ещё брат."],"genesis-43-7":["Они сказали: «Этот человек настойчиво расспрашивал нас о нас самих и о нашей родне: „ваш отец ещё жив? есть ли у вас брат?“ Мы и ответили ему по этим словам. Разве могли мы знать, что он скажет: „сведите вашего брата вниз“?»","Zij zeiden: «Die man heeft ons dringend ondervraagd over onszelf en over onze familie: „leeft jullie vader nog? hebben jullie een broer?“ Wij hebben hem geantwoord naar die woorden. Konden wij weten dat hij zou zeggen: „breng jullie broer naar beneden“?»",""],"genesis-43-8":["Йегуда сказал Исраэлю, своему отцу: «Отпусти юношу со мной. Мы встанем и пойдём и будем жить, а не умрём — и мы, и ты, и наши малыши.","Jehoeda zei tegen Israël, zijn vader: «Stuur de jongen met mij mee. Wij zullen opstaan en gaan, en wij zullen leven en niet sterven, wij en jij en onze kleinen.",""],"genesis-43-9":["Я поручусь за него. С моей руки ты его потребуешь. Если я не приведу его к тебе и не поставлю его перед тобой, я буду виноват перед тобой все дни.","Ik sta borg voor hem. Uit mijn hand zul je hem opeisen. Als ik hem niet bij je breng en hem voor je neerzet, blijf ik alle dagen schuldig tegenover je.",""],"genesis-43-10":["Ведь если бы мы не медлили, мы бы уже дважды вернулись».","Want als wij niet hadden getalmd, waren wij nu al twee keer terug geweest.»",""],"numbers-7-54":["В восьмой день — князь сыновей Менаше, Гамлиэль, сын Педацура.","Op de achtste dag: de vorst van de zonen van Menasje, Gamliël, zoon van Pedatsoer.",""],"numbers-7-55":["Его приношение: одно серебряное блюдо, вес его сто тридцать, одна серебряная чаша в семьдесят шекелей по шекелю святилища. Оба наполнены тонкой мукой, смешанной с маслом, для мучного приношения.","Zijn offergave: één zilveren schotel, haar gewicht honderddertig, één zilveren schaal van zeventig sjekel, naar de sjekel van het heiligdom. Beide vol fijne bloem, gemengd met olie, voor een meeloffer.","У блюда в еврейском нет слова «шекель»: שְׁלֹשִׁים וּמֵאָה מִשְׁקָלָהּ. Шекель назван только у чаши. JPS добавляет shekels и к блюду."],"numbers-7-56":["один ковш, десять, из золота, полный благовоний;","één lepel, tien, van goud, vol wierook;","В стихе нет слова «шекель»: עֲשָׂרָה זָהָב. JPS и фр. добавляют sicles."],"numbers-7-57":["один молодой бык, один баран, один годовалый ягнёнок — для всесожжения;","één jonge stier, één ram, één eenjarig lam, voor een brandoffer;",""],"numbers-7-58":["один козёл — для жертвы за грех;","één geitenbok voor een zondoffer;",""],"numbers-7-59":["а для мирной жертвы — два вола, пять баранов, пять козлов, пять годовалых ягнят. Это приношение Гамлиэля, сына Педацура.","en voor het vredesoffer: twee ossen, vijf rammen, vijf bokken, vijf eenjarige lammeren. Dit is de offergave van Gamliël, zoon van Pedatsoer.","JPS: peace-offerings; фр.: sacrifice de rémunération. По-еврейски זֶבַח הַשְּׁלָמִים — мирная жертва."],"i-kings-7-40":["Хирам сделал умывальники, лопаты и чаши. Хирам закончил всю работу, которую делал для царя Шломо в доме Господа:","Chiram maakte de wasbekkens, de scheppen en de schalen. Chiram voltooide al het werk dat hij voor koning Sjlomo in het huis van de Eeuwige deed:","JPS: pots; фр.: cendriers. По-еврейски הַכִּיֹּרוֹת — умывальники, не горшки."],"i-kings-7-41":["два столба и две чаши наверший, что наверху столбов, и две сетки, чтобы покрыть две чаши наверший наверху столбов;","twee zuilen, en de twee schalen van de kapitelen boven op de zuilen, en de twee vlechtwerken om de twee schalen van de kapitelen boven op de zuilen te bedekken;",""],"i-kings-7-42":["и четыреста гранатовых яблок на две сетки, по два ряда гранатовых яблок на одну сетку, чтобы покрыть две чаши наверший, что на столбах;","en de vierhonderd granaatappels voor de twee vlechtwerken, twee rijen granaatappels voor het ene vlechtwerk, om de twee schalen van de kapitelen op de zuilen te bedekken;",""],"i-kings-7-43":["и десять подставок, и десять умывальников на подставках;","en de tien onderstellen, en de tien wasbekkens op de onderstellen;",""],"i-kings-7-44":["и одно море, и двенадцать быков под морем;","en de ene zee, en de twaalf ossen onder de zee;",""],"i-kings-7-45":["и горшки, и лопаты, и чаши. Все эти сосуды, которые Хирам сделал для царя Шломо в доме Господа, — из полированной бронзы.","en de potten, de scheppen en de schalen. Al deze voorwerpen die Chiram voor koning Sjlomo in het huis van de Eeuwige maakte, waren van gepolijst brons.","JPS: pots, brass; фр.: cendriers, cuivre. По-еврейски הַסִּירוֹת — горшки, נְחֹשֶׁת — бронза."],"i-kings-7-46":["В долине Ярдена царь отлил их в глинистой толще земли, между Суккот и Царетаном.","In de vlakte van de Jarden goot de koning ze in de dikke kleigrond, tussen Sukkot en Tsaretan.",""],"i-kings-7-47":["Шломо оставил все сосуды. Из-за чрезвычайного множества вес бронзы не был выяснен.","Sjlomo liet alle voorwerpen staan. Vanwege de zeer, zeer grote hoeveelheid werd het gewicht van het brons niet nagegaan.","JPS: brass; фр.: cuivre. По-еврейски נְחֹשֶׁת — бронза."],"i-kings-7-48":["Шломо сделал все сосуды, что в доме Господа: золотой жертвенник и стол, на котором хлеб присутствия, — из золота.","Sjlomo maakte alle voorwerpen die in het huis van de Eeuwige waren: het gouden altaar en de tafel waarop het brood van de aanwezigheid lag, van goud.","JPS: all the vessels; фр.: le reste des objets. По-еврейски כָּל־הַכֵּלִים — все сосуды."],"i-kings-7-49":["и светильники, пять справа и пять слева, перед внутренним святилищем, из чистого золота, и цветок, и лампады, и щипцы — из золота;","en de lampenstandaards, vijf rechts en vijf links, vóór het binnenste heiligdom, van zuiver goud, en de bloem, de lampen en de tangen, van goud;","JPS: flowers, tongs; фр.: fleurons, mouchettes. По-еврейски הַפֶּרַח — цветок, מֶלְקַחַיִם — щипцы."],"i-kings-7-50":["и кубки, и щипцы для нагара, и чаши, и ковши, и жаровни — из чистого золота, и петли для дверей внутреннего дома — Святая святых — и для дверей дома — Хейхала — из золота.","en de bekers, de snuiters, de schalen, de lepels en de vuurpannen, van zuiver goud, en de hengsels voor de deuren van het binnenste huis — het heilige der heiligen — en voor de deuren van het huis — de Hechal — van goud.","JPS: snuffers, fire-pans; фр.: couteaux, encensoirs. По-еврейски מְזַמְּרוֹת — щипцы для нагара, מַחְתּוֹת — жаровни."],"genesis-45-28":["Исраэль сказал: «Довольно. Йосеф, мой сын, ещё жив. Я пойду и увижу его, прежде чем умру».","Israël zei: «Het is genoeg. Josef, mijn zoon, leeft nog. Ik ga hem zien voordat ik sterf.»",""],"genesis-46-1":["Исраэль отправился со всем, что у него было, пришёл в Беэр-Шеву и принёс жертвы Богу своего отца Ицхака.","Israël ging op reis met alles wat hij had, kwam in Beër-Sjeva en bracht offers aan de God van zijn vader Jitschak.",""],"genesis-46-2":["Бог сказал Исраэлю в ночных видениях. Он сказал: «Яаков, Яаков». Тот сказал: «Вот я».","God sprak tot Israël in de visioenen van de nacht en zei: «Jaäkov, Jaäkov.» Hij antwoordde: «Hier ben ik.»",""],"genesis-46-3":["Он сказал: «Я — Бог, Бог твоего отца. Не бойся сойти в Египет, потому что там Я сделаю тебя великим народом.","Hij zei: «Ik ben God, de God van je vader. Wees niet bang om naar Egypte af te dalen, want daar zal Ik je tot een groot volk maken.","JPS: fear not; фр.: n'hésite point. По-еврейски אַל־תִּירָא — не бойся."],"genesis-46-4":["Я сам сойду с тобой в Египет, и Я же непременно выведу тебя обратно. Йосеф положит свою руку тебе на глаза».","Ik zelf zal met je naar Egypte afdalen, en Ik zal je ook zeker weer omhoog brengen. Josef zal zijn hand op je ogen leggen.»",""],"genesis-46-5":["Яаков поднялся из Беэр-Шевы. Сыновья Исраэля повезли Яакова, своего отца, своих маленьких детей и своих жён на повозках, которые фараон послал, чтобы везти его.","Jaäkov stond op uit Beër-Sjeva. De zonen van Israël brachten Jaäkov, hun vader, hun kleine kinderen en hun vrouwen weg op de wagens die de farao had gestuurd om hem te vervoeren.",""],"genesis-46-6":["Они взяли свой скот и своё имущество, которое приобрели в земле Кнаан, и пришли в Египет, Яаков и всё его потомство с ним.","Zij namen hun vee en hun have, die zij in het land Kenaän hadden verworven, en kwamen in Egypte, Jaäkov en heel zijn nageslacht met hem.",""],"genesis-46-7":["Своих сыновей и сыновей своих сыновей, своих дочерей и дочерей своих сыновей — всё своё потомство он привёл с собой в Египет.","Zijn zonen en de zonen van zijn zonen, zijn dochters en de dochters van zijn zonen, heel zijn nageslacht bracht hij met zich mee naar Egypte.",""],"genesis-46-8":["Вот имена сыновей Исраэля, пришедших в Египет. Яаков и его сыновья. Первенец Яакова — Реувен.","Dit zijn de namen van de zonen van Israël die naar Egypte kwamen. Jaäkov en zijn zonen. De eerstgeborene van Jaäkov: Reüven.",""],"genesis-46-9":["Сыновья Реувена: Ханох, Паллу, Хецрон и Карми.","De zonen van Reüven: Chanoch, Palloe, Chetsron en Karmi.",""],"genesis-46-10":["Сыновья Шимона: Йемуэль, Ямин, Охад, Яхин, Цохар и Шауль, сын кнаанеянки.","De zonen van Sjimon: Jemoeëel, Jamin, Ohad, Jachin, Tsochar en Sjaoel, de zoon van de Kenaänitische vrouw.",""],"genesis-46-11":["Сыновья Леви: Гершон, Кехат и Мерари.","De zonen van Levi: Gersjon, Kehat en Merari.",""],"genesis-46-12":["Сыновья Йегуды: Эр, Онан, Шела, Перец и Зерах. Эр и Онан умерли в земле Кнаан. Сыновьями Переца были Хецрон и Хамуль.","De zonen van Jehoeda: Er, Onan, Sjela, Perets en Zerach. Er en Onan stierven in het land Kenaän. De zonen van Perets waren Chetsron en Chamul.",""],"genesis-46-13":["Сыновья Иссахара: Тола, Пува, Йов и Шимрон.","De zonen van Jissachar: Tola, Poewa, Jov en Sjimron.",""],"genesis-46-14":["Сыновья Зевулуна: Серед, Элон и Яхлеэль.","De zonen van Zevuloen: Sered, Elon en Jachleëel.",""],"genesis-46-15":["Это сыновья Леи, которых она родила Яакову в Паддан-Араме, и Дина, его дочь. Всех душ его сыновей и дочерей — тридцать три.","Dit zijn de zonen van Lea, die zij aan Jaäkov baarde in Paddan-Aram, en Dina, zijn dochter. Alle zielen van zijn zonen en zijn dochters: drieëndertig.","JPS: Paddan-aram; фр.: territoire araméen. По-еврейски בְּפַדַּן אֲרָם — в Паддан-Араме."],"genesis-46-16":["Сыновья Гада: Цифйон, Хагги, Шуни, Эцбон, Эри, Ароди и Арели.","De zonen van Gad: Tsifjon, Chaggi, Sjoeni, Etsbon, Eri, Arodi en Areli.",""],"genesis-46-17":["Сыновья Ашера: Йимна, Йишва, Йишви, Берия и Серах, их сестра. Сыновья Берии: Хевер и Малкиэль.","De zonen van Asjer: Jimna, Jisjwa, Jisjwi, Beria en Serach, hun zuster. De zonen van Beria: Chever en Malkiëel.",""],"genesis-46-18":["Это сыновья Зилпы, которую Лаван дал Лее, своей дочери. Она родила их Яакову, шестнадцать душ.","Dit zijn de zonen van Zilpa, die Lavan aan Lea, zijn dochter, gaf. Zij baarde hen aan Jaäkov: zestien zielen.",""],"genesis-46-19":["Сыновья Рахели, жены Яакова: Йосеф и Биньямин.","De zonen van Rachel, de vrouw van Jaäkov: Josef en Binjamin.",""],"genesis-46-20":["У Йосефа в земле Египта родились дети, которых родила ему Аснат, дочь Поти-Фера, священника Она: Менаше и Эфраим.","Bij Josef werden in het land Egypte kinderen geboren, die Asnat, de dochter van Poti-Fera, priester van On, hem baarde: Menasje en Efrajim.",""],"genesis-46-21":["Сыновья Биньямина: Бела, Бехер, Ашбель, Гера, Нааман, Эхи, Рош, Муппим, Хуппим и Ард.","De zonen van Binjamin: Bela, Becher, Asjbel, Gera, Naäman, Echi, Rosj, Moeppim, Choeppim en Ard.",""],"genesis-46-22":["Это сыновья Рахели, которые родились у Яакова. Всех душ — четырнадцать.","Dit zijn de zonen van Rachel die bij Jaäkov geboren werden. Alle zielen: veertien.",""],"genesis-46-23":["Сыновья Дана: Хушим.","De zonen van Dan: Choesjim.",""],"genesis-46-24":["Сыновья Нафтали: Яхцеэль, Гуни, Йецер и Шиллем.","De zonen van Naftali: Jachtseël, Goeni, Jetser en Sjillem.",""],"genesis-46-25":["Это сыновья Билхи, которую Лаван дал Рахели, своей дочери. Она родила их Яакову. Всех душ — семь.","Dit zijn de zonen van Bilha, die Lavan aan Rachel, zijn dochter, gaf. Zij baarde hen aan Jaäkov. Alle zielen: zeven.",""],"genesis-46-26":["Всех душ, пришедших с Яаковом в Египет, вышедших из его бедра, не считая жён сыновей Яакова, — шестьдесят шесть.","Alle zielen die met Jaäkov naar Egypte kwamen, voortgekomen uit zijn dij, afgezien van de vrouwen van de zonen van Jaäkov: zesenzestig.","JPS: out of his loins; фр.: issues de lui. По-еврейски יֹצְאֵי יְרֵכוֹ — вышедшие из его бедра."],"genesis-46-27":["Сыновья Йосефа, родившиеся у него в Египте, — две души. Всех душ дома Яакова, пришедших в Египет, — семьдесят.","De zonen van Josef die hem in Egypte geboren werden: twee zielen. Alle zielen van het huis van Jaäkov die naar Egypte kwamen: zeventig.",""],"genesis-46-28":["Йегуду он послал перед собой к Йосефу, чтобы тот указал ему путь в Гошен. Они пришли в землю Гошен.","Jehoeda stuurde hij voor zich uit naar Josef, om hem de weg te wijzen naar Gosjen. Zij kwamen in het land Gosjen.","JPS: to show the way; фр.: préparât l'entrée. По-еврейски לְהוֹרֹת — указать путь."],"genesis-46-29":["Йосеф запряг свою колесницу и выехал навстречу Исраэлю, своему отцу, в Гошен. Он показался ему, упал ему на шею и ещё долго плакал у него на шее.","Josef spande zijn strijdwagen in en reed zijn vader Israël tegemoet, naar Gosjen. Hij liet zich aan hem zien, viel hem om de hals en huilde nog lang aan zijn hals.","JPS: presented himself; фр.: à sa vue. По-еврейски וַיֵּרָא אֵלָיו — он показался ему."],"genesis-46-30":["Исраэль сказал Йосефу: «Теперь я могу умереть, после того как увидел твоё лицо, ведь ты ещё жив».","Israël zei tegen Josef: «Nu kan ik sterven, nu ik je gezicht heb gezien, want je leeft nog.»",""],"genesis-46-31":["Йосеф сказал своим братьям и дому своего отца: «Я поднимусь, расскажу фараону и скажу ему: „Мои братья и дом моего отца, которые были в земле Кнаан, пришли ко мне.","Josef zei tegen zijn broers en tegen het huis van zijn vader: «Ik ga naar boven, ik vertel het de farao en ik zal tegen hem zeggen: „Mijn broers en het huis van mijn vader, die in het land Kenaän waren, zijn bij mij gekomen.",""],"genesis-46-32":["Эти люди — пастухи овец, потому что они были скотниками. Своих овец, свой крупный скот и всё, что у них есть, они привели“.","Die mannen zijn schaapherders, want zij waren veehouders. Hun schapen, hun runderen en alles wat van hen is, hebben zij meegebracht.“",""],"genesis-46-33":["Когда фараон позовёт вас и скажет: „Чем вы занимаетесь?“,","Wanneer de farao jullie laat roepen en zegt: „Wat is jullie werk?“,",""],"genesis-46-34":["вы скажете: „Твои рабы были скотниками с нашей юности и доныне, и мы, и наши отцы“. Чтобы вы жили в земле Гошен, потому что для Египта всякий пастух овец — мерзость».","dan zeggen jullie: „Jouw dienaren zijn veehouders geweest van onze jeugd af tot nu, wij en onze vaderen.“ Zo kunnen jullie in het land Gosjen wonen, want elke schaapherder is een gruwel voor Egypte.»",""],"ii-samuel-18-24":["Давид сидел между двумя воротами. Дозорный поднялся на крышу ворот, к стене, поднял глаза, посмотрел, и вот — человек бежит один.","David zat tussen de twee poorten. De wachter ging naar het dak van de poort, naar de muur, sloeg zijn ogen op, keek, en zie: een man kwam alleen aanrennen.",""],"ii-samuel-18-25":["Дозорный крикнул и сообщил царю. Царь сказал: «Если он один, во рту у него весть». Тот всё бежал и приближался.","De wachter riep en meldde het de koning. De koning zei: «Als hij alleen is, is er een bericht in zijn mond.» Hij kwam al rennend dichterbij.","JPS: tidings; фр.: bonne nouvelle. По-еврейски בְּשׂוֹרָה — весть; слово «добрая» стоит только в 18:27."],"ii-samuel-18-26":["Дозорный увидел: бежит другой человек. Дозорный крикнул привратнику: «Вот человек бежит один». Царь сказал: «И этот несёт весть».","De wachter zag een andere man rennen. De wachter riep naar de poortwachter: «Zie, een man rent alleen.» De koning zei: «Ook deze brengt bericht.»","JPS: tidings; фр.: bonne nouvelle. По-еврейски מְבַשֵּׂר — тот, кто несёт весть."],"ii-samuel-18-27":["Дозорный сказал: «Я вижу: бег первого — как бег Ахимааца, сына Цадока». Царь сказал: «Это хороший человек, и он придёт с доброй вестью».","De wachter zei: «Ik zie dat de loop van de eerste is als de loop van Achimaäts, de zoon van Tsadok.» De koning zei: «Dit is een goed man, en hij komt met een goede boodschap.»","JPS: I think; фр.: j'observe. По-еврейски אֲנִי רֹאֶה — я вижу."],"ii-samuel-18-28":["Ахимаац крикнул и сказал царю: «Благополучно». Он поклонился царю лицом до земли и сказал: «Благословен Господь, твой Бог, который отдал людей, поднявших руку на господина моего, царя».","Achimaäts riep en zei tegen de koning: «Het is goed.» Hij boog zich voor de koning, met het gezicht naar de aarde, en zei: «Gezegend is de Eeuwige, jouw God, die de mannen heeft overgegeven die hun hand hebben opgeheven tegen mijn heer de koning.»",""],"ii-samuel-18-29":["Царь сказал: «Благополучно ли с юношей, с Авшаломом?» Ахимаац сказал: «Я видел большое смятение, когда Йоав посылал слугу царя и твоего слугу, но я не знал, что это».","De koning zei: «Is het goed met de jongeman, met Avsjalom?» Achimaäts zei: «Ik zag een grote verwarring toen Joav de dienaar van de koning en jouw dienaar stuurde, maar ik wist niet wat het was.»",""],"ii-samuel-18-30":["Царь сказал: «Отойди, стань здесь». Тот отошёл и встал.","De koning zei: «Ga opzij en blijf hier staan.» Hij ging opzij en bleef staan.",""],"ii-samuel-18-31":["Вот пришёл кушит. Кушит сказал: «Пусть господин мой, царь, примет весть: сегодня Господь дал тебе суд из руки всех, кто восстал на тебя».","Daar kwam de Koesjiet. De Koesjiet zei: «Laat mijn heer de koning het bericht ontvangen: vandaag heeft de Eeuwige je recht verschaft uit de hand van allen die tegen je zijn opgestaan.»","JPS: avenged; фр.: a fait justice. По-еврейски שְׁפָטְךָ מִיַּד — дал тебе суд из руки."],"ii-samuel-18-32":["Царь сказал кушиту: «Благополучно ли с юношей, с Авшаломом?» Кушит сказал: «Пусть будут, как этот юноша, враги господина моего, царя, и все, кто восстал на тебя, чтобы сделать зло».","De koning zei tegen de Koesjiet: «Is het goed met de jongeman, met Avsjalom?» De Koesjiet zei: «Laten de vijanden van mijn heer de koning worden als die jongeman, en allen die tegen je zijn opgestaan om kwaad te doen.»",""],"ii-samuel-19-1":["Царь затрясся, поднялся в комнату над воротами и заплакал. На ходу он говорил так: «Сын мой Авшалом, сын мой, сын мой Авшалом! Если бы умер я вместо тебя, Авшалом, сын мой, сын мой!»","De koning beefde, ging naar de kamer boven de poort en huilde. Terwijl hij liep, zei hij: «Mijn zoon Avsjalom, mijn zoon, mijn zoon Avsjalom! Was ik maar gestorven in jouw plaats, Avsjalom, mijn zoon, mijn zoon!»",""],"ii-samuel-19-2":["Йоаву сообщили: «Вот царь плачет и скорбит об Авшаломе».","Aan Joav werd verteld: «Zie, de koning huilt en treurt om Avsjalom.»",""],"ii-samuel-19-3":["Избавление в тот день стало скорбью для всего народа, потому что народ услышал в тот день: «Царь горюет о своём сыне».","De redding werd op die dag tot rouw voor heel het volk, want het volk hoorde op die dag zeggen: «De koning treurt om zijn zoon.»",""],"ii-samuel-19-4":["Народ в тот день пробирался в город украдкой, как пробираются пристыженные, когда бегут с битвы.","Het volk sloop die dag de stad binnen, zoals beschaamde mensen wegsluipen wanneer zij uit de strijd vluchten.",""],"ii-samuel-19-5":["Царь закрыл лицо и закричал громким голосом: «Сын мой Авшалом! Авшалом, сын мой, сын мой!»","De koning bedekte zijn gezicht en schreeuwde met luide stem: «Mijn zoon Avsjalom! Avsjalom, mijn zoon, mijn zoon!»",""],"ii-samuel-19-6":["Йоав вошёл к царю в дом и сказал: «Сегодня ты покрыл стыдом лица всех твоих слуг, которые сегодня спасли твою жизнь, жизнь твоих сыновей и твоих дочерей, жизнь твоих жён и жизнь твоих наложниц,","Joav kwam bij de koning het huis binnen en zei: «Vandaag heb je de gezichten van al je dienaren beschaamd, die vandaag je leven hebben gered, het leven van je zonen en je dochters, het leven van je vrouwen en het leven van je bijvrouwen,",""],"ii-samuel-19-7":["тем, что любишь тех, кто тебя ненавидит, и ненавидишь тех, кто тебя любит. Сегодня ты объявил, что нет у тебя начальников и слуг. Сегодня я понял: если бы Авшалом был жив, а все мы сегодня мёртвы, тогда это было бы прямо в твоих глазах.","doordat je liefhebt wie jou haten, en haat wie jou liefhebben. Vandaag heb je verklaard dat je geen bevelhebbers en geen dienaren hebt. Vandaag zie ik: als Avsjalom had geleefd en wij allen vandaag dood waren, dan was dat recht in jouw ogen.","JPS: princes; фр.: officiers. По-еврейски שָׂרִים — начальники."],"ii-samuel-19-8":["Теперь встань, выйди и скажи по сердцу твоим слугам. Клянусь Господом: если ты не выйдешь, ни один человек не останется с тобой эту ночь. И это будет для тебя хуже всего зла, которое приходило на тебя от юности твоей доныне».","Sta nu op, ga naar buiten en spreek tot het hart van je dienaren. Ik zweer bij de Eeuwige: als jij niet naar buiten gaat, blijft er deze nacht geen mens bij je. Dat zal erger voor je zijn dan al het kwaad dat je is overkomen van je jeugd af tot nu.»",""],"ii-samuel-19-9":["Царь встал и сел в воротах. Всему народу сказали: «Вот царь сидит в воротах». Весь народ пришёл к царю, а Исраэль бежал, каждый к своим шатрам.","De koning stond op en ging in de poort zitten. Aan heel het volk werd gezegd: «Zie, de koning zit in de poort.» Heel het volk kwam voor de koning, en Israël vluchtte, ieder naar zijn tenten.",""],"genesis-49-1":["Яаков позвал своих сыновей и сказал: «Соберитесь, и я скажу вам, что случится с вами в конце дней.","Jaäkov riep zijn zonen en zei: «Kom bijeen, ik zal jullie zeggen wat jullie zal overkomen aan het einde der dagen.","JPS: end of days; фр.: la suite des jours. По-еврейски בְּאַחֲרִית הַיָּמִים — в конце дней."],"genesis-49-2":["Сойдитесь и слушайте, сыновья Яакова, слушайте Исраэля, вашего отца.","Schaar u samen en hoor, zonen van Jaäkov, hoor naar Israël, jullie vader.",""],"genesis-49-3":["Реувен, ты мой первенец, моя сила и первый плод моей крепости, превосходство достоинства и превосходство мощи.","Reüven, jij bent mijn eerstgeborene, mijn kracht en de eersteling van mijn sterkte, voorrang in waardigheid en voorrang in macht.","JPS: my might; фр.: mon orgueil. По-еврейски כֹּחִי — моя сила."],"genesis-49-4":["Неустойчив, как вода, — не тебе превосходство, потому что ты взошёл на ложе своего отца. Тогда ты осквернил моё ложе. Он взошёл.","Onstabiel als water — de voorrang is niet voor jou, want je bent op het bed van je vader geklommen. Toen heb je mijn ligplaats ontwijd. Hij klom erop.","JPS: have not the excellency, и в конце «он взошёл»; фр.: tu as perdu ta noblesse, без третьего лица. По-еврейски אַל־תּוֹתַר и עָלָה."],"genesis-49-5":["Шимон и Леви — братья. Их мечи — орудия насилия.","Sjimon en Levi zijn broers. Hun zwaarden zijn werktuigen van geweld.","מְכֵרֹתֵיהֶם тёмное: JPS kinship, фр. armes, по огласовке ближе к «их мечи»."],"genesis-49-6":["В их совет не входи, душа моя, к их собранию не примыкай, слава моя, потому что в гневе своём они убили человека и по своей воле подрезали жилы быку.","Kom niet in hun raad, mijn ziel, voeg je niet bij hun samenkomst, mijn eer, want in hun woede hebben zij een man gedood en naar eigen wil een stier de pezen doorgesneden.","JPS: houghed oxen и 3-е лицо; фр.: frappé des taureaux, обращение к душе. По-еврейски עִקְּרוּ־שׁוֹר — подрезали жилы быку, אַל־תָּבֹא — «не входи»."],"genesis-49-7":["Проклят их гнев, потому что он силён, и их ярость, потому что она жестока. Я разделю их в Яакове и рассею их в Исраэле.","Vervloekt is hun woede, want die is hevig, en hun grimmigheid, want die is hard. Ik zal hen verdelen in Jaäkov en hen verstrooien in Israël.",""],"genesis-49-8":["Йегуда, тебя будут славить твои братья. Твоя рука — на затылке твоих врагов. Сыновья твоего отца поклонятся тебе.","Jehoeda, jou zullen je broers prijzen. Je hand is op de nek van je vijanden. De zonen van je vader zullen zich voor je buigen.",""],"genesis-49-9":["Львёнок — Йегуда. От добычи, сын мой, ты поднялся. Он припал, он лёг, как лев и как львица. Кто поднимет его?","Een leeuwenwelp is Jehoeda. Van de prooi, mijn zoon, ben je opgestegen. Hij kromde zich, hij lag neer als een leeuw en als een leeuwin. Wie zal hem doen opstaan?","JPS: lioness; фр.: léopard. По-еврейски לָבִיא — львица."],"genesis-49-10":["Не отойдёт посох от Йегуды и жезл правителя из промежутка между его ног, пока не придёт Шило, и ему — покорность народов.","De staf zal niet wijken van Jehoeda, noch de heersersstaf van tussen zijn voeten, totdat Sjilo komt, en hem behoort de gehoorzaamheid van de volken.","שִׁילֹה неясно: JPS добавляет men и меняет синтаксис, фр. Pacifique — мессианский пересказ, по-еврейски עַד כִּי־יָבֹא שִׁילֹה — пока не придёт Шило."],"genesis-49-11":["Он привязывает к лозе своего ослёнка и к отборной лозе сына своей ослицы. В вине он стирает свою одежду, в крови винограда — своё одеяние.","Hij bindt aan de wijnstok zijn ezeljong en aan de edele rank het jong van zijn ezelin. In wijn wast hij zijn kleed, in druivenbloed zijn gewaad.",""],"genesis-49-12":["Тёмно-красные глаза от вина и белые зубы от молока.","Donkerrode ogen van wijn, en witte tanden van melk.","JPS: red with wine; фр.: pétillants. По-еврейски חַכְלִילִי — тёмно-красные, покрасневшие."],"genesis-49-13":["Зевулун будет жить у берега морей. Он — берег для кораблей, и его край у Цидона.","Zevuloen zal wonen aan de oever van de zeeën. Hij is een oever voor schepen, en zijn flank ligt bij Tsidon.","JPS: his flank; фр.: sa plage. По-еврейски יַרְכָתוֹ — его бок, край."],"genesis-49-14":["Иссахар — костистый осёл, он лежит между загонами.","Jissachar is een bonkige ezel, hij ligt tussen de schaapskooien.","JPS: large-boned ass, sheep-folds; фр.: âne musculeux, collines. По-еврейски חֲמֹר גָּרֶם — костистый осёл, הַמִּשְׁפְּתָיִם — загоны."],"genesis-49-15":["Он увидел, что покой хорош и что земля приятна, подставил плечо, чтобы нести, и стал рабом барщины.","Hij zag dat de rust goed was en het land aangenaam. Hij boog zijn schouder om te dragen en werd een knecht voor herendienst.","JPS: the land, servant under task-work; фр.: pâturage, tributaire. По-еврейски הָאָרֶץ — земля, לְמַס־עֹבֵד — раб барщины."],"genesis-49-16":["Дан будет судить свой народ, как одно из колен Исраэля.","Dan zal zijn volk richten, als een van de stammen van Israël.","JPS: as one of the tribes; фр.: sous lui se grouperont les tribus. По-еврейски כְּאַחַד שִׁבְטֵי יִשְׂרָאֵל — как одно из колен."],"genesis-49-17":["Дан будет змеем на дороге, рогатой змеёй на тропе, он жалит коня в пятки, и всадник падает назад.","Dan zal een slang op de weg zijn, een hoornslang op het pad, die de hielen van het paard bijt, zodat zijn ruiter achterover valt.","JPS: horned snake, heels; фр.: aspic, le pied. По-еврейски שְׁפִיפֹן — рогатая змея, עִקְּבֵי — пятки."],"genesis-49-18":["Твоего спасения жду я, Господь.","Op Uw redding wacht ik, Eeuwige.","JPS: salvation; фр.: assistance. По-еврейски יְשׁוּעָתְךָ — Твоё спасение."],"genesis-49-19":["Гад: отряд будет набегать на него, а он набежит им в пяту.","Gad: een bende zal hem overvallen, en hij valt aan op de hiel.","JPS сохраняет heel; фр. без пятки. По-еврейски עָקֵב — пята."],"genesis-49-20":["У Ашера тучен его хлеб, и он даст лакомства царя.","Van Asjer is zijn brood vet, en hij geeft lekkernijen van een koning.","JPS: his bread shall be fat; фр.: production abondante. По-еврейски שְׁמֵנָה לַחְמוֹ — тучен его хлеб."],"genesis-49-21":["Нафтали — лань, пущенная на волю. Он даёт прекрасные слова.","Naftali is een hinde die losgelaten is. Hij geeft schone woorden.",""],"genesis-49-22":["Плодоносный сын — Йосеф, плодоносный сын у источника. Дочери шагнули на стену.","Een vruchtbare zoon is Josef, een vruchtbare zoon bij een bron. Dochters schreden over de muur.","JPS: fruitful vine, branches; фр.: rameau fertile. По-еврейски בֵּן פֹּרָת — плодоносный сын, בָּנוֹת — дочери."],"genesis-49-23":["Его огорчили, стреляли в него и возненавидели его владельцы стрел.","Zij verbitterden hem, zij schoten op hem en haatten hem, de meesters van de pijlen.",""],"genesis-49-24":["Но его лук остался твёрд, и мышцы его рук стали гибки — от рук Могучего Яакова, оттуда Пастырь, Камень Исраэля,","Maar zijn boog bleef vast, en de spieren van zijn armen werden lenig, door de handen van de Machtige van Jaäkov, vandaar de Herder, de Steen van Israël,","וַיָּפֹזּוּ спорно: JPS supple, фр. fermes, а конец фр. пересказывает как «готовил жизнь скале»; по-еврейски Пастырь и Камень Исраэля."],"genesis-49-25":["от Бога твоего отца, и Он поможет тебе, и от Шаддая, и Он благословит тебя благословениями неба сверху, благословениями бездны, что залегла внизу, благословениями грудей и утробы.","van de God van je vader, en Hij zal je helpen, en van Sjaddai, en Hij zal je zegenen met zegeningen van de hemel boven, zegeningen van de diepte die beneden neerligt, zegeningen van borsten en schoot.","JPS: the Almighty; фр.: le Tout-Puissant. В стихе имя שַׁדַּי, не перевод «Всемогущий»."],"genesis-49-26":["Благословения твоего отца сильнее благословений моих родителей, до края вечных холмов. Они будут на голове Йосефа и на темени отделённого среди его братьев.","De zegeningen van je vader zijn sterker dan de zegeningen van mijn ouders, tot de grens van de eeuwige heuvels. Zij zullen op het hoofd van Josef zijn en op de schedel van de afgezonderde onder zijn broers.","JPS: prince; фр.: l'Élu. По-еврейски נְזִיר אֶחָיו — отделённый среди братьев."],"genesis-49-27":["Биньямин — волк, он рвёт. Утром он ест добычу, а к вечеру делит награбленное».","Binjamin is een wolf die verscheurt. In de morgen eet hij de prooi, en tegen de avond verdeelt hij de buit.»",""],"genesis-49-28":["Все эти — двенадцать колен Исраэля, и вот что сказал им их отец. Он благословил их, каждого по его благословению он благословил.","Dit alles zijn de twaalf stammen van Israël, en dit is wat hun vader tot hen sprak. Hij zegende hen, ieder naar zijn eigen zegen zegende hij hen.",""],"genesis-49-29":["Он дал им наказ и сказал им: «Меня забирают к моему народу. Похороните меня с моими отцами в пещере, которая на поле Эфрона-хетта,","Hij gebood hun en zei tegen hen: «Ik word verzameld bij mijn volk. Begraaf mij bij mijn vaderen in de grot die op het veld van Efron de Chitti ligt,",""],"genesis-49-30":["в пещере, которая на поле Махпела, что против Мамре, в земле Кнаан. Это поле Авраам купил у Эфрона-хетта во владение для погребения,","in de grot die op het veld Machpela ligt, tegenover Mamre, in het land Kenaän. Dat veld kocht Abraham van Efron de Chitti als eigen grafgrond,",""],"genesis-49-31":["там похоронили Авраама и Сару, его жену, там похоронили Ицхака и Ривку, его жену, и там я похоронил Леу.","daar begroeven zij Abraham en Sara, zijn vrouw, daar begroeven zij Jitschak en Rivka, zijn vrouw, en daar begroef ik Lea.",""],"genesis-49-32":["Купля поля и пещеры, которая на нём, — у сыновей Хета».","De koop van het veld en de grot die daarin is, van de zonen van Chet.»",""],"genesis-49-33":["Яаков закончил давать наказ своим сыновьям, подобрал ноги на постель, испустил дыхание и был взят к своим народам.","Jaäkov was klaar met zijn zonen te gebieden. Hij trok zijn voeten op het bed, blies de adem uit en werd verzameld bij zijn volken.",""],"genesis-50-22":["Йосеф жил в Египте, он и дом его отца. Йосеф прожил сто десять лет.","Josef woonde in Egypte, hij en het huis van zijn vader. Josef leefde honderdtien jaar.",""],"genesis-50-23":["Йосеф видел у Эфраима сыновей третьего поколения. Также сыновья Махира, сына Менаше, родились на коленях Йосефа.","Josef zag van Efrajim zonen van het derde geslacht. Ook de zonen van Machir, de zoon van Menasje, werden op de knieën van Josef geboren.",""],"genesis-50-24":["Йосеф сказал своим братьям: «Я умираю. Бог непременно вспомнит о вас и выведет вас из этой земли в землю, о которой Он клялся Аврааму, Ицхаку и Яакову».","Josef zei tegen zijn broers: «Ik sterf. God zal zeker aan jullie denken en jullie uit dit land brengen naar het land dat Hij onder ede heeft beloofd aan Abraham, aan Jitschak en aan Jaäkov.»","JPS: remember; фр.: visitera. По-еврейски פָּקֹד יִפְקֹד — непременно вспомнит, обратит внимание."],"genesis-50-25":["Йосеф взял клятву с сыновей Исраэля и сказал: «Бог непременно вспомнит о вас, и вы вынесете мои кости отсюда».","Josef nam een eed af van de zonen van Israël en zei: «God zal zeker aan jullie denken, en dan brengen jullie mijn beenderen hiervandaan.»","JPS: remember; фр.: visitera. По-еврейски פָּקֹד יִפְקֹד — непременно вспомнит, обратит внимание."],"genesis-50-26":["Йосеф умер ста десяти лет. Его набальзамировали и положили в гроб в Египте.","Josef stierf, honderdtien jaar oud. Men balsemde hem en legde hem in een kist in Egypte.",""],"isaiah-38-9":["Запись Хизкиягу, царя Йегуды, когда он болел и выжил от своей болезни.","Het geschrift van Chizkiahoe, koning van Jehoeda, toen hij ziek was en van zijn ziekte in leven bleef.","JPS: writing; фр.: cantique. По-еврейски מִכְתָּב — запись."],"isaiah-38-10":["Я сказал: «В половине моих дней я войду во врата Шеола. Я лишён остатка моих лет».","Ik zei: «In de helft van mijn dagen zal ik de poorten van Sjeool binnengaan. Ik ben beroofd van de rest van mijn jaren.»","JPS: noontide of my days; фр.: ruine de mes jours. По-еврейски בִּדְמִי יָמַי — в половине моих дней."],"isaiah-38-11":["Я сказал: «Не увижу я Господа, Господа, в земле живых. Не взгляну больше на человека среди жителей преходящего».","Ik zei: «Ik zal de Eeuwige, de Eeuwige, niet zien in het land van de levenden. Ik zal geen mens meer aanschouwen bij de bewoners van het vergankelijke.»","В стихе дважды краткое יָהּ, не полное יהוה. JPS: the LORD; фр.: Dieu, mon Dieu. חָדֶל: JPS world, фр. néant — преходящее."],"isaiah-38-12":["Моё жилище снято и унесено от меня, как шатёр пастуха. Я скатал, как ткач, свою жизнь. От свисающих нитей Он отрежет меня. От дня до ночи Ты покончишь со мной.","Mijn woning is afgebroken en van mij weggedragen, als een tent van een herder. Ik heb als een wever mijn leven opgerold. Van de losse draden snijdt Hij mij af. Van dag tot nacht maakt U een einde aan mij.",""],"isaiah-38-13":["Я держался до утра. Как лев, так Он дробит все мои кости. От дня до ночи Ты покончишь со мной.","Ik hield mij tot de morgen. Als een leeuw, zo verbrijzelt Hij al mijn beenderen. Van dag tot nacht maakt U een einde aan mij.","JPS относит «как лев» к говорящему; фр. — к тому, кто ломает кости. По-еврейски כָּאֲרִי כֵּן יְשַׁבֵּר — как лев, так он дробит."],"isaiah-38-14":["Как ласточка, как журавль, так я щебечу, стону, как голубь. Глаза мои истомились, глядя ввысь. Владыка, мне тесно, будь мне порукой.","Als een zwaluw, als een kraanvogel, zo kwetter ik, ik kreun als een duif. Mijn ogen zijn moe van het opzien. Heer, het is mij te nauw, wees mijn borg.","Обращение אֲדֹנָי, не יהוה: Владыка / Heer. JPS: swallow or a crane; фр.: только hirondelle. По-еврейски סוּס и עָגוּר — ласточка и журавль."],"isaiah-38-15":["Что мне сказать? Он сказал мне, и Он сделал это. Все мои годы я буду ходить тихо из-за горечи моей души.","Wat zal ik zeggen? Hij heeft tot mij gesproken, en Hij heeft het gedaan. Al mijn jaren zal ik langzaam gaan om de bitterheid van mijn ziel.","JPS: go softly; фр.: avec humilité. По-еврейски אֶדַּדֶּה — пойду медленно, без «смирения»."],"isaiah-38-16":["Владыка, ими живут, и во всём, что в них, — жизнь моего духа. Укрепи меня и оживи меня.","Heer, daardoor leven zij, en in alles daarin is het leven van mijn geest. Maak mij sterk en laat mij leven.","Обращение אֲדֹנָי, не יהוה: Владыка / Heer. Стих тёмный: JPS — просьба укрепить и оживить, фр. делает из этого долг живущих и прошедшее «ты вернул силы»."],"isaiah-38-17":["Вот, ради цельности горько было мне, горько. А Ты в любви удержал мою душу от ямы гибели, потому что бросил за Свою спину все мои грехи.","Zie, om heelheid was het mij bitter, bitter. Maar U hebt in liefde mijn ziel van de kuil van het verderf afgehouden, want U hebt al mijn zonden achter Uw rug geworpen.","JPS: for my peace I had bitterness; фр.: горечь сменилась миром. По-еврейски לְשָׁלוֹם מַר־לִי מָר — ради цельности горько было."],"isaiah-38-18":["Ведь не Шеол славит Тебя, не смерть хвалит Тебя. Сходящие в яму не надеются на Твою истину.","Want Sjeool looft U niet, de dood prijst U niet. Wie in de kuil afdalen, hopen niet op Uw waarheid.",""],"isaiah-38-19":["Живой, живой — он славит Тебя, как я сегодня. Отец детям возвещает Твою истину.","De levende, de levende, hij looft U, zoals ik vandaag. De vader maakt aan de kinderen Uw waarheid bekend.",""],"isaiah-38-20":["Господь — чтобы спасти меня. Мои песни мы будем играть на струнах все дни нашей жизни у дома Господа.","De Eeuwige is er om mij te redden. Mijn snarenspel zullen wij spelen, al de dagen van ons leven, bij het huis van de Eeuwige.","JPS: the LORD is ready to save me; фр.: je te dois mon salut. По-еврейски יְהֹוָה לְהוֹשִׁיעֵנִי — Господь, чтобы спасти меня."],"exodus-3-1":["Моше пас стадо Йитро, своего тестя, священника Мидьяна. Он повёл стадо в заднюю часть пустыни и пришёл к горе Бога, к Хореву.","Mosje hoedde de kudde van Jitro, zijn schoonvader, de priester van Midjan. Hij dreef de kudde naar de achterkant van de woestijn en kwam bij de berg van God, bij Chorev.","Фр.: bétail, montagne divine. По-еврейски צֹאן и הַר הָאֱלֹהִים — стадо и гора Бога."],"exodus-3-2":["Посланник Господа явился ему в пламени огня из середины куста. Он увидел: вот, куст горит огнём, а куст не сгорает.","De bode van de Eeuwige verscheen aan hem in een vuurvlam uit het midden van de struik. Hij zag, en zie: de struik brandde in het vuur, en de struik werd niet verteerd.","JPS: angel of the LORD; фр.: ange du Seigneur. По-еврейски מַלְאַךְ יְהוָה — посланник Господа. הַסְּנֶה — куст."],"exodus-3-3":["Моше сказал: «Сверну-ка я и посмотрю на это великое зрелище: почему куст не сгорает?»","Mosje zei: «Laat ik afwijken en deze grote aanblik bekijken: waarom verbrandt de struik niet?»","Фр.: m’approcher. По-еврейски אָסֻרָה — сверну в сторону."],"exodus-3-4":["Господь увидел, что он свернул посмотреть, и Бог позвал его из середины куста и сказал: «Моше, Моше». Он сказал: «Вот я».","De Eeuwige zag dat hij afweek om te kijken, en God riep hem uit het midden van de struik en zei: «Mosje, Mosje.» Hij zei: «Hier ben ik.»","Фр.: s’approchait. По-еврейски סָר לִרְאוֹת — свернул посмотреть."],"exodus-3-5":["Он сказал: «Не подходи сюда. Сними свою обувь с ног, потому что место, на котором ты стоишь, — святая земля».","Hij zei: «Kom hier niet dichterbij. Trek je schoenen van je voeten, want de plaats waarop jij staat, is heilige grond.»",""],"exodus-3-6":["Он сказал: «Я — Бог твоего отца, Бог Авраама, Бог Ицхака и Бог Яакова». Моше закрыл лицо, потому что боялся смотреть на Бога.","Hij zei: «Ik ben de God van je vader, de God van Abraham, de God van Jitschak en de God van Jaäkov.» Mosje verborg zijn gezicht, want hij was bang om naar God te kijken.","Фр.: la Divinité de ton père, regarder le Seigneur. По-еврейски אֱלֹהִים — Бог, и перед Авраамом, Ицхаком и Яаковом слово повторено."],"exodus-3-7":["Господь сказал: «Я действительно увидел страдание Моего народа, который в Мицраиме, и услышал их вопль из-за его надсмотрщиков, потому что Я знаю его боли.","De Eeuwige zei: «Ik heb werkelijk de ellende gezien van Mijn volk dat in Mitsrajim is, en Ik heb hun kreet gehoord vanwege zijn opzichters, want Ik ken zijn pijnen.","Фр.: humiliation. По-еврейски עֳנִי — страдание."],"exodus-3-8":["Я сошёл, чтобы спасти его из руки Мицраима и поднять его из той земли в землю хорошую и просторную, в землю, текущую молоком и мёдом, на место кнаани, хеттов, эмори, перизеев, хивви и евусеев.","Ik ben neergedaald om hem te redden uit de hand van Mitsrajim en hem uit dat land omhoog te brengen, naar een goed en wijd land, naar een land dat overvloeit van melk en honing, naar de plaats van de Kenaäniet, de Chitti, de Emori, de Perizzi, de Chivvi en de Jevusiet.","Фр.: Je suis intervenu, contrée fertile. По-еврейски וָאֵרֵד — Я сошёл, אֶרֶץ טוֹבָה — хорошая земля."],"exodus-3-9":["А теперь вот, вопль сыновей Исраэля дошёл до Меня, и Я также увидел гнёт, которым Мицраим теснит их.","En nu, zie, de kreet van de zonen van Israël is tot Mij gekomen, en Ik heb ook de verdrukking gezien waarmee Mitsrajim hen verdrukt.",""],"exodus-3-10":["Теперь иди. Я пошлю тебя к фараону, и выведи Мой народ, сыновей Исраэля, из Мицраима».","Ga nu. Ik zend je naar de farao, en leid Mijn volk, de zonen van Israël, uit Mitsrajim.»",""],"exodus-3-11":["Моше сказал Богу: «Кто я, чтобы идти к фараону и вывести сыновей Исраэля из Мицраима?»","Mosje zei tegen God: «Wie ben ik, dat ik naar de farao zou gaan en de zonen van Israël uit Mitsrajim zou leiden?»","Фр.: au Seigneur. По-еврейски אֶל־הָאֱלֹהִים — Богу."],"exodus-3-12":["Он сказал: «Я буду с тобой, и вот тебе знак, что Я послал тебя: когда ты выведешь народ из Мицраима, вы будете служить Богу на этой горе».","Hij zei: «Ik zal met je zijn, en dit is voor jou het teken dat Ik je gezonden heb: wanneer jij het volk uit Mitsrajim hebt geleid, zullen jullie God dienen op deze berg.»","Фр.: vous adorerez le Seigneur. По-еврейски תַּעַבְדוּן אֶת־הָאֱלֹהִים — вы будете служить Богу. אֶהְיֶה עִמָּךְ здесь «Я буду с тобой», не имя из 3:14."],"exodus-3-13":["Моше сказал Богу: «Вот, я приду к сыновьям Исраэля и скажу им: „Бог ваших отцов послал меня к вам“. А они скажут мне: „Как Его имя?“ Что я скажу им?»","Mosje zei tegen God: «Zie, ik kom bij de zonen van Israël en ik zal tegen hen zeggen: „De God van jullie vaderen heeft mij naar jullie gezonden.“ En zij zullen tegen mij zeggen: „Wat is Zijn naam?“ Wat zal ik tegen hen zeggen?»",""],"exodus-3-14":["Бог сказал Моше: «Я буду тем, кем буду». И Он сказал: «Так скажи сыновьям Исраэля: „«Я буду» послал меня к вам“».","God zei tegen Mosje: «Ik zal zijn die Ik zijn zal.» En Hij zei: «Zo zul je tegen de zonen van Israël zeggen: „«Ik zal zijn» heeft mij naar jullie gezonden.“»","JPS: I AM THAT I AM, I AM. Фр.: l’Être invariable. По-еврейски אֶהְיֶה אֲשֶׁר אֶהְיֶה — «Я буду тем, кем буду»; короткое אֶהְיֶה — «Я буду»."],"exodus-3-15":["Бог сказал Моше ещё: «Так скажи сыновьям Исраэля: „Господь, Бог ваших отцов, Бог Авраама, Бог Ицхака и Бог Яакова, послал меня к вам. Это Моё имя навеки, и это Моё поминание из рода в род“.","God zei nog tegen Mosje: «Zo zul je tegen de zonen van Israël zeggen: „De Eeuwige, de God van jullie vaderen, de God van Abraham, de God van Jitschak en de God van Jaäkov, heeft mij naar jullie gezonden. Dit is Mijn naam voor eeuwig, en dit is Mijn gedachtenis van geslacht tot geslacht.“","Фр.: mon attribut. По-еврейски זִכְרִי — Моё поминание."],"exodus-3-16":["Иди, собери старейшин Исраэля и скажи им: „Господь, Бог ваших отцов, явился мне, Бог Авраама, Ицхака и Яакова, и сказал: Я действительно отметил вас и то, что делают с вами в Мицраиме.","Ga, verzamel de oudsten van Israël en zeg tegen hen: „De Eeuwige, de God van jullie vaderen, is aan mij verschenen, de God van Abraham, Jitschak en Jaäkov, en Hij heeft gezegd: Ik heb werkelijk acht geslagen op jullie en op wat men jullie in Mitsrajim aandoet.","JPS: remembered; фр.: fixé mon attention. По-еврейски פָּקֹד פָּקַדְתִּי — действительно отметил. В 3:16 одно אֱלֹהֵי на Авраама, Ицхака и Яакова."],"exodus-3-17":["Я сказал: Я подниму вас из страдания Мицраима в землю кнаани, хеттов, эмори, перизеев, хивви и евусеев, в землю, текущую молоком и мёдом“.","Ik heb gezegd: Ik zal jullie uit de ellende van Mitsrajim omhoog brengen naar het land van de Kenaäniet, de Chitti, de Emori, de Perizzi, de Chivvi en de Jevusiet, naar een land dat overvloeit van melk en honing.“","Фр.: servage. По-еврейски עֳנִי — страдание. אַעֲלֶה — подниму."],"exodus-3-18":["Они послушают твоего голоса. Ты придёшь, ты и старейшины Исраэля, к царю Мицраима и скажете ему: „Господь, Бог евреев, встретился нам. Теперь пойдём же путём трёх дней в пустыню и принесём жертву Господу, нашему Богу“.","Zij zullen naar je stem luisteren. Jij komt, jij en de oudsten van Israël, bij de koning van Mitsrajim, en jullie zeggen tegen hem: „De Eeuwige, de God van de Hebreeërs, is ons tegengekomen. Laten wij nu een weg van drie dagen de woestijn in gaan en offeren aan de Eeuwige, onze God.“","Фр.: s’est manifesté. По-еврейски נִקְרָה עָלֵינוּ — встретился нам."],"exodus-3-19":["А Я знаю, что царь Мицраима не даст вам пойти, и не сильной рукой.","Maar Ik weet dat de koning van Mitsrajim jullie niet zal laten gaan, en niet door een sterke hand.","Тёмное место: וְלֹא בְּיָד חֲזָקָה. JPS добавляет except и читает наоборот: «разве что сильной рукой». Фр.: pas même en présence d’une puissance supérieure. Переведено по написанному: и не сильной рукой."],"exodus-3-20":["Я протяну Свою руку и поражу Мицраим всеми Моими чудесами, которые сделаю среди него, и после этого он отпустит вас.","Ik zal Mijn hand uitstrekken en Mitsrajim treffen met al Mijn wonderen die Ik in zijn midden zal doen, en daarna zal hij jullie laten gaan.",""],"exodus-3-21":["Я дам этому народу расположение в глазах Мицраима. И будет: когда вы пойдёте, вы не пойдёте пустыми.","Ik zal dit volk gunst geven in de ogen van Mitsrajim. En het zal zo zijn: wanneer jullie gaan, gaan jullie niet leeg weg.",""],"exodus-3-22":["Женщина попросит у своей соседки и у пришелицы своего дома сосуды серебра, сосуды золота и одежды. Вы положите их на своих сыновей и на своих дочерей и оберете Мицраим».","Een vrouw zal vragen van haar buurvrouw en van de vreemdelinge in haar huis: zilveren voorwerpen, gouden voorwerpen en kleren. Jullie leggen ze op jullie zonen en op jullie dochters, en jullie plunderen Mitsrajim.»","JPS: her that sojourneth, jewels, raiment; фр.: l’habitante, vases, parures. По-еврейски גָּרַת — пришелица, כְּלֵי — сосуды, שְׂמָלֹת — одежды."],"exodus-4-1":["Моше ответил и сказал: «Но вот, они не поверят мне и не послушают моего голоса, потому что скажут: „Господь не явился тебе“».","Mosje antwoordde en zei: «Maar zie, zij zullen mij niet geloven en niet naar mijn stem luisteren, want zij zullen zeggen: „De Eeuwige is aan jou niet verschenen.“»",""],"exodus-4-2":["Господь сказал ему: «Что это у тебя в руке?» Он сказал: «Посох».","De Eeuwige zei tegen hem: «Wat is dat in je hand?» Hij zei: «Een staf.»",""],"exodus-4-3":["Он сказал: «Брось его на землю». Он бросил его на землю, тот стал змеёй, и Моше побежал от него.","Hij zei: «Werp hem op de grond.» Hij wierp hem op de grond, hij werd een slang, en Mosje vluchtte voor hem weg.",""],"exodus-4-4":["Господь сказал Моше: «Протяни руку и схвати его за хвост». Он протянул руку, схватил его, и тот стал посохом в его ладони.","De Eeuwige zei tegen Mosje: «Steek je hand uit en grijp hem bij de staart.» Hij stak zijn hand uit, greep hem, en hij werd een staf in zijn handpalm.",""],"exodus-4-5":["«Чтобы они поверили, что тебе явился Господь, Бог их отцов, Бог Авраама, Бог Ицхака и Бог Яакова».","«Zodat zij geloven dat de Eeuwige, de God van hun vaderen, de God van Abraham, de God van Jitschak en de God van Jaäkov, aan jou verschenen is.»",""],"exodus-4-6":["Господь сказал ему ещё: «Положи свою руку себе за пазуху». Он положил руку себе за пазуху, вынул её, и вот его рука прокажённая, как снег.","De Eeuwige zei nog tegen hem: «Leg je hand in je boezem.» Hij legde zijn hand in zijn boezem, haalde haar eruit, en zie: zijn hand was melaats, als sneeuw.","JPS: as white as snow; фр.: blanche comme la neige. По-еврейски כַּשָּׁלֶג — как снег, без слова «белая»."],"exodus-4-7":["Он сказал: «Верни руку себе за пазуху». Он вернул руку себе за пазуху, вынул её из пазухи, и вот она снова стала как его плоть.","Hij zei: «Leg je hand terug in je boezem.» Hij legde zijn hand terug in zijn boezem, haalde haar eruit, en zie: zij was weer geworden als zijn vlees.",""],"exodus-4-8":["«И будет: если они не поверят тебе и не послушают голоса первого знака, они поверят голосу последнего знака.","«En het zal zo zijn: als zij jou niet geloven en niet luisteren naar de stem van het eerste teken, zullen zij de stem van het laatste teken geloven.","Фр.: prodige. По-еврейски הָאֹת — знак."],"exodus-4-9":["И будет: если они не поверят и этим двум знакам и не послушают твоего голоса, возьми воды из реки и вылей на сушу. И вода, которую ты возьмёшь из реки, станет кровью на суше».","En het zal zo zijn: als zij ook deze twee tekenen niet geloven en niet naar je stem luisteren, neem dan water uit de rivier en giet het op het droge. En het water dat je uit de rivier neemt, zal bloed worden op het droge.»","Фр.: prodiges, sur la terre. По-еврейски הָאֹתוֹת — знаки, הַיַּבָּשָׁה — суша."],"exodus-4-10":["Моше сказал Господу: «Прошу, Владыка, я не человек слов: ни со вчерашнего дня, ни с третьего дня, ни с тех пор, как Ты говоришь Своему слуге, потому что я тяжёл устами и тяжёл языком».","Mosje zei tegen de Eeuwige: «Alstublieft, Heer, ik ben geen man van woorden, niet sinds gisteren, niet sinds eergisteren, en niet sinds U tot Uw dienaar spreekt, want ik ben zwaar van mond en zwaar van tong.»","В стихе יְהֹוָה и написанное אֲדֹנָי: Господь и Владыка. Моше говорит Богу на Ты. JPS сжимает «вчера» и «третьего дня» в heretofore. Фр. ставит tu."],"exodus-4-11":["Господь сказал ему: «Кто дал человеку уста? Или кто делает немым, или глухим, или зрячим, или слепым? Разве не Я, Господь?","De Eeuwige zei tegen hem: «Wie heeft de mens een mond gegeven? Of wie maakt iemand stom, of doof, of ziend, of blind? Ben Ik het niet, de Eeuwige?",""],"exodus-4-12":["Теперь иди. Я буду с твоими устами и научу тебя, что говорить».","Ga nu. Ik zal met je mond zijn en je leren wat je spreken zult.»","Фр.: je seconderai ta parole, je t’inspirerai. По-еврейски אֶהְיֶה עִם־פִּיךָ וְהוֹרֵיתִיךָ — буду с твоими устами и научу тебя."],"exodus-4-13":["Он сказал: «Прошу, Владыка, пошли же рукой того, кого Ты пошлёшь».","Hij zei: «Alstublieft, Heer, zend toch door de hand van wie U zenden zult.»","Фр.: donne cette mission à quelque autre. По-еврейски שְׁלַח־נָא בְּיַד־תִּשְׁלָח — пошли рукой того, кого пошлёшь. Написанное אֲדֹנָי: Владыка."],"exodus-4-14":["И вспыхнул гнев Господа на Моше, и Он сказал: «Разве нет Аарона, твоего брата, левита? Я знаю, что он действительно говорит. И вот он выходит тебе навстречу, увидит тебя и возрадуется в своём сердце.","De toorn van de Eeuwige ontbrandde tegen Mosje, en Hij zei: «Is Aharon, je broer, de Leviet, er niet? Ik weet dat hij werkelijk spreekt. En zie, hij komt je tegemoet, hij zal je zien en zich in zijn hart verheugen.","Фр. добавляет que je désigne и делает из דַבֵּר יְדַבֵּר будущее «он будет говорить». По-еврейски: Я знаю, что он действительно говорит."],"exodus-4-15":["Ты будешь говорить ему и вложишь слова в его уста. Я буду с твоими устами и с его устами и научу вас, что вам делать.","Jij zult tot hem spreken en de woorden in zijn mond leggen. Ik zal met je mond zijn en met zijn mond, en Ik zal jullie leren wat jullie moeten doen.",""],"exodus-4-16":["Он будет говорить за тебя народу. Он будет тебе устами, а ты будешь ему Богом.","Hij zal voor jou tot het volk spreken. Hij zal voor jou een mond zijn, en jij zult voor hem tot God zijn.","JPS: in God’s stead; фр.: un organe, un inspirateur. По-еврейски לְפֶה и לֵאלֹהִים — устами и Богом."],"exodus-4-17":["И этот посох возьми в свою руку: им ты сделаешь знаки».","En deze staf zul je in je hand nemen: daarmee zul je de tekenen doen.»","Фр.: miracles. По-еврейски הָאֹתֹת — знаки."],"i-samuel-3-1":["Мальчик Шмуэль служил Господу перед Эли. Слово Господа было драгоценно в те дни: не было распространённого видения.","De jongen Sjemoeël diende de Eeuwige voor Eli. Het woord van de Eeuwige was kostbaar in die dagen: er was geen wijdverbreid visioen.","JPS: precious, no frequent vision; фр.: rare, vision prophétique peu répandue. По-еврейски יָקָר — драгоценно, אֵין חָזוֹן נִפְרָץ — не было распространённого видения. Фр. добавляет prophétique."],"i-samuel-3-2":["В тот день было так: Эли лежал на своём месте, его глаза начали тускнеть, и он не мог видеть.","Op die dag gebeurde het: Eli lag op zijn plaats, zijn ogen begonnen dof te worden, en hij kon niet zien.","JPS: at that time; фр.: en ce temps-là. По-еврейски בַּיּוֹם הַהוּא — в тот день."],"i-samuel-3-3":["Светильник Бога ещё не погас, и Шмуэль лежал в храме Господа, там, где ковчег Бога.","De lamp van God was nog niet gedoofd, en Sjemoeël lag in de tempel van de Eeuwige, waar de ark van God was.","Фр.: lampe sacrée, arche divine. По-еврейски נֵר אֱלֹהִים — светильник Бога, אֲרוֹן אֱלֹהִים — ковчег Бога."],"i-samuel-3-4":["Господь позвал Шмуэля, и тот сказал: «Вот я».","De Eeuwige riep Sjemoeël, en hij zei: «Hier ben ik.»",""],"i-samuel-3-5":["Он побежал к Эли и сказал: «Вот я, ведь ты звал меня». Тот сказал: «Я не звал. Ложись снова». Он пошёл и лёг.","Hij rende naar Eli en zei: «Hier ben ik, want je hebt mij geroepen.» Hij zei: «Ik heb niet geroepen. Ga weer liggen.» Hij ging en ging liggen.",""],"i-samuel-3-6":["Господь снова позвал Шмуэля. Шмуэль встал, пошёл к Эли и сказал: «Вот я, ведь ты звал меня». Тот сказал: «Я не звал, сын мой. Ложись снова».","De Eeuwige riep Sjemoeël opnieuw. Sjemoeël stond op, ging naar Eli en zei: «Hier ben ik, want je hebt mij geroepen.» Hij zei: «Ik heb niet geroepen, mijn zoon. Ga weer liggen.»",""],"i-samuel-3-7":["А Шмуэль ещё не знал Господа, и слово Господа ещё не открывалось ему.","Maar Sjemoeël kende de Eeuwige nog niet, en het woord van de Eeuwige was nog niet aan hem geopenbaard.","Фр.: la parole divine. По-еврейски דְּבַר־יְהֹוָה — слово Господа."],"i-samuel-3-8":["Господь снова позвал Шмуэля, в третий раз. Он встал, пошёл к Эли и сказал: «Вот я, ведь ты звал меня». Эли понял, что Господь зовёт мальчика.","De Eeuwige riep Sjemoeël opnieuw, de derde keer. Hij stond op, ging naar Eli en zei: «Hier ben ik, want je hebt mij geroepen.» Eli begreep dat de Eeuwige de jongen riep.","Фр.: Dieu appela. По-еврейски יְהֹוָה — Господь."],"i-samuel-3-9":["Эли сказал Шмуэлю: «Иди, ложись. Если он позовёт тебя, скажи: „Говори, Господь, Твой слуга слушает“». Шмуэль пошёл и лёг на своём месте.","Eli zei tegen Sjemoeël: «Ga, ga liggen. Als hij je roept, zeg dan: „Spreek, Eeuwige, want Uw dienaar luistert.“» Sjemoeël ging en ging liggen op zijn plaats.","Фр.: Parle, Seigneur, ton serviteur. По-еврейски דַּבֵּר יְהֹוָה — говори, Господь; עַבְדֶּךָ — Твой слуга. Подлежащее יִקְרָא не названо."],"i-samuel-3-10":["Господь пришёл, встал и позвал, как в прежние разы: «Шмуэль, Шмуэль». Шмуэль сказал: «Говори, потому что Твой слуга слушает».","De Eeuwige kwam, ging staan en riep zoals de vorige keren: «Sjemoeël, Sjemoeël.» Sjemoeël zei: «Spreek, want Uw dienaar luistert.»",""],"i-samuel-3-11":["Господь сказал Шмуэлю: «Вот, Я делаю в Исраэле такое дело, что у каждого, кто услышит его, зазвенит в обоих ушах.","De Eeuwige zei tegen Sjemoeël: «Zie, Ik doe een ding in Israël, zodat bij ieder die het hoort beide oren zullen tuiten.",""],"i-samuel-3-12":["В тот день Я исполню против Эли всё, что Я говорил о его доме, от начала и до конца.","Op die dag zal Ik tegen Eli alles volbrengen wat Ik over zijn huis gesproken heb, van het begin tot het einde.","Фр.: toutes mes menaces. По-еврейски כׇּל־אֲשֶׁר דִּבַּרְתִּי — всё, что Я говорил."],"i-samuel-3-13":["Я сказал ему, что Я сужу его дом навеки за вину, о которой он знал: его сыновья проклинают их, а он их не одёрнул.","Ik heb hem gezegd dat Ik zijn huis voor altijd oordeel om de schuld waarvan hij wist: zijn zonen vervloeken hen, en hij heeft hen niet terechtgewezen.","Тёмное место: מְקַלְלִים לָהֶם. JPS: bring a curse upon themselves; фр.: conduite indigne. Переведено по написанному: сыновья проклинают их. וְלֹא כִהָה בָּם — не одёрнул их."],"i-samuel-3-14":["Поэтому Я поклялся дому Эли: вина дома Эли не искупится ни жертвой, ни приношением вовек».","Daarom heb Ik aan het huis van Eli gezworen: de schuld van het huis van Eli zal niet verzoend worden door slachtoffer of gave, voor eeuwig.»",""],"i-samuel-3-15":["Шмуэль лежал до утра и открыл двери дома Господа. Шмуэль боялся рассказать Эли видение.","Sjemoeël lag tot de morgen en opende de deuren van het huis van de Eeuwige. Sjemoeël was bang om Eli het visioen te vertellen.","Фр.: maison de Dieu. По-еврейски בֵּית־יְהֹוָה — дом Господа."],"i-samuel-3-16":["Эли позвал Шмуэля и сказал: «Шмуэль, сын мой». Тот сказал: «Вот я».","Eli riep Sjemoeël en zei: «Sjemoeël, mijn zoon.» Hij zei: «Hier ben ik.»",""],"i-samuel-3-17":["Он сказал: «Что за слово Он сказал тебе? Прошу, не скрывай от меня. Так пусть сделает тебе Бог и так пусть прибавит, если ты скроешь от меня хоть слово из всего, что Он сказал тебе».","Hij zei: «Wat is het woord dat Hij tot je gesproken heeft? Verberg het toch niet voor mij. Zo doe God je, en zo doe Hij erbij, als je voor mij ook maar iets verbergt van heel het woord dat Hij tot je gesproken heeft.»",""],"i-samuel-3-18":["Шмуэль рассказал ему все слова и ничего от него не скрыл. Тот сказал: «Он — Господь. Пусть сделает то, что хорошо в Его глазах».","Sjemoeël vertelde hem al de woorden en verborg niets voor hem. Hij zei: «Hij is de Eeuwige. Laat Hij doen wat goed is in Zijn ogen.»","Фр.: selon sa volonté. По-еврейски הַטּוֹב בְּעֵינָו יַעֲשֶׂה — пусть сделает то, что хорошо в Его глазах."],"i-samuel-3-19":["Шмуэль вырос, и Господь был с ним и не дал ни одному из его слов упасть на землю.","Sjemoeël groeide op, en de Eeuwige was met hem, en Hij liet geen van zijn woorden ter aarde vallen.","Фр.: prophéties. По-еврейски דְּבָרָיו — его слова."],"i-samuel-3-20":["И узнал весь Исраэль, от Дана до Беэр-Шевы, что Шмуэль утверждён пророком Господа.","Heel Israël, van Dan tot Beër-Sjeva, wist dat Sjemoeël bevestigd was als profeet van de Eeuwige.","JPS: established to be a prophet; фр.: reconnut l’autorité de Samuel. По-еврейски נֶאֱמָן לְנָבִיא — утверждён пророком."],"i-samuel-3-21":["И Господь продолжал являться в Шило, потому что Господь открывался Шмуэлю в Шило словом Господа.","En de Eeuwige bleef verschijnen in Sjilo, want de Eeuwige openbaarde Zich aan Sjemoeël in Sjilo door het woord van de Eeuwige.","Фр.: souvent, la parole divine. По-еврейски וַיֹּסֶף לְהֵרָאֹה — продолжал являться; בִּדְבַר יְהֹוָה — словом Господа."],"exodus-7-14":["Господь сказал Моше: «Сердце фараона тяжело, он отказывается отпустить народ.","De Eeuwige zei tegen Mosje: «Het hart van de farao is zwaar, hij weigert het volk te laten gaan.",""],"exodus-7-15":["Утром пойди к фараону. Вот, он выходит к воде. Встань ему навстречу на берегу реки и возьми в руку посох, который превратился в змею.","Ga 's ochtends naar de farao. Zie, hij komt naar het water. Ga aan de oever van de rivier staan om hem te ontmoeten, en neem de staf die in een slang veranderde in je hand.",""],"exodus-7-16":["Скажи ему: „Господь, Бог евреев, послал меня к тебе сказать: «Отпусти Мой народ, пусть служат Мне в пустыне». И вот, до сих пор ты не послушал.","Zeg tegen hem: „De Eeuwige, de God van de Hebreeën, heeft mij naar jou gestuurd om te zeggen: «Laat Mijn volk gaan, laat hen Mij dienen in de woestijn». En zie, tot nu toe heb je niet geluisterd.","JPS: serve; фр.: adore. По-еврейски וְיַעַבְדֻנִי — пусть служат Мне."],"exodus-7-17":["Так сказал Господь: «Этим ты узнаешь, что Я — Господь. Вот, Я ударяю посохом, который в Моей руке, по воде, что в реке, и она превратится в кровь.","Zo zegt de Eeuwige: «Hieraan zul je weten dat Ik de Eeuwige ben. Zie, Ik sla met de staf die in Mijn hand is op het water dat in de rivier is, en het zal in bloed veranderen.",""],"exodus-7-18":["Рыба в реке умрёт, река протухнет, и Мицраим измучится, стараясь пить воду из реки.»“»","De vis in de rivier zal sterven, de rivier zal stinken, en Mitsrajim zal zich uitputten om water uit de rivier te drinken.»“»","JPS: loathe; фр.: renonceront. По-еврейски וְנִלְאוּ — намучаются."],"exodus-7-19":["Господь сказал Моше: «Скажи Аарону: „Возьми свой посох и протяни руку над водами Мицраима, над их реками, над их протоками, над их водоёмами и над всяким скоплением их вод, и пусть они станут кровью. Кровь будет по всей земле Мицраима, и в дереве, и в камне.“»","De Eeuwige zei tegen Mosje: «Zeg tegen Aharon: „Neem je staf en strek je hand uit over de wateren van Mitsrajim, over hun rivieren, over hun stromen, over hun plassen en over elke verzameling van hun water, en laten zij bloed worden. Er zal bloed zijn in heel het land Mitsrajim, in het hout en in de steen.“»","JPS и фр. добавляют «сосуды». По-еврейски וּבָעֵצִים וּבָאֲבָנִים — и в дереве, и в камне."],"exodus-7-20":["Моше и Аарон сделали так, как повелел Господь. Он поднял посох и ударил по воде, которая в реке, на глазах у фараона и на глазах у его слуг. Вся вода в реке превратилась в кровь.","Mosje en Aharon deden zo, zoals de Eeuwige geboden had. Hij hief de staf op en sloeg het water dat in de rivier was, voor de ogen van de farao en voor de ogen van zijn dienaren. Al het water dat in de rivier was, veranderde in bloed.","Фр. называет Аарона. По-еврейски וַיָּרֶם — он поднял, без имени."],"exodus-7-21":["Рыба в реке умерла, река протухла, и Мицраим не мог пить воду из реки. Кровь была по всей земле Мицраима.","De vis in de rivier stierf, de rivier stonk, en Mitsrajim kon geen water uit de rivier drinken. Het bloed was in heel het land Mitsrajim.","Фр.: только кровь. По-еврейски וַיְהִי הַדָּם — и была кровь."],"exodus-7-22":["То же сделали чародеи Мицраима своими тайными искусствами. Сердце фараона ожесточилось, и он не послушал их, как говорил Господь.","De magiërs van Mitsrajim deden hetzelfde met hun geheime kunsten. Het hart van de farao werd hard, en hij luisterde niet naar hen, zoals de Eeuwige gesproken had.",""],"exodus-7-23":["Фараон повернулся, вошёл в свой дом и не принял к сердцу и этого.","De farao keerde zich om, ging zijn huis in en nam ook dit niet ter harte.",""],"exodus-7-24":["Весь Мицраим копал вокруг реки, чтобы добыть воду для питья, потому что не мог пить воду реки.","Heel Mitsrajim groef rondom de rivier naar water om te drinken, want zij konden het water van de rivier niet drinken.",""],"exodus-7-25":["Исполнилось семь дней с тех пор, как Господь поразил реку.","Zeven dagen waren vervuld nadat de Eeuwige de rivier had getroffen.",""],"exodus-7-26":["Господь сказал Моше: «Пойди к фараону и скажи ему: „Так сказал Господь: «Отпусти Мой народ, пусть служат Мне.","De Eeuwige zei tegen Mosje: «Ga naar de farao en zeg tegen hem: „Zo zegt de Eeuwige: «Laat Mijn volk gaan, laat hen Mij dienen.","Фр. опускает «так сказал Господь» и переводит службу как adorer. По-еврейски כֹּה אָמַר יְהוָה, וְיַעַבְדֻנִי — пусть служат Мне."],"exodus-7-27":["Если же ты откажешься отпустить, вот, Я поражу все твои пределы лягушками.","Maar als je weigert hen te laten gaan, zie, Ik tref al je grenzen met kikkers.","JPS: smite; фр.: infester. По-еврейски נֹגֵף — поражаю."],"exodus-7-28":["Река закишит лягушками. Они поднимутся и войдут в дом твой, и в спальню твою, и на постель твою, и в дом твоих слуг, и в народ твой, и в печи твои, и в квашни твои.","De rivier zal wemelen van kikkers. Zij zullen opkomen en je huis binnenkomen, en je slaapkamer, en op je bed, en in het huis van je dienaren, en bij je volk, en in je ovens, en in je deegtroggen.","Фр.: demeures de ton peuple. По-еврейски וּבְעַמְּךָ — и в народ твой."],"exodus-7-29":["И на тебя, и на народ твой, и на всех слуг твоих поднимутся лягушки.»“»","En op jou, en op je volk, en op al je dienaren zullen de kikkers opkomen.»“»",""],"exodus-8-1":["Господь сказал Моше: «Скажи Аарону: „Протяни руку с посохом над реками, над протоками и над водоёмами и выведи лягушек на землю Мицраима.“»","De Eeuwige zei tegen Mosje: «Zeg tegen Aharon: „Strek je hand met je staf uit over de rivieren, over de stromen en over de plassen, en laat de kikkers opkomen over het land Mitsrajim.“»",""],"exodus-8-2":["Аарон протянул руку над водами Мицраима, и лягушки поднялись и покрыли землю Мицраима.","Aharon strekte zijn hand uit over de wateren van Mitsrajim. De kikkers kwamen op en bedekten het land Mitsrajim.",""],"exodus-8-3":["Чародеи сделали то же своими тайными искусствами и вывели лягушек на землю Мицраима.","De magiërs deden hetzelfde met hun geheime kunsten en lieten de kikkers opkomen over het land Mitsrajim.",""],"exodus-8-4":["Фараон позвал Моше и Аарона и сказал: «Упросите Господа, пусть Он уберёт лягушек от меня и от моего народа, и я отпущу народ, и они принесут жертву Господу».","De farao riep Mosje en Aharon en zei: «Smeken jullie de Eeuwige, dat Hij de kikkers van mij en van mijn volk wegneemt. Dan zal ik het volk laten gaan, zodat zij aan de Eeuwige offeren.»",""],"exodus-8-5":["Моше сказал фараону: «Прими эту честь надо мной. К какому сроку мне просить за тебя, за твоих слуг и за твой народ, чтобы истребить лягушек от тебя и из твоих домов? Только в реке пусть они останутся».","Mosje zei tegen de farao: «Neem deze eer boven mij. Voor welke tijd zal ik voor jou, voor je dienaren en voor je volk pleiten, om de kikkers van jou en uit je huizen uit te roeien? Alleen in de rivier zullen zij blijven.»","JPS: be destroyed; фр.: se retirent. По-еврейски לְהַכְרִית — истребить."],"exodus-8-6":["Он сказал: «Завтра». И он сказал: «Будет по твоему слову, чтобы ты знал, что нет подобного Господу, нашему Богу.","Hij zei: «Morgen.» En hij zei: «Het zal zijn naar jouw woord, zodat je weet dat niemand is als de Eeuwige, onze God.",""],"exodus-8-7":["Лягушки отойдут от тебя, из твоих домов, от твоих слуг и от твоего народа. Только в реке они останутся».","De kikkers zullen wijken van jou, uit je huizen, van je dienaren en van je volk. Alleen in de rivier zullen zij blijven.»",""],"exodus-8-8":["Моше и Аарон вышли от фараона, и Моше воззвал к Господу о лягушках, которых Он навёл на фараона.","Mosje en Aharon gingen bij de farao weg, en Mosje riep tot de Eeuwige over de kikkers die Hij over de farao had gebracht.",""],"exodus-8-9":["Господь сделал по слову Моше, и лягушки вымерли в домах, во дворах и на полях.","De Eeuwige deed naar het woord van Mosje, en de kikkers stierven weg uit de huizen, uit de binnenplaatsen en van de velden.","JPS: courts; фр.: fermes. По-еврейски חֲצֵרֹת — дворы."],"exodus-8-10":["Их сгребли куча на куче, и земля протухла.","Men veegde ze bijeen, hoop aan hoop, en het land stonk.",""],"exodus-8-11":["Фараон увидел, что настала передышка, отяготил своё сердце и не послушал их, как говорил Господь.","De farao zag dat er verlichting gekomen was. Hij maakte zijn hart zwaar en luisterde niet naar hen, zoals de Eeuwige gesproken had.",""],"exodus-8-12":["Господь сказал Моше: «Скажи Аарону: „Протяни свой посох и ударь по пыли земли, и она станет вшами по всей земле Мицраима.“»","De Eeuwige zei tegen Mosje: «Zeg tegen Aharon: „Strek je staf uit en sla het stof van de aarde, en het zal luizen worden in heel het land Mitsrajim.“»","JPS: gnats; фр.: vermine. По-еврейски כִּנִּים — вши."],"exodus-8-13":["Они так и сделали. Аарон протянул руку со своим посохом и ударил по пыли земли, и вши были на людях и на скоте. Вся пыль земли стала вшами по всей земле Мицраима.","Zij deden zo. Aharon strekte zijn hand uit met zijn staf en sloeg het stof van de aarde, en de luizen waren op mens en op vee. Al het stof van de aarde veranderde in luizen in heel het land Mitsrajim.","JPS: gnats; фр.: vermine. По-еврейски כִּנִּים — вши."],"exodus-8-14":["То же сделали чародеи своими тайными искусствами, чтобы вывести вшей, но не смогли. И вши были на людях и на скоте.","De magiërs deden hetzelfde met hun geheime kunsten om de luizen voort te brengen, maar zij konden het niet. En de luizen waren op mens en op vee.","JPS: to bring forth gnats. Фр.: faire disparaître la vermine. По-еврейски לְהוֹצִיא אֶת־הַכִּנִּים — вывести вшей."],"exodus-8-15":["Чародеи сказали фараону: «Это палец Бога». Сердце фараона ожесточилось, и он не послушал их, как говорил Господь.","De magiërs zeiden tegen de farao: «Dit is de vinger van God.» Het hart van de farao werd hard, en hij luisterde niet naar hen, zoals de Eeuwige gesproken had.",""],"exodus-8-16":["Господь сказал Моше: «Встань рано утром и стань перед фараоном. Вот, он выходит к воде. Скажи ему: „Так сказал Господь: «Отпусти Мой народ, пусть служат Мне.","De Eeuwige zei tegen Mosje: «Sta 's ochtends vroeg op en ga voor de farao staan. Zie, hij komt naar het water. Zeg tegen hem: „Zo zegt de Eeuwige: «Laat Mijn volk gaan, laat hen Mij dienen.","Фр. добавляет «demain» и переводит службу как adorer. По-еврейски הַשְׁכֵּם בַּבֹּקֶר — встань рано утром; וְיַעַבְדֻנִי — пусть служат Мне."],"exodus-8-17":["Если же ты не отпустишь Мой народ, вот, Я насылаю на тебя, на твоих слуг, на твой народ и в твои дома полчище. Дома Мицраима наполнятся полчищем, и земля под ними тоже наполнится.","Maar als je Mijn volk niet laat gaan, zie, Ik zend op jou, op je dienaren, op je volk en in je huizen een horde. De huizen van Mitsrajim zullen vol raken van de horde, en ook de grond waarop zij zijn zal vol raken.","JPS: swarms of flies; фр.: animaux malfaisants. По-еврейски עָרֹב — полчище, вид не назван."],"exodus-8-18":["В тот день Я отделю землю Гошен, на которой стоит Мой народ, чтобы там не было полчища, и чтобы ты узнал, что Я — Господь посреди земли.","Op die dag zal Ik het land Gosjen afzonderen, waarop Mijn volk staat, zodat daar geen horde zal zijn, en zodat jij weet dat Ik de Eeuwige ben, in het midden van de aarde.","JPS: in the midst of the earth; фр.: au milieu de cette province. По-еврейски בְּקֶרֶב הָאָרֶץ — посреди земли."],"exodus-8-19":["Я положу избавление между Моим народом и твоим народом. Завтра будет этот знак.»“»","Ik zal een verlossing stellen tussen Mijn volk en jouw volk. Morgen zal dit teken er zijn.»“»","JPS: division; фр.: séparation salutaire. По-еврейски פְדֻת — избавление; слово редкое."],"exodus-8-20":["Господь сделал так. Тяжёлое полчище вошло в дом фараона и в дом его слуг, и по всей земле Мицраима земля была разорена из-за полчища.","De Eeuwige deed zo. Een zware horde kwam het huis van de farao binnen en het huis van zijn dienaren, en in heel het land Mitsrajim werd het land te gronde gericht door de horde.","JPS: ruined; фр.: infestée. По-еврейски תִּשָּׁחֵת — земля разорена. עָרֹב — полчище, вид не назван."],"exodus-8-21":["Фараон позвал Моше и Аарона и сказал: «Идите, принесите жертву вашему Богу в этой стране».","De farao riep Mosje en Aharon en zei: «Ga, offer aan jullie God in het land.»",""],"exodus-8-22":["Моше сказал: «Так делать нельзя: мерзость Мицраима мы принесём в жертву Господу, нашему Богу. Если мы на их глазах принесём в жертву мерзость Мицраима, разве они не побьют нас камнями?","Mosje zei: «Het past niet om zo te doen, want wij zullen de gruwel van Mitsrajim offeren aan de Eeuwige, onze God. Als wij de gruwel van Mitsrajim voor hun ogen offeren, zullen zij ons dan niet stenigen?","JPS: abomination; фр.: terreur. По-еврейски תּוֹעֵבָה — мерзость."],"exodus-8-23":["Мы уйдём на три дня пути в пустыню и принесём жертву Господу, нашему Богу, как Он скажет нам».","Drie dagreizen ver gaan wij de woestijn in, en wij zullen offeren aan de Eeuwige, onze God, zoals Hij ons zeggen zal.»",""],"exodus-8-24":["Фараон сказал: «Я отпущу вас, и вы принесёте жертву Господу, вашему Богу, в пустыне. Только далеко не уходите. Попросите за меня».","De farao zei: «Ik zal jullie laten gaan, en jullie zullen offeren aan de Eeuwige, jullie God, in de woestijn. Alleen, ga niet ver weg. Pleit voor mij.»",""],"exodus-8-25":["Моше сказал: «Вот, я выхожу от тебя и буду просить Господа, и завтра полчище отойдёт от фараона, от его слуг и от его народа. Только пусть фараон больше не обманывает, не отпуская народ принести жертву Господу».","Mosje zei: «Zie, ik ga bij je weg en ik zal de Eeuwige smeken, en morgen zal de horde wijken van de farao, van zijn dienaren en van zijn volk. Alleen, laat de farao niet opnieuw bedriegen door het volk niet te laten gaan om aan de Eeuwige te offeren.»","JPS: swarms of flies; фр.: animaux malfaisants. По-еврейски עָרֹב — полчище, вид не назван."],"exodus-8-26":["Моше вышел от фараона и стал просить Господа.","Mosje ging bij de farao weg en smeekte de Eeuwige.",""],"exodus-8-27":["Господь сделал по слову Моше и убрал полчище от фараона, от его слуг и от его народа. Не осталось ни одного.","De Eeuwige deed naar het woord van Mosje en nam de horde weg van de farao, van zijn dienaren en van zijn volk. Er bleef niet één over.","JPS: swarms of flies; фр.: animaux malfaisants. По-еврейски עָרֹב — полчище, вид не назван."],"exodus-8-28":["В этот раз фараон тоже отяготил своё сердце и не отпустил народ.","Ook deze keer maakte de farao zijn hart zwaar, en hij liet het volk niet gaan.",""],"genesis-1-14":["Бог сказал: «Пусть будут светила на своде небес, чтобы отделять день от ночи, и пусть будут они для знаков, для сроков, для дней и годов,","God zei: «Laten er lichten zijn aan het gewelf van de hemel, om de dag van de nacht te scheiden, en laten zij dienen tot tekens, tot vastgestelde tijden, tot dagen en jaren,","JPS: firmament; фр.: espace. По-еврейски רָקִיעַ — свод. Фр. сводит «для знаков и для сроков» к signes pour les saisons."],"genesis-1-15":["и пусть будут они светилами на своде небес, чтобы светить на землю». Так и стало.","en laten zij lichten zijn aan het gewelf van de hemel, om de aarde te verlichten.» Zo gebeurde het.","JPS: firmament; фр.: espace. По-еврейски רָקִיעַ — свод."],"genesis-1-16":["Бог сделал два великих светила: большое светило — для власти над днём, малое светило — для власти над ночью, и звёзды.","God maakte de twee grote lichten: het grote licht tot heerschappij over de dag, het kleine licht tot heerschappij over de nacht, en de sterren.","JPS: to rule; фр.: royauté. По-еврейски מֶמְשָׁלָה — власть."],"genesis-1-17":["Бог поместил их на своде небес, чтобы светить на землю,","God plaatste ze aan het gewelf van de hemel om de aarde te verlichten,","JPS: firmament; фр.: espace. По-еврейски רָקִיעַ — свод."],"genesis-1-18":["и чтобы править днём и ночью и отделять свет от тьмы. Бог увидел, что это хорошо.","en om te heersen over de dag en over de nacht en om het licht van de duisternis te scheiden. God zag dat het goed was.",""],"genesis-1-19":["Был вечер и было утро: день четвёртый.","Het werd avond en het werd ochtend: een vierde dag.",""],"isaiah-66-10":["Радуйтесь с Йерушалаимом и веселитесь о ней, все, кто любит её. Ликуйте с ней ликованием, все, кто скорбит о ней,","Verheug jullie met Jeroesjalajim en juich om haar, allen die haar liefhebben. Jubel met haar van vreugde, allen die om haar treuren,",""],"isaiah-66-11":["чтобы вы сосали и насытились от груди её утешений, чтобы вы высасывали и наслаждались изобилием её славы.","zodat jullie aan de borst van haar vertroostingen zuigen en verzadigd worden, zodat jullie van de overvloed van haar heerlijkheid uitzuigen en genieten.","Фр. добавляет lait. זִיז — редкое слово; JPS и фр. читают его как обилие славы."],"isaiah-66-12":["Потому что так сказал Господь: «Вот, Я простираю к ней мир, как реку, и славу народов, как разливающийся поток. Вы будете сосать. На боку вас будут носить и на коленях тешить.","Want zo zegt de Eeuwige: «Zie, Ik strek vrede naar haar uit als een rivier, en als een overstromende beek de heerlijkheid van de volken. Jullie zullen zuigen. Op de heup zullen jullie gedragen worden, op de knieën vertroeteld worden.","JPS: wealth, upon the side; фр.: richesse, dans leurs bras. По-еврейски כְּבוֹד — слава, עַל־צַד — на боку."],"isaiah-66-13":["Как человека утешает его мать, так Я утешу вас, и в Йерушалаиме вы будете утешены.","Zoals een mens wiens moeder hem troost, zo zal Ik jullie troosten, en in Jeroesjalajim zullen jullie getroost worden.","JPS: as one; фр.: comme un fils. По-еврейски כְּאִישׁ — как человек."],"isaiah-66-14":["Вы увидите, и возрадуется ваше сердце, и ваши кости расцветут, как зелень. И рука Господа откроется Его слугам, и Он прогневается на врагов Своих».","Jullie zullen het zien, en jullie hart zal juichen, en jullie beenderen zullen opbloeien als het jonge groen. De hand van de Eeuwige zal bekend worden aan zijn dienaren, en Hij zal verbolgen zijn op zijn vijanden.»","JPS: bones; фр.: membres. По-еврейски עֲצְמוֹתֵיכֶם — ваши кости. Фр. «main de Dieu» при יַד־יְהוָה."],"isaiah-66-15":["Вот, Господь придёт в огне, и колесницы Его — как вихрь, чтобы обрушить гнев Свой в ярости и укор Свой — в пламени огня.","Zie, de Eeuwige komt in vuur, en zijn wagens zijn als een wervelwind, om zijn toorn in grimmigheid te keren en zijn berisping in vlammen van vuur.","JPS: fury and flames of fire; фр.: colère par le feu. По-еврейски בְּחֵמָה — яростью, וּגַעֲרָתוֹ בְּלַהֲבֵי־אֵשׁ — укор пламенем огня."],"isaiah-66-16":["Огнём и мечом Своим Господь будет судиться со всякой плотью. Много будет убитых Господом.","Met vuur en met zijn zwaard zal de Eeuwige in het gericht treden met alle vlees. Talrijk zullen de gedoden van de Eeuwige zijn.",""],"isaiah-66-17":["Кто освящает себя и очищает себя к садам, вслед за одной посредине, кто ест мясо свиньи, мерзость и мышь, — вместе они погибнут, слово Господа.","Zij die zich heiligen en zich reinigen voor de tuinen, achter één in het midden, eters van varkensvlees, van het walgelijke en van de muis, zullen samen omkomen — zo spreekt de Eeuwige.","JPS: behind one in the midst; фр.: autour d'une idole, reptiles. По-еврейски אַחַר אַחַת בַּתָּוֶךְ — вслед за одной посредине; שֶׁקֶץ — мерзость."],"isaiah-66-18":["«А Я — их дела и их мысли. Грядёт собрать все народы и языки. Они придут и увидят Мою славу.","«En Ik — hun daden en hun gedachten. Het komt, om alle volken en talen te verzamelen. Zij zullen komen en Mijn heerlijkheid zien.","Стих без глагола при «Я». JPS добавляет [know] и [the time], фр. — [je juge que le temps]. Этих слов в еврейском нет."],"isaiah-66-19":["Я положу среди них знак и пошлю из них уцелевших к народам: к Таршишу, к Пулу и к Луду, которые натягивают лук, к Тувалу и к Явану, к далёким островам, которые не слышали вести обо Мне и не видели Моей славы. И они возвестят Мою славу среди народов.","Ik zal een teken onder hen stellen en uit hen ontkomenen zenden naar de volken: Tarsjisj, Poel en Loed, die de boog spannen, Toebal en Javan, de verre eilanden, die Mijn tijding niet hebben gehoord en Mijn heerlijkheid niet hebben gezien. En zij zullen Mijn heerlijkheid onder de volken verkondigen.","JPS: such as escape, My fame; фр.: sains et saufs, mon nom. По-еврейски פְּלֵיטִים — уцелевшие, שִׁמְעִי — весть обо Мне."],"isaiah-66-20":["Они привезут всех ваших братьев из всех народов в дар Господу, на лошадях, в колесницах, в носилках, на мулах и на быстрых животных, на святую гору Мою, Йерушалаим, — сказал Господь, — как сыновья Исраэля приносят дар в чистом сосуде в дом Господа.","Zij zullen al jullie broeders uit alle volken brengen als een gave aan de Eeuwige, op paarden, in wagens, in draagstoelen, op muildieren en op snelle dieren, naar Mijn heilige berg Jeroesjalajim, zegt de Eeuwige, zoals de zonen van Israël de gave in een rein vat naar het huis van de Eeuwige brengen.","JPS: offering, swift beasts; фр.: tribut, dromadaires, temple. По-еврейски מִנְחָה — дар, כִּרְכָּרוֹת — неясные животные, בֵּית — дом."],"isaiah-66-21":["И из них тоже Я возьму в священники и в левиты, — сказал Господь.","En ook uit hen zal Ik er nemen tot priesters en tot Levieten, zegt de Eeuwige.",""],"isaiah-66-22":["Ведь как новые небеса и новая земля, которые Я творю, стоят передо Мной, — слово Господа, — так будет стоять ваше потомство и ваше имя.","Want zoals de nieuwe hemelen en de nieuwe aarde die Ik maak voor Mij blijven staan, spreekt de Eeuwige, zo zal jullie nageslacht en jullie naam blijven staan.",""],"isaiah-66-23":["Будет так: от новолуния к новолунию и от шабата к шабату всякая плоть будет приходить, чтобы пасть ниц передо Мной, — сказал Господь».","En het zal zijn: van nieuwe maan tot nieuwe maan en van sjabbat tot sjabbat zal alle vlees komen om zich voor Mij neer te werpen, zegt de Eeuwige.»",""],"exodus-11-4":["Моше сказал: «Так сказал Господь: „Около полуночи Я выйду в середину Мицраима,","Mosje zei: «Zo zei de Eeuwige: „Rond middernacht ga Ik uit, het midden van Mitsrajim in,",""],"exodus-11-5":["и умрёт всякий первенец в земле Мицраим, от первенца фараона, который сидит на его престоле, до первенца рабыни, которая за жерновами, и всякий первенец скота.","en iedere eerstgeborene in het land Mitsrajim zal sterven, van de eerstgeborene van de farao die op zijn troon zit tot de eerstgeborene van de slavin achter de maalstenen, en iedere eerstgeborene van het vee.","JPS: that sitteth upon his throne, the maid-servant; фр.: qui devait occuper son trône, l’esclave. По-еврейски הַיֹּשֵׁב עַל־כִּסְאוֹ — который сидит на его престоле; הַשִּׁפְחָה — рабыня."],"exodus-11-6":["Будет великий вопль по всей земле Мицраим, какого не было и какого больше не будет.","Er zal een groot geroep zijn in heel het land Mitsrajim, zoals er nog nooit is geweest en zoals er nooit meer zal zijn.",""],"exodus-11-7":["А у всех сыновей Исраэля ни один пёс не заострит языка, ни на человека, ни на скот, чтобы вы знали, что Господь проводит различие между Мицраимом и Исраэлем“.","Maar bij alle zonen van Israël zal geen hond zijn tong scherpen, niet naar een mens en niet naar vee, zodat jullie weten dat de Eeuwige onderscheid maakt tussen Mitsrajim en Israël.“","JPS: shall not a dog whet his tongue; фр.: pas un chien n’aboiera. По-еврейски לֹא יֶחֱרַץ־כֶּלֶב לְשֹׁנוֹ — пёс не заострит языка."],"exodus-11-8":["Все эти твои слуги сойдут ко мне и поклонятся мне ниц со словами: „Выйди, ты и весь народ, который у твоих ног“, и после этого я выйду». Он вышел от фараона в пылу гнева.","Al deze dienaren van je zullen naar mij afdalen en zich voor mij neerwerpen en zeggen: „Ga weg, jij en heel het volk dat aan je voeten is“, en daarna zal ik weggaan.» Hij ging bij de farao weg in hevige woede.","JPS: thy servants… that follow thee; фр.: courtisans… qui t’obéit, à mes pieds. По-еврейски עֲבָדֶיךָ — твои слуги; אֲשֶׁר־בְּרַגְלֶיךָ — кто у твоих ног. «К моим ногам» во французском добавлено."],"exodus-11-9":["Господь сказал Моше: «Фараон не послушает вас, чтобы умножились Мои чудеса в земле Мицраим».","De Eeuwige zei tegen Mosje: «De farao zal niet naar jullie luisteren, zodat Mijn wonderen talrijk worden in het land Mitsrajim.»","JPS: will not hearken unto you; фр.: ne vous cédera point. По-еврейски לֹא־יִשְׁמַע אֲלֵיכֶם — не послушает вас, множественное число."],"exodus-11-10":["Моше и Аарон сделали все эти чудеса перед фараоном. Господь укрепил сердце фараона, и он не отпустил сыновей Исраэля из своей земли.","Mosje en Aharon deden al deze wonderen voor de farao. De Eeuwige sterkte het hart van de farao, en hij liet de zonen van Israël niet uit zijn land gaan.",""],"exodus-12-1":["Господь сказал Моше и Аарону в земле Мицраим:","De Eeuwige zei tegen Mosje en Aharon in het land Mitsrajim:",""],"exodus-12-2":["«Этот месяц для вас — начало месяцев. Он первый для вас среди месяцев года.","«Deze maand is voor jullie het begin van de maanden. Hij is voor jullie de eerste van de maanden van het jaar.",""],"exodus-12-3":["Скажите всей общине Исраэля: „В десятый день этого месяца пусть каждый возьмёт себе ягнёнка на дом отцов, ягнёнка на дом.","Zegt tegen heel de gemeenschap van Israël: „Op de tiende dag van deze maand moet ieder voor zich een lam nemen voor het huis van de vaders, een lam voor het huis.",""],"exodus-12-4":["Если дом слишком мал для ягнёнка, пусть он и его сосед, ближайший к его дому, возьмут по числу душ. Каждого по тому, сколько он съест, рассчитывайте на ягнёнка.","Als het huis te klein is voor een lam, dan nemen hij en zijn buurman die het dichtst bij zijn huis woont er een, naar het aantal zielen. Ieder naar wat hij eet, moeten jullie voor het lam rekenen.",""],"exodus-12-5":["Ягнёнок пусть будет у вас без порока, самец, однолетний. Из овец и из коз берите его.","Een lam moet voor jullie zonder gebrek zijn, mannelijk, van één jaar. Uit de schapen en uit de geiten moeten jullie het nemen.",""],"exodus-12-6":["Пусть он будет у вас на хранении до четырнадцатого дня этого месяца, и пусть всё собрание общины Исраэля заколет его между вечерами.","Jullie moeten het ter bewaring houden tot de veertiende dag van deze maand, en heel de gemeente van de gemeenschap van Israël moet het slachten tussen de avonden.","JPS: at dusk; фр.: vers le soir. По-еврейски בֵּין הָעַרְבָּיִם — между вечерами."],"exodus-12-7":["Пусть возьмут от крови и положат на оба косяка и на притолоку домов, в которых его будут есть.","Zij moeten van het bloed nemen en het doen op de twee deurposten en op de bovendorpel, op de huizen waarin zij het zullen eten.",""],"exodus-12-8":["Пусть едят мясо в эту ночь, жареное на огне, и мацу. С горькими травами пусть едят его.","Zij moeten het vlees eten in deze nacht, op het vuur gebraden, en matses. Met bittere kruiden moeten zij het eten.",""],"exodus-12-9":["Не ешьте от него сырого и сваренного в воде, а только жареное на огне: голову его вместе с ногами и внутренностями.","Jullie mogen er niets van eten, rauw of gekookt in water, alleen op het vuur gebraden: zijn kop samen met zijn poten en zijn ingewanden.","JPS: raw; фр.: à demi cuit. По-еврейски נָא — сырое."],"exodus-12-10":["Не оставляйте от него до утра. Что останется от него до утра, сожгите огнём.","Laat er niets van over tot de morgen. Wat ervan tot de morgen overblijft, moeten jullie met vuur verbranden.",""],"exodus-12-11":["Ешьте его так: бёдра ваши подпоясаны, обувь ваша на ногах и посох ваш в руке. Ешьте его в спешке. Это песах Господу.","Zo moeten jullie het eten: jullie heupen omgord, jullie schoenen aan jullie voeten en jullie staf in jullie hand. Jullie moeten het in haast eten. Het is pesach voor de Eeuwige.",""],"exodus-12-12":["В эту ночь Я пройду по земле Мицраим и поражу всякого первенца в земле Мицраим, от человека до скота, и над всеми богами Мицраима Я совершу суды. Я — Господь.","In deze nacht zal Ik door het land Mitsrajim gaan en iedere eerstgeborene in het land Mitsrajim slaan, van mens tot vee, en aan alle goden van Mitsrajim zal Ik gerichten voltrekken. Ik ben de Eeuwige.",""],"exodus-12-13":["Кровь будет вам знаком на домах, где вы находитесь. Я увижу кровь и пройду мимо вас, и не будет на вас поражения на погибель, когда Я поражу землю Мицраим.","Het bloed zal voor jullie een teken zijn op de huizen waar jullie zijn. Ik zal het bloed zien en aan jullie voorbijgaan, en er zal op jullie geen plaag tot verderf zijn wanneer Ik het land Mitsrajim sla.","JPS: I will pass over you, to destroy you; фр.: je vous épargnerai, le fléau. По-еврейски וּפָסַחְתִּי עֲלֵכֶם — Я пройду мимо вас; נֶגֶף לְמַשְׁחִית — поражение на погибель."],"exodus-12-14":["Этот день будет вам памятью, и празднуйте его как праздник Господу. Для ваших поколений празднуйте его как вечный устав.","Deze dag zal voor jullie een herinnering zijn, en jullie moeten hem vieren als een feest voor de Eeuwige. Voor jullie generaties moeten jullie hem vieren als een eeuwige inzetting.","JPS: by an ordinance for ever; фр.: à jamais. По-еврейски חֻקַּת עוֹלָם — вечный устав."],"exodus-12-15":["Семь дней ешьте мацу. В первый же день устраните закваску из ваших домов. Всякий, кто ест квасное, — та душа будет отсечена от Исраэля, с первого дня до седьмого.","Zeven dagen moeten jullie matses eten. Maar op de eerste dag moeten jullie het zuurdeeg uit jullie huizen wegdoen. Ieder die gezuurd eet: die ziel wordt afgesneden van Israël, van de eerste dag tot de zevende.","JPS: the first day; фр.: le jour précédent. По-еврейски בַּיּוֹם הָרִאשׁוֹן — в первый день."],"exodus-12-16":["В первый день — священное созвание, и в седьмой день священное созвание будет у вас. Никакой работы нельзя делать в эти дни. Только то, что будет съедено для всякой души, одно это можно сделать для вас.","Op de eerste dag is er een heilige samenroeping, en op de zevende dag zal er een heilige samenroeping voor jullie zijn. Geen enkele arbeid mag daarop gedaan worden. Alleen wat voor iedere ziel gegeten wordt, dat alleen mag voor jullie gedaan worden.",""],"exodus-12-17":["Храните мацу, потому что в этот самый день Я вывел ваши воинства из земли Мицраим. Храните этот день для ваших поколений как вечный устав.","Bewaar de matses, want op deze zelfde dag heb Ik jullie legers uit het land Mitsrajim geleid. Bewaar deze dag voor jullie generaties als een eeuwige inzetting.","JPS: the feast of unleavened bread, have I brought; фр.: la fête des Azymes, j’aurai fait sortir. По-еврейски אֶת־הַמַּצּוֹת — маца, слова «праздник» нет; הוֹצֵאתִי — Я вывел."],"exodus-12-18":["В первом, в четырнадцатый день месяца, вечером, ешьте мацу до двадцать первого дня месяца, вечером.","In de eerste, op de veertiende dag van de maand, in de avond, moeten jullie matses eten tot de eenentwintigste dag van de maand, in de avond.","JPS: In the first month; фр.: Le premier mois. По-еврейски בָּרִאשֹׁן — в первом, слово «месяц» при нём не стоит."],"exodus-12-19":["Семь дней пусть не найдётся закваски в ваших домах. Всякий, кто ест квасное, — та душа будет отсечена от общины Исраэля, пришелец и уроженец земли.","Zeven dagen mag er geen zuurdeeg in jullie huizen gevonden worden. Ieder die iets gezuurds eet: die ziel wordt afgesneden van de gemeenschap van Israël, de vreemdeling en de in het land geborene.","JPS: a sojourner, or one that is born in the land; фр.: le prosélyte comme l’indigène. По-еврейски גֵּר — пришелец, אֶזְרַח הָאָרֶץ — уроженец земли."],"exodus-12-20":["Никакого квасного не ешьте. Во всех ваших селениях ешьте мацу“».","Niets gezuurds mogen jullie eten. In al jullie woonplaatsen moeten jullie matses eten.“»",""],"exodus-12-21":["Моше созвал всех старейшин Исраэля и сказал им: «Вытяните и возьмите себе мелкий скот по вашим семьям и заколите песах.","Mosje riep alle oudsten van Israël en zei tegen hen: «Trek en neem voor jullie kleinvee voor jullie families, en slacht het pesach.","JPS: Draw out… the passover lamb; фр.: Choisissez… la victime pascale. По-еврейски מִשְׁכוּ — вытяните; הַפָּסַח — песах."],"exodus-12-22":["Возьмите пучок иссопа, обмакните в кровь, которая в чаше, и коснитесь притолоки и обоих косяков кровью, которая в чаше. А вы — никто не выходите из входа своего дома до утра.","Neemt een bundel hysop, doopt die in het bloed dat in de schaal is, en raakt de bovendorpel en de twee deurposten aan met het bloed dat in de schaal is. En jullie: niemand mag de deuropening van zijn huis uit gaan tot de morgen.","וְהִגַּעְתֶּם — коснитесь. JPS: strike; фр.: teindrez. סַף тёмное: чаша или порог. JPS и фр.: basin."],"exodus-12-23":["Господь пройдёт, чтобы поразить Мицраим, увидит кровь на притолоке и на обоих косяках, и Господь пройдёт мимо входа и не даст губителю войти в ваши дома, чтобы поразить.","De Eeuwige zal doortrekken om Mitsrajim te slaan, Hij zal het bloed zien op de bovendorpel en op de twee deurposten, en de Eeuwige zal aan de deuropening voorbijgaan en de verderver niet toelaten jullie huizen binnen te gaan om te slaan.","JPS: the LORD… the destroyer; фр.: le Seigneur… le fléau. По-еврейски יְהֹוָה — Господь, הַמַּשְׁחִית — губитель."],"exodus-12-24":["Храните это дело как устав для тебя и для твоих сыновей навеки.","Jullie moeten deze zaak bewaren als een inzetting voor jou en voor je zonen, voor altijd.","JPS: this thing… to thee and to thy sons; фр.: cette loi… pour toi et pour tes enfants. По-еврейски הַדָּבָר הַזֶּה — это дело. Глагол множественного числа, לְךָ וּלְבָנֶיךָ — единственное."],"exodus-12-25":["Когда вы придёте в землю, которую Господь даст вам, как Он сказал, храните эту службу.","Wanneer jullie komen in het land dat de Eeuwige jullie geven zal, zoals Hij gezegd heeft, moeten jullie deze dienst houden.","JPS: as He hath promised… this service; фр.: le Seigneur… comme il l’a promis… ce rite. По-еврейски יְהֹוָה — Господь, כַּאֲשֶׁר דִּבֵּר — как Он сказал, הָעֲבֹדָה — служба."],"exodus-12-26":["Когда ваши сыновья скажут вам: „Что эта служба вам?“,","Wanneer jullie zonen tegen jullie zeggen: „Wat is deze dienst voor jullie?“,","JPS: What mean ye by this service; фр.: Que signifie pour vous ce rite. По-еврейски מָה הָעֲבֹדָה הַזֹּאת לָכֶם — что эта служба вам."],"exodus-12-27":["скажите: „Это жертва песаха Господу, который прошёл мимо домов сыновей Исраэля в Мицраиме, когда Он поражал Мицраим, а наши дома Он спас“». Народ склонился, и они поверглись ниц.","zeg dan: „Het is het offer van pesach voor de Eeuwige, die voorbijging aan de huizen van de zonen van Israël in Mitsrajim, toen Hij Mitsrajim sloeg, en onze huizen heeft Hij gered.“» Het volk boog zich, en zij wierpen zich neer.","JPS: passed over… delivered our houses; фр.: épargna… préserver nos familles. По-еврейски פָּסַח — прошёл мимо; בָּתֵּינוּ הִצִּיל — наши дома спас. וַיִּקֹּד единственное число, וַיִּשְׁתַּחֲווּ — множественное."],"exodus-12-28":["Сыновья Исраэля пошли и сделали. Как Господь повелел Моше и Аарону, так они сделали.","De zonen van Israël gingen en deden het. Zoals de Eeuwige Mosje en Aharon geboden had, zo deden zij.",""],"ezra-6-19":["Сыновья изгнания совершили песах в четырнадцатый день первого месяца.","De zonen van de ballingschap deden het pesach op de veertiende dag van de eerste maand.",""],"ezra-6-20":["Потому что священники и левиим очистились как один: все они чисты. Они закололи песах для всех сыновей изгнания, для своих братьев-священников и для себя.","Want de priesters en de Leviem hadden zich als één gereinigd: zij allen waren rein. Zij slachtten het pesach voor alle zonen van de ballingschap, voor hun broeders de priesters en voor zichzelf.","JPS: the passover lamb; фр.: le sacrifice pascal. По-еврейски הַפֶּסַח — песах."],"ezra-6-21":["Ели сыновья Исраэля, вернувшиеся из изгнания, и всякий, кто отделился к ним от нечистоты народов земли, чтобы искать Господа, Бога Исраэля.","De zonen van Israël die uit de ballingschap waren teruggekeerd, aten, en ieder die zich tot hen had afgezonderd van de onreinheid van de volken van het land, om de Eeuwige, de God van Israël, te zoeken.",""],"ezra-6-22":["Они совершили праздник мацы семь дней в радости, потому что Господь обрадовал их и обратил к ним сердце царя Ашшура, чтобы укрепить их руки в работе дома Бога, Бога Исраэля.","Zij deden het feest van de matses zeven dagen met vreugde, want de Eeuwige had hen verblijd en het hart van de koning van Asjoer tot hen gewend, om hun handen te sterken in het werk van het huis van God, de God van Israël.","JPS: the house of God… to strengthen their hands; фр.: le temple de Dieu… les seconder. По-еврейски בֵּית־הָאֱלֹהִים — дом Бога; לְחַזֵּק יְדֵיהֶם — укрепить их руки."],"ezra-7-1":["После этих событий, в царствование Артахшасты, царя Параса, Эзра, сын Сераи, сын Азарьи, сын Хилкии,","Na deze gebeurtenissen, in het koningschap van Artachsjasta, koning van Paras, Ezra, zoon van Seraja, zoon van Azarja, zoon van Chilkja,",""],"ezra-7-2":["сын Шаллума, сын Цадока, сын Ахитува,","zoon van Sjalloem, zoon van Tsadok, zoon van Achitoev,",""],"ezra-7-3":["сын Амарьи, сын Азарьи, сын Мерайота,","zoon van Amarja, zoon van Azarja, zoon van Merajot,",""],"ezra-7-4":["сын Зерахьи, сын Уззи, сын Букки,","zoon van Zerachja, zoon van Oezzi, zoon van Boekki,",""],"ezra-7-5":["сын Авишуа, сын Пинхаса, сын Элазара, сын Аарона, главного священника.","zoon van Avisjoea, zoon van Pinchas, zoon van Elazar, zoon van Aharon, de hoofdpriester.","JPS: the chief priest; фр.: le pontife suprême. По-еврейски הַכֹּהֵן הָרֹאשׁ — главный священник."],"ezra-7-6":["Он, Эзра, поднялся из Бавеля. Он был искусным писцом в Торе Моше, которую дал Господь, Бог Исраэля. Царь дал ему всю его просьбу, по руке Господа, его Бога, на нём.","Hij, Ezra, trok op uit Bavel. Hij was een bedreven schrijver in de Tora van Mosje, die de Eeuwige, de God van Israël, had gegeven. De koning gaf hem heel zijn verzoek, naar de hand van de Eeuwige, zijn God, over hem.","JPS: the hand of the LORD his God; фр.: la protection de Dieu. По-еврейски כְּיַד־יְהֹוָה אֱלֹהָיו עָלָיו — по руке Господа, его Бога, на нём."],"ezra-7-7":["Поднялись из сыновей Исраэля и из священников, левиим, певцов, привратников и нетиним в Йерушалаим, в седьмой год царя Артахшасты.","Zij trokken op uit de zonen van Israël en uit de priesters, de Leviem, de zangers, de poortwachters en de netinim naar Jeroesjalajim, in het zevende jaar van koning Artachsjasta.","JPS: the Nethinim; фр.: serviteurs. По-еврейски הַנְּתִינִים — нетиним."],"ezra-7-8":["Он пришёл в Йерушалаим в пятый месяц. Это седьмой год царя.","Hij kwam in Jeroesjalajim aan in de vijfde maand. Het was het zevende jaar van de koning.",""],"ezra-7-9":["Потому что в первый день первого месяца он — основание подъёма из Бавеля, а в первый день пятого месяца он пришёл в Йерушалаим, по доброй руке его Бога на нём.","Want op de eerste dag van de eerste maand was hij de grondslag van het optrekken uit Bavel, en op de eerste dag van de vijfde maand kwam hij in Jeroesjalajim aan, naar de goede hand van zijn God over hem.","יְסֻד הַמַּעֲלָה тёмное: основание подъёма. JPS: began he to go up; фр.: commença à s’organiser le départ. יַד־אֱלֹהָיו הַטּוֹבָה — добрая рука его Бога; фр.: la protection de Dieu."],"ezra-7-10":["Потому что Эзра приготовил своё сердце искать Тору Господа, и исполнять, и учить в Исраэле закон и право.","Want Ezra had zijn hart bereid om de Tora van de Eeuwige te zoeken, en te doen, en in Israël wet en recht te onderwijzen.","JPS: to seek… and to do it… statutes and ordinances; фр.: étudier… la pratiquer… la loi et le droit. По-еврейски לִדְרֹשׁ — искать; וְלַעֲשֹׂת без «её»; חֹק וּמִשְׁפָּט — закон и право, единственное число."],"exodus-14-26":["Господь сказал Моше: «Протяни руку над морем, и воды вернутся на Мицраим, на его колесницу и на его всадников».","De Eeuwige zei tegen Mosje: «Strek je hand uit over de zee, en het water zal terugkeren over Mitsrajim, over zijn wagen en over zijn ruiters.»","JPS: the Egyptians, their chariots and their horsemen. По-еврейски מִצְרַיִם, רִכְבּוֹ, פָּרָשָׁיו — Мицраим, его колесница и его всадники. Фр. сохраняет единственное число."],"exodus-14-27":["Моше протянул руку над морем, и к утру море вернулось к своей силе. Мицраим бежал ему навстречу, и Господь стряхнул Мицраим в середину моря.","Mosje strekte zijn hand uit over de zee, en tegen de morgen keerde de zee terug naar haar kracht. Mitsrajim vluchtte haar tegemoet, en de Eeuwige schudde Mitsrajim af midden in de zee.","JPS: overthrew, to its strength, fled against it; фр.: précipita, reprit son niveau, s’élançaient en avant. По-еврейски וַיְנַעֵר — стряхнул; לְאֵיתָנוֹ — к своей силе; נָסִים לִקְרָאתוֹ — бежали ему навстречу."],"exodus-14-28":["Воды вернулись и покрыли колесницу и всадников, всё войско фараона, которое вошло за ними в море. Не осталось из них ни одного.","Het water keerde terug en bedekte de wagen en de ruiters, heel het leger van de farao dat hen achterna de zee in was gegaan. Niet één van hen bleef over.","Фр.: n’échappa. По-еврейски לֹא־נִשְׁאַר — не осталось. הָרֶכֶב — колесница, единственное число; JPS и фр. ставят множественное."],"exodus-14-29":["А сыновья Исраэля шли по суше посреди моря, и воды были им стеной справа и слева.","De zonen van Israël liepen over droge grond midden door de zee, en het water was hun een muur aan hun rechterhand en aan hun linkerhand.",""],"exodus-14-30":["В тот день Господь спас Исраэля от руки Мицраима, и Исраэль увидел Мицраим мёртвым на берегу моря.","Op die dag redde de Eeuwige Israël uit de hand van Mitsrajim, en Israël zag Mitsrajim dood op de oever van de zee.","JPS: the Egyptians dead. По-еврейски מִצְרַיִם מֵת — Мицраим мёртвый, единственное число. Фр.: l’Égyptien."],"exodus-14-31":["Исраэль увидел великую руку, которую сделал Господь в Мицраиме. Народ устрашился Господа и поверил в Господа и в Моше, Его слугу.","Israël zag de grote hand die de Eeuwige tegen Mitsrajim had gedaan. Het volk vreesde de Eeuwige, en zij vertrouwden op de Eeuwige en op Mosje, Zijn dienaar.","JPS: the great work, feared; фр.: la haute puissance, révéra. По-еврейски הַיָּד הַגְּדֹלָה — великая рука; וַיִּירְאוּ — устрашились."],"exodus-15-1":["Тогда спел Моше и сыновья Исраэля эту песнь Господу. Они сказали: «Буду петь Господу, потому что Он высоко вознёсся. Коня и его всадника Он бросил в море.","Toen zong Mosje, en de zonen van Israël, dit lied voor de Eeuwige. Zij zeiden: «Ik zal zingen voor de Eeuwige, want Hij is hoog verheven. Het paard en zijn ruiter heeft Hij in de zee geworpen.","JPS: I will sing; фр.: Chantons. По-еврейски אָשִׁירָה — буду петь, единственное число. Глагол יָשִׁיר тоже единственного числа."],"exodus-15-2":["Моя сила и песнь — Господь, и Он стал мне спасением. Вот мой Бог, Его я прославлю, Бог моего отца, Его я превознесу.","Mijn kracht en mijn lied is de Eeuwige, en Hij is mij tot redding geworden. Dit is mijn God, Hem zal ik eren, de God van mijn vader, Hem zal ik verheffen.","JPS: song, glorify; фр.: gloire, rends hommage. По-еврейски זִמְרָת — песнь. וְאַנְוֵהוּ тёмное: «прославлю», не «устрою Ему жилище». יָהּ — Господь, не имя."],"exodus-15-3":["Господь — муж войны, Господь — имя Его.","De Eeuwige is een man van de strijd, de Eeuwige is Zijn naam.","JPS: a man of war; фр.: le maître des batailles. По-еврейски אִישׁ מִלְחָמָה — муж войны."],"exodus-15-4":["Колесницы фараона и его войско Он бросил в море, и его отборные командиры потонули в Тростниковом море.","De wagens van de farao en zijn leger wierp Hij in de zee, en de keur van zijn officieren zonk in de Rietzee.","JPS: Red Sea, chosen captains; фр.: mer des Joncs, élite de ses combattants. По-еврейски יַם־סוּף — Тростниковое море; שָׁלִשָׁיו — его шелишим, командиры."],"exodus-15-5":["Бездны покрывают их. Они сошли в глубины, как камень.","De diepten bedekken hen. Zij daalden in de kolken als een steen.","JPS: cover; фр.: s’est fermé. По-еврейски יְכַסְיֻמוּ — покрывают."],"exodus-15-6":["Твоя правая рука, Господь, величественна в силе. Твоя правая рука, Господь, сокрушает врага.","Uw rechterhand, Eeuwige, is heerlijk in kracht. Uw rechterhand, Eeuwige, verplettert de vijand.",""],"exodus-15-7":["И в величии Твоей высоты Ты рушишь тех, кто встаёт на Тебя. Ты посылаешь Свой жар, он пожирает их, как солому.","In de grootheid van Uw hoogheid werpt U neer wie tegen U opstaan. U zendt Uw gloed uit, hij verteert hen als stoppels.",""],"exodus-15-8":["От дуновения Твоих ноздрей воды собрались грудами. Потоки встали, как вал. Бездны застыли в сердце моря.","Door de adem van Uw neusgaten stapelden de wateren zich op. De stromen stonden als een dam. De diepten stolden in het hart van de zee.","JPS: blast of Thy nostrils; фр.: souffle de ta face. По-еврейски אַפֶּיךָ — Твои ноздри."],"exodus-15-9":["Враг сказал: „Я буду гнаться, я настигну, я разделю добычу. Моя душа наполнится ими. Обнажу свой меч, моя рука лишит их владения“.","De vijand zei: „Ik jaag achterna, ik haal in, ik verdeel de buit. Mijn ziel zal van hen vol worden. Ik trek mijn zwaard, mijn hand onteigent hen.“.","JPS: my lust shall be satisfied, destroy; фр.: mon âme s’en repaisse, extermine. По-еврейски תִּמְלָאֵמוֹ נַפְשִׁי — моя душа наполнится ими; תּוֹרִישֵׁמוֹ — лишит владения."],"exodus-15-10":["Ты дунул Своим ветром — море покрыло их. Они пошли ко дну, как свинец, в могучих водах.","U blies met Uw wind, de zee bedekte hen. Zij zonken als lood in de machtige wateren.","Фр.: l’océan. По-еврейски יָם — море."],"exodus-15-11":["Кто как Ты среди богов, Господь? Кто как Ты, величественный во святости, внушающий трепет в хвалах, творящий чудо?","Wie is als U onder de goden, Eeuwige? Wie is als U, heerlijk in heiligheid, ontzagwekkend in lof, die een wonder doet?","JPS: among the mighty, fearful in praises, wonders; фр.: parmi les forts, inaccessible à la louange, merveilles. По-еврейски בָּאֵלִם — среди богов; נוֹרָא תְהִלֹּת — внушающий трепет в хвалах; פֶלֶא — чудо, одно."],"exodus-15-12":["Ты простёр Свою правую руку — земля поглощает их.","U strekte Uw rechterhand uit — de aarde verslindt hen.",""],"exodus-15-13":["Ты вёл Своей милостью народ, который Ты искупил. Ты направлял его Своей силой к Твоему святому жилищу.","U leidde in Uw goedheid het volk dat U hebt vrijgekocht. U geleidde het in Uw kracht naar Uw heilige woning.","Фр.: affranchir. По-еврейски גָּאָלְתָּ — искупил."],"exodus-15-14":["Услышали народы, они дрожат. Трепет охватил жителей Пелашета.","Volken hoorden het, zij beven. Siddering greep de inwoners van Pelasjet.","JPS: pangs; фр.: frisson. По-еврейски חִיל — трепет."],"exodus-15-15":["Тогда смутились вожди Эдома. Вождей Моава охватывает дрожь. Растаяли все жители Кнаана.","Toen werden de hoofden van Edom verbijsterd. Beving grijpt de leiders van Moav aan. Alle inwoners van Kenaän smolten weg.","JPS: mighty men, melted away; фр.: vaillants, consternés. По-еврейски אֵילֵי — овны, вожди; נָמֹגוּ — растаяли."],"exodus-15-16":["На них падают ужас и страх. От величия Твоей руки они немеют, как камень, пока не пройдёт Твой народ, Господь, пока не пройдёт народ, который Ты приобрёл.","Schrik en angst vallen op hen. Door de grootheid van Uw arm verstommen zij als een steen, totdat Uw volk voorbijtrekt, Eeuwige, totdat het volk voorbijtrekt dat U hebt verworven.",""],"exodus-15-17":["Ты приводишь их и насаждаешь их на горе наследия Твоего, на месте, которое Ты устроил Себе для обитания, Господь, — святилище, Владыка, которое утвердили Твои руки.","U brengt hen binnen en plant hen op de berg van Uw erfdeel, de plaats die U voor Uw woning hebt gemaakt, Eeuwige, het heiligdom, Heer, dat Uw handen hebben gegrondvest.","В стихе и יְהֹוָה, и написанное אֲדֹנָי. JPS: O Lord; фр.: ô mon Dieu. אֲדֹנָי — Владыка, не тетраграмматон и не «мой Бог»."],"exodus-15-18":["Господь будет царствовать вовек и вечно».","De Eeuwige zal voor altijd en eeuwig regeren.»",""],"exodus-15-19":["Ведь конь фараона вошёл в море с его колесницей и его всадниками, и Господь обратил на них воды моря. А сыновья Исраэля шли по суше посреди моря.","Want het paard van de farao kwam met zijn wagen en zijn ruiters de zee in, en de Eeuwige deed het water van de zee over hen terugkeren. De zonen van Israël liepen over droge grond midden door de zee.","JPS: horses, chariots; фр.: chevaux, chars. По-еврейски סוּס и רִכְבּוֹ — конь и его колесница, единственное число."],"exodus-15-20":["Мирьям, пророчица, сестра Аарона, взяла бубен в руку, и все женщины вышли за ней с бубнами и с плясками.","Mirjam, de profetes, de zuster van Aharon, nam een trom in haar hand, en alle vrouwen gingen achter haar aan met trommen en met dansen.","JPS: dances; фр.: instruments de danse. По-еврейски מְחֹלֹת — пляски."],"exodus-15-21":["Мирьям ответила им: «Пойте Господу, потому что Он высоко вознёсся. Коня и его всадника Он бросил в море».","Mirjam antwoordde hun: «Zingt voor de Eeuwige, want Hij is hoog verheven. Het paard en zijn ruiter heeft Hij in de zee geworpen.»","JPS: sang unto them; фр.: leur fit répéter. По-еврейски וַתַּעַן לָהֶם — ответила им."],"exodus-15-22":["Моше двинул Исраэля от Тростникового моря. Они вышли в пустыню Шур, шли три дня по пустыне и не нашли воды.","Mosje liet Israël opbreken van de Rietzee. Zij trokken de woestijn Sjoer in, gingen drie dagen door de woestijn en vonden geen water.","JPS: Red Sea; фр.: plage des joncs. По-еврейски מִיַּם־סוּף — от Тростникового моря, не «берег»."],"exodus-15-23":["Они пришли в Мару и не могли пить воду из Мары, потому что воды были горькими. Поэтому её назвали Мара.","Zij kwamen bij Mara en konden het water uit Mara niet drinken, want het water was bitter. Daarom noemde men haar Mara.",""],"exodus-15-24":["Народ роптал на Моше и говорил: «Что нам пить?»","Het volk morde tegen Mosje en zei: «Wat moeten we drinken?»",""],"exodus-15-25":["Он воззвал к Господу, и Господь указал ему дерево. Он бросил его в воду, и вода стала сладкой. Там Он установил ему закон и право, и там испытал его.","Hij riep tot de Eeuwige, en de Eeuwige wees hem een boom. Hij wierp die in het water, en het water werd zoet. Daar stelde Hij voor hem een wet en een recht vast, en daar stelde Hij hem op de proef.","JPS: a tree, for them, proved them; фр.: un bois, lui, le mit à l’épreuve. По-еврейски עֵץ — дерево; לוֹ и נִסָּהוּ — ему и его, единственное число."],"exodus-15-26":["Он сказал: «Если ты будешь внимательно слушать голос Господа, твоего Бога, делать то, что прямо в Его глазах, приклонять ухо к Его мицвот и хранить все Его уставы, то всю болезнь, которую Я навёл на Мицраим, Я не наведу на тебя, потому что Я — Господь, твой целитель».","Hij zei: «Als je goed luistert naar de stem van de Eeuwige, je God, en doet wat recht is in Zijn ogen, en je oor neigt naar Zijn mitswot, en al Zijn inzettingen houdt, dan zal Ik geen enkele ziekte die Ik op Mitsrajim heb gelegd, op jou leggen, want Ik ben de Eeuwige, je genezer.»","JPS: diseases, that healeth thee; фр.: plaies, je te préserverai. По-еврейски מַחֲלָה — болезнь; רֹפְאֶךָ — твой целитель. Обращение единственное."],"exodus-15-27":["Они пришли в Эйлим. Там было двенадцать источников воды и семьдесят пальм, и они стали там станом у воды.","Zij kwamen bij Eilim. Daar waren twaalf waterbronnen en zeventig palmen, en zij sloegen daar hun kamp op bij het water.",""],"exodus-16-1":["Они отправились из Эйлима, и вся община сыновей Исраэля пришла в пустыню Син, что между Эйлимом и Синаем, в пятнадцатый день второго месяца после их выхода из земли Мицраима.","Zij braken op uit Eilim, en heel de gemeenschap van de zonen van Israël kwam in de woestijn Sin, die tussen Eilim en Sinaj ligt, op de vijftiende dag van de tweede maand na hun uittocht uit het land Mitsrajim.",""],"exodus-16-2":["Вся община сыновей Исраэля роптала в пустыне на Моше и на Аарона.","Heel de gemeenschap van de zonen van Israël morde in de woestijn tegen Mosje en tegen Aharon.",""],"exodus-16-3":["Сыновья Исраэля сказали им: «Если бы только мы умерли от руки Господа в земле Мицраима, когда сидели у котла с мясом и ели хлеб досыта. Ведь вы вывели нас в эту пустыню, чтобы уморить голодом всё это собрание».","De zonen van Israël zeiden tegen hen: «Waren we maar gestorven door de hand van de Eeuwige in het land Mitsrajim, toen we bij de pot met vlees zaten en brood aten tot we verzadigd waren. Jullie hebben ons naar deze woestijn geleid om heel deze gemeente door honger te doden.»","JPS: flesh-pots; фр.: marmites, tout ce peuple. По-еврейски סִיר הַבָּשָׂר — котёл с мясом, один; הַקָּהָל — собрание."],"exodus-16-4":["Господь сказал Моше: «Вот, Я пролью вам хлеб с неба. Народ выйдет и будет собирать дневную долю в свой день, чтобы Мне испытать его: пойдёт ли он по Моей Торе или нет.","De Eeuwige zei tegen Mosje: «Zie, Ik laat voor jullie brood uit de hemel regenen. Het volk zal uitgaan en de voorraad van de dag op die dag verzamelen, zodat Ik hem op de proef stel: zal hij in Mijn Tora gaan of niet.","JPS: prove them, walk in My law; фр.: s’il obéit, ma doctrine. По-еврейски אֲנַסֶּנּוּ и הֲיֵלֵךְ — его и он, единственное число; בְּתוֹרָתִי — идти по Моей Торе."],"exodus-16-5":["А в шестой день они приготовят то, что принесут, и будет вдвое против того, что они собирают изо дня в день».","Op de zesde dag zullen zij klaarmaken wat zij binnenbrengen, en het zal het dubbele zijn van wat zij dag aan dag verzamelen.»",""],"exodus-16-6":["Моше и Аарон сказали всем сыновьям Исраэля: «Вечером вы узнаете, что Господь вывел вас из земли Мицраима,","Mosje en Aharon zeiden tegen alle zonen van Israël: «Tegen de avond zullen jullie weten dat de Eeuwige jullie uit het land Mitsrajim heeft geleid,",""],"exodus-16-7":["а утром вы увидите славу Господа, когда Он услышит ваш ропот на Господа. А мы что, что вы ропщете на нас?»","en in de morgen zullen jullie de heerlijkheid van de Eeuwige zien, wanneer Hij jullie gemor tegen de Eeuwige hoort. En wat zijn wij, dat jullie tegen ons morren?»","JPS: for that He hath heard; фр.: lorsqu’il fera droit. По-еврейски בְּשׇׁמְעוֹ — когда Он услышит, без «воздаст»."],"exodus-16-8":["Моше сказал: «Когда Господь даст вам вечером мясо в пищу, а утром хлеб досыта, когда Господь услышит ваш ропот, которым вы ропщете на Него, — а мы что? Не на нас ваш ропот, а на Господа».","Mosje zei: «Wanneer de Eeuwige jullie ’s avonds vlees te eten geeft en ’s morgens brood tot verzadiging, wanneer de Eeuwige het gemor hoort dat jullie tegen Hem uiten — wat zijn wij? Jullie gemor is niet tegen ons, maar tegen de Eeuwige.»","Фр.: lorsque Dieu vous donnera, и добавляет Vous le verrez. По-еврейски יְהֹוָה — Господь; этих слов в стихе нет."],"exodus-16-9":["Моше сказал Аарону: «Скажи всей общине сыновей Исраэля: „Приблизьтесь перед лицом Господа, потому что Он услышал ваш ропот“».","Mosje zei tegen Aharon: «Zeg tegen heel de gemeenschap van de zonen van Israël: „Komt nader tot voor de Eeuwige, want Hij heeft jullie gemor gehoord.“»",""],"exodus-16-10":["И когда Аарон говорил всей общине сыновей Исраэля, они обернулись к пустыне, и вот — слава Господа явилась в облаке.","Toen Aharon sprak tot heel de gemeenschap van de zonen van Israël, wendden zij zich naar de woestijn, en zie: de heerlijkheid van de Eeuwige verscheen in de wolk.","Фр.: la majesté divine. По-еврейски כְּבוֹד יְהֹוָה — слава Господа."],"nehemiah-9-5":["И сказали левиим — Йешуа и Кадмиэль, Бани, Хашавнея, Шеревья, Ходия, Шеванья, Петахья: «Встаньте, благословите Господа, вашего Бога, от века и до века. И пусть благословят Твоё славное имя, превознесённое над всяким благословением и хвалой.","De Leviem zeiden — Jesjoea en Kadmiël, Bani, Chasjavneja, Sjerevja, Hodija, Sjevanja, Petachja: «Staat op, zegent de Eeuwige, jullie God, van eeuwigheid tot eeuwigheid. En laten zij Uw heerlijke naam zegenen, verheven boven elke zegen en elke lof.","JPS добавляет let them say: Blessed be; фр. добавляет qui existe. По-еврейски בָּרְכוּ מִן־הָעוֹלָם עַד־הָעוֹלָם — благословите от века до века; וִיבָרְכוּ — пусть благословят, без «благословен»."],"nehemiah-9-6":["Это Ты, Господь, Ты один. Ты сотворил небо, небеса небес и всё их воинство, землю и всё, что на ней, моря и всё, что в них. Ты хранишь их всех в живых, и воинство небес повергается ниц перед Тобой.","U bent het, Eeuwige, U alleen. U hebt de hemel gemaakt, de hemel der hemelen en heel hun legerschaar, de aarde en alles wat daarop is, de zeeën en alles wat daarin is. U houdt dit alles in leven, en de legerschaar van de hemel werpt zich voor U neer.","JPS: worshippeth; фр.: s’incline. По-еврейски מִשְׁתַּחֲוִים — повергаются ниц. JPS: preservest; фр.: donnes la vie. מְחַיֶּה — хранишь живыми."],"nehemiah-9-7":["Это Ты, Господь, Бог, который избрал Аврама, вывел его из Ур-Касдим и дал ему имя Авраам.","U bent het, de Eeuwige, de God, die Avram koos, hem uit Ur-Kasdim leidde en hem de naam Abraham gaf.",""],"nehemiah-9-8":["Ты нашёл его сердце верным перед Тобой и заключил с ним брит: отдать землю кнаани, хетта, эмори, перизея, евусея и гиргаши, отдать её его потомству. Ты исполнил Свои слова, потому что Ты праведен.","U vond zijn hart trouw voor U en sloot met hem de briet om het land van de Kenaäniet, de Chitti, de Emori, de Perizzi, de Jevusiet en de Girgasji te geven, om het aan zijn nageslacht te geven. U hebt Uw woorden waargemaakt, want U bent rechtvaardig.",""],"nehemiah-9-9":["Ты увидел бедствие наших отцов в Мицраиме и их вопль услышал у Тростникового моря.","U zag de ellende van onze vaderen in Mitsrajim, en hun geroep hoorde U bij de Rietzee.","JPS: Red Sea; фр.: mer des joncs. По-еврейски יַם־סוּף — Тростниковое море."],"nehemiah-9-10":["Ты дал знамения и чудеса на фараона, на всех его слуг и на весь народ его земли, потому что Ты знал, что они дерзко поступали с ними. И Ты сделал Себе имя, как это сегодня.","U gaf tekenen en wonderen aan de farao, aan al zijn dienaren en aan heel het volk van zijn land, want U wist dat zij vermetel tegen hen handelden. U maakte Zich een naam, zoals het vandaag is.","JPS: dealt proudly; фр.: agi tyranniquement. По-еврейски הֵזִידוּ — поступали дерзко."],"nehemiah-9-11":["Ты рассёк перед ними море, и они прошли посреди моря по суше, а их преследователей Ты бросил в глубины, как камень в могучие воды.","De zee spleet U voor hen. Zij trokken midden door de zee over droge grond, en hun achtervolgers wierp U in de diepten, als een steen in machtige wateren.","Фр.: persécuteurs. По-еврейски רֹדְפֵיהֶם — преследователи."],"nehemiah-9-12":["Столпом облака Ты вёл их днём и столпом огня ночью, чтобы освещать им путь, которым идти.","In een wolkkolom leidde U hen overdag en in een vuurkolom bij nacht, om voor hen de weg te verlichten waarop zij moesten gaan.",""],"nehemiah-9-13":["Ты сошёл на гору Синай и говорил с ними с небес. Ты дал им прямые суды, истинные учения, добрые уставы и мицвот.","U daalde neer op de berg Sinaj en sprak met hen vanuit de hemel. U gaf hun rechte vonnissen, ware leringen, goede inzettingen en mitswot.","JPS: laws of truth; фр.: doctrines de vérité. По-еврейски תּוֹרוֹת — учения, множественное число."],"nehemiah-9-14":["Ты открыл им Твой святой шабат и заповедал им мицвот, уставы и Тору рукою Моше, Твоего слуги.","Uw heilige sjabbat maakte U hun bekend, en mitswot, inzettingen en Tora gebood U hun door de hand van Mosje, Uw dienaar.","Фр.: une doctrine, par l’organe de Moïse. По-еврейски תּוֹרָה — Тора; בְּיַד מֹשֶׁה — рукою Моше."],"nehemiah-9-15":["Хлеб с неба Ты дал им против их голода, воду из скалы Ты вывел им против их жажды и сказал им пойти и взять во владение землю, о которой Ты поднял Свою руку, чтобы отдать её им.","Brood uit de hemel gaf U hun voor hun honger, water uit de rots deed U voor hen ontspringen voor hun dorst, en U zei hun dat zij binnen moesten gaan om het land in bezit te nemen waarvan U Uw hand had opgeheven om het hun te geven.","JPS: lifted up Thy hand; фр.: promis solennellement. По-еврейски נָשָׂאתָ אֶת־יָדְךָ — Ты поднял Свою руку."],"nehemiah-9-16":["Но они и наши отцы поступали дерзко, сделали свою шею жёсткой и не слушали Твоих мицвот.","Maar zij en onze vaderen handelden vermetel, zij maakten hun nek hard en luisterden niet naar Uw mitswot.","Фр.: eux, nos ancêtres, как одно. По-еврейски וְהֵם וַאֲבֹתֵינוּ — и они, и наши отцы."],"nehemiah-9-17":["Они отказались слушать и не помнили Твоих чудес, которые Ты сделал с ними. Они сделали свою шею жёсткой и поставили вождя, чтобы вернуться в своё рабство, в своём мятеже. Но Ты — Бог прощений, благосклонный и милосердный, медленный на гнев и великий милостью, и Ты не оставил их.","Zij weigerden te luisteren en dachten niet aan Uw wonderen die U bij hen had gedaan. Zij maakten hun nek hard en stelden een hoofd aan om in hun opstand terug te keren naar hun slavernij. Maar U bent een God van vergevingen, genadig en barmhartig, traag tot toorn en groot in goedheid, en U hebt hen niet verlaten.","JPS: a God ready to pardon; фр.: un Dieu de pardon. По-еврейски אֱלוֹהַּ סְלִיחוֹת — Бог прощений, множественное число."],"nehemiah-9-18":["Мало того: они сделали себе литого тельца и сказали: „Это твой бог, который вывел тебя из Мицраима“, и совершили великие оскорбления.","Sterker nog: zij maakten voor zichzelf een gegoten kalf en zeiden: „Dit is je god, die je uit Mitsrajim heeft geleid“, en zij begingen grote beschimpingen.","JPS: provocations; фр.: blasphèmes. По-еврейски נֶאָצוֹת — оскорбления. זֶה אֱלֹהֶיךָ — этот твой бог, единственное число."],"nehemiah-9-19":["А Ты, в великих Твоих милостях, не оставил их в пустыне. Столп облака не отходил от них сверху днём, чтобы вести их по пути, и столп огня ночью, чтобы светить им, и путь, которым им идти.","Maar U, in Uw vele barmhartigheden, hebt hen in de woestijn niet verlaten. De wolkkolom week overdag niet van boven hen om hen op de weg te leiden, en de vuurkolom bij nacht om hun licht te geven, en de weg waarop zij moesten gaan.","В конце וְאֶת־הַדֶּרֶךְ — «и путь». JPS сохраняет and the way; фр. сглаживает в le chemin."],"nehemiah-9-20":["Твой добрый дух Ты дал, чтобы вразумлять их, и Твой ман Ты не отнял от их рта, и воду Ты дал им против их жажды.","Uw goede geest gaf U om hen inzicht te geven, Uw man onthield U niet aan hun mond, en water gaf U hun voor hun dorst.","JPS: Thy good spirit; фр.: ton esprit de bienveillance. По-еврейски רוּחֲךָ הַטּוֹבָה — Твой добрый дух."],"nehemiah-9-21":["Сорок лет Ты кормил их в пустыне. Они ни в чём не нуждались. Их одежды не износились, и их ноги не опухали.","Veertig jaar onderhield U hen in de woestijn. Zij kwamen niets tekort. Hun kleren sleten niet, en hun voeten zwollen niet.","JPS: swelled not; фр.: ne furent meurtris. По-еврейски לֹא בָצֵקוּ — не опухли."],"nehemiah-9-22":["Ты отдал им царства и народы и разделил их по сторонам. Они взяли во владение землю Сихона и землю царя Хешбона и землю Ога, царя Башана.","U gaf hun koninkrijken en volken en deelde hen in naar de zijde. Zij namen het land van Sichon in bezit, het land van de koning van Chesjbon en het land van Og, koning van Basjan.","לְפֵאָה тёмное. JPS: quarter by quarter; фр.: dans toute direction. По-еврейски — по стороне. Земля Сихона и земля царя Хешбона названы рядом."],"nehemiah-9-23":["Их сыновей Ты умножил, как звёзды небес, и привёл их в землю, о которой Ты сказал их отцам, чтобы войти и взять её во владение.","Hun zonen maakte U talrijk als de sterren van de hemel, en U bracht hen naar het land waarvan U tegen hun vaderen had gezegd dat zij het binnen moesten gaan om het in bezit te nemen.","Фр.: conquérir. По-еврейски לָרָשֶׁת — взять во владение."],"exodus-19-1":["В третий месяц после выхода сынов Исраэля из земли Мицраим, в этот день, они пришли в пустыню Синай.","In de derde maand na de uittocht van de kinderen van Israël uit het land Mitsrajim, op deze dag, kwamen zij in de woestijn Sinaj.","фр.: troisième néoménie. По-еврейски בַּחֹדֶשׁ הַשְּׁלִישִׁי — в третий месяц. JPS: third month."],"exodus-19-2":["Они отправились из Рефидима, пришли в пустыню Синай и встали лагерем в пустыне. Там Исраэль встал лагерем напротив горы.","Zij vertrokken uit Refidim, kwamen in de woestijn Sinaj en sloegen hun kamp op in de woestijn. Daar sloeg Israël zijn kamp op tegenover de berg.",""],"exodus-19-3":["Моше поднялся к Богу, и Господь позвал его с горы и сказал: «Так скажи дому Яакова и объяви сынам Исраэля:","Mosje ging omhoog naar God, en de Eeuwige riep hem vanaf de berg en zei: «Zeg dit tot het huis van Jaäkov en maak het bekend aan de kinderen van Israël:","фр.: vers le Seigneur для обоих имён. По-еврейски אֶל־הָאֱלֹהִים — к Богу, затем יְהֹוָה — Господь. JPS: unto God, the LORD."],"exodus-19-4":["„Вы видели, что Я сделал с Мицраимом. Я нёс вас на орлиных крыльях и привёл вас к Себе.","„Jullie hebben gezien wat Ik Mitsrajim heb aangedaan. Ik heb jullie op adelaarsvleugels gedragen en jullie bij Mij gebracht.",""],"exodus-19-5":["Теперь, если вы действительно будете слушать Мой голос и хранить Мою брит, вы будете Моим драгоценным достоянием из всех народов, потому что вся земля — Моя.","Nu dan, als jullie werkelijk naar Mijn stem luisteren en Mijn briet bewaren, zullen jullie Mijn kostbare bezit zijn uit alle volken, want de hele aarde is van Mij.",""],"exodus-19-6":["А вы будете для Меня царством священников и святым народом“. Вот слова, которые ты скажешь сынам Исраэля».","En jullie zullen voor Mij een koninkrijk van priesters zijn en een heilig volk.“ Dit zijn de woorden die je tot de kinderen van Israël zult spreken.»","фр.: dynastie de pontifes. По-еврейски מַמְלֶכֶת כֹּהֲנִים — царство священников. JPS: a kingdom of priests."],"exodus-19-7":["Моше пришёл, созвал старейшин народа и изложил перед ними все эти слова, которые заповедал ему Господь.","Mosje kwam, riep de oudsten van het volk bijeen en legde hun al deze woorden voor die de Eeuwige hem had opgedragen.",""],"exodus-19-8":["Весь народ ответил вместе и сказал: «Всё, что сказал Господь, мы сделаем». Моше передал слова народа Господу.","Heel het volk antwoordde samen en zei: «Alles wat de Eeuwige heeft gesproken, zullen wij doen.» Mosje bracht de woorden van het volk over aan de Eeuwige.",""],"exodus-19-9":["Господь сказал Моше: «Вот, Я приду к тебе в густом облаке, чтобы народ слышал, когда Я говорю с тобой, и чтобы они также навсегда верили тебе». Моше передал слова народа Господу.","De Eeuwige zei tegen Mosje: «Zie, Ik kom naar je in een dichte wolk, zodat het volk hoort wanneer Ik met je spreek, en zodat zij ook voor altijd in je geloven.» Mosje bracht de woorden van het volk over aan de Eeuwige.","фр.: je t’apparaîtrai; que c’est moi qui te parle. По-еврейски בָא אֵלֶיךָ — Я приду к тебе; בְּדַבְּרִי עִמָּךְ — когда Я говорю с тобой. JPS: I come unto thee; when I speak with thee."],"exodus-19-10":["Господь сказал Моше: «Пойди к народу и освяти их сегодня и завтра, и пусть они вымоют свои одежды.","De Eeuwige zei tegen Mosje: «Ga naar het volk en heilig hen vandaag en morgen, en laten zij hun kleren wassen.","фр.: enjoins-leur de se tenir purs. По-еврейски וְקִדַּשְׁתָּם — освяти их: это делает Моше. JPS: sanctify them."],"exodus-19-11":["Пусть они будут готовы к третьему дню, потому что на третий день Господь сойдёт на глазах у всего народа на гору Синай.","Laten zij gereed zijn voor de derde dag, want op de derde dag zal de Eeuwige voor de ogen van heel het volk neerdalen op de berg Sinaj.",""],"exodus-19-12":["И проведи границу вокруг народа и скажи: „Берегитесь подниматься на гору и касаться её края. Всякий, кто коснётся горы, непременно будет предан смерти.","En baken het volk rondom af en zeg: „Pas op dat jullie de berg niet opgaan en zijn rand niet aanraken. Ieder die de berg aanraakt, zal zeker ter dood worden gebracht.","фр.: maintiendras le peuple; toucher le pied. По-еврейски וְהִגְבַּלְתָּ — проведи границу; בְּקָצֵהוּ — край горы. JPS: set bounds; the border of it."],"exodus-19-13":["Рука пусть не коснётся его, потому что его непременно забьют камнями или застрелят. Скотина или человек — он не останется в живых. Когда протянется звук бараньего рога, они поднимутся на гору“».","Geen hand mag hem aanraken, want hij zal zeker gestenigd of neergeschoten worden. Dier of mens, hij zal niet in leven blijven. Wanneer de ramshoorn lang aangehouden wordt, zullen zij de berg opgaan.“»","фр.: aux derniers sons du cor. По-еврейски בִּמְשֹׁךְ הַיֹּבֵל — когда протянут бараний рог. JPS: when the ram’s horn soundeth long."],"exodus-19-14":["Моше сошёл с горы к народу, освятил народ, и они вымыли свои одежды.","Mosje daalde van de berg af naar het volk, heiligde het volk, en zij wasten hun kleren.",""],"exodus-19-15":["Он сказал народу: «Будьте готовы три дня. Не приближайтесь к женщине».","Hij zei tegen het volk: «Wees drie dagen gereed. Kom niet bij een vrouw.»","JPS: against the third day; фр.: pour le troisième jour. По-еврейски לִשְׁלֹשֶׁת יָמִים — на три дня, не «к третьему дню»."],"exodus-19-16":["На третий день, когда настало утро, были громы, молнии и тяжёлое облако на горе, и очень сильный звук шофара. Весь народ, который был в лагере, задрожал.","Op de derde dag, toen het morgen werd, waren er donderslagen, bliksemschichten en een zware wolk op de berg, en een zeer sterke klank van de sjofar. Heel het volk dat in het kamp was, beefde.",""],"exodus-19-17":["Моше вывел народ из лагеря навстречу Богу, и они встали у подножия горы.","Mosje leidde het volk het kamp uit, God tegemoet, en zij stelden zich op aan de voet van de berg.","фр.: la Divinité. По-еврейски הָאֱלֹהִים — Бог. JPS: God."],"exodus-19-18":["Гора Синай вся дымилась, потому что Господь сошёл на неё в огне. Её дым поднимался, как дым печи, и вся гора сильно задрожала.","De berg Sinaj rookte geheel, omdat de Eeuwige in vuur op hem neerdaalde. Zijn rook steeg op als de rook van een oven, en de hele berg beefde hevig.",""],"exodus-19-19":["Звук шофара становился всё сильнее. Моше говорил, и Бог отвечал ему голосом.","De klank van de sjofar werd almaar sterker. Mosje sprak, en God antwoordde hem met een stem.","фр.: la voix divine lui répondait. По-еврейски וְהָאֱלֹהִים יַעֲנֶנּוּ בְקוֹל — Бог отвечал ему голосом. JPS: God answered him by a voice."],"exodus-19-20":["Господь сошёл на гору Синай, на вершину горы. Господь позвал Моше на вершину горы, и Моше поднялся.","De Eeuwige daalde neer op de berg Sinaj, op de top van de berg. De Eeuwige riep Mosje naar de top van de berg, en Mosje ging omhoog.",""],"exodus-19-21":["Господь сказал Моше: «Сойди, предупреди народ, чтобы они не прорвались к Господу смотреть и чтобы многие из них не пали.","De Eeuwige zei tegen Mosje: «Daal af, waarschuw het volk, anders breken zij door naar de Eeuwige om te kijken en vallen er velen van hen.","фр.: contempler sa gloire. По-еврейски לִרְאוֹת — чтобы смотреть; «слава» не сказано. JPS: to gaze."],"exodus-19-22":["И священники, которые приближаются к Господу, пусть освятятся, чтобы Господь не разразился против них».","Ook de priesters die tot de Eeuwige naderen, moeten zich heiligen, anders breekt de Eeuwige tegen hen uit.»","фр.: plus rapprochés; s’observent religieusement. По-еврейски הַנִּגָּשִׁים יִתְקַדָּשׁוּ — приближающиеся пусть освятятся. JPS: that come near, sanctify themselves."],"exodus-19-23":["Моше сказал Господу: «Народ не может подняться на гору Синай, потому что Ты предупредил нас: „Проведи границу вокруг горы и освяти её“».","Mosje zei tegen de Eeuwige: «Het volk kan de berg Sinaj niet opgaan, want U hebt ons gewaarschuwd: „Zet een grens om de berg en heilig hem.“»",""],"exodus-19-24":["Господь сказал ему: «Иди, сойди, а потом поднимешься ты и Аарон с тобой. А священники и народ пусть не прорываются, чтобы подняться к Господу, иначе Он разразится против них».","De Eeuwige zei tegen hem: «Ga, daal af, en daarna zul je opgaan, jij en Aharon met je. Maar de priesters en het volk mogen niet doorbreken om naar de Eeuwige op te gaan, anders breekt Hij tegen hen uit.»",""],"exodus-19-25":["Моше сошёл к народу и сказал им.","Mosje daalde af naar het volk en zei tegen hen.","JPS: told them; фр.: lui en fit part. По-еврейски וַיֹּאמֶר אֲלֵהֶם — и сказал им; самих слов нет."],"exodus-20-1":["Бог произнёс все эти слова и сказал:","God sprak al deze woorden en zei:",""],"exodus-20-2":["«Я — Господь, твой Бог, который вывел тебя из земли Мицраим, из дома рабов.","«Ik ben de Eeuwige, je God, die je uit het land Mitsrajim heeft geleid, uit het huis van slaven.",""],"exodus-20-3":["Да не будет у тебя других богов пред Моим лицом.","Je zult geen andere goden hebben voor Mijn aangezicht.","фр.: d’autre dieu que moi. По-еврейски אֱלֹהִים אֲחֵרִים עַל־פָּנָי — другие боги пред Моим лицом. JPS: no other gods before Me."],"exodus-20-4":["Не делай себе изваяния и никакого изображения того, что на небе вверху, что на земле внизу и что в воде под землёй.","Maak voor jezelf geen gesneden beeld en geen enkele afbeelding van wat boven in de hemel is, van wat beneden op de aarde is en van wat in het water onder de aarde is.","фр.: idole. По-еврейски פֶסֶל — изваяние, резное изображение. JPS: graven image."],"exodus-20-5":["Не поклоняйся им и не служи им, потому что Я — Господь, твой Бог, ревнивый Бог. Я взыскиваю вину отцов с детей, с третьего и с четвёртого поколения тех, кто ненавидит Меня,","Buig je niet voor hen neer en dien hen niet, want Ik ben de Eeuwige, je God, een jaloerse God. Ik zoek de schuld van de vaders op bij de kinderen, bij het derde en bij het vierde geslacht van hen die Mij haten,","фр.: le crime; qui m’offensent. По-еврейски עֲוֺן — вина; לְשֹׂנְאָי — ненавидящих Меня. JPS: iniquity; them that hate Me."],"exodus-20-6":["и оказываю верность тысячам — тем, кто любит Меня и хранит Мои заповеди.","en Ik bewijs trouw aan duizenden, aan wie Mij liefhebben en Mijn geboden bewaren.","JPS: mercy unto the thousandth generation; фр.: bienveillance à la millième. По-еврейски חֶסֶד לַאֲלָפִים — верность тысячам; слово «поколение» не сказано."],"exodus-20-7":["Не произноси имени Господа, твоего Бога, напрасно, потому что Господь не признает невиновным того, кто произносит Его имя напрасно.","Neem de naam van de Eeuwige, je God, niet tevergeefs op, want de Eeuwige spreekt niet vrij wie zijn naam tevergeefs opneemt.","фр.: à l’appui du mensonge. По-еврейски לַשָּׁוְא — напрасно, впустую. JPS: in vain."],"exodus-20-8":["Помни день шабата, чтобы освящать его.","Gedenk de dag van de sjabbat, om die te heiligen.",""],"exodus-20-9":["Шесть дней работай и делай всю свою работу,","Zes dagen zul je arbeiden en al je werk doen,",""],"exodus-20-10":["а седьмой день — шабат для Господа, твоего Бога. Не делай никакой работы: ни ты, ни твой сын, ни твоя дочь, ни твой раб, ни твоя рабыня, ни твой скот, ни твой пришелец, который в твоих воротах.","maar de zevende dag is een sjabbat voor de Eeuwige, je God. Doe geen enkel werk, jij niet, je zoon niet, je dochter niet, je slaaf niet, je slavin niet, je vee niet, en je vreemdeling die in je poorten is niet.","фр.: la trêve de l’Éternel. По-еврейски שַׁבָּת — шабат. JPS: a sabbath. JPS: man-servant, maid-servant; по-еврейски עֶבֶד וַאֲמָה — раб и рабыня."],"exodus-20-11":["Потому что за шесть дней Господь создал небо и землю, море и всё, что в них есть, и отдыхал в седьмой день. Поэтому Господь благословил день шабата и освятил его.","Want in zes dagen heeft de Eeuwige de hemel en de aarde gemaakt, de zee en alles wat daarin is, en Hij rustte op de zevende dag. Daarom heeft de Eeuwige de dag van de sjabbat gezegend en hem geheiligd.",""],"exodus-20-12":["Почитай своего отца и свою мать, чтобы продлились твои дни на земле, которую Господь, твой Бог, даёт тебе.","Eer je vader en je moeder, zodat je dagen lang worden op het land dat de Eeuwige, je God, je geeft.",""],"exodus-20-13":["Не убивай. Не прелюбодействуй. Не кради. Не свидетельствуй ложно против своего ближнего.","Pleeg geen moord. Pleeg geen overspel. Steel niet. Leg tegen je naaste geen vals getuigenis af.",""],"exodus-20-14":["Не желай дома своего ближнего. Не желай жены своего ближнего, ни его раба, ни его рабыни, ни его быка, ни его осла, ни чего-либо, что есть у твоего ближнего».","Begeer het huis van je naaste niet. Begeer de vrouw van je naaste niet, noch zijn slaaf, noch zijn slavin, noch zijn os, noch zijn ezel, noch iets dat van je naaste is.»","JPS: man-servant, maid-servant. По-еврейски וְעַבְדּוֹ וַאֲמָתוֹ — его раб и его рабыня. фр.: esclave, servante."],"isaiah-43-1":["А теперь так сказал Господь, сотворивший тебя, Яаков, и образовавший тебя, Исраэль: «Не бойся, потому что Я выкупил тебя. Я назвал тебя по имени. Ты — Мой.","En nu, zo zegt de Eeuwige, die je geschapen heeft, Jaäkov, en die je gevormd heeft, Israël: «Wees niet bang, want Ik heb je losgekocht. Ik heb je bij je naam geroepen. Jij bent van Mij.","фр.: je vais te libérer. По-еврейски גְאַלְתִּיךָ — Я выкупил тебя, совершенное время. JPS: I have redeemed thee."],"isaiah-43-2":["Когда ты пойдёшь через воды, Я с тобой, а через реки — они тебя не захлестнут. Когда ты пойдёшь сквозь огонь, ты не обожжёшься, и пламя на тебе не разгорится.","Wanneer je door het water gaat, ben Ik bij je, en door de rivieren: zij sleuren je niet mee. Wanneer je door het vuur loopt, zul je niet verbranden, en de vlam zal niet op je branden.",""],"isaiah-43-3":["Потому что Я — Господь, твой Бог, Святой Исраэля, твой избавитель. Я отдал Мицраим как выкуп за тебя, Куш и Севу вместо тебя.","Want Ik ben de Eeuwige, je God, de Heilige van Israël, je redder. Ik heb Mitsrajim als losprijs voor je gegeven, Koesj en Seva in jouw plaats.","JPS: Ethiopia. По-еврейски כּוּשׁ — Куш. фр.: Couch."],"isaiah-43-4":["Потому что ты дорог в Моих глазах, ты в почёте, и Я полюбил тебя, Я отдам человека вместо тебя и народы вместо твоей жизни.","Omdat je kostbaar bent in Mijn ogen, omdat je geëerd bent en Ik je heb liefgehad, zal Ik een mens geven in jouw plaats en volken in plaats van je leven.","JPS: men; фр.: des hommes. По-еврейски אָדָם — человек, единственное число."],"isaiah-43-5":["Не бойся, потому что Я с тобой. С востока приведу твоё семя и с запада соберу тебя.","Wees niet bang, want Ik ben bij je. Van het oosten zal Ik je nageslacht brengen, en van het westen zal Ik je verzamelen.","фр.: tes enfants. По-еврейски זַרְעֶךָ — твоё семя. JPS: thy seed."],"isaiah-43-6":["Скажу северу: „Отдай“, и югу: „Не удерживай. Приведи Моих сыновей издалека и Моих дочерей от края земли,","Ik zal tot het noorden zeggen: „Geef“, en tot het zuiden: „Houd niet tegen. Breng Mijn zonen van verre en Mijn dochters van het einde van de aarde,",""],"isaiah-43-7":["каждого, кто назван Моим именем. Для Моей славы Я сотворил его, Я образовал его и даже создал его“».","ieder die bij Mijn naam geroepen is. Tot Mijn eer heb Ik hem geschapen, Ik heb hem gevormd, Ik heb hem ook gemaakt.“»","фр.: qui se réclament de mon nom. По-еврейски הַנִּקְרָא בִשְׁמִי — кто назван Моим именем. JPS: that is called by My name."],"isaiah-43-8":["Выведи слепой народ, хотя у него есть глаза, и глухих, хотя у них есть уши.","Breng het blinde volk naar buiten, hoewel het ogen heeft, en de doven, hoewel zij oren hebben.","JPS: shall be brought forth; фр.: Laissez sortir. По-еврейски הוֹצִיא — выведи."],"isaiah-43-9":["Все народы собрались вместе, и пусть соберутся племена. Кто среди них возвестит это и даст нам услышать прежнее? Пусть представят своих свидетелей и будут правы, пусть услышат и скажут: «Истина».","Alle volken zijn samen verzameld, laten de naties samenkomen. Wie onder hen maakt dit bekend en laat ons de vroegere dingen horen? Laten zij hun getuigen aandragen en in het gelijk worden gesteld, laten zij het horen en zeggen: «Waarheid.»","фр.: Que tous se réunissent; prédictions de jadis. По-еврейски נִקְבְּצוּ — уже собрались; רִאשֹׁנוֹת — прежнее, не предсказания. JPS: are gathered; former things."],"isaiah-43-10":["«Вы — Мои свидетели, — слово Господа, — и Мой раб, которого Я избрал, чтобы вы знали, верили Мне и поняли, что Я — Он. Прежде Меня не был сотворён бог, и после Меня иного не будет.","«Jullie zijn Mijn getuigen, — uitspraak van de Eeuwige, — en Mijn dienaar die Ik heb gekozen, opdat jullie weten, Mij geloven en begrijpen dat Ik het ben. Vóór Mij is geen god gevormd, en na Mij zal er geen zijn.","фр.: nul Dieu n’a existé. По-еврейски לֹא־נוֹצַר אֵל — не был сотворён бог. JPS: there was no God formed."],"isaiah-43-11":["Я, Я — Господь, и нет избавителя кроме Меня.","Ik, Ik ben de Eeuwige, en buiten Mij is er geen redder.",""],"isaiah-43-12":["Я возвестил, Я избавил и Я дал услышать, и нет среди вас чужого. Вы — Мои свидетели, — слово Господа, — и Я — Бог.","Ik heb verkondigd, Ik heb gered en Ik heb doen horen, en er is geen vreemde onder jullie. Jullie zijn Mijn getuigen, — uitspraak van de Eeuwige, — en Ik ben God.","JPS: no strange god; фр.: aucun [dieu] étranger; votre Dieu. По-еврейски וְאֵין בָּכֶם זָר — нет среди вас чужого, слово «бог» не сказано; וַאֲנִי־אֵל — и Я Бог."],"isaiah-43-13":["Даже от дня Я — Он, и некому вырвать из Моей руки. Я совершу, и кто повернёт это вспять?»","Ook vanaf de dag ben Ik het, en niemand kan uit Mijn hand redden. Ik zal handelen, en wie zal het keren?»","גַּם־מִיּוֹם неясно. JPS: since the day was; фр.: dès l’origine des jours. Буквально «также от дня»; «изначала» в тексте нет."],"isaiah-43-14":["Так сказал Господь, ваш Выкупитель, Святой Исраэля: «Ради вас Я послал в Бавель и низвёл всех беглецов, и Касдим — в кораблях их крика.","Zo zegt de Eeuwige, jullie Verlosser, de Heilige van Israël: «Omwille van jullie heb Ik naar Bavel gezonden en alle vluchtenden neergehaald, en de Kasdim in de schepen van hun geschreeuw.","Стих тёмен. JPS: I have sent to Babylon; fugitives; ships of their shouting. фр.: un mandataire; vaisseaux qu’ils prônaient. По-еврейски у «послал» нет объекта; בָּאֳנִיּוֹת רִנָּתָם — в кораблях их крика."],"isaiah-43-15":["Я — Господь, ваш Святой, Творец Исраэля, ваш Царь».","Ik ben de Eeuwige, jullie Heilige, de Schepper van Israël, jullie Koning.»",""],"isaiah-43-16":["Так сказал Господь, который даёт путь в море и тропу в могучих водах,","Zo zegt de Eeuwige, die een weg geeft in de zee en een pad in de machtige wateren,",""],"isaiah-43-17":["который выводит колесницу и коня, войско и мощь вместе. Они лягут и не встанут, погасли и угасли, как льняной фитиль.","die wagen en paard doet uittrekken, leger en kracht samen. Zij zullen neerliggen en niet opstaan, zij zijn gedoofd en uitgeblust als een vlaspit.",""],"isaiah-43-18":["«Не вспоминайте прежнее и не вникайте в древнее.","«Herinner jullie de vroegere dingen niet, en verdiep jullie niet in de dingen van oudsher.",""],"isaiah-43-19":["Вот Я делаю новое. Сейчас оно прорастёт. Разве вы её не узнаете? Я также проложу путь в пустыне, реки в пустоши.","Zie, Ik doe iets nieuws. Nu spruit het op. Zouden jullie het niet kennen? Ik zal ook een weg leggen in de woestijn, rivieren in de woestenij.","фр.: des choses nouvelles. По-еврейски חֲדָשָׁה — одно новое. JPS: a new thing. יְשִׁימוֹן — пустошь, не то же, что מִדְבָּר; JPS: desert, фр.: aride solitude."],"isaiah-43-20":["Меня почтит зверь поля, шакалы и страусы, потому что Я дал в пустыне воду, реки в пустоши, чтобы напоить Мой народ, Моего избранного».","Het wild van het veld zal Mij eren, jakhalzen en struisvogels, omdat Ik in de woestijn water heb gegeven, rivieren in de woestenij, om Mijn volk te drinken te geven, Mijn uitverkorene.»",""],"exodus-22-4":["Если человек вытравит поле или виноградник, пустит свой скот, и тот потравит поле другого, он заплатит лучшим со своего поля и лучшим со своего виноградника.","Als iemand een veld of een wijngaard laat afgrazen, zijn vee uitstuurt en het graast op het veld van een ander, dan betaalt hij met het beste van zijn veld en het beste van zijn wijngaard.","Фр.: du meilleur de son champ ou de sa vigne. По-еврейски מֵיטַב שָׂדֵהוּ וּמֵיטַב כַּרְמוֹ — и лучшим с поля, и лучшим с виноградника."],"exodus-22-5":["Если вырвется огонь и охватит колючки, и сгорит копна, или хлеб на корню, или поле, то тот, кто разжёг, непременно заплатит за пожар.","Als vuur uitbreekt en doorns vat, en een graanschelf, of het graan op stam, of het veld verbrandt, dan moet degene die het vuur heeft aangestoken de brand zeker vergoeden.","JPS: thorns; фр.: buissons и champ d’autrui. По-еврейски קֹצִים — колючки, а чужого поля в стихе нет."],"exodus-22-6":["Если человек отдаст ближнему серебро или вещи на хранение, и их украдут из дома этого человека, то, если вор найдётся, он заплатит вдвое.","Als iemand zijn naaste zilver of spullen in bewaring geeft en die worden uit het huis van die man gestolen, dan betaalt de dief het dubbele, als hij gevonden wordt.",""],"exodus-22-7":["Если вор не найдётся, хозяин дома подойдёт к Богу: не протянул ли он руку к имуществу своего ближнего.","Wordt de dief niet gevonden, dan nadert de heer van het huis tot God, of hij zijn hand niet heeft uitgestoken naar het goed van zijn naaste.","JPS: unto God; фр.: jurer au tribunal. По-еврейски אֶל־הָאֱלֹהִים — к Богу; «клясться» и «суд» в стихе не сказаны."],"exodus-22-8":["Во всяком деле о правонарушении — о быке, об осле, об овце, о плаще, о любой пропаже, о которой скажут: «это оно», — дело обоих дойдёт до Бога. Кого Бог признает виновным, заплатит ближнему вдвое.","Bij elke zaak van een vergrijp — over een rund, over een ezel, over een schaap, over een mantel, over elk verloren voorwerp waarvan iemand zegt: «dit is het» — komt de zaak van beiden voor God. Wie God schuldig verklaart, betaalt zijn naaste het dubbele.","JPS: before God, whom God shall condemn; фр.: au tribunal, les juges. По-еврейски הָאֱלֹהִים и אֱלֹהִים — Бог."],"exodus-22-9":["Если человек отдаст ближнему на хранение осла, или быка, или овцу, или любое животное, и оно умрёт, или будет покалечено, или угнано, и никто этого не видел,","Als iemand zijn naaste een ezel, of een rund, of een schaap, of welk dier ook in bewaring geeft, en het sterft, of wordt verminkt, of weggevoerd, en niemand ziet het,",""],"exodus-22-10":["клятва Господом будет между ними обоими: он не протягивал руку к имуществу своего ближнего. Хозяин примет её, и тот не заплатит.","dan ligt er een eed bij de Eeuwige tussen hen beiden, dat hij zijn hand niet heeft uitgestoken naar het goed van zijn naaste. De eigenaar aanvaardt die, en hij hoeft niet te betalen.","JPS: the oath of the LORD; фр.: un serment solennel. По-еврейски שְׁבֻעַת יְהֹוָה — клятва Господом."],"exodus-22-11":["Если же у него украдут, он заплатит хозяину.","Wordt het bij hem gestolen, dan vergoedt hij het aan de eigenaar.",""],"exodus-22-12":["Если оно будет растерзано, пусть принесёт его как свидетельство. За растерзанное он не платит.","Wordt het verscheurd, dan brengt hij het als getuigenis. Voor het verscheurde hoeft hij niet te betalen.",""],"exodus-22-13":["Если человек возьмёт у ближнего взаймы, и взятое будет покалечено или умрёт, а хозяина при этом нет, он непременно заплатит.","Als iemand iets van zijn naaste leent en het wordt verminkt of sterft, terwijl de eigenaar er niet bij is, dan moet hij het zeker vergoeden.",""],"exodus-22-14":["Если хозяин при нём, тот не платит. Если он наёмный, он пришёл за свою плату.","Is de eigenaar erbij, dan betaalt hij niet. Is hij een gehuurde, dan is hij gekomen voor zijn huur.","Тёмное: אִם־שָׂכִיר הוּא בָּא בִּשְׂכָרוֹ. JPS: если это наёмник, он теряет плату. Фр.: если животное было нанято, его получили за эту плату."],"exodus-22-15":["Если человек соблазнит девственницу, которая не обручена, и ляжет с ней, он непременно внесёт за неё брачный выкуп, чтобы она стала его женой.","Als een man een maagd verleidt die niet uitgehuwelijkt is, en hij ligt bij haar, dan moet hij voor haar de bruidsprijs betalen, zodat zij zijn vrouw wordt.","JPS: pay a dowry. Фр.: l’acquérir. По-еврейски מָהֹר יִמְהָרֶנָּה — внести брачный выкуп, чтобы она стала его женой, не приданое."],"exodus-22-16":["Если её отец решительно откажется отдать её ему, тот отвесит серебро по брачному выкупу за девственниц.","Als haar vader haar beslist weigert aan hem te geven, dan weegt hij zilver af naar de bruidsprijs voor maagden.","JPS: pay money according to the dowry; фр.: la somme fixée pour la dot. По-еврейски כֶּסֶף יִשְׁקֹל כְּמֹהַר — отвесит серебро по брачному выкупу."],"exodus-22-17":["Колдунью не оставляй в живых.","Een tovenares mag je niet in leven laten.",""],"exodus-22-18":["Всякий, кто ляжет с животным, непременно будет предан смерти.","Wie bij een dier ligt, moet zeker ter dood worden gebracht.",""],"exodus-22-19":["Кто приносит жертву богам, будет предан заклятию, кроме как одному только Господу.","Wie aan goden offert, wordt onder de ban gesteld, behalve aan de Eeuwige alleen.","JPS: utterly destroyed; фр.: voué à la mort. По-еврейски יׇחֳרָם — предан заклятию, не «смерть» предыдущего стиха."],"exodus-22-20":["Пришельца не притесняй и не угнетай: вы сами были пришельцами в земле Мицраим.","Een vreemdeling mag je geen onrecht doen en je mag hem niet verdrukken, want jullie zijn zelf vreemdelingen geweest in het land Mitsrajim.",""],"exodus-22-21":["Ни одну вдову и ни одну сироту не угнетайте.","Jullie mogen geen enkele weduwe en geen enkele wees verdrukken.",""],"exodus-22-22":["Если ты всё же будешь его угнетать, — ведь если он воззовёт ко Мне, Я непременно услышу его крик, —","Als je hem toch verdrukt — want als hij tot Mij schreeuwt, zal Ik zijn schreeuw zeker horen —","JPS: if thou afflict them. По-еврейски אֹתוֹ — его, единственное число."],"exodus-22-23":["вспыхнет Мой гнев, и Я убью вас мечом, и ваши жёны станут вдовами, а ваши дети — сиротами.","dan zal Mijn toorn ontbranden, en Ik zal jullie met het zwaard doden. Jullie vrouwen zullen weduwen worden en jullie kinderen wezen.",""],"exodus-22-24":["Если ты дашь взаймы серебро Моему народу, бедному, который с тобой, не будь ему кредитором. Не налагайте на него проценты.","Als je zilver leent aan Mijn volk, aan de arme bij je, wees dan niet voor hem als een schuldeiser. Jullie mogen hem geen rente opleggen.",""],"exodus-22-25":["Если ты всё же возьмёшь в залог плащ своего ближнего, до захода солнца верни его ему.","Als je de mantel van je naaste toch als pand neemt, geef die hem terug voordat de zon ondergaat.",""],"exodus-22-26":["Ведь это единственный его покров, это его плащ для кожи. В чём ему лечь? Если он воззовёт ко Мне, Я услышу, потому что Я милостив.","Want dat is zijn enige bedekking, dat is zijn mantel voor zijn huid. Waarin moet hij liggen? Als hij tot Mij roept, zal Ik horen, want Ik ben genadig.","JPS: garment for his skin, wherein shall he sleep; фр.: vêtement de son corps, comment abritera-t-il son sommeil. По-еврейски לְעֹרוֹ — на кожу, בַּמֶּה יִשְׁכָּב — в чём лечь."],"exodus-22-27":["Бога не проклинай, и правителя в твоём народе не кляни.","God mag je niet vervloeken, en een leider van je volk mag je niet verwensen.","JPS: God; фр.: l’autorité suprême. По-еврейски אֱלֹהִים — Бог."],"exodus-22-28":["Не задерживай свою полноту и свой сок. Первенца твоих сыновей отдай Мне.","Stel je volheid en je sap niet uit. De eerstgeborene van je zonen zul je aan Mij geven.","מְלֵאָתְךָ וְדִמְעֲךָ тёмное: полнота и капля. JPS добавляет harvest и presses. Фр.: abondance et liqueur."],"exodus-22-29":["Так же поступай со своим быком и со своим мелким скотом. Семь дней он пусть будет при матери, а на восьмой день отдай его Мне.","Zo zul je doen met je rund en met je kleinvee. Zeven dagen blijft het bij zijn moeder, op de achtste dag zul je het aan Mij geven.","Фр. добавляет le premier-né. В этом стихе слова нет: כֵּן־תַּעֲשֶׂה — так же поступай."],"exodus-22-30":["Будьте для Меня святыми людьми. Мясо, растерзанное в поле, не ешьте. Бросайте его собаке.","Wees voor Mij heilige mensen. Vlees dat op het veld verscheurd is, mogen jullie niet eten. Werp het aan de hond.","JPS: to the dogs; фр.: aux chiens. По-еврейски לַכֶּלֶב — собаке, единственное число."],"exodus-23-1":["Не разноси пустой слух. Не клади свою руку со злодеем, чтобы быть свидетелем насилия.","Neem geen leeg gerucht over. Leg je hand niet bij een boosdoener om een getuige van geweld te zijn.",""],"exodus-23-2":["Не иди за большинством, чтобы сделать зло. Не свидетельствуй в тяжбе, склоняясь за большинством, чтобы искривить.","Ga niet achter de meerderheid aan om kwaad te doen. Getuig niet in een rechtszaak door met de meerderheid mee te buigen, om het te verdraaien.","לְהַטֹּת без дополнения. JPS добавляет justice, фр. — le droit."],"exodus-23-3":["Бедному не потворствуй в его тяжбе.","Een arme mag je in zijn rechtszaak niet voortrekken.",""],"exodus-23-4":["Если ты встретишь быка своего врага или его осла, когда тот блуждает, непременно верни его ему.","Als je het rund of de ezel van je vijand tegenkomt terwijl die is afgedwaald, breng hem dan zeker bij hem terug.",""],"exodus-23-5":["Если ты увидишь осла того, кто тебя ненавидит, лежащего под своей ношей, не оставляй это ему: непременно развьючь вместе с ним.","Als je ziet dat de ezel van iemand die je haat onder zijn last ligt, laat het hem dan niet over: maak de last zeker samen met hem los.","שֹׁנַאֲךָ — тот, кто ненавидит; фр. и здесь ennemi, как для אוֹיִב. וְחָדַלְתָּ מֵעֲזֹב לוֹ עָזֹב תַּעֲזֹב עִמּוֹ сжато: JPS forbear to pass by, release with him; фр. не бросай, помоги разгрузить."],"exodus-23-6":["Не искривляй право твоего нищего в его тяжбе.","Verdraai het recht van je behoeftige niet in zijn rechtszaak.","Фр. добавляет prochain. По-еврейски אֶבְיֹנְךָ — твоего нищего."],"exodus-23-7":["От ложного дела держись далеко. Невинного и праведного не убивай, потому что Я не признаю правым злодея.","Blijf ver van een valse zaak. Dood een onschuldige en een rechtvaardige niet, want Ik zal een slechte niet rechtvaardig verklaren.","JPS: a false matter, I will not justify the wicked; фр.: parole de mensonge, je n’absoudrais point le prévaricateur. По-еврейски דְּבַר־שֶׁקֶר — ложное дело, לֹא־אַצְדִּיק רָשָׁע — не признаю правым злодея."],"exodus-23-8":["Взятки не бери: взятка ослепляет зрячих и извращает слова праведных.","Neem geen steekpenning aan, want een steekpenning verblindt de scherpzienden en verdraait de woorden van rechtvaardigen.","JPS: gift; фр.: présents corrupteurs. По-еврейски שֹׁחַד — взятка."],"exodus-23-9":["Пришельца не угнетай. Вы знаете душу пришельца, потому что вы сами были пришельцами в земле Мицраим.","Een vreemdeling mag je niet verdrukken. Jullie kennen de ziel van de vreemdeling, want jullie zijn zelf vreemdelingen geweest in het land Mitsrajim.","JPS: the heart; фр.: le cœur. По-еврейски נֶפֶשׁ — душа."],"exodus-23-10":["Шесть лет засевай свою землю и собирай её урожай.","Zes jaar zul je je land inzaaien en de opbrengst ervan binnenhalen.",""],"exodus-23-11":["А в седьмой год оставь её и забрось. Пусть едят нищие твоего народа, а что останется, пусть ест зверь поля. Так же поступай со своим виноградником и со своей оливой.","Maar in het zevende jaar zul je het laten liggen en het prijsgeven. De behoeftigen van je volk mogen eten, en wat zij overlaten, eet het dier van het veld. Zo zul je doen met je wijngaard en met je olijf.",""],"exodus-23-12":["Шесть дней делай свои дела, а в седьмой день остановись, чтобы отдохнули твой бык и твой осёл и чтобы сын твоей рабыни и пришелец перевели дух.","Zes dagen zul je je werk doen, maar op de zevende dag zul je ophouden, zodat je rund en je ezel rusten en de zoon van je slavin en de vreemdeling op adem komen.",""],"exodus-23-13":["Берегите всё, что Я сказал вам. Имени других богов не поминайте: пусть его не слышат из твоих уст.","Neem alles wat Ik jullie heb gezegd in acht. De naam van andere goden mogen jullie niet noemen. Uit je mond mag die niet gehoord worden.",""],"exodus-23-14":["Три раза в году справляй для Меня праздник.","Drie keer per jaar zul je voor Mij een feest vieren.",""],"exodus-23-15":["Соблюдай праздник пресных хлебов. Семь дней ешь пресные хлебы, как Я повелел тебе, в срок месяца Авив, потому что в нём ты вышел из Мицраима. И пусть не являются перед Моим лицом ни с чем.","Het feest van de ongezuurde broden zul je houden. Zeven dagen zul je ongezuurde broden eten, zoals Ik je geboden heb, op de vastgestelde tijd van de maand Aviv, want daarin ben je uit Mitsrajim getrokken. En zij mogen niet leeg voor Mijn aangezicht verschijnen.","Фр.: mois de la germination и les mains vides. JPS: the month Abib, empty. По-еврейски חֹדֶשׁ הָאָבִיב — месяц Авив, רֵיקָם — ни с чем."],"exodus-23-16":["И праздник жатвы, первые плоды твоих трудов, которые ты сеешь в поле, и праздник сбора при исходе года, когда ты собираешь свои труды с поля.","En het feest van de oogst, de eerstelingen van je werk dat je op het veld zaait, en het feest van het binnenhalen, bij het uitgaan van het jaar, wanneer je je werk van het veld haalt.","Фр.: fête de l’Automne, au déclin de l’année. По-еврейски חַג הָאָסִף בְּצֵאת הַשָּׁנָה — праздник сбора при исходе года. חַג הַקָּצִיר — праздник жатвы."],"exodus-23-17":["Три раза в году все, кто у тебя мужского пола, явятся перед лицом Владыки, Господа.","Drie keer per jaar zal iedereen die bij je mannelijk is verschijnen voor het aangezicht van de Heer, de Eeuwige.",""],"exodus-23-18":["Не закалывай на квасном кровь Моей жертвы, и жир Моего праздника пусть не остаётся до утра.","Slacht het bloed van Mijn offer niet bij gezuurd brood, en het vet van Mijn feest mag niet tot de morgen blijven liggen.","Фр. добавляет sans être offerte и переводит חַגִּי как victimes. По-еврейски חֵלֶב־חַגִּי — жир Моего праздника, он не ночует до утра."],"exodus-23-19":["Первое из первых плодов твоей земли приноси в дом Господа, твоего Бога. Не вари козлёнка в молоке его матери.","Het eerste van de eerstelingen van je aarde zul je brengen naar het huis van de Eeuwige, je God. Een bokje mag je niet koken in de melk van zijn moeder.",""],"i-samuel-20-18":["Йегонатан сказал ему: «Завтра новолуние. Тебя хватятся, потому что твоё место окажется пустым.","Jehonatan zei tegen hem: «Morgen is de nieuwe maan. Men zal je missen, want je plaats zal leeg bevonden worden.",""],"i-samuel-20-19":["На третий день сойди далеко вниз, приди на то место, где ты скрывался в день дела, и останься у камня Эзель.","Op de derde dag zul je ver naar beneden gaan, naar de plaats komen waar je je verborg op de dag van de daad, en bij de steen Ezel blijven.","Тёмное: וְשִׁלַּשְׁתָּ תֵּרֵד מְאֹד. JPS: on the third day hide thyself well. Фр.: tu t’enfonceras encore plus avant. הָאֶבֶן הָאָזֶל — JPS: stone Ezel; фр.: pierre itinéraire."],"i-samuel-20-20":["А я пущу три стрелы в сторону, чтобы послать их себе в цель.","En ik zal drie pijlen opzij schieten, om ze voor mij naar een doel te sturen.","JPS добавляет as though, фр. — comme pour. По-еврейски לְשַׁלַּח־לִי לְמַטָּרָה — чтобы послать себе в цель."],"i-samuel-20-21":["Вот я пошлю мальчика: „Иди, найди стрелы“. Если я скажу мальчику: „Вот стрелы от тебя и ближе, возьми их“, — тогда приходи, потому что тебе мир и нет ничего. Жив Господь.","Zie, ik stuur de jongen: „Ga, zoek de pijlen.“ Als ik tegen de jongen zeg: „Kijk, de pijlen zijn aan deze kant van je, pak ze,“ kom dan, want het is vrede voor je en er is niets. Zo waar de Eeuwige leeft.","JPS: no hurt; фр.: nul danger. По-еврейски וְאֵין דָּבָר — и нет ничего."],"i-samuel-20-22":["А если я так скажу юноше: „Вот стрелы от тебя и дальше“, — уходи, потому что Господь отослал тебя.","Maar als ik zo tegen de jongeman zeg: „Kijk, de pijlen zijn voorbij je,“ ga dan, want de Eeuwige heeft je weggestuurd.","Фр.: le Seigneur veut ton départ. По-еврейски שִׁלַּחֲךָ יְהֹוָה — Господь отослал тебя. Здесь עֶלֶם — юноша, в предыдущем стихе נַעַר — мальчик."],"i-samuel-20-23":["А слово, которое мы сказали, я и ты: вот, Господь между мной и тобой навсегда».","En de zaak waarover wij gesproken hebben, ik en jij: zie, de Eeuwige is tussen mij en jou voor altijd.»",""],"i-samuel-20-24":["Давид скрылся в поле. Наступило новолуние, и царь сел есть хлеб.","Dawid verborg zich in het veld. Het werd nieuwe maan, en de koning ging zitten om brood te eten.","JPS: to the meal; фр.: se mit à table. По-еврейски אֶל־הַלֶּחֶם — к хлебу."],"i-samuel-20-25":["Царь сел на своё место, как и в другие разы, на место у стены. Йегонатан встал, Авнер сел сбоку от Шауля, а место Давида пустовало.","De koning zat op zijn plaats, zoals telkens weer, op de plaats bij de muur. Jehonatan stond op, Avner zat aan de zijde van Sjaoel, en de plaats van Dawid bleef leeg.",""],"i-samuel-20-26":["Шауль ничего не сказал в тот день, потому что сказал: «Это случайность. Он нечист, ведь он нечист».","Sjaoel zei die dag niets, want hij zei: «Het is een toeval. Hij is niet rein, want hij is niet rein.»",""],"i-samuel-20-27":["На следующий день после новолуния, на второй день, место Давида пустовало. Шауль сказал Йегонатану, своему сыну: «Почему сын Ишая не пришёл к хлебу ни вчера, ни сегодня?»","De dag na de nieuwe maan, de tweede dag, was de plaats van Dawid leeg. Sjaoel zei tegen zijn zoon Jehonatan: «Waarom is de zoon van Jisjai niet naar het brood gekomen, niet gisteren en niet vandaag?»",""],"i-samuel-20-28":["Йегонатан ответил Шаулю: «Давид настоятельно просил у меня пойти в Бейт-Лехем.","Jehonatan antwoordde Sjaoel: «Dawid heeft mij dringend gevraagd om naar Bet-Lechem te gaan.",""],"i-samuel-20-29":["Он сказал: „Отпусти меня, пожалуйста: у нас в городе семейная жертва, и брат мой велел мне. Теперь, если я нашёл милость в твоих глазах, дай мне, пожалуйста, ускользнуть и увидеть моих братьев“. Поэтому он не пришёл к столу царя».","Hij zei: „Laat mij alsjeblieft gaan, want wij hebben een familieoffer in de stad, en mijn broer heeft het mij bevolen. Als ik nu genade heb gevonden in jouw ogen, laat mij alsjeblieft wegglippen en mijn broers zien.“ Daarom is hij niet aan de tafel van de koning gekomen.»","JPS: a sacrifice, he hath commanded me; фр.: un banquet, me l’a demandé. По-еврейски זֶבַח — жертва, צִוָּה — велел."],"i-samuel-20-30":["Шауль вспыхнул гневом на Йегонатана и сказал ему: «Сын строптивой бунтарки! Разве я не знаю, что ты выбираешь сына Ишая себе на позор и на позор наготы твоей матери?","De toorn van Sjaoel ontbrandde tegen Jehonatan, en hij zei tegen hem: «Zoon van een weerbarstige, opstandige vrouw! Weet ik niet dat jij de zoon van Jisjai kiest, tot je eigen schande en tot schande van de naaktheid van je moeder?","בֶּן־נַעֲוַת הַמַּרְדּוּת тёмное. JPS: son of perverse rebellion. Фр.: fils perfide et rebelle. Дальше עֶרְוַת אִמֶּךָ — нагота матери; фр.: flancs de ta mère."],"i-samuel-20-31":["Ведь все дни, пока сын Ишая жив на земле, не устоять ни тебе, ни твоему царству. Теперь пошли и приведи его ко мне, потому что он — сын смерти».","Want al de dagen dat de zoon van Jisjai in leven is op de aarde, zul jij niet staande blijven, jij en je koningschap. Stuur nu en haal hem bij mij, want hij is een zoon van de dood.»",""],"i-samuel-20-32":["Йегонатан ответил Шаулю, своему отцу, и сказал ему: «За что его предавать смерти? Что он сделал?»","Jehonatan antwoordde zijn vader Sjaoel en zei tegen hem: «Waarom zou hij ter dood gebracht worden? Wat heeft hij gedaan?»",""],"i-samuel-20-33":["Шауль метнул в него копьё, чтобы поразить его. Йегонатан понял, что его отец твёрдо решил убить Давида.","Sjaoel slingerde de speer naar hem om hem te treffen. Jehonatan begreep dat het bij zijn vader vaststond om Dawid te doden.",""],"i-samuel-20-34":["Йегонатан встал из-за стола в пылу гнева и не ел хлеба во второй день новолуния, потому что скорбел о Давиде и потому что отец опозорил его.","Jehonatan stond in brandende toorn op van de tafel en at geen brood op de tweede dag van de nieuwe maan, want hij was bedroefd om Dawid, omdat zijn vader hem te schande had gemaakt.","JPS: the second day of the month. По-еврейски בְּיוֹם־הַחֹדֶשׁ הַשֵּׁנִי — во второй день новолуния."],"i-samuel-20-35":["Утром Йегонатан вышел в поле к условленному с Давидом времени, и с ним был маленький мальчик.","In de morgen ging Jehonatan naar het veld, naar de tijd die met Dawid was afgesproken, en een kleine jongen was bij hem.","Фр.: à l’endroit convenu. По-еврейски לְמוֹעֵד דָּוִד — к условленному времени с Давидом. JPS: at the time appointed."],"i-samuel-20-36":["Он сказал своему мальчику: «Беги, найди, пожалуйста, стрелы, которые я пускаю». Мальчик побежал, а он пустил стрелу так, чтобы она пролетела дальше него.","Hij zei tegen zijn jongen: «Ren, zoek alsjeblieft de pijlen die ik schiet.» De jongen rende, en hij schoot de pijl zodat die voorbij hem vloog.","Фр.: les flèches. По-еврейски в конце הַחֵצִי — одну стрелу; в начале הַחִצִּים — стрелы."],"i-samuel-20-37":["Мальчик добежал до места стрелы, которую пустил Йегонатан. Йегонатан крикнул вслед мальчику: «Стрела ведь дальше тебя?»","De jongen kwam tot de plaats van de pijl die Jehonatan had geschoten. Jehonatan riep de jongen na en zei: «Ligt de pijl niet voorbij je?»","Фр.: les flèches, оба раза. По-еврейски הַחֵצִי — одна стрела."],"i-samuel-20-38":["Йегонатан крикнул вслед мальчику: «Скорее, спеши, не стой!» Мальчик Йегонатана собрал стрелы и пришёл к своему господину.","Jehonatan riep de jongen na: «Snel, haast je, blijf niet staan!» De jongen van Jehonatan raapte de pijlen op en kwam bij zijn meester.",""],"i-samuel-20-39":["Мальчик ничего не знал. Только Йегонатан и Давид знали, в чём дело.","De jongen wist van niets. Alleen Jehonatan en Dawid wisten wat de zaak was.","Фр.: étaient d’intelligence. По-еврейски יָדְעוּ אֶת־הַדָּבָר — знали это дело."],"i-samuel-20-40":["Йегонатан отдал своё оружие своему мальчику и сказал ему: «Иди, отнеси в город».","Jehonatan gaf zijn wapens aan zijn jongen en zei tegen hem: «Ga, breng ze naar de stad.»",""],"i-samuel-20-41":["Мальчик ушёл, и Давид встал с южной стороны, пал лицом на землю и трижды поклонился. Они поцеловали друг друга и плакали друг с другом, пока Давид не заплакал ещё сильнее.","De jongen was weg, en Dawid stond op van naast het zuiden, viel met zijn gezicht naar de aarde en boog zich driemaal. Zij kusten elkaar en huilden met elkaar, totdat Dawid het nog heviger deed.","עַד־דָּוִד הִגְדִּיל сжато. JPS: until David exceeded. Фр.: David surtout versa d’abondantes larmes. Речь о плаче из предыдущих слов."],"i-samuel-20-42":["Йегонатан сказал Давиду: «Иди с миром, ведь мы оба поклялись именем Господа: „Господь будет между мной и тобой и между моим потомством и твоим потомством навсегда“».","Jehonatan zei tegen Dawid: «Ga in vrede, want wij beiden hebben gezworen bij de naam van de Eeuwige: „De Eeuwige zal zijn tussen mij en jou, en tussen mijn nageslacht en jouw nageslacht, voor altijd.“»","Фр.: Que Dieu soit entre toi et moi, entre ta postérité et la mienne. По-еврейски יְהֹוָה יִהְיֶה בֵּינִי וּבֵינֶךָ וּבֵין זַרְעִי וּבֵין זַרְעֲךָ — Господь будет между мной и тобой и между моим потомством и твоим."],"exodus-26-1":["Сделай Мишкан из десяти полотнищ тонкого кручёного льна, синей, пурпурной и алой пряжи. Керувим работой искусного ткача сделай на них.","Maak de misjkan van tien kleden van fijn getwijnd linnen, blauw, purper en scharlaken. Maak daarop keroeviem, het werk van een kunstwever.",""],"exodus-26-2":["Длина одного полотнища — двадцать восемь локтей, ширина одного полотнища — четыре локтя. Одна мера для всех полотнищ.","De lengte van het ene kleed is achtentwintig el, de breedte van het ene kleed vier el. Eén maat voor alle kleden.",""],"exodus-26-3":["Пять полотнищ пусть будут соединены одно с другим, и пять полотнищ соединены одно с другим.","Vijf kleden moeten aan elkaar verbonden zijn, het ene aan het andere, en vijf kleden verbonden, het ene aan het andere.",""],"exodus-26-4":["Сделай петли из синей пряжи на краю одного полотнища, с конца в соединении, и так же сделай на краю крайнего полотнища во втором соединении.","Maak lussen van blauw aan de rand van het ene kleed, aan het uiteinde van de verbinding, en doe zo ook aan de rand van het buitenste kleed in de tweede verbinding.","JPS: loops; фр.: nœuds. По-еврейски לֻלָאֹת — петли."],"exodus-26-5":["Пятьдесят петель сделай на одном полотнище и пятьдесят петель сделай на краю полотнища во втором соединении. Петли пусть приходятся одна против другой.","Vijftig lussen moet je maken aan het ene kleed en vijftig lussen aan de rand van het kleed in de tweede verbinding. De lussen moeten tegenover elkaar staan, de ene tegen de andere.","JPS: loops; фр.: nœuds. По-еврейски לֻלָאֹת — петли."],"exodus-26-6":["Сделай пятьдесят золотых крючков и соедини полотнища одно с другим крючками, и Мишкан будет одним.","Maak vijftig gouden haken en verbind de kleden met elkaar met de haken, en de misjkan zal één zijn.","JPS: the tabernacle may be one whole; фр.: l’enceinte sera continue. По-еврейски וְהָיָה הַמִּשְׁכָּן אֶחָד — Мишкан будет одним."],"exodus-26-7":["Сделай полотнища из козьей шерсти для шатра над Мишканом. Сделай их одиннадцать.","Maak kleden van geitenhaar voor een tent over de misjkan. Maak er elf.",""],"exodus-26-8":["Длина одного полотнища — тридцать локтей, ширина одного полотнища — четыре локтя. Одна мера для одиннадцати полотнищ.","De lengte van het ene kleed is dertig el, de breedte van het ene kleed vier el. Eén maat voor de elf kleden.",""],"exodus-26-9":["Соедини пять полотнищ отдельно и шесть полотнищ отдельно и сложи шестое полотнище вдвое к передней стороне шатра.","Verbind vijf kleden apart en zes kleden apart, en vouw het zesde kleed dubbel naar de voorkant van de tent.",""],"exodus-26-10":["Сделай пятьдесят петель на краю одного крайнего полотнища в соединении и пятьдесят петель на краю полотнища второго соединения.","Maak vijftig lussen aan de rand van het ene buitenste kleed in de verbinding en vijftig lussen aan de rand van het kleed van de tweede verbinding.","JPS: loops; фр.: nœuds. По-еврейски לֻלָאֹת — петли."],"exodus-26-11":["Сделай пятьдесят бронзовых крючков, вдень крючки в петли, соедини шатёр, и он будет одним.","Maak vijftig bronzen haken, steek de haken in de lussen, verbind de tent, en hij zal één zijn.","JPS: brass; фр.: cuivre. По-еврейски נְחֹשֶׁת — бронза."],"exodus-26-12":["Лишний свес полотнищ шатра, половина лишнего полотнища, пусть свисает на заднюю сторону Мишкана.","De overhang die overblijft bij de kleden van de tent, de helft van het kleed die over is, moet afhangen over de achterkant van de misjkan.",""],"exodus-26-13":["Локоть с одной стороны и локоть с другой, излишек в длине полотнищ шатра, пусть свисает по бокам Мишкана, с одной стороны и с другой, чтобы покрыть его.","De el aan deze kant en de el aan de andere kant, wat overblijft in de lengte van de kleden van de tent, moet afhangen langs de zijkanten van de misjkan, aan deze kant en aan de andere, om hem te bedekken.",""],"exodus-26-14":["Сделай для шатра покрытие из шкур баранов, выкрашенных в красный, и сверху покрытие из шкур тахаш.","Maak voor de tent een bedekking van rood geverfde ramshuiden en daarboven een bedekking van tachasjhuiden.","JPS: sealskins; фр.: peaux de tahach. По-еврейски תְּחָשִׁים — неназванное животное."],"exodus-26-15":["Сделай брусья для Мишкана из дерева акации, стоячие.","Maak de planken voor de misjkan van acaciahout, rechtop staand.","JPS: boards of acacia-wood; фр.: solives de chittîm. По-еврейски קְרָשִׁים עֲצֵי שִׁטִּים — брусья из акации."],"exodus-26-16":["Длина бруса — десять локтей, ширина одного бруса — локоть и половина локтя.","De lengte van een plank is tien el, de breedte van de ene plank een el en een halve el.",""],"exodus-26-17":["У одного бруса два шипа, скреплённые один с другим. Так сделай у всех брусьев Мишкана.","Aan de ene plank twee tappen, in elkaar gezet, de ene tegen de andere. Zo moet je het maken bij alle planken van de misjkan.","JPS: joined one to another; фр.: parallèles. По-еврейски מְשֻׁלָּבֹת אִשָּׁה אֶל־אֲחֹתָהּ — скреплённые одна с другой."],"exodus-26-18":["Сделай брусья для Мишкана: двадцать брусьев на южную сторону, к югу.","Maak de planken voor de misjkan: twintig planken aan de zuidzijde, naar het zuiden.",""],"exodus-26-19":["Сделай сорок серебряных оснований под двадцать брусьев: два основания под один брус для двух его шипов и два основания под другой брус для двух его шипов.","Maak veertig zilveren voetstukken onder de twintig planken: twee voetstukken onder de ene plank voor zijn twee tappen, en twee voetstukken onder de andere plank voor zijn twee tappen.",""],"exodus-26-20":["Для второй стороны Мишкана, на северную сторону, — двадцать брусьев.","Voor de tweede zijde van de misjkan, aan de noordkant, twintig planken.",""],"exodus-26-21":["Их сорок оснований — серебряные: два основания под один брус и два основания под другой брус.","Hun veertig voetstukken zijn van zilver: twee voetstukken onder de ene plank en twee voetstukken onder de andere plank.",""],"exodus-26-22":["Для задней стороны Мишкана, к западу, сделай шесть брусьев.","Voor de achterkant van de misjkan, naar het westen, moet je zes planken maken.",""],"exodus-26-23":["Два бруса сделай для углов Мишкана на задней стороне.","Twee planken moet je maken voor de hoeken van de misjkan aan de achterkant.",""],"exodus-26-24":["Снизу они будут парными, а вместе наверху будут цельными, до одного кольца. Так будет у них обоих: они будут на двух углах.","Van onderen zullen zij gepaard zijn, en samen zullen zij tot aan de top één geheel zijn, tot aan de ene ring. Zo zal het zijn voor hen beide; zij zullen voor de twee hoeken zijn.","Стих тёмен. JPS: double beneath, complete unto the top; фр.: accouplées en bas et au sommet. По-еврейски תֹאֲמִם — парные, תַמִּים — цельные."],"exodus-26-25":["Будет восемь брусьев, и их основания серебряные: шестнадцать оснований, два основания под один брус и два основания под другой брус.","Er zullen acht planken zijn, en hun voetstukken van zilver: zestien voetstukken, twee voetstukken onder de ene plank en twee voetstukken onder de andere plank.",""],"exodus-26-26":["Сделай засовы из дерева акации: пять для брусьев одной стороны Мишкана.","Maak grendels van acaciahout: vijf voor de planken van de ene zijde van de misjkan.",""],"exodus-26-27":["Пять засовов для брусьев второй стороны Мишкана и пять засовов для брусьев задней стороны Мишкана, к западу.","Vijf grendels voor de planken van de tweede zijde van de misjkan, en vijf grendels voor de planken van de achterkant van de misjkan, naar het westen.",""],"exodus-26-28":["Средний засов внутри брусьев проходит насквозь от края до края.","De middelste grendel midden in de planken loopt door van het ene uiteinde tot het andere.",""],"exodus-26-29":["Брусья обложи золотом, их кольца сделай из золота, гнёздами для засовов, и засовы обложи золотом.","De planken overtrek je met goud, hun ringen maak je van goud, als houders voor de grendels, en de grendels overtrek je met goud.",""],"exodus-26-30":["Поставь Мишкан так, как ему положено, как тебе было показано на горе.","Richt de misjkan op volgens zijn voorschrift, zoals jou op de berg getoond is.","JPS: shown thee; фр.: enseignée. По-еврейски הׇרְאֵיתָ — тебе было показано."],"i-kings-8-1":["Тогда Шломо собрал к царю Шломо в Йерушалаим старейшин Исраэля и всех глав колен, предводителей родов сыновей Исраэля, чтобы поднять ковчег брит Господа из города Давида, то есть Циона.","Toen bracht Sjlomo de oudsten van Israël bijeen en alle hoofden van de stammen, de vorsten van de geslachten van de zonen van Israël, bij koning Sjlomo in Jeroesjalajim, om de ark van de briet van de Eeuwige omhoog te brengen uit de stad van Dawid, dat is Tsion.",""],"i-kings-8-2":["Все мужи Исраэля собрались к царю Шломо в месяце Этаним, на праздник; это седьмой месяц.","Alle mannen van Israël kwamen bij koning Sjlomo samen in de maand Etanim, op het feest; dat is de zevende maand.","JPS: all the men of Israel; фр.: tous les citoyens. По-еврейски כׇּל־אִישׁ יִשְׂרָאֵל — все мужи Исраэля."],"i-kings-8-3":["Пришли все старейшины Исраэля, и священники понесли ковчег.","Alle oudsten van Israël kwamen, en de priesters droegen de ark.",""],"i-kings-8-4":["Подняли ковчег Господа, шатёр встречи и все святые сосуды, что были в шатре. Подняли их священники и левиты.","Zij brachten de ark van de Eeuwige omhoog, de tent der samenkomst en alle heilige voorwerpen die in de tent waren. De priesters en de Levieten brachten ze omhoog.",""],"i-kings-8-5":["Царь Шломо и вся община Исраэля, собравшиеся к нему, были с ним перед ковчегом и приносили в жертву мелкий и крупный скот, который не счесть и не пересчитать, так его много.","Koning Sjlomo en heel de gemeenschap van Israël die bij hem samenkwam, waren met hem voor de ark en offerden kleinvee en grootvee, zo veel dat het niet geteld en niet opgesomd kon worden.","JPS: sheep and oxen; фр.: menu et gros bétail. По-еврейски צֹאן וּבָקָר — мелкий и крупный скот."],"i-kings-8-6":["Священники внесли ковчег брит Господа на его место, в девир дома, во Святое святых, под крылья керувим.","De priesters brachten de ark van de briet van de Eeuwige naar zijn plaats, in de debir van het huis, in het heilige der heiligen, onder de vleugels van de keroeviem.",""],"i-kings-8-7":["Керувим простирают крылья к месту ковчега и покрыли ковчег и его шесты сверху.","De keroeviem spreiden vleugels uit naar de plaats van de ark, en de keroeviem bedekten de ark en zijn draagstokken van boven.","JPS: over the place of the ark; фр.: dans la direction de l’arche. По-еврейски אֶל־מְקוֹם הָאָרוֹן — к месту ковчега."],"i-kings-8-8":["Шесты удлинились, и головки шестов были видны из святилища перед девиром, а снаружи их не было видно. Они там до сегодняшнего дня.","De draagstokken reikten ver, en de koppen van de draagstokken waren te zien vanuit het heiligdom, vóór de debir, maar buiten waren zij niet te zien. Zij zijn daar tot op deze dag.","JPS: the staves were so long, before the Sanctuary; фр.: on avait prolongé, à l’entrée du debir. По-еврейски וַיַּאֲרִכוּ — шесты удлинились, עַל־פְּנֵי הַדְּבִיר — перед девиром."],"i-kings-8-9":["В ковчеге не было ничего, кроме двух каменных плит, которые Моше положил там у Хорева, когда Господь заключил союз с сыновьями Исраэля при их выходе из земли Мицраим.","In de ark was niets dan de twee stenen platen die Mosje daar bij Chorev gelegd had, toen de Eeuwige een verbond sloot met de zonen van Israël bij hun uittocht uit het land Mitsrajim.",""],"i-kings-8-10":["Когда священники вышли из святилища, облако наполнило дом Господа.","Toen de priesters uit het heiligdom gingen, vulde de wolk het huis van de Eeuwige.",""],"i-kings-8-11":["Священники не могли стоять, чтобы служить, из-за облака, потому что слава Господа наполнила дом Господа.","De priesters konden niet blijven staan om dienst te doen vanwege de wolk, want de heerlijkheid van de Eeuwige vulde het huis van de Eeuwige.","JPS: the glory of the LORD; фр.: la majesté divine. По-еврейски כְבוֹד־יְהֹוָה — слава Господа."],"i-kings-8-12":["Тогда Шломо сказал: «Господь сказал, что будет обитать в густой мгле.","Toen zei Sjlomo: «De Eeuwige heeft gezegd dat Hij in de dichte duisternis zou wonen.","JPS: thick darkness; фр.: brume. По-еврейски בָּעֲרָפֶל — густая мгла."],"i-kings-8-13":["Я действительно построил Тебе дом обитания, место Твоего пребывания навеки».","Ik heb U waarlijk een huis gebouwd om te bewonen, een plaats waar U voor eeuwig woont».","Фр. добавляет Éternel. В еврейском Бог не назван, только לָךְ и שִׁבְתְּךָ."],"i-kings-8-14":["Царь повернул лицо и благословил всё собрание Исраэля, а всё собрание Исраэля стояло.","De koning keerde zijn gezicht en zegende heel de samenkomst van Israël, en heel de samenkomst van Israël stond.",""],"i-kings-8-15":["Он сказал: «Благословен Господь, Бог Исраэля, который Своими устами говорил Давиду, моему отцу, и Своей рукой исполнил, сказав:","Hij zei: «Gezegend is de Eeuwige, de God van Israël, die met Zijn mond tot mijn vader Dawid sprak en het met Zijn hand vervulde, met de woorden:",""],"i-kings-8-16":["„Со дня, когда Я вывел свой народ, Исраэль, из Мицраима, Я не избрал ни одного города из всех колен Исраэля, чтобы построить дом, где было бы моё имя. Я избрал Давида, чтобы он был над моим народом Исраэлем“.","„Vanaf de dag dat Ik mijn volk Israël uit Mitsrajim heb geleid, heb Ik geen enkele stad uit alle stammen van Israël gekozen om een huis te bouwen waar mijn naam zou zijn. Ik heb Dawid gekozen om over mijn volk Israël te staan“.","JPS: a house, but I chose; фр.: temple, Et maintenant j’ai adopté. По-еврейски בַּיִת — дом, וָאֶבְחַר — и Я избрал."],"i-kings-8-17":["На сердце у Давида, моего отца, было построить дом имени Господа, Бога Исраэля.","Het lag op het hart van mijn vader Dawid om een huis te bouwen voor de naam van de Eeuwige, de God van Israël.","JPS: a house for the name; фр.: un temple en l’honneur. По-еврейски בַּיִת לְשֵׁם — дом для имени."],"i-kings-8-18":["Господь сказал Давиду, моему отцу: „Раз у тебя на сердце было построить дом моему имени, ты хорошо сделал, что это было у тебя на сердце.","De Eeuwige zei tegen mijn vader Dawid: „Omdat het op je hart lag om een huis voor mijn naam te bouwen, heb je goed gedaan dat dit op je hart lag.","JPS: a house for My name; фр.: un temple en mon honneur. По-еврейски בַּיִת לִשְׁמִי — дом моему имени."],"i-kings-8-19":["Только ты не построишь дом. Сын твой, который выйдет из твоих чресл, он построит дом моему имени“.","Alleen jij zult het huis niet bouwen. Je zoon die uit je lendenen komt, hij zal het huis voor mijn naam bouwen“.","JPS: house, out of thy loins; фр.: temple, naître de toi. По-еврейски הַבַּיִת — дом, מֵחֲלָצֶיךָ — из твоих чресл."],"i-kings-8-20":["Господь утвердил Своё слово, которое Он сказал. Я встал на место Давида, моего отца, и сел на престол Исраэля, как сказал Господь, и построил дом имени Господа, Бога Исраэля.","De Eeuwige heeft Zijn woord bevestigd dat Hij gesproken had. Ik ben opgestaan in de plaats van mijn vader Dawid en zit op de troon van Israël, zoals de Eeuwige gezegd heeft, en ik heb het huis gebouwd voor de naam van de Eeuwige, de God van Israël.","JPS: the house for the name; фр.: ce temple sous l’invocation. По-еврейски הַבַּיִת לְשֵׁם — дом для имени."],"i-kings-8-21":["Я устроил там место для ковчега, где брит Господа, которую Он заключил с нашими отцами, когда вывел их из земли Мицраим».","Ik heb daar een plaats gemaakt voor de ark waarin de briet van de Eeuwige is, die Hij met onze vaderen sloot toen Hij hen uit het land Mitsrajim leidde».","JPS: wherein is the covenant; фр.: où repose l’alliance. По-еврейски אֲשֶׁר־שָׁם — где находится."],"exodus-28-31":["Сделай одеяние эфода целиком из синей ткани.","Maak het gewaad van de efod geheel van blauwe stof.",""],"exodus-28-32":["Отверстие для головы будет посредине. Вокруг отверстия будет тканый край, как отверстие кольчуги, чтобы оно не рвалось.","De opening voor het hoofd zit in het midden. Rond de opening komt een geweven rand, als de opening van een maliënkolder, zodat hij niet scheurt.","פי־ראשו בתוכו — отверстие для головы посредине; французский: верхнее отверстие «загнуто внутрь». תחרא — редкое слово; JPS и французский: кольчуга."],"exodus-28-33":["По его подолу сделай гранаты из синего, пурпура и алого, по всему подолу кругом, и золотые колокольчики между ними кругом.","Maak aan zijn zoom granaatappels van blauw, purper en scharlaken, rondom de zoom, en gouden belletjes ertussen, rondom.",""],"exodus-28-34":["Золотой колокольчик и гранат, золотой колокольчик и гранат — по подолу одеяния кругом.","Een gouden belletje en een granaatappel, een gouden belletje en een granaatappel, rondom de zoom van het gewaad.",""],"exodus-28-35":["Оно будет на Аароне, когда он служит. Звук этого одеяния будет слышен, когда он входит в святилище перед Господом и когда выходит, чтобы он не умер.","Het zal op Aharon zijn wanneer hij dienstdoet. Het geluid ervan zal te horen zijn wanneer hij het heilige binnengaat, voor de Eeuwige, en wanneer hij naar buiten gaat, zodat hij niet sterft.",""],"exodus-28-36":["Сделай пластину из чистого золота и вырежь на ней, как на печати: «Святыня Господу».","Maak een plaat van zuiver goud en graveer erop, als een zegel: «Heilig voor de Eeuwige».",""],"exodus-28-37":["Помести её на синий шнур, и она будет на тюрбане, с лицевой стороны тюрбана.","Zet hem op een blauw koord. Hij komt op de tulband, aan de voorkant van de tulband.",""],"exodus-28-38":["Она будет на лбу Аарона, и Аарон понесёт вину святынь, которые освящают сыны Исраэля, при всех их священных дарах. Она всегда будет на его лбу, ради благоволения к ним перед Господом.","Hij zal op het voorhoofd van Aharon zijn. Aharon draagt de schuld van de heilige dingen die de zonen van Israël heiligen, bij al hun heilige gaven. Hij zal altijd op zijn voorhoofd zijn, tot welgevallen voor hen bij de Eeuwige.","Французский говорит о «грехах посвящений». В иврите — вина святынь, которые освящают сыны Исраэля."],"exodus-28-39":["Сделай тунику клетчатым плетением из тонкого льна, сделай тюрбан из тонкого льна, а кушак сделай вышитым.","Maak de tuniek in schaakpatroon van fijn linnen, maak een tulband van fijn linnen, en maak de gordel als borduurwerk.",""],"exodus-28-40":["Сыновьям Аарона сделай туники, сделай им кушаки и сделай им шапки, для славы и для красоты.","Maak voor de zonen van Aharon tunieken, maak gordels voor hen en maak mutsen voor hen, tot eer en tot schoonheid.",""],"exodus-28-41":["Надень их на Аарона, твоего брата, и на его сыновей с ним. Помажь их, наполни их руку, освяти их, и они будут священниками Мне.","Kleed Aharon, je broer, ermee, en zijn zonen met hem. Zalf hen, vul hun hand, heilig hen, en zij zullen Mij als priesters dienen.","«Наполнить руку» — так в иврите, обряд поставления. JPS: consecrate, французский: installer."],"exodus-28-42":["Сделай им льняные штаны, чтобы прикрыть наготу тела. Они доходят от поясницы до бёдер.","Maak voor hen linnen broeken om de naaktheid van het lichaam te bedekken. Ze reiken van de lendenen tot de dijen.","Французский добавляет к льну «простой». В иврите просто лён."],"exodus-28-43":["Они будут на Аароне и на его сыновьях, когда те входят в шатёр встречи или подходят к жертвеннику для служения в святилище. Так они не понесут вины и не умрут. Это устав навеки для него и для его потомства после него.","Ze zullen op Aharon en op zijn zonen zijn wanneer zij de tent der samenkomst binnengaan of het altaar naderen om in het heilige te dienen, zodat zij geen schuld dragen en niet sterven. Het is een eeuwige inzetting voor hem en voor zijn nageslacht na hem.",""],"exodus-29-1":["Вот что ты сделаешь им, чтобы освятить их для священства Мне. Возьми одного быка из крупного скота и двух баранов без порока.","Dit is wat je met hen doet om hen te heiligen tot priesters voor Mij. Neem één stier van het rundvee en twee rammen zonder gebrek.",""],"exodus-29-2":["И пресный хлеб, и пресные булки, замешанные с маслом, и пресные тонкие коржи, помазанные маслом. Сделай их из пшеничной муки тонкого помола.","En ongezuurd brood, ongezuurde broden met olie dooreengemengd, en ongezuurde dunne koeken met olie bestreken. Van fijne tarwebloem maak je ze.",""],"exodus-29-3":["Положи их в одну корзину и поднеси их в корзине, вместе с быком и двумя баранами.","Leg ze in één mand en breng ze in de mand naar voren, samen met de stier en de twee rammen.",""],"exodus-29-4":["Аарона и его сыновей подведи ко входу шатра встречи и омой их водой.","Breng Aharon en zijn zonen naar de ingang van de tent der samenkomst en was hen met water.",""],"exodus-29-5":["Возьми одежды и надень на Аарона тунику, одеяние эфода, эфод и нагрудник, и опояшь его искусно тканым поясом эфода.","Neem de kleding en doe Aharon de tuniek aan, het gewaad van de efod, de efod en het borstschild, en gord hem met de kunstig geweven band van de efod.",""],"exodus-29-6":["Возложи тюрбан ему на голову и помести святую диадему на тюрбан.","Zet de tulband op zijn hoofd en leg de heilige diadeem op de tulband.",""],"exodus-29-7":["Возьми масло помазания, вылей его ему на голову и помажь его.","Neem de zalfolie, giet die op zijn hoofd en zalf hem.",""],"exodus-29-8":["Подведи его сыновей и одень их в туники.","Breng zijn zonen naar voren en trek hun tunieken aan.",""],"exodus-29-9":["Опояшь их кушаком, Аарона и его сыновей, и повяжи им шапки. Священство будет у них по вечному уставу. Наполни руку Аарона и руку его сыновей.","Gord hun een gordel om, Aharon en zijn zonen, en bind hun mutsen om. Het priesterschap zal voor hen zijn als eeuwige inzetting. Vul de hand van Aharon en de hand van zijn zonen.","«Наполнить руку» — так в иврите. JPS: consecrate, французский: investir."],"exodus-29-10":["Приведи быка перед шатром встречи, и Аарон и его сыновья возложат руки ему на голову.","Breng de stier voor de tent der samenkomst, en Aharon en zijn zonen leggen hun handen op de kop van de stier.",""],"exodus-29-11":["Зарежь быка перед Господом, у входа в шатёр встречи.","Slacht de stier voor de Eeuwige, bij de ingang van de tent der samenkomst.",""],"exodus-29-12":["Возьми крови быка и твоим пальцем положи её на рога жертвенника, а всю кровь вылей к основанию жертвенника.","Neem van het bloed van de stier en doe het met je vinger op de horens van het altaar, en giet al het bloed uit aan de voet van het altaar.","В иврите «всю кровь». JPS добавляет «оставшуюся», французский — «остальную». יסוד — основание, французский говорит «сосуд»."],"exodus-29-13":["Возьми весь жир, который покрывает внутренности, отросток на печени, обе почки и жир на них, и обрати это в дым на жертвеннике.","Neem al het vet dat de ingewanden bedekt, de kwab op de lever, de twee nieren en het vet daarop, en laat het op het altaar in rook opgaan.","היתרת — отросток на печени. JPS: доля над печенью, французский: перепонка."],"exodus-29-14":["А мясо быка, его шкуру и его помёт сожги огнём вне лагеря. Это жертва за грех.","Verbrand het vlees van de stier, zijn huid en zijn mest met vuur buiten het kamp. Het is een zondoffer.","חטאת — жертва за грех. Французский: expiatoire."],"exodus-29-15":["Возьми одного барана, и Аарон и его сыновья возложат руки ему на голову.","Neem de ene ram, en Aharon en zijn zonen leggen hun handen op de kop van de ram.",""],"exodus-29-16":["Зарежь барана, возьми его кровь и плесни ею на жертвенник кругом.","Slacht de ram, neem zijn bloed en plens het rondom tegen het altaar.","זרק — плеснуть. Французский: окропить."],"exodus-29-17":["Рассеки барана на части, омой его внутренности и голени и положи их на части и на голову.","Snijd de ram in zijn stukken, was zijn ingewanden en zijn schenkels en leg die op zijn stukken en op zijn kop.",""],"exodus-29-18":["Обрати всего барана в дым на жертвеннике. Это всесожжение Господу, приятный запах, огненная жертва Господу.","Laat de hele ram op het altaar in rook opgaan. Het is een brandoffer voor de Eeuwige, een aangename geur, een vuuroffer voor de Eeuwige.","אשה — жертва огнём. Французский сводит это к sacrifice."],"isaiah-61-1":["Дух Господа Бога на мне, потому что Господь помазал меня нести добрую весть смиренным. Он послал меня перевязать разбитых сердцем, возгласить пленным свободу и узникам — раскрытие.","De geest van Eeuwige, God, is op mij, omdat de Eeuwige mij gezalfd heeft om de nederigen een blijde boodschap te brengen. Hij heeft mij gezonden om gebroken harten te verbinden, voor gevangenen vrijheid uit te roepen en voor gebondenen opening.","פקח־קוח — неясное «раскрытие». JPS добавляет «глаз», французский говорит «освобождение». Французский также ставит «миссию» вместо помазания и «исцелить» вместо «перевязать»."],"isaiah-61-2":["Возгласить год благоволения Господа и день возмездия нашего Бога, утешить всех скорбящих.","Om een jaar van welgevallen van de Eeuwige uit te roepen en een dag van wraak van onze God, om allen die treuren te troosten.",""],"isaiah-61-3":["Назначить скорбящим Циона и дать им головной убор вместо пепла, масло радости вместо траура, покров хвалы вместо унылого духа. Их назовут теревинфами праведности, насаждением Господа, которым Он будет славиться.","Om aan de treurenden van Tsion toe te wijzen en hun te geven: een hoofdtooi in plaats van as, olie van vreugde in plaats van rouw, een mantel van lof in plaats van een doffe geest. Men zal hen terebinten van gerechtigheid noemen, een aanplant van de Eeuwige, waarop Hij zich beroemt.","אילי הצדק — теревинфы праведности, не «спасения», как во французском. מעטה תהלה — покров хвалы, не «триумфа»."],"isaiah-61-4":["Они отстроят древние развалины, поднимут прежние пустоши и обновят разорённые города, пустоши из поколения в поколение.","Zij bouwen de oude puinhopen weer op, richten de vroegere verwoestingen op en vernieuwen de verwoeste steden, de woestenijen van geslacht op geslacht.",""],"isaiah-61-5":["Чужие встанут и будут пасти ваших овец, а сыны чужеземца станут вашими пахарями и виноградарями.","Vreemden zullen staan en jullie schapen weiden, en zonen van de vreemdeling zullen jullie akkerbouwers en wijnbouwers zijn.",""],"isaiah-61-6":["А вас назовут священниками Господа, служителями нашего Бога назовут вас. Вы будете есть богатство народов и хвалиться их славой.","Jullie zullen priesters van de Eeuwige heten. Dienaren van onze God zal men jullie noemen. Jullie zullen de rijkdom van de volken eten en op hun glorie roemen.",""],"isaiah-61-7":["Вместо вашего стыда — двойная доля, а вместо бесчестья они будут ликовать о своём уделе. Поэтому в своей земле они наследуют вдвойне. Вечная радость будет у них.","In plaats van jullie schaamte het dubbele, en in plaats van schande zullen zij juichen over hun deel. Daarom zullen zij in hun land het dubbele bezitten. Vreugde voor altijd zal voor hen zijn.","Стих тёмный. JPS вводит реплику, что доля противников — позор. Французский: «вдвое счастливы». Здесь: вместо стыда двойная доля и ликование об уделе."],"isaiah-61-8":["Я, Господь, люблю правосудие и ненавижу грабёж при всесожжении. Я дам им награду по истине и заключу с ними вечный союз.","Ik, de Eeuwige, heb het recht lief en haat roof bij het brandoffer. Ik zal hun loon in waarheid geven en een eeuwig verbond met hen sluiten.","בעולה — «при всесожжении». JPS и французский читают «при несправедливости». פעלתם באמת — награда по истине, французский: «дело» и «по справедливости»."],"isaiah-61-9":["Среди народов узнают их потомство, а их потомков — среди племён. Все, кто видит их, признают их: это потомство, которое благословил Господь.","Onder de naties wordt hun nageslacht bekend, en hun nakomelingen onder de volken. Allen die hen zien, herkennen hen: zij zijn het nageslacht dat de Eeuwige heeft gezegend.","Во французском «Dieu», в иврите Господь."],"exodus-31-18":["Он дал Моше, когда закончил говорить с ним на горе Синай, две скрижали свидетельства, каменные скрижали, написанные пальцем Бога.","Hij gaf aan Mosje, toen Hij geëindigd had met hem te spreken op de berg Sinaj, de twee tafelen van de getuigenis, tafelen van steen, geschreven met de vinger van God.","Фр. называет подлежащим Бога, пишет Statut и burinées. Подлежащее וַיִּתֵּן не названо; הָעֵדֻת — свидетельство; כְּתֻבִים — написаны."],"exodus-32-1":["Народ увидел, что Моше медлит спуститься с горы. Народ собрался вокруг Аарона и сказал ему: «Встань, сделай нам богов, которые пойдут перед нами. Ведь этот Моше, человек, который вывел нас наверх из земли Мицраим, — мы не знаем, что с ним стало».","Het volk zag dat Mosje talmde om van de berg af te dalen. Het volk schaarde zich rond Aharon en zei tegen hem: «Sta op, maak ons goden die voor ons uit gaan. Want deze Mosje, de man die ons uit het land Mitsrajim omhoog heeft geleid — wij weten niet wat er met hem gebeurd is.»","JPS: a god who shall go; фр.: un dieu qui marche. По-еврейски אֱלֹהִים и глагол יֵלְכוּ — боги, которые пойдут."],"exodus-32-2":["Аарон сказал им: «Сорвите золотые серьги, которые в ушах ваших жён, ваших сыновей и ваших дочерей, и принесите их мне».","Aharon zei tegen hen: «Ruk de gouden ringen af die in de oren van jullie vrouwen, van jullie zonen en van jullie dochters zijn, en breng ze bij mij.»",""],"exodus-32-3":["Весь народ сорвал золотые серьги, которые были в их ушах, и принёс их Аарону.","Heel het volk rukte de gouden ringen af die in hun oren waren, en bracht ze naar Aharon.",""],"exodus-32-4":["Он взял это из их рук, придал ему форму резцом и сделал из этого литого тельца. Они сказали: «Вот твои боги, Исраэль, которые вывели тебя наверх из земли Мицраим».","Hij nam het uit hun hand, vormde het met een graveerstift en maakte er een gegoten kalf van. Zij zeiden: «Dit zijn je goden, Israël, die je uit het land Mitsrajim omhoog hebben geleid.»","JPS: graving tool, thy god; фр.: jeta en moule, tes dieux. По-еврейски בַּחֶרֶט — резцом; אֵלֶּה אֱלֹהֶיךָ … הֶעֱלוּךָ — множественное число."],"exodus-32-5":["Аарон увидел это, построил перед ним жертвенник и провозгласил: «Завтра праздник Господу».","Aharon zag het, bouwde een altaar ervoor en riep uit: «Morgen is er een feest voor de Eeuwige.»",""],"exodus-32-6":["На другой день они встали рано, вознесли всесожжения и принесли жертвы благополучия. Народ сел есть и пить, а потом встал веселиться.","De volgende dag stonden zij vroeg op, brachten brandoffers en brachten vredeoffers. Het volk ging zitten om te eten en te drinken, en stond op om zich te vermaken.","JPS: peace-offerings; фр.: victimes rémunératoires. По-еврейски שְׁלָמִים — жертвы благополучия."],"exodus-32-7":["Господь сказал Моше: «Ступай, спустись. Твой народ, который ты вывел наверх из земли Мицраим, развратился.","De Eeuwige zei tegen Mosje: «Ga, daal af. Je volk, dat jij uit het land Mitsrajim omhoog hebt geleid, heeft zich verdorven.",""],"exodus-32-8":["Они быстро свернули с пути, который Я им заповедал. Они сделали себе литого тельца, поклонились ему, принесли ему жертву и сказали: „Вот твои боги, Исраэль, которые вывели тебя наверх из земли Мицраим“».","Zij zijn snel afgeweken van de weg die Ik hun geboden heb. Zij hebben zich een gegoten kalf gemaakt, zich ervoor neergebogen, ervoor geofferd en gezegd: „Dit zijn je goden, Israël, die je uit het land Mitsrajim omhoog hebben geleid.“»","JPS: quickly, thy god; фр.: de bonne heure, tes dieux. По-еврейски מַהֵר — быстро; אֵלֶּה אֱלֹהֶיךָ … הֶעֱלוּךָ — множественное число."],"exodus-32-9":["Господь сказал Моше: «Я видел этот народ, и вот, это народ с жёсткой шеей.","De Eeuwige zei tegen Mosje: «Ik heb dit volk gezien, en zie, het is een volk met een stijve nek.",""],"exodus-32-10":["Теперь оставь Меня, и вспыхнет Мой гнев на них, и Я истреблю их, а тебя сделаю великим народом».","Laat Mij nu met rust, dan zal Mijn toorn tegen hen ontbranden, Ik zal hen vernietigen, en Ik zal je tot een groot volk maken.»","JPS: let Me alone; фр.: cesse de me solliciter. По-еврейски הַנִּיחָה לִּי — оставь Меня, без «ходатайства»."],"exodus-32-11":["Моше стал умолять Господа, своего Бога, и сказал: «Зачем, Господь, пылает Твой гнев на Твой народ, который Ты вывел из земли Мицраим великой силой и крепкой рукой?","Mosje smeekte de Eeuwige, zijn God, en zei: «Waarom, Eeuwige, ontbrandt Uw toorn tegen Uw volk, dat U met grote kracht en met een sterke hand uit het land Mitsrajim hebt uitgeleid?","Фр. обрывает стих на «en disant» и переносит речь в следующий. По-еврейски речь Моше начинается здесь."],"exodus-32-12":["Зачем Мицраиму говорить: „На беду Он вывел их, чтобы убить их в горах и истребить их с лица земли“? Вернись от пыла Твоего гнева и пожалей о бедствии для Твоего народа.","Waarom zou Mitsrajim zeggen: „Ten kwade heeft Hij hen uitgeleid, om hen in de bergen te doden en hen van de aardbodem weg te vagen“? Keer terug van de gloed van Uw toorn en heb berouw over het onheil voor Uw volk.","Фр. начинает стих словами из 32:11. Здесь по-еврейски нет имени: просьба вернуться от пыла гнева и пожалеть о бедствии."],"exodus-32-13":["Вспомни Авраама, Ицхака и Исраэля, Твоих слуг, которым Ты клялся Собой и сказал им: „Я умножу ваше потомство, как звёзды небесные, и всю эту землю, о которой Я сказал, что отдам её вашему потомству, и они будут владеть ею вечно“».","Gedenk Abraham, Jitschak en Israël, Uw dienaren, aan wie U bij Uzelf hebt gezworen en tegen wie U hebt gezegd: „Ik zal jullie nageslacht talrijk maken als de sterren van de hemel, en heel dit land waarvan Ik gezegd heb dat Ik het aan jullie nageslacht geef, en zij zullen het voor altijd bezitten.“»",""],"exodus-32-14":["И Господь пожалел о бедствии, которое Он сказал сделать Своему народу.","En de Eeuwige kreeg berouw over het onheil dat Hij gezegd had Zijn volk aan te doen.","JPS: repented of the evil; фр.: révoqua le malheur. По-еврейски וַיִּנָּחֶם עַל־הָרָעָה — пожалел о бедствии."],"exodus-32-15":["Моше повернулся и спустился с горы. В руке у него были две скрижали свидетельства, скрижали, написанные с обеих сторон: с одной и с другой они были написаны.","Mosje keerde zich om en daalde de berg af, met de twee tafelen van de getuigenis in zijn hand, tafelen die aan beide kanten beschreven waren: aan deze kant en aan die kant waren ze beschreven.","Фр.: tables du Statut. По-еврейски לֻחֹת הָעֵדֻת — скрижали свидетельства."],"exodus-32-16":["Скрижали были делом Бога, и письмена были письменами Бога, вырезанными на скрижалях.","De tafelen waren het werk van God, en het schrift was het schrift van God, gegrift op de tafelen.","Фр.: caractères divins. По-еврейски מִכְתַּב אֱלֹהִים — письмена Бога."],"exodus-32-17":["Йехошуа услышал голос народа в крике и сказал Моше: «В стане голос войны».","Jehosjoea hoorde het geluid van het volk in hun geschreeuw en zei tegen Mosje: «Een geluid van oorlog in het kamp.»","JPS: as they shouted; фр.: clameur jubilante. По-еврейски בְּרֵעֹה — в крике, без «ликования»."],"exodus-32-18":["Он сказал: «Это не голос клича силы и не голос клича слабости. Голос пения я слышу».","Hij zei: «Het is niet het geluid van een kreet van kracht en niet het geluid van een kreet van zwakte. Het geluid van zingen hoor ik.»","עַנּוֹת тёмное. JPS: them that sing; фр.: clameur affligeante. По огласовке — пение, не скорбный крик. עֲנוֹת גְּבוּרָה и חֲלוּשָׁה — клич силы и клич слабости."],"exodus-32-19":["Когда он приблизился к стану и увидел тельца и пляски, гнев Моше вспыхнул. Он бросил скрижали из своих рук и разбил их у подножия горы.","Toen hij dicht bij het kamp kwam en het kalf en de dansen zag, ontbrandde de toorn van Mosje. Hij wierp de tafelen uit zijn handen en brak ze aan de voet van de berg.",""],"exodus-32-20":["Он взял тельца, которого они сделали, сжёг его в огне, стёр, пока тот не стал пылью, рассыпал по воде и напоил этим сынов Исраэля.","Hij nam het kalf dat zij gemaakt hadden, verbrandde het in het vuur, vermaalde het tot het fijn was, strooide het op het water en liet de kinderen van Israël ervan drinken.",""],"exodus-32-21":["Моше сказал Аарону: «Что сделал тебе этот народ, что ты навёл на него великий грех?»","Mosje zei tegen Aharon: «Wat heeft dit volk je aangedaan, dat je een grote zonde over hen hebt gebracht?»","JPS: a great sin; фр.: une telle prévarication. По-еврейски חֲטָאָה גְדֹלָה — великий грех."],"exodus-32-22":["Аарон сказал: «Пусть не вспыхнет гнев моего господина. Ты сам знаешь этот народ: он во зле.","Aharon zei: «Laat de toorn van mijn heer niet ontbranden. Jij weet zelf hoe dit volk is: het zit in het kwaad.","אֲדֹנִי — «мой господин», обращение Аарона к Моше, не имя Владыка."],"exodus-32-23":["Они сказали мне: „Сделай нам богов, которые пойдут перед нами. Ведь этот Моше, человек, который вывел нас наверх из земли Мицраим, — мы не знаем, что с ним стало“.","Zij zeiden tegen mij: „Maak ons goden die voor ons uit gaan. Want deze Mosje, de man die ons uit het land Mitsrajim omhoog heeft geleid — wij weten niet wat er met hem gebeurd is.“","JPS: a god; фр.: un dieu. По-еврейски אֱלֹהִים и יֵלְכוּ — множественное число."],"exodus-32-24":["Я сказал им: „У кого есть золото — сорвите“. Они отдали его мне, я бросил его в огонь, и вышел этот телец».","Ik zei tegen hen: „Wie goud heeft, ruk het af.“ Zij gaven het mij, ik wierp het in het vuur, en dit kalf kwam eruit.»","JPS: let them break it off; фр.: Qui a de l’or? и прошедшее. По-еврейски לְמִי זָהָב הִתְפָּרָקוּ — повелительное: у кого золото, сорвите."],"exodus-32-25":["Моше увидел народ: он распущен, потому что Аарон распустил его, на позор перед их противниками.","Mosje zag het volk: het was losgebroken, want Aharon had hen losgelaten, tot een schande voor hun tegenstanders.","פָּרֻעַ и שִׁמְצָה тёмные. JPS: broken loose, derision among their enemies; фр.: désordre, ses ennemis. По-еврейски распущен; בְּקָמֵיהֶם — их восставшие."],"exodus-32-26":["Моше встал у ворот стана и сказал: «Кто за Господа — ко мне!» И собрались к нему все сыны Леви.","Mosje ging in de poort van het kamp staan en zei: «Wie voor de Eeuwige is, kom naar mij!» En alle zonen van Levi verzamelden zich bij hem.","Фр.: Qui aime l’Éternel, les Lévites. По-еврейски מִי לַיהֹוָה — кто за Господа; כׇּל־בְּנֵי לֵוִי — все сыны Леви."],"exodus-32-27":["Он сказал им: «Так сказал Господь, Бог Исраэля: „Пусть каждый возложит свой меч на бедро. Пройдите стан от ворот до ворот и обратно и убейте каждый своего брата, каждый своего товарища и каждый своего ближнего“».","Hij zei tegen hen: «Zo zegt de Eeuwige, de God van Israël: „Laat ieder zijn zwaard aan zijn heup doen. Trek door het kamp van poort tot poort en weer terug, en dood ieder zijn broer, ieder zijn gezel en ieder zijn naaste.“»","Фр. добавляет au besoin. В еврейском этого нет."],"exodus-32-28":["Сыны Леви сделали по слову Моше, и пало из народа в тот день около трёх тысяч человек.","De zonen van Levi deden naar het woord van Mosje, en van het volk vielen er die dag ongeveer drieduizend man.",""],"exodus-32-29":["Моше сказал: «Наполните сегодня ваши руки для Господа, потому что каждый выступил против своего сына и против своего брата, и чтобы дать вам сегодня благословение».","Mosje zei: «Vul vandaag jullie handen voor de Eeuwige, want ieder is tegen zijn zoon en tegen zijn broer opgetreden, en om jullie vandaag een zegen te geven.»","מִלְאוּ יֶדְכֶם — буквально «наполните руки», идиома посвящения. JPS: Consecrate yourselves; фр.: l’a vengé и «день заслужил благословение». По-еврейски каждый против сына и брата, וְלָתֵת — чтобы дать благословение."],"exodus-32-30":["На другой день Моше сказал народу: «Вы совершили великий грех. А теперь я поднимусь к Господу. Может быть, я покрою ваш грех».","De volgende dag zei Mosje tegen het volk: «Jullie hebben een grote zonde begaan. Nu zal ik opgaan naar de Eeuwige. Misschien zal ik jullie zonde bedekken.»","JPS: make atonement; фр.: obtiendrai grâce. По-еврейски אֲכַפְּרָה — покрою."],"exodus-32-31":["Моше вернулся к Господу и сказал: «О, этот народ совершил великий грех: они сделали себе богов из золота.","Mosje keerde terug naar de Eeuwige en zei: «Ach, dit volk heeft een grote zonde begaan: zij hebben zich goden van goud gemaakt.","JPS: a god of gold; фр.: un dieu d’or. По-еврейски אֱלֹהֵי זָהָב — боги из золота."],"exodus-32-32":["А теперь, если Ты простишь их грех... А если нет — сотри меня, прошу, из Твоей книги, которую Ты написал».","Nu dan, als U hun zonde vergeeft... En zo niet, wis mij dan, bid ik, uit Uw boek dat U geschreven hebt.»",""],"exodus-32-33":["Господь сказал Моше: «Кто согрешил против Меня, того Я сотру из Моей книги.","De Eeuwige zei tegen Mosje: «Wie tegen Mij gezondigd heeft, die zal Ik uit Mijn boek wissen.",""],"exodus-32-34":["А теперь иди, веди народ туда, куда Я говорил тебе. Вот, Мой посланник пойдёт перед тобой. А в день, когда Я взыщу, Я взыщу с них их грех».","Ga nu, leid het volk naar de plaats waarover Ik je gesproken heb. Zie, Mijn bode zal voor je uit gaan. Maar op de dag dat Ik verhaal, zal Ik hun zonde op hen verhalen.»","JPS: Mine angel; фр.: mon envoyé. По-еврейски מַלְאָכִי — Мой посланник."],"exodus-32-35":["И Господь поразил народ за то, что они сделали тельца, которого сделал Аарон.","En de Eeuwige trof het volk, omdat zij het kalf gemaakt hadden dat Aharon gemaakt had.","JPS: smote, the calf which Aaron made; фр.: châtia, comme auteur du veau. По-еврейски וַיִּגֹּף — поразил; народ сделал тельца, которого сделал Аарон."],"exodus-33-1":["Господь сказал Моше: «Иди, поднимись отсюда, ты и народ, который ты вывел наверх из земли Мицраим, в землю, о которой Я клялся Аврааму, Ицхаку и Яакову, сказав: „Твоему потомству Я отдам её“.","De Eeuwige zei tegen Mosje: «Ga, trek hiervandaan op, jij en het volk dat jij uit het land Mitsrajim omhoog hebt geleid, naar het land waarvan Ik aan Abraham, aan Jitschak en aan Jaäkov heb gezworen: „Aan je nageslacht zal Ik het geven.“","Фр.: votre postérité. По-еврейски לְזַרְעֲךָ — твоему потомству, единственное число."],"exodus-33-2":["Я пошлю перед тобой посланника и прогоню кнаани, эмори, хетта, перизея, хивви и евусея.","Ik zal een bode voor je uit zenden en de Kenaäniet, de Emori, de Chitti, de Perizzi, de Chivvi en de Jevusiet verdrijven.","JPS: an angel; фр.: un ange. По-еврейски מַלְאָךְ — посланник."],"exodus-33-3":["В землю, текущую молоком и мёдом. Я не поднимусь среди тебя, потому что ты народ с жёсткой шеей, иначе Я истреблю тебя в пути».","Naar een land dat overvloeit van melk en honing. Ik zal niet in je midden meetrekken, want jij bent een volk met een stijve nek; anders vernietig Ik je onderweg.»",""],"exodus-33-4":["Народ услышал это злое слово и стал скорбеть, и никто не надел на себя своего украшения.","Het volk hoorde dit kwade woord en treurde, en niemand deed zijn sieraad om.",""],"exodus-33-5":["Господь сказал Моше: «Скажи сынам Исраэля: „Вы — народ с жёсткой шеей. Один миг поднимусь среди тебя — и Я истреблю тебя. А теперь сними с себя своё украшение, и Я узнаю, что Мне сделать с тобой“».","De Eeuwige zei tegen Mosje: «Zeg tegen de kinderen van Israël: „Jullie zijn een volk met een stijve nek. Eén ogenblik trek Ik in je midden mee, en Ik vernietig je. Neem nu je sieraad van je af, en Ik zal weten wat Ik je doen zal.“»","JPS добавляет if; фр. ставит vous и si. В еврейском אַתֶּם — вы, а дальше בְּקִרְבְּךָ, וְכִלִּיתִיךָ, עֶדְיְךָ — единственное, без «если»."],"exodus-33-6":["Сыны Исраэля сняли с себя свои украшения от горы Хорев.","De kinderen van Israël legden hun sieraden af, vanaf de berg Chorev.","JPS добавляет onward; фр.: à dater. По-еврейски מֵהַר חוֹרֵב — от горы Хорев."],"exodus-33-7":["Моше брал шатёр и ставил его себе вне стана, далеко от стана, и называл его шатром встречи. Всякий, кто искал Господа, выходил к шатру встречи, который был вне стана.","Mosje nam de tent en zette die voor zich buiten het kamp op, ver van het kamp, en hij noemde die de tent der samenkomst. Ieder die de Eeuwige zocht, ging uit naar de tent der samenkomst die buiten het kamp stond.","Фр.: sa tente, consulter. По-еврейски הָאֹהֶל — шатёр; מְבַקֵּשׁ יְהֹוָה — ищущий Господа."],"exodus-33-8":["Когда Моше выходил к шатру, весь народ вставал, и каждый стоял у входа в свой шатёр и смотрел вслед Моше, пока тот не входил в шатёр.","Telkens als Mosje naar de tent uitging, stond heel het volk op, en ieder bleef bij de ingang van zijn tent staan en keek Mosje na, tot hij de tent binnenging.",""],"exodus-33-9":["Когда Моше входил в шатёр, облачный столп спускался, вставал у входа в шатёр, и Он говорил с Моше.","Telkens als Mosje de tent binnenging, daalde de wolkkolom neer, bleef bij de ingang van de tent staan, en Hij sprak met Mosje.","JPS добавляет the LORD; фр.: Dieu. Подлежащее וְדִבֶּר не названо."],"exodus-33-10":["Весь народ видел облачный столп, стоящий у входа в шатёр. Весь народ вставал, и каждый кланялся у входа в свой шатёр.","Heel het volk zag de wolkkolom bij de ingang van de tent staan. Heel het volk stond op, en ieder boog zich neer bij de ingang van zijn tent.",""],"exodus-33-11":["Господь говорил с Моше лицом к лицу, как человек говорит со своим другом. Потом он возвращался в стан, а его служитель Йехошуа, сын Нуна, юноша, не отходил из середины шатра.","De Eeuwige sprak met Mosje van aangezicht tot aangezicht, zoals een man met zijn vriend spreekt. Daarna keerde hij terug naar het kamp, maar zijn dienaar Jehosjoea, de zoon van Noen, een jongeman, week niet uit het midden van de tent.","Фр.: un autre, son jeune serviteur. По-еврейски אֶל־רֵעֵהוּ — со своим другом; נַעַר стоит отдельно: юноша."],"i-kings-18-20":["Ахав разослал ко всем сынам Исраэля и собрал пророков к горе Кармель.","Achav zond onder alle kinderen van Israël en bracht de profeten bijeen bij de berg Karmel.","Фр.: envoya des ordres. По-еврейски וַיִּשְׁלַח — послал."],"i-kings-18-21":["Элиягу подошёл ко всему народу и сказал: «До каких пор вы будете хромать на двух ветвях? Если Господь — Бог, идите за Ним, а если Бааль — идите за ним». Народ не ответил ему ни слова.","Eliahoe trad op heel het volk toe en zei: «Hoelang blijven jullie hinken op twee takken? Als de Eeuwige God is, ga Hem achterna; en als Baäl, ga hem achterna.» Het volk antwoordde hem geen woord.","הַסְּעִפִּים тёмное. JPS: two opinions; фр.: deux partis и vrai. По-еврейски פֹּסְחִים עַל־שְׁתֵּי הַסְּעִפִּים — хромаете на двух ветвях."],"i-kings-18-22":["Элиягу сказал народу: «Я один остался пророком Господа, а пророков Бааля — четыреста пятьдесят человек.","Eliahoe zei tegen het volk: «Ik alleen ben overgebleven als profeet van de Eeuwige, en de profeten van Baäl zijn vierhonderdvijftig man.",""],"i-kings-18-23":["Пусть дадут нам двух быков. Пусть выберут себе одного быка, рассекут его и положат на дрова, а огня пусть не подкладывают. Я приготовлю другого быка, положу на дрова и огня не подложу.","Laten zij ons twee stieren geven. Laten zij voor zich de ene stier kiezen, hem in stukken snijden en op het hout leggen, en er geen vuur bij doen. Ik zal de andere stier bereiden, op het hout leggen en er geen vuur bij doen.",""],"i-kings-18-24":["Вы призовёте имя вашего бога, а я призову имя Господа. И бог, который ответит огнём, — он Бог». Весь народ ответил и сказал: «Хорошо сказано».","Jullie zullen de naam van jullie god aanroepen, en ik zal de naam van de Eeuwige aanroepen. De god die met vuur antwoordt, die is God.» Heel het volk antwoordde en zei: «Het woord is goed.»","Фр. добавляет le vrai Dieu. По-еврейски הוּא הָאֱלֹהִים — он Бог."],"i-kings-18-25":["Элиягу сказал пророкам Бааля: «Выберите себе одного быка и приготовьте первыми, потому что вас много. Призовите имя вашего бога и огня не подкладывайте».","Eliahoe zei tegen de profeten van Baäl: «Kies voor jezelf de ene stier en bereid hem als eersten, want jullie zijn met velen. Roep de naam van jullie god aan en doe er geen vuur bij.»",""],"i-kings-18-26":["Они взяли быка, которого он им дал, приготовили его и призывали имя Бааля с утра до полудня: «Бааль, ответь нам!» Но не было ни голоса, ни ответа. И они хромали вокруг жертвенника, который он сделал.","Zij namen de stier die hij hun gegeven had, bereidden hem en riepen de naam van Baäl aan, van de morgen tot de middag: «Baäl, antwoord ons!» Maar er was geen stem en geen antwoord. En zij hinkten rond het altaar dat hij gemaakt had.","JPS: was given, danced in halting wise; фр.: laissé choisir, se démenaient. По-еврейски נָתַן — он дал; וַיְפַסְּחוּ — хромали, тот же глагол, что в 18:21. עָשָׂה — он сделал."],"i-kings-18-27":["В полдень Элиягу стал насмехаться над ними и сказал: «Кричите громким голосом, ведь он бог. То у него разговор, то отлучка, то путь. Может быть, он спит и проснётся».","Op het middaguur dreef Eliahoe de spot met hen en zei: «Roep met luide stem, want hij is een god. Hij heeft een gesprek, of een afwezigheid, of een reis. Misschien slaapt hij en wordt hij wakker.»","שִׂיחַ и שִׂיג тёмные. JPS: musing, gone aside, journey; фр.: affaire, expédition, voyage."],"i-kings-18-28":["Они кричали громким голосом и наносили себе порезы, по своему обычаю, мечами и копьями, пока не полилась по ним кровь.","Zij riepen met luide stem en sneden zich, naar hun gewoonte, met zwaarden en speren, tot het bloed over hen uitstroomde.",""],"i-kings-18-29":["Когда прошёл полдень, они пророчествовали до вознесения минхи, но не было ни голоса, ни ответа, ни внимания.","Toen de middag voorbij was, profeteerden zij tot het opgaan van de mincha, maar er was geen stem, geen antwoord en geen aandacht.","JPS: prophesied, regarded; фр.: transports, pas un signe. По-еврейски וַיִּתְנַבְּאוּ — пророчествовали; קָשֶׁב — внимание."],"i-kings-18-30":["Элиягу сказал всему народу: «Подойдите ко мне». Весь народ подошёл к нему. Он восстановил разрушенный жертвенник Господа.","Eliahoe zei tegen heel het volk: «Kom dichter bij mij.» Heel het volk kwam dichter bij hem. Hij herstelde het afgebroken altaar van de Eeuwige.",""],"i-kings-18-31":["Элиягу взял двенадцать камней, по числу колен сынов Яакова, к которому было слово Господа: «Исраэль будет твоё имя».","Eliahoe nam twaalf stenen, naar het getal van de stammen van de zonen van Jaäkov, tot wie het woord van de Eeuwige gekomen was: «Israël zal je naam zijn.»","Фр.: la voix de l’Éternel. По-еврейски דְבַר־יְהֹוָה — слово Господа."],"i-kings-18-32":["Из камней он построил жертвенник во имя Господа и сделал вокруг жертвенника канаву, как участок на две сеи зерна.","Met de stenen bouwde hij een altaar in de naam van de Eeuwige, en hij maakte rond het altaar een greppel, als een stuk grond voor twee sea zaad.","JPS: two measures of seed; фр.: deux mesures de grains. По-еврейски סָאתַיִם — две сеи."],"i-kings-18-33":["Он разложил дрова, рассёк быка и положил его на дрова.","Hij schikte het hout, sneed de stier in stukken en legde hem op het hout.",""],"i-kings-18-34":["Он сказал: «Наполните четыре кувшина водой и вылейте на всесожжение и на дрова». Он сказал: «Сделайте второй раз». И они сделали второй раз. Он сказал: «Сделайте третий раз». И они сделали третий раз.","Hij zei: «Vul vier kruiken met water en giet het uit over het brandoffer en over het hout.» Hij zei: «Doe het een tweede keer.» En zij deden het een tweede keer. Hij zei: «Doe het een derde keer.» En zij deden het een derde keer.","Фр.: la victime. По-еврейски הָעֹלָה — всесожжение."],"i-kings-18-35":["Вода потекла вокруг жертвенника, и канаву он тоже наполнил водой.","Het water liep rond het altaar, en ook de greppel vulde hij met water.","JPS: he filled; фр.: on l’avait remplie. По-еврейски מִלֵּא — он наполнил."],"i-kings-18-36":["Во время вознесения минхи подошёл пророк Элиягу и сказал: «Господь, Бог Авраама, Ицхака и Исраэля! Да станет сегодня известно, что Ты — Бог в Исраэле, и что я Твой слуга, и что по Твоему слову я сделал всё это.","Bij het opgaan van de mincha trad de profeet Eliahoe naar voren en zei: «Eeuwige, God van Abraham, van Jitschak en van Israël! Laat het vandaag bekend worden dat U God bent in Israël, dat ik Uw dienaar ben en dat ik al deze dingen op Uw woord heb gedaan.","Фр.: la Divinité, par ton ordre. По-еврейски אַתָּה אֱלֹהִים — Ты Бог; בִּדְבָרְךָ — по Твоему слову."],"i-kings-18-37":["Ответь мне, Господь, ответь мне, и узнает этот народ, что Ты, Господь, — Бог, и что Ты обратил их сердце назад».","Antwoord mij, Eeuwige, antwoord mij, zodat dit volk weet dat U, Eeuwige, God bent, en dat U hun hart achterwaarts hebt gekeerd.»","JPS: turn their heart backward; фр.: amené leur cœur à résipiscence. По-еврейски הֲסִבֹּתָ אֶת־לִבָּם אֲחֹרַנִּית — обратил их сердце назад."],"i-kings-18-38":["И упал огонь Господа, и пожрал всесожжение, и дрова, и камни, и прах, и слизал воду, которая была в канаве.","Toen viel het vuur van de Eeuwige en verteerde het brandoffer, het hout, de stenen en het stof, en likte het water op dat in de greppel was.","Фр.: absorba. По-еврейски לִחֵכָה — слизал."],"i-kings-18-39":["Весь народ увидел это. Они пали на свои лица и сказали: «Господь — Он Бог, Господь — Он Бог».","Heel het volk zag het. Zij vielen op hun gezicht en zeiden: «De Eeuwige, Hij is God; de Eeuwige, Hij is God.»","Фр. добавляет vrai. По-еврейски дважды יְהֹוָה הוּא הָאֱלֹהִים, без «истинный»."],"exodus-36-8":["Все мудрые сердцем среди делающих работу сделали Мишкан: десять полотнищ из кручёного льна и из синей, пурпурной и алой пряжи, с керувим. Работой мастера узора сделал он их.","Allen die wijs van hart waren onder hen die het werk deden, maakten de misjkan: tien kleden van getwijnd linnen, blauw, purper en scharlaken, met keroeviem. Als werk van een patroonwever maakte hij ze.","Фр.: les plus habiles, enceinte. По-еврейски כׇל־חֲכַם־לֵב — всякий мудрый сердцем среди делающих работу, и это הַמִּשְׁכָּן, Мишкан."],"exodus-36-9":["Длина одного полотнища — двадцать восемь локтей, ширина одного полотнища — четыре локтя. Одна мера у всех полотнищ.","De lengte van het ene kleed was achtentwintig el, de breedte van het ene kleed vier el. Eén maat voor alle kleden.",""],"exodus-36-10":["Он соединил пять полотнищ одно с другим, и пять полотнищ соединил одно с другим.","Hij voegde vijf kleden aan elkaar, en vijf kleden voegde hij aan elkaar.",""],"exodus-36-11":["Он сделал синие петли на краю одного полотнища, на конце, в скреплении. Так же он сделал на краю крайнего полотнища во втором скреплении.","Hij maakte lussen van blauw aan de rand van het ene kleed, aan het uiteinde, in het samenstel. Zo deed hij aan de rand van het buitenste kleed in het tweede samenstel.",""],"exodus-36-12":["Пятьдесят петель он сделал на одном полотнище, и пятьдесят петель сделал на краю полотнища, которое во втором скреплении. Петли приходились одна напротив другой.","Vijftig lussen maakte hij aan het ene kleed, en vijftig lussen maakte hij aan de rand van het kleed dat in het tweede samenstel zit. De lussen stonden tegenover elkaar, de ene bij de andere.",""],"exodus-36-13":["Он сделал пятьдесят золотых застёжек и соединил полотнища друг с другом застёжками, и Мишкан стал одним целым.","Hij maakte vijftig gouden gespen en voegde de kleden aan elkaar met de gespen, en de misjkan werd één.",""],"exodus-36-14":["Он сделал полотнища из козьей шерсти для шатра над Мишканом. Одиннадцать полотнищ он сделал.","Hij maakte kleden van geitenhaar voor een tent over de misjkan. Elf kleden maakte hij.",""],"exodus-36-15":["Длина одного полотнища — тридцать локтей, ширина одного полотнища — четыре локтя. Одна мера у одиннадцати полотнищ.","De lengte van het ene kleed was dertig el, en vier el de breedte van het ene kleed. Eén maat voor de elf kleden.",""],"exodus-36-16":["Он соединил пять полотнищ отдельно и шесть полотнищ отдельно.","Hij voegde de vijf kleden afzonderlijk aaneen, en de zes kleden afzonderlijk.",""],"exodus-36-17":["Он сделал пятьдесят петель на краю крайнего полотнища в скреплении и пятьдесят петель сделал на краю полотнища, смыкающего второе скрепление.","Hij maakte vijftig lussen aan de rand van het buitenste kleed in het samenstel, en vijftig lussen maakte hij aan de rand van het kleed dat het tweede samenstel verbindt.",""],"exodus-36-18":["Он сделал пятьдесят медных застёжек, чтобы соединить шатёр, так чтобы он стал одним целым.","Hij maakte vijftig koperen gespen om de tent samen te voegen, zodat die één werd.",""],"exodus-36-19":["Он сделал для шатра покрытие из бараньих кож, окрашенных в красное, и сверху покрытие из кож тахаш.","Hij maakte voor de tent een bedekking van rood geverfde ramsvellen, en daarboven een bedekking van tachasj-huiden.","תְּחָשִׁים — неизвестное животное. JPS: sealskins, это уже тюлень. Фр.: peaux de tahach."],"exodus-36-20":["Он сделал брусья для Мишкана из дерева акации, стоящие.","Hij maakte de planken voor de misjkan van acaciahout, rechtop staand.",""],"exodus-36-21":["Десять локтей — длина бруса, и полтора локтя — ширина одного бруса.","Tien el was de lengte van de plank, en anderhalve el de breedte van de ene plank.",""],"exodus-36-22":["Два шипа у одного бруса, скреплённые один с другим. Так он сделал у всех брусьев Мишкана.","Twee pennen aan de ene plank, in elkaar gevoegd. Zo maakte hij het bij alle planken van de misjkan.","מְשֻׁלָּבֹת אַחַת אֶל־אֶחָת — скреплены один с другим. Фр.: parallèles."],"exodus-36-23":["Он сделал брусья для Мишкана: двадцать брусьев для южной стороны, к югу.","Hij maakte de planken voor de misjkan: twintig planken voor de zuidzijde, naar het zuiden.",""],"exodus-36-24":["И сорок серебряных оснований он сделал под двадцать брусьев: два основания под один брус для двух его шипов и два основания под другой брус для двух его шипов.","En veertig zilveren voetstukken maakte hij onder de twintig planken: twee voetstukken onder de ene plank voor zijn twee pennen, en twee voetstukken onder de andere plank voor zijn twee pennen.",""],"exodus-36-25":["И для второй стороны Мишкана, для северной стороны, он сделал двадцать брусьев,","En voor de tweede zijde van de misjkan, aan de noordzijde, maakte hij twintig planken,",""],"exodus-36-26":["и сорок их оснований из серебра: два основания под один брус и два основания под другой брус.","en hun veertig voetstukken van zilver: twee voetstukken onder de ene plank en twee voetstukken onder de andere plank.",""],"exodus-36-27":["И для задней стороны Мишкана, к западу, он сделал шесть брусьев.","En voor de achterzijde van de misjkan, naar het westen, maakte hij zes planken.",""],"exodus-36-28":["И два бруса он сделал для углов Мишкана сзади.","En twee planken maakte hij voor de hoeken van de misjkan aan de achterzijde.",""],"exodus-36-29":["Они были сдвоены снизу и вместе доходили цельными до его верха, до одного кольца. Так он сделал с обоими, для двух углов.","Zij waren van onderen gepaard en kwamen samen heel tot aan de top, tot aan de ene ring. Zo deed hij met allebei, voor de twee hoeken.","Стих тёмный. תוֹאֲמִם מִלְּמַטָּה — сдвоены снизу; יַחְדָּו תַמִּים אֶל־רֹאשׁוֹ אֶל־הַטַּבַּעַת הָאֶחָת — вместе цельные до верха, до одного кольца. JPS: double beneath, complete unto the first ring. Фр.: accouplées par le bas, par un seul anneau."],"exodus-36-30":["И было восемь брусьев, и их основания серебряные: шестнадцать оснований, по два основания под каждый брус.","Zo waren er acht planken, en hun voetstukken van zilver: zestien voetstukken, twee voetstukken onder elke plank.",""],"exodus-36-31":["Он сделал поперечины из дерева акации: пять для брусьев одной стороны Мишкана,","Hij maakte dwarsbalken van acaciahout: vijf voor de planken van de ene zijde van de misjkan,",""],"exodus-36-32":["и пять поперечин для брусьев второй стороны Мишкана, и пять поперечин для брусьев Мишкана сзади, к западу.","en vijf dwarsbalken voor de planken van de tweede zijde van de misjkan, en vijf dwarsbalken voor de planken van de misjkan aan de achterzijde, naar het westen.",""],"exodus-36-33":["Он сделал среднюю поперечину, чтобы она проходила внутри брусьев от края до края.","Hij maakte de middelste dwarsbalk zo dat die midden door de planken liep, van het ene uiteinde tot het andere.",""],"exodus-36-34":["Брусья он покрыл золотом, их кольца сделал из золота, гнёздами для поперечин, и покрыл поперечины золотом.","De planken bedekte hij met goud, hun ringen maakte hij van goud, als houders voor de dwarsbalken, en hij bedekte de dwarsbalken met goud.",""],"exodus-36-35":["Он сделал завесу из синей, пурпурной и алой пряжи и кручёного льна. Работой мастера узора он сделал её, с керувим.","Hij maakte het voorhangsel van blauw, purper, scharlaken en getwijnd linnen. Als werk van een patroonwever maakte hij het, met keroeviem.",""],"exodus-36-36":["Он сделал для неё четыре столба из акации и покрыл их золотом, их крюки — из золота, и отлил для них четыре серебряных основания.","Hij maakte ervoor vier zuilen van acacia en bedekte ze met goud. Hun haken waren van goud, en hij goot voor hen vier zilveren voetstukken.",""],"exodus-36-37":["Он сделал занавес для входа шатра из синей, пурпурной и алой пряжи и кручёного льна, работой вышивальщика,","Hij maakte een gordijn voor de ingang van de tent, van blauw, purper, scharlaken en getwijnd linnen, werk van een borduurder,",""],"exodus-36-38":["и пять его столбов с их крюками. Он покрыл золотом их навершия и их обручи, а пять их оснований были из меди.","en de vijf zuilen ervan met hun haken. Hij bedekte hun koppen en hun banden met goud, en hun vijf voetstukken waren van koper.",""],"exodus-37-1":["Бецалель сделал ковчег из дерева акации: два с половиной локтя его длина, полтора локтя его ширина и полтора локтя его высота.","Betsalel maakte de ark van acaciahout: twee en een halve el was zijn lengte, anderhalve el zijn breedte en anderhalve el zijn hoogte.",""],"exodus-37-2":["Он покрыл его чистым золотом изнутри и снаружи и сделал ему золотой ободок вокруг.","Hij bedekte hem met zuiver goud, van binnen en van buiten, en maakte er een gouden rand omheen.","זֵר — ободок вокруг. JPS: crown. Фр.: corniche."],"exodus-37-3":["Он отлил для него четыре золотых кольца на четыре его стопы: два кольца на одной его стороне и два кольца на другой его стороне.","Hij goot voor hem vier gouden ringen, aan zijn vier voeten: twee ringen aan de ene zijde en twee ringen aan de andere zijde.","פַּעֲמֹתָיו тёмное: стопа или угол. JPS: feet. Фр.: angles."],"exodus-37-4":["Он сделал шесты из дерева акации и покрыл их золотом.","Hij maakte draagstokken van acaciahout en bedekte ze met goud.",""],"exodus-37-5":["Он вдел шесты в кольца по сторонам ковчега, чтобы нести ковчег.","Hij stak de draagstokken in de ringen aan de zijden van de ark, om de ark te dragen.",""],"exodus-37-6":["Он сделал крышку из чистого золота: два с половиной локтя её длина и полтора локтя её ширина.","Hij maakte een deksel van zuiver goud: twee en een halve el was de lengte ervan, en anderhalve el de breedte ervan.","כַּפֹּרֶת — крышка. JPS: ark-cover. Фр.: propitiatoire. «Крышка очищения» и «умилостивилище» добавляют поздний смысл."],"exodus-37-7":["Он сделал двух керувим из золота. Чеканной работой он сделал их, с двух краёв крышки.","Hij maakte twee keroeviem van goud. Als gedreven werk maakte hij ze, aan de twee uiteinden van het deksel.","כַּפֹּרֶת — крышка, не propitiatoire. מִקְשָׁה — чеканная работа. Фр.: d'une seule pièce, propitiatoire."],"exodus-37-8":["Один керув с этого края и один керув с того края. Из крышки он сделал керувим, с двух её краёв.","Eén keroev aan dit uiteinde en één keroev aan dat uiteinde. Uit het deksel maakte hij de keroeviem, aan zijn twee uiteinden.","כַּפֹּרֶת — крышка. JPS: ark-cover. Фр.: propitiatoire."],"exodus-37-9":["Керувим были с крыльями, распростёртыми вверх, и крыльями заслоняли крышку. Их лица были обращены одно к другому; к крышке были обращены лица керувим.","De keroeviem hadden de vleugels naar boven uitgespreid en beschutten met hun vleugels het deksel. Hun gezichten waren naar elkaar toe, en naar het deksel waren de gezichten van de keroeviem.","לְמַעְלָה — вверх, не вперёд. Фр.: en avant, s'inclinaient, propitiatoire. Лица обращены к крышке, а не склонены. כַּפֹּרֶת — крышка."],"exodus-30-11":["Господь сказал Моше:","De Eeuwige zei tegen Mosje:",""],"exodus-30-12":["«Когда ты будешь считать сынов Исраэля по их переписи, каждый даст Господу выкуп за свою жизнь, когда ты будешь считать их, и не будет среди них язвы, когда ты их считаешь.","«Wanneer je de kinderen van Israël telt volgens hun telling, zal ieder een losprijs voor zijn leven aan de Eeuwige geven, wanneer je hen telt, zodat er geen plaag onder hen is wanneer je hen telt.","JPS: ransom for his soul, plague. Фр.: rachat de sa personne, mortalité. По-еврейски כֹּפֶר נַפְשׁוֹ — выкуп за жизнь; נֶגֶף — язва, не названный мор."],"exodus-30-13":["Вот что дадут все, кто проходит среди исчисленных: половину шекеля по шекелю святилища, — шекель составляет двадцать гер, — половину шекеля в приношение Господу.","Dit zullen allen geven die bij de getelden worden opgenomen: een halve sikkel, naar de sikkel van het heiligdom — de sikkel is twintig gera — een halve sikkel als bijdrage aan de Eeuwige.","Фр.: tribut, poids du sanctuaire. По-еврейски מַחֲצִית הַשֶּׁקֶל בְּשֶׁקֶל הַקֹּדֶשׁ — половина шекеля по шекелю святилища; תְּרוּמָה — приношение, не подать."],"exodus-30-14":["Каждый, кто проходит среди исчисленных, от двадцати лет и старше, даст приношение Господу.","Ieder die bij de getelden wordt opgenomen, van twintig jaar en ouder, zal de bijdrage aan de Eeuwige geven.","Фр.: impôt de l'Éternel. По-еврейски תְּרוּמַת יְהֹוָה — приношение Господу, не налог."],"exodus-30-15":["Богатый не даст больше, и бедный не даст меньше половины шекеля, отдавая приношение Господу, чтобы искупить ваши жизни.","De rijke zal niet meer geven en de arme niet minder dan een halve sikkel, bij het geven van de bijdrage aan de Eeuwige, om verzoening te doen voor jullie levens.","JPS: atonement for your souls. Фр.: impôt, racheter vos personnes. По-еврейски תְּרוּמָה — приношение; לְכַפֵּר עַל־נַפְשֹׁתֵיכֶם — покрыть ваши жизни. Окончание множественного числа."],"exodus-30-16":["И ты возьмёшь серебро искупления у сынов Исраэля и отдашь его на службу шатра встречи. Оно будет сынам Исраэля памятью перед Господом, чтобы искупить ваши жизни.»","En je zult het zilver van de verzoening aannemen van de kinderen van Israël en het geven voor de dienst van de tent der samenkomst. Het zal voor de kinderen van Israël een herinnering zijn voor de Eeuwige, om verzoening te doen voor jullie levens.»","Фр.: recommandation, épargne vos personnes. По-еврейски לְזִכָּרוֹן — память; לְכַפֵּר — искупить. כֶּסֶף הַכִּפֻּרִים — серебро искупления, слова «шекель» в стихе нет."],"ii-kings-12-1":["Йегоашу было семь лет, когда он стал царём.","Jehoasj was zeven jaar toen hij koning werd.",""],"ii-kings-12-2":["В седьмой год Йеху воцарился Йегоаш, и сорок лет он царствовал в Йерушалаиме. Имя его матери — Цивья, из Беэр-Шевы.","In het zevende jaar van Jehu werd Jehoasj koning, en veertig jaar regeerde hij in Jeroesjalajim. Zijn moeder heette Tsivja, uit Beër-Sjeva.",""],"ii-kings-12-3":["Йегоаш делал правильное в глазах Господа во все свои дни, пока его наставлял священник Йехояда.","Jehoasj deed wat recht is in de ogen van de Eeuwige, al zijn dagen dat de priester Jehojada hem onderwees.","אֲשֶׁר הוֹרָהוּ ограничивает срок: все дни, пока Йехояда его наставлял. Фр.: toute sa vie, conformément aux enseignements — снимает эту границу."],"ii-kings-12-4":["Только высоты не исчезли: народ ещё приносил жертвы и воскурял на высотах.","Alleen de hoogten verdwenen niet. Het volk bracht nog offers en brandde wierook op de hoogten.","JPS: sacrificed and offered. По-еврейски מְזַבְּחִים וּמְקַטְּרִים — приносили жертвы и воскуряли."],"ii-kings-12-5":["Йегоаш сказал священникам: «Всё серебро святынь, которое приносят в дом Господа, — серебро каждого проходящего, серебро людей по его оценке, всё серебро, которое человеку придёт на сердце принести в дом Господа, —","Jehoasj zei tegen de priesters: «Al het zilver van de heilige gaven dat in het huis van de Eeuwige wordt gebracht — het zilver van ieder die voorbijgaat, het zilver van personen naar zijn schatting, al het zilver dat een mens ter harte komt om naar het huis van de Eeuwige te brengen —","כֶּסֶף עוֹבֵר אִישׁ тёмное. JPS: current money. Фр.: argent de chaque homme recensé, и maison de Dieu. По-еврейски עוֹבֵר — проходящий, как при переписи, не ходячая монета; כֶּסֶף נַפְשׁוֹת עֶרְכּוֹ — серебро людей по оценке. יְהֹוָה — Господь. Слова «шекель» нет."],"ii-kings-12-6":["пусть священники берут его себе, каждый от своего знакомого, и сами чинят повреждения дома везде, где найдётся повреждение».","laten de priesters het voor zich nemen, ieder van zijn kennis, en laten zij de schade aan het huis herstellen overal waar schade wordt gevonden.»","מַכָּרוֹ — знакомый. JPS: him that bestoweth it upon him."],"ii-kings-12-7":["В двадцать третий год царя Йегоаша священники не починили повреждений дома.","In het drieëntwintigste jaar van koning Jehoasj hadden de priesters de schade aan het huis niet hersteld.",""],"ii-kings-12-8":["Царь Йегоаш призвал священника Йехояду и священников и сказал им: «Почему вы не чините повреждения дома? Теперь не берите серебро у ваших знакомых, а отдавайте его на повреждения дома».","Koning Jehoasj riep de priester Jehojada en de priesters en zei tegen hen: «Waarom herstellen jullie de schade aan het huis niet? Neem nu geen zilver meer aan van jullie bekenden, maar geef het voor de schade aan het huis.»",""],"ii-kings-12-9":["Священники согласились не брать серебро у народа и не чинить повреждений дома.","De priesters stemden toe geen zilver van het volk aan te nemen en de schade aan het huis niet te herstellen.",""],"ii-kings-12-10":["Священник Йехояда взял один ящик, просверлил отверстие в его двери и поставил его возле жертвенника, справа, когда человек входит в дом Господа. Священники, стражи порога, клали туда всё серебро, приносимое в дом Господа.","De priester Jehojada nam één kist, boorde een gat in de deur ervan en zette hem naast het altaar, rechts wanneer een mens het huis van de Eeuwige binnengaat. De priesters die de drempel bewaakten, legden daar al het zilver dat naar het huis van de Eeuwige werd gebracht.","JPS: lid. Фр.: couvercle, maison de Dieu. По-еврейски בְּדַלְתּוֹ — в его двери. אֲרוֹן здесь ящик для серебра, не ковчег. יְהֹוָה — Господь."],"ii-kings-12-11":["И бывало, когда видели, что серебра в ящике много, поднимались писец царя и первосвященник, увязывали и считали серебро, найденное в доме Господа.","Telkens wanneer zij zagen dat er veel zilver in de kist was, gingen de schrijver van de koning en de hogepriester naar boven, bonden het bijeen en telden het zilver dat in het huis van de Eeuwige werd gevonden.","וַיָּצֻרוּ — увязывали. Фр.: ramasser — только собирали."],"ii-kings-12-12":["Отвешенное серебро они отдавали в руки делающих работу, приставленных к дому Господа, а те выплачивали его плотникам и строителям, которые работали в доме Господа,","Het afgewogen zilver gaven zij in handen van hen die het werk deden en over het huis van de Eeuwige waren aangesteld, en die betaalden het uit aan de houtbewerkers en de bouwers die aan het huis van de Eeuwige werkten,","הַמְתֻכָּן — отвешенное. Фр.: ainsi compté, maison de Dieu. По-еврейски это вес, не только счёт. יְהֹוָה — Господь."],"ii-kings-12-13":["и каменщикам, и каменотёсам, и на покупку дерева и тёсаного камня, чтобы чинить повреждения дома Господа, и на всё, что выходило на дом для его починки.","en aan de metselaars en de steenhouwers, en om hout en gehouwen steen te kopen, om de schade aan het huis van de Eeuwige te herstellen, en voor alles wat voor het huis werd uitgegeven om het te herstellen.","Фр.: maison de Dieu. По-еврейски בֵּית־יְהֹוָה — дом Господа."],"ii-kings-12-14":["Но для дома Господа не делали серебряных чаш, щипцов, кропильных чаш, труб, никакой золотой утвари и никакой серебряной утвари из серебра, которое приносили в дом Господа.","Maar voor het huis van de Eeuwige maakte men geen schalen van zilver, geen snuiters, geen sprengkommen en geen trompetten, geen enkel voorwerp van goud en geen voorwerp van zilver, van het zilver dat naar het huis van de Eeuwige werd gebracht.","מְזַמְּרוֹת тёмное: щипцы для светильников или ножи. JPS: snuffers. Фр.: couteaux, maison de Dieu. По-еврейски יְהֹוָה — Господь."],"ii-kings-12-15":["потому что его отдавали делающим работу, и они чинили им дом Господа.","want men gaf het aan hen die het werk deden, en zij herstelden daarmee het huis van de Eeuwige.","Фр.: maison de Dieu. По-еврейски בֵּית יְהֹוָה — дом Господа."],"ii-kings-12-16":["И не требовали отчёта у людей, которым отдавали серебро в руки, чтобы передать делающим работу, потому что те действовали верно.","En zij vroegen geen rekenschap van de mannen in wier hand zij het zilver gaven om het te geven aan hen die het werk deden, want zij handelden in trouw.",""],"ii-kings-12-17":["Серебро жертвы повинности и серебро жертв за грех не вносили в дом Господа: они принадлежали священникам.","Zilver van het schuldoffer en zilver van de zondoffers werd niet naar het huis van de Eeuwige gebracht: ze behoorden aan de priesters.","JPS: forfeit money, the sin money. Фр.: argent des sacrifices délictifs ou expiatoires. По-еврейски כֶּסֶף אָשָׁם וְכֶסֶף חַטָּאוֹת — серебро жертвы повинности и серебро жертв за грех. Слова «шекель» нет."],"deuteronomy-32-49":["«Поднимись на эту гору Аварим, на гору Нево, что в земле Моава, напротив Иерихона, и посмотри на землю Кнаана, которую Я отдаю сынам Израиля во владение.","«Ga omhoog op deze berg Avariem, de berg Nevo, die in het land Moav ligt, tegenover Jericho, en zie het land Kenaän, dat Ik aan de zonen van Israël in bezit geef.",""],"deuteronomy-32-50":["Ты умрёшь на горе, на которую поднимешься, и присоединишься к своему народу, как умер твой брат Аарон на горе Ор и присоединился к своему народу,","Je zult sterven op de berg waarop je gaat, en je zult bij je volk worden verzameld, zoals je broer Aharon is gestorven op de berg Hor en bij zijn volk is verzameld,",""],"deuteronomy-32-51":["потому что вы изменили Мне среди сынов Израиля у вод Мериват-Кадеш, в пустыне Цин, и не явили Моей святости среди сынов Израиля.","omdat jullie Mij ontrouw zijn geweest te midden van de zonen van Israël bij het water van Meriwat-Kadesj, in de woestijn Tsin, omdat jullie Mij niet geheiligd hebben te midden van de zonen van Israël.",""],"deuteronomy-32-52":["Ты увидишь землю издали, но туда, в землю, которую Я отдаю сынам Израиля, ты не войдёшь».","Want van verre zul je het land zien, maar daarheen, naar het land dat Ik aan de zonen van Israël geef, zul je niet komen.»",""]} as const;

const BOOK_SLUG: Record<string, string> = {
  Genesis: 'genesis',
  Numbers: 'numbers',
  Joshua: 'joshua',
  I_Samuel: 'i-samuel',
  II_Samuel: 'ii-samuel',
  I_Kings: 'i-kings',
  Isaiah: 'isaiah',
  Proverbs: 'proverbs',
  Zechariah: 'zechariah',
  Exodus: 'exodus',
  Ezra: 'ezra',
  Nehemiah: 'nehemiah',
  II_Kings: 'ii-kings',
  Deuteronomy: 'deuteronomy',
};

/** The draft line for this Sefaria range and verse, or null when this span was not prepared. */
export function draftLine(sefariaRef: string, chapter: number, verse: number): DraftLine | null {
  const book = BOOK_SLUG[sefariaRef.split('.')[0] ?? ''];
  if (!book) return null;
  const row = LINES[`${book}-${chapter}-${verse}`];
  if (!row) return null;
  return { ru: row[0], nl: row[1], note: row[2] };
}

/** True when the first verse of this Sefaria range already has a draft line. */
export function draftStarts(sefariaRef: string): boolean {
  const parts = sefariaRef.split('.');
  const chapter = Number(parts[1]);
  const verse = Number(parts[2]?.split('-')[0]);
  if (!Number.isFinite(chapter) || !Number.isFinite(verse)) return false;
  return draftLine(sefariaRef, chapter, verse) !== null;
}

export const DRAFT_VERSE_COUNT = Object.keys(LINES).length;
